const ARENA_QUESTIONS = {"10": {"1": [{"q": "Nguyên tử được cấu tạo từ những loại hạt cơ bản nào sau đây?", "opts": ["Proton, neutron và electron.", "Chỉ gồm proton và electron.", "Chỉ gồm proton và neutron.", "Chỉ gồm neutron và electron."], "ans": 0, "exp": "• <b>Kiến thức SGK Hóa 10:</b> Nguyên tử gồm hạt nhân mang điện tích dương ở tâm và lớp vỏ electron mang điện tích âm.<br>• Hạt nhân gồm proton (mang điện tích +1) và neutron (không mang điện, trừ hạt nhân nguyên tử <sup>1</sup>H không có neutron).<br>• Vỏ nguyên tử gồm các electron mang điện tích -1.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 500 220\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"250\" y=\"28\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\">MÔ HÌNH CẤU TẠO NGUYÊN TỬ</text>\n  <!-- Shells -->\n  <circle cx=\"250\" cy=\"120\" r=\"80\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.3)\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n  <circle cx=\"250\" cy=\"120\" r=\"50\" fill=\"none\" stroke=\"rgba(56, 189, 248, 0.4)\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n  <!-- Nucleus -->\n  <circle cx=\"250\" cy=\"120\" r=\"24\" fill=\"rgba(244, 63, 94, 0.25)\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n  <text x=\"250\" y=\"117\" text-anchor=\"middle\" fill=\"#fecdd3\" font-size=\"11\" font-weight=\"bold\">Hạt nhân</text>\n  <text x=\"250\" y=\"130\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"10\">(p + n)</text>\n  <!-- Electrons -->\n  <circle cx=\"200\" cy=\"120\" r=\"5\" fill=\"#38bdf8\"/>\n  <circle cx=\"300\" cy=\"120\" r=\"5\" fill=\"#38bdf8\"/>\n  <circle cx=\"250\" cy=\"40\" r=\"5\" fill=\"#38bdf8\"/>\n  <circle cx=\"250\" cy=\"200\" r=\"5\" fill=\"#38bdf8\"/>\n  <text x=\"320\" y=\"125\" fill=\"#38bdf8\" font-size=\"11\">Electron (e⁻)</text>\n  <text x=\"50\" y=\"170\" fill=\"#94a3b8\" font-size=\"11\">m<sub>p</sub> ≈ m<sub>n</sub> ≈ 1 amu; m<sub>e</sub> ≈ 0,00055 amu</text>\n</svg>"}, {"q": "Khối lượng của một electron xấp xỉ bằng bao nhiêu lần khối lượng của một proton?", "opts": ["Xấp xỉ 1/1836 lần.", "Xấp xỉ bằng nhau.", "Xấp xỉ gấp đôi.", "Xấp xỉ 1/100 lần."], "ans": 0, "exp": "• Khối lượng electron: m<sub>e</sub> ≈ 9,109·10⁻³¹ kg ≈ 0,00055 amu.<br>• Khối lượng proton: m<sub>p</sub> ≈ 1,673·10⁻²⁷ kg ≈ 1 amu.<br>• Do đó: m<sub>e</sub> / m<sub>p</sub> ≈ 1/1836. Vì khối lượng electron vô cùng nhỏ so với hạt nhân nên khối lượng nguyên tử hầu như tập trung ở hạt nhân.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho các nhận định sau về kích thước và khối lượng của nguyên tử:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Kích thước của nguyên tử thường được đo bằng đơn vị angstrom (Å) hoặc nanomet (nm). Biết 1 nm bằng bao nhiêu mét?", "opts": ["10⁻⁹ m.", "10⁻¹⁰ m.", "10⁻¹² m.", "10⁻⁶ m."], "ans": 0, "exp": "• 1 nm = 10⁻⁹ m; 1 Å = 10⁻¹⁰ m = 0,1 nm.<br>• Đường kính nguyên tử khoảng 10⁻¹⁰ m (0,1 nm), đường kính hạt nhân khoảng 10⁻¹⁴ m.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các loại hạt cấu tạo nên nguyên tử (Cột A) với đặc điểm điện tích và khối lượng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Proton (p) ➔ A. Mang điện tích +1 (+1,602·10⁻¹⁹ C), khối lượng ≈ 1 amu.", "1. Proton (p) ➔ B. Không mang điện, khối lượng ≈ 1 amu.", "1. Proton (p) ➔ C. Mang điện tích -1 (-1,602·10⁻¹⁹ C), khối lượng ≈ 0,00055 amu.", "1. Proton (p) ➔ D. Mang điện tích dương, chiếm phần lớn khối lượng nguyên tử."], "ans": 0, "exp": "• Proton mang điện tích dương +1, khối lượng xấp xỉ 1 amu.<br>• Neutron không mang điện, khối lượng xấp xỉ 1 amu.<br>• Electron mang điện tích âm -1, khối lượng rất nhỏ ≈ 0,00055 amu.<br>• Hạt nhân gồm p và n, mang điện tích +Z.", "svgGraph": null}, {"q": "Điện tích hạt nhân của nguyên tử được quyết định bởi loại hạt nào sau đây?", "opts": ["Số hạt proton trong hạt nhân.", "Số hạt neutron trong hạt nhân.", "Tổng số proton và neutron.", "Số hạt electron ở lớp vỏ ngoài cùng."], "ans": 0, "exp": "• Trong hạt nhân chỉ có proton mang điện (+1), neutron không mang điện.<br>• Do đó điện tích hạt nhân bằng +Z (với Z là số proton).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về đơn vị khối lượng nguyên tử (amu):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Một nguyên tử có 11 proton, 12 neutron và 11 electron. Số khối (A) của nguyên tử này là bao nhiêu?", "opts": ["23", "11", "12", "34"], "ans": 0, "exp": "• Số khối A = Z + N = Số proton + Số neutron = 11 + 12 = 23.<br>• Đây là nguyên tử Sodium (Na).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền các từ khóa thích hợp vào chỗ trống:<br>Nguyên tử trung hòa về điện nên số [ ... ] bằng số [ ... ]. Khối lượng nguyên tử hầu như tập trung toàn bộ ở [ ... ], trong khi lớp vỏ [ ... ] chiếm hầu hết thể tích của nguyên tử.", "opts": ["proton — electron — hạt nhân — nguyên tử", "nguyên tử — hạt nhân — electron — proton", "electron — hạt nhân — nguyên tử — proton", "hạt nhân — nguyên tử — proton — electron"], "ans": 0, "exp": "• Số p = Số e để trung hòa điện.<br>• Hạt nhân tập trung gần 99,95% khối lượng.<br>• Vỏ electron chuyển động tạo không gian rỗng chiếm thể tích nguyên tử.", "svgGraph": null}, {"q": "Thí nghiệm khám phá ra hạt nhân nguyên tử do nhà bác học nào thực hiện bằng cách bắn phá lá vàng mỏng bằng hạt alpha (α)?", "opts": ["Ernest Rutherford (1911).", "J.J. Thomson (1897).", "James Chadwick (1932).", "John Dalton (1803)."], "ans": 0, "exp": "• Rutherford (1911) bắn phá lá vàng mỏng bằng tia alpha, phát hiện hạt nhân mang điện dương ở tâm nguyên tử.<br>• J.J. Thomson tìm ra electron (1897).<br>• Chadwick tìm ra neutron (1932).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "2": [{"q": "Nguyên tố hóa học là tập hợp các nguyên tử có cùng đặc điểm nào sau đây?", "opts": ["Cùng số proton trong hạt nhân (cùng số hiệu nguyên tử Z).", "Cùng số neutron trong hạt nhân.", "Cùng số khối A.", "Cùng tổng số hạt proton và neutron."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 10:</b> Nguyên tố hóa học là tập hợp các nguyên tử có cùng số đơn vị điện tích hạt nhân (cùng số proton Z).<br>• Các nguyên tử có cùng số Z thì có tính chất hóa học giống nhau.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Kí hiệu nguyên tử <sup>A</sup><sub>Z</sub>X cho biết những thông tin nào về nguyên tử X?", "opts": ["Số khối A ở phía trên và số hiệu nguyên tử Z ở phía dưới.", "Số neutron ở phía trên và số proton ở phía dưới.", "Số electron ở phía trên và số khối ở phía dưới.", "Điện tích hạt nhân ở phía trên và nguyên tử khối ở phía dưới."], "ans": 0, "exp": "• Trong kí hiệu <sup>A</sup><sub>Z</sub>X: X là kí hiệu hóa học, Z là số hiệu nguyên tử (số p = số e), A là số khối (A = Z + N).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho các nguyên tử: <sup>35</sup><sub>17</sub>Cl và <sup>37</sup><sub>17</sub>Cl. Xét tính đúng / sai của các nhận định:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Đồng vị là các nguyên tử của cùng một nguyên tố hóa học có đặc điểm gì?", "opts": ["Cùng số proton nhưng khác nhau về số neutron (dẫn đến số khối A khác nhau).", "Cùng số neutron nhưng khác nhau về số proton.", "Cùng số khối A nhưng khác nhau về số proton.", "Cùng số electron nhưng khác nhau về số proton."], "ans": 0, "exp": "• Đồng vị (isotope): Các nguyên tử cùng số proton Z, khác số neutron N, do đó số khối A khác nhau.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các kí hiệu nguyên tử (Cột A) với số lượng các hạt tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. <sup>12</sup><sub>6</sub>C ➔ A. 6 proton, 6 neutron, 6 electron.", "1. <sup>12</sup><sub>6</sub>C ➔ B. 11 proton, 12 neutron, 11 electron.", "1. <sup>12</sup><sub>6</sub>C ➔ C. 26 proton, 30 neutron, 26 electron.", "1. <sup>12</sup><sub>6</sub>C ➔ D. 1 proton, 0 neutron, 1 electron."], "ans": 0, "exp": "• <sup>12</sup><sub>6</sub>C: Z=6, N=12-6=6, e=6.<br>• <sup>23</sup><sub>11</sub>Na: Z=11, N=23-11=12, e=11.<br>• <sup>56</sup><sub>26</sub>Fe: Z=26, N=56-26=30, e=26.<br>• <sup>1</sup><sub>1</sub>H: Z=1, N=1-1=0, e=1.", "svgGraph": null}, {"q": "Trong tự nhiên, nguyên tố Chlorine có 2 đồng vị bền là <sup>35</sup>Cl (chiếm 75,77%) và <sup>37</sup>Cl (chiếm 24,23%). Nguyên tử khối trung bình của Chlorine là bao nhiêu?", "opts": ["35,48 amu.", "36,00 amu.", "35,50 amu.", "37,25 amu."], "ans": 0, "exp": "• Áp dụng công thức nguyên tử khối trung bình:<br>Ā = (35·75,77 + 37·24,23) / 100 = (2651,95 + 896,51) / 100 = 3548,46 / 100 ≈ 35,48 amu (thường làm tròn 35,5 amu).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về nguyên tử khối và nguyên tử khối trung bình:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nguyên tố Boron có 2 đồng vị: <sup>10</sup>B (nguyên tử khối 10,01) và <sup>11</sup>B (nguyên tử khối 11,01). Nguyên tử khối trung bình của B là 10,81. Phần trăm số nguyên tử của đồng vị <sup>11</sup>B là bao nhiêu?", "opts": ["80%", "20%", "50%", "75%"], "ans": 0, "exp": "• Gọi x là phần trăm của <sup>11</sup>B, phần trăm của <sup>10</sup>B là (100 - x).<br>• Ta có: 10,81 = [11,01·x + 10,01·(100 - x)] / 100<br>⇒ 1081 = 11,01x + 1001 - 10,01x = x + 1001 ⇒ x = 80%.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hoàn thiện nhận định sau:<br>Các đồng vị của cùng một nguyên tố hóa học có cùng số [ ... ] nhưng khác nhau về số [ ... ], do đó có [ ... ] khác nhau. Các đồng vị có tính chất hóa học [ ... ] nhau.", "opts": ["proton — neutron — số khối — tương tự", "tương tự — số khối — neutron — proton", "neutron — số khối — tương tự — proton", "số khối — tương tự — proton — neutron"], "ans": 0, "exp": "• Cùng số proton = cùng vị trí ô nguyên tố.<br>• Khác neutron = khác khối lượng (số khối).<br>• Cùng electron lớp ngoài cùng = tính chất hóa học tương tự.", "svgGraph": null}, {"q": "Nguyên tử của nguyên tố X có 19 electron ở vỏ và 20 neutron trong hạt nhân. Kí hiệu nguyên tử của X là gì?", "opts": ["<sup>39</sup><sub>19</sub>K", "<sup>20</sup><sub>19</sub>K", "<sup>39</sup><sub>20</sub>Ca", "<sup>19</sup><sub>39</sub>K"], "ans": 0, "exp": "• Số hiệu nguyên tử Z = số e = 19 (Potassium - K).<br>• Số khối A = Z + N = 19 + 20 = 39.<br>• Kí hiệu nguyên tử: <sup>39</sup><sub>19</sub>K.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "3": [{"q": "Các electron trong vỏ nguyên tử được phân bố vào các lớp electron theo thứ tự mức năng lượng từ thấp đến cao. Kí hiệu các lớp electron từ n = 1 đến n = 4 lần lượt là:", "opts": ["K, L, M, N", "L, M, N, O", "K, M, L, N", "A, B, C, D"], "ans": 0, "exp": "• Theo quy ước quốc tế (SGK Hóa 10): n = 1 (lớp K), n = 2 (lớp L), n = 3 (lớp M), n = 4 (lớp N).<br>• Các electron ở lớp K gần hạt nhân nhất, có mức năng lượng thấp nhất và liên kết chặt chẽ nhất với hạt nhân.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Số electron tối đa có thể chứa trong lớp thứ n (với n ≤ 4) được tính theo công thức nào?", "opts": ["2n²", "n²", "2n + 1", "2n"], "ans": 0, "exp": "• Số electron tối đa ở lớp thứ n là 2n² (với n ≤ 4).<br>• Cụ thể: Lớp 1 (K): 2·1² = 2 e; Lớp 2 (L): 2·2² = 8 e; Lớp 3 (M): 2·3² = 18 e; Lớp 4 (N): 2·4² = 32 e.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho các nhận định về obitan nguyên tử (AO) và các phân lớp electron:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Cấu hình electron nguyên tử của nguyên tố Sulfur (Z = 16) ở trạng thái cơ bản là:", "opts": ["1s² 2s² 2p⁶ 3s² 3p⁴", "1s² 2s² 2p⁶ 3s² 3p⁶", "1s² 2s² 2p⁶ 3s² 3p²", "1s² 2s² 2p⁶ 3s¹ 3p⁵"], "ans": 0, "exp": "• Sulfur có Z = 16, phân bố 16 electron theo thứ tự năng lượng:<br>1s² (2e) -> 2s² 2p⁶ (8e) -> 3s² 3p⁴ (6e).<br>• Lớp ngoài cùng (lớp 3) có 2 + 4 = 6 electron, do đó Sulfur là phi kim.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các phân lớp electron (Cột A) với số electron tối đa chứa trong phân lớp đó (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Phân lớp s (1 AO) ➔ A. Tối đa 2 electron.", "1. Phân lớp s (1 AO) ➔ B. Tối đa 6 electron.", "1. Phân lớp s (1 AO) ➔ C. Tối đa 10 electron.", "1. Phân lớp s (1 AO) ➔ D. Tối đa 14 electron."], "ans": 0, "exp": "• s: 1 AO -> 2 e.<br>• p: 3 AO -> 6 e.<br>• d: 5 AO -> 10 e.<br>• f: 7 AO -> 14 e.", "svgGraph": null}, {"q": "Nguyên tử của nguyên tố nào sau đây là nguyên tố kim loại dựa vào số electron ở lớp ngoài cùng?", "opts": ["Nguyên tử X có cấu hình e: [Ne] 3s¹ (1 e lớp ngoài cùng).", "Nguyên tử Y có cấu hình e: [Ne] 3s² 3p⁵ (7 e lớp ngoài cùng).", "Nguyên tử Z có cấu hình e: [Ne] 3s² 3p⁶ (8 e lớp ngoài cùng).", "Nguyên tử T có cấu hình e: [He] 2s² 2p⁴ (6 e lớp ngoài cùng)."], "ans": 0, "exp": "• Nguyên tử có 1, 2, 3 electron ở lớp ngoài cùng thường là kim loại (trừ H, He, B).<br>• Nguyên tử có 5, 6, 7 electron ở lớp ngoài cùng thường là phi kim.<br>• Nguyên tử có 8 electron lớp ngoài cùng (hoặc 2e ở He) là khí hiếm.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về trật tự sắp xếp mức năng lượng Klechkowski (trật tự phân mức năng lượng):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nguyên tử Iron (Fe) có Z = 26. Cấu hình electron của ion Fe²⁺ là:", "opts": ["[Ar] 3d⁶", "[Ar] 3d⁴ 4s²", "[Ar] 3d⁵ 4s¹", "[Ar] 3d⁶ 4s²"], "ans": 0, "exp": "• Cấu hình e của Fe (Z = 26): 1s² 2s² 2p⁶ 3s² 3p⁶ 3d⁶ 4s² (hay [Ar] 3d⁶ 4s²).<br>• Khi tạo thành ion Fe²⁺, nguyên tử Fe nhường 2 electron ở phân lớp ngoài cùng 4s: Fe -> Fe²⁺ + 2e.<br>• Do đó cấu hình e của Fe²⁺ là [Ar] 3d⁶.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Trong nguyên tử, các electron chuyển động rất nhanh quanh hạt nhân tạo thành đám mây electron. Khu vực không gian xung quanh hạt nhân mà tại đó xác suất tìm thấy electron khoảng 90% được gọi là [ ... ]. Phân lớp s có [ ... ] obitan, phân lớp p có [ ... ] obitan và phân lớp d có [ ... ] obitan.", "opts": ["obitan nguyên tử (AO) — 1 — 3 — 5", "5 — 3 — 1 — obitan nguyên tử (AO)", "1 — 3 — 5 — obitan nguyên tử (AO)", "3 — 5 — obitan nguyên tử (AO) — 1"], "ans": 0, "exp": "• Định nghĩa obitan nguyên tử (Atomic Orbital - AO).<br>• Số AO tương ứng: s (1), p (3), d (5), f (7).", "svgGraph": null}, {"q": "Nguyên tử Chromium (Cr) có Z = 24. Cấu hình electron ở trạng thái cơ bản có hiện tượng bán bão hòa là:", "opts": ["[Ar] 3d⁵ 4s¹", "[Ar] 3d⁴ 4s²", "[Ar] 3d⁶", "[Ar] 3d³ 4s² 4p¹"], "ans": 0, "exp": "• Do cấu hình phân lớp d bán bão hòa (3d⁵) bền vững hơn nên 1 electron từ 4s nhảy sang 3d: [Ar] 3d⁴ 4s² -> [Ar] 3d⁵ 4s¹.<br>• Tương tự Copper (Cu, Z = 29) đạt trạng thái bão hòa [Ar] 3d¹⁰ 4s¹.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "4": [{"q": "Tổng số hạt proton, neutron và electron trong nguyên tử của một nguyên tố X là 40. Trong đó số hạt mang điện nhiều hơn số hạt không mang điện là 12. Số khối của nguyên tử X là:", "opts": ["27", "13", "14", "40"], "ans": 0, "exp": "• Hệ phương trình:<br>  2Z + N = 40 (1)<br>  2Z - N = 12 (2)<br>• Cộng (1) và (2) ta được: 4Z = 52 ⇒ Z = 13 (Aluminium).<br>• Thay Z = 13 vào (1) ⇒ N = 40 - 26 = 14.<br>• Số khối A = Z + N = 13 + 14 = 27.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nguyên tử của nguyên tố Potassium (K) có Z = 19. Số electron độc thân của K ở trạng thái cơ bản là:", "opts": ["1", "2", "3", "0"], "ans": 0, "exp": "• Cấu hình e của K (Z = 19): 1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹.<br>• Phân lớp 4s có 1 electron, do đó có 1 electron độc thân.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính đúng/sai của các nhận định tổng kết Chương 1:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Cặp nguyên tử nào sau đây thuộc cùng một nguyên tố hóa học?", "opts": ["X (Z = 8, A = 16) và Y (Z = 8, A = 17)", "M (Z = 6, A = 12) và N (Z = 7, A = 14)", "P (Z = 11, A = 23) và Q (Z = 12, A = 24)", "A (Z = 19, A = 39) và B (Z = 20, A = 40)"], "ans": 0, "exp": "• Cùng nguyên tố hóa học khi và chỉ khi có cùng số proton Z.<br>• X và Y đều có Z = 8 (Oxygen) nên là đồng vị của cùng một nguyên tố.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép cấu hình electron lớp ngoài cùng (Cột A) với tính chất nguyên tố tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. 3s¹ ➔ A. Kim loại điển hình (nhóm IA).", "1. 3s¹ ➔ B. Phi kim điển hình (nhóm VIIA - Halogen).", "1. 3s¹ ➔ C. Khí hiếm bền vững (Neon).", "1. 3s¹ ➔ D. Phi kim nhóm IVA (Silicon)."], "ans": 0, "exp": "• 1-3 e lớp ngoài cùng: Kim loại.<br>• 5-7 e: Phi kim.<br>• 8 e (hoặc 2e ở He): Khí hiếm.<br>• 4 e: Có thể là kim loại hoặc phi kim (C, Si là phi kim; Sn, Pb là kim loại).", "svgGraph": null}, {"q": "Ion X²⁻ có cấu hình electron là 1s² 2s² 2p⁶. Vị trí của nguyên tố X trong bảng tuần hoàn là:", "opts": ["Ô số 8, chu kì 2, nhóm VIA (Oxygen).", "Ô số 10, chu kì 2, nhóm VIIIA (Neon).", "Ô số 12, chu kì 3, nhóm IIA (Magnesium).", "Ô số 16, chu kì 3, nhóm VIA (Sulfur)."], "ans": 0, "exp": "• Ion X²⁻ nhận 2e để có 10e: e_X = 10 - 2 = 8e ⇒ Z = 8.<br>• Cấu hình e của X: 1s² 2s² 2p⁴.<br>• Vị trí: Ô số 8 (Z = 8), Chu kì 2 (2 lớp e), Nhóm VIA (6e lớp ngoài cùng, nguyên tố p).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho nguyên tố X có Z = 17 (Chlorine) và nguyên tố Y có Z = 11 (Sodium):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Một nguyên tử X có 3 lớp electron và có 5 electron ở lớp ngoài cùng. Số hiệu nguyên tử của X là:", "opts": ["15 (Phosphorus)", "7 (Nitrogen)", "17 (Chlorine)", "13 (Aluminium)"], "ans": 0, "exp": "• 3 lớp electron: lớp 1 có 2e (1s²), lớp 2 có 8e (2s² 2p⁶), lớp 3 có 5e (3s² 3p³).<br>• Tổng số electron = 2 + 8 + 5 = 15 ⇒ Z = 15 (Phosphorus).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hoàn thành đoạn văn sau:<br>Nguyên tử được cấu tạo gồm hạt nhân mang điện tích [ ... ] và vỏ electron mang điện tích [ ... ]. Khối lượng của nguyên tử xấp xỉ bằng tổng khối lượng của [ ... ] và [ ... ] trong hạt nhân.", "opts": ["dương — âm — proton — neutron", "neutron — proton — âm — dương", "âm — proton — neutron — dương", "proton — neutron — dương — âm"], "ans": 0, "exp": "• Điện tích: Hạt nhân dương, vỏ âm.<br>• Khối lượng: p + n (neutron).", "svgGraph": null}, {"q": "Cấu hình electron nào sau đây viết sai quy tắc?", "opts": ["1s² 2s² 2p⁷ (quá số e tối đa phân lớp p)", "1s² 2s² 2p⁶ 3s¹", "1s² 2s² 2p⁶ 3s² 3p⁵", "1s² 2s² 2p⁶"], "ans": 0, "exp": "• Phân lớp p chỉ có 3 obitan nên chứa tối đa 6 electron (2p⁶). Phân lớp 2p⁷ là hoàn toàn sai nguyên lí Pauli.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "5": [{"q": "Các nguyên tố trong bảng tuần hoàn hiện đại được sắp xếp theo nguyên tắc nào sau đây?", "opts": ["Theo chiều tăng dần của điện tích hạt nhân nguyên tử.", "Theo chiều tăng dần của khối lượng nguyên tử.", "Theo chiều giảm dần của bán kính nguyên tử.", "Theo thứ tự bảng chữ cái của tên gọi nguyên tố."], "ans": 0, "exp": "• <b>Nguyên tắc sắp xếp BTH (Mendeleev & Moseley):</b><br>1. Theo chiều tăng dần của điện tích hạt nhân (Z).<br>2. Các nguyên tố có cùng số lớp electron trong nguyên tử được xếp thành một hàng (chu kì).<br>3. Các nguyên tố có tính chất hóa học tương tự nhau được xếp thành một cột (nhóm).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Số thứ tự của chu kì trong bảng tuần hoàn bằng đại lượng nào của nguyên tử nguyên tố thuộc chu kì đó?", "opts": ["Số lớp electron của nguyên tử.", "Số electron ở lớp ngoài cùng.", "Số hiệu nguyên tử Z.", "Số electron hóa trị."], "ans": 0, "exp": "• Số thứ tự chu kì = Số lớp electron trong nguyên tử.<br>• Bảng tuần hoàn gồm 7 chu kì (chu kì 1, 2, 3 là chu kì nhỏ; chu kì 4, 5, 6, 7 là chu kì lớn).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về cấu tạo chu kì và nhóm trong bảng tuần hoàn:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nguyên tố X có số hiệu nguyên tử Z = 15. Vị trí của X trong bảng tuần hoàn là:", "opts": ["Ô số 15, chu kì 3, nhóm VA (Phosphorus).", "Ô số 15, chu kì 2, nhóm VA.", "Ô số 15, chu kì 3, nhóm VB.", "Ô số 15, chu kì 4, nhóm IIIA."], "ans": 0, "exp": "• Cấu hình e của X (Z = 15): 1s² 2s² 2p⁶ 3s² 3p³.<br>• Có 15 electron ⇒ Ô số 15.<br>• Có 3 lớp electron ⇒ Chu kì 3.<br>• Có 5 electron lớp ngoài cùng (3s² 3p³), electron cuối điền vào p ⇒ Nhóm VA.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các nhóm nguyên tố (Cột A) với tên gọi đặc trưng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Nhóm IA (trừ H) ➔ A. Kim loại kiềm (Alkali metals).", "1. Nhóm IA (trừ H) ➔ B. Kim loại kiềm thổ (Alkaline earth metals).", "1. Nhóm IA (trừ H) ➔ C. Nhóm Halogen.", "1. Nhóm IA (trừ H) ➔ D. Khí hiếm (Noble gases)."], "ans": 0, "exp": "• IA: Kim loại kiềm.<br>• IIA: Kim loại kiềm thổ.<br>• VIIA: Halogen.<br>• VIIIA: Khí hiếm.", "svgGraph": null}, {"q": "Các nguyên tố thuộc khối d (nguyên tố chuyển tiếp) trong bảng tuần hoàn đều thuộc phân nhóm nào?", "opts": ["Các nhóm B.", "Các nhóm A.", "Chỉ thuộc nhóm VIIIB.", "Chỉ thuộc các chu kì nhỏ."], "ans": 0, "exp": "• Khối nguyên tố d và f đều thuộc các nhóm B.<br>• Khối nguyên tố s và p thuộc các nhóm A.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các thông tin được ghi trong mỗi ô nguyên tố của bảng tuần hoàn:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nguyên tử của nguyên tố Calcium (Ca) có cấu hình electron [Ar] 4s². Calcium là nguyên tố loại nào?", "opts": ["Nguyên tố s, kim loại.", "Nguyên tố p, phi kim.", "Nguyên tố d, kim loại chuyển tiếp.", "Nguyên tố f, kim loại hiếm."], "ans": 0, "exp": "• Electron cuối cùng điền vào phân lớp 4s ⇒ nguyên tố s.<br>• Có 2 electron ở lớp ngoài cùng ⇒ kim loại nhóm IIA (kiềm thổ).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Bảng tuần hoàn gồm [ ... ] chu kì và [ ... ] cột được chia thành [ ... ] nhóm A và 8 nhóm B. Mỗi chu kì bắt đầu bằng một kim loại kiềm (trừ chu kì 1) và kết thúc bằng một [ ... ].", "opts": ["7 — 18 — 8 — khí hiếm", "khí hiếm — 8 — 18 — 7", "18 — 8 — khí hiếm — 7", "8 — khí hiếm — 7 — 18"], "ans": 0, "exp": "• 7 chu kì, 18 cột, 8 nhóm A.<br>• Chu kì mở đầu bằng kim loại kiềm (ns¹), kết thúc bằng khí hiếm (ns²np⁶).", "svgGraph": null}, {"q": "Chu kì 4 của bảng tuần hoàn có tất cả bao nhiêu nguyên tố?", "opts": ["18", "8", "32", "2"], "ans": 0, "exp": "• Chu kì 1: 2 nguyên tố.<br>• Chu kì 2, 3: 8 nguyên tố.<br>• Chu kì 4, 5: 18 nguyên tố.<br>• Chu kì 6, 7: 32 nguyên tố.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "6": [{"q": "Trong một chu kì, theo chiều tăng dần của điện tích hạt nhân (từ trái sang phải), bán kính nguyên tử của các nguyên tố biến đổi như thế nào?", "opts": ["Giảm dần.", "Tăng dần.", "Không đổi.", "Biến thiên không có quy luật."], "ans": 0, "exp": "• <b>Quy luật SGK Hóa 10:</b> Trong cùng một chu kì, số lớp electron không đổi nhưng điện tích hạt nhân Z tăng dần làm lực hút tĩnh điện giữa hạt nhân và electron lớp ngoài cùng tăng lên, kéo các electron lại gần hạt nhân hơn ⇒ Bán kính nguyên tử giảm dần.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Trong một nhóm A, theo chiều từ trên xuống dưới (điện tích hạt nhân tăng), tính chất nào sau đây của các nguyên tố tăng dần?", "opts": ["Bán kính nguyên tử và tính kim loại.", "Độ âm điện và tính phi kim.", "Năng lượng ion hóa thứ nhất.", "Ái lực electron."], "ans": 0, "exp": "• Đi từ trên xuống trong nhóm A: Số lớp electron tăng làm bán kính nguyên tử tăng nhanh ⇒ Khả năng nhường electron tăng (tính kim loại tăng) và độ âm điện giảm.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét xu hướng biến đổi độ âm điện của các nguyên tố trong bảng tuần hoàn:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Dãy các nguyên tố nào sau đây được xếp theo chiều tính phi kim tăng dần?", "opts": ["Si < P < S < Cl", "Cl < S < P < Si", "F < Cl < Br < I", "Na < Mg < Al < Si"], "ans": 0, "exp": "• Si, P, S, Cl cùng thuộc chu kì 3. Đi từ trái sang phải theo chu kì, điện tích hạt nhân tăng, bán kính giảm, độ âm điện tăng nên tính phi kim tăng dần: Si < P < S < Cl.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các quy luật biến đổi trong chu kì (từ trái qua phải) với xu hướng tương ứng:<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Bán kính nguyên tử ➔ A. Giảm dần.", "1. Bán kính nguyên tử ➔ B. Tăng dần.", "1. Bán kính nguyên tử ➔ C. Giảm dần.", "1. Bán kính nguyên tử ➔ D. Tăng dần."], "ans": 0, "exp": "• Trong chu kì (trái -> phải): Bán kính giảm, Kim loại giảm, Độ âm điện tăng, Phi kim tăng.", "svgGraph": null}, {"q": "Trong các hydroxide của chu kì 3: NaOH, Mg(OH)₂, Al(OH)₃, H₂SiO₃, H₃PO₄, H₂SO₄, HClO₄. Chất có tính acid mạnh nhất là:", "opts": ["HClO₄ (perchloric acid)", "H₂SO₄ (sulfuric acid)", "NaOH (sodium hydroxide)", "Al(OH)₃ (aluminium hydroxide)"], "ans": 0, "exp": "• Đi từ trái sang phải trong chu kì, tính base của hydroxide giảm dần và tính acid tăng dần.<br>• NaOH (base mạnh) -> Mg(OH)₂ (base yếu) -> Al(OH)₃ (lưỡng tính) -> H₂SiO₃ (acid rất yếu) -> H₃PO₄ (acid trung bình) -> H₂SO₄ (acid mạnh) -> HClO₄ (acid rất mạnh).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về oxide cao nhất của các nguyên tố chu kì 3:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nguyên tố nào sau đây có tính kim loại mạnh nhất trong số các nguyên tố: Na (Z = 11), K (Z = 19), Mg (Z = 12), Al (Z = 13)?", "opts": ["Potassium (K)", "Sodium (Na)", "Magnesium (Mg)", "Aluminium (Al)"], "ans": 0, "exp": "• Trong chu kì 3: Na > Mg > Al (tính kim loại giảm dần).<br>• Trong nhóm IA: K (chu kì 4) > Na (chu kì 3) (tính kim loại tăng dần từ trên xuống).<br>• Do đó Potassium (K) có tính kim loại mạnh nhất.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hoàn thành quy luật biến đổi tuần hoàn:<br>Trong một chu kì, đi từ trái sang phải: bán kính nguyên tử [ ... ], độ âm điện [ ... ], tính kim loại [ ... ] và tính phi kim [ ... ].", "opts": ["giảm dần — tăng dần — giảm dần — tăng dần", "tăng dần — giảm dần — tăng dần — giảm dần", "tăng dần — giảm dần — tăng dần — giảm dần", "giảm dần — tăng dần — giảm dần — tăng dần"], "ans": 0, "exp": "• Chu kì: Bán kính giảm -> độ âm điện tăng -> kim loại giảm -> phi kim tăng.", "svgGraph": null}, {"q": "Kim loại nào sau đây có nhiệt độ nóng chảy thấp nhất, ở trạng thái lỏng ở nhiệt độ phòng (25 °C)?", "opts": ["Mercury (Hg - Thủy ngân)", "Cesium (Cs)", "Gallium (Ga)", "Sodium (Na)"], "ans": 0, "exp": "• Mercury (Hg) là kim loại duy nhất ở thể lỏng ở điều kiện thường (t_nc = -38,83 °C).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "7": [{"q": "Định luật tuần hoàn phát biểu rằng tính chất của các đơn chất cũng như thành phần và tính chất của các hợp chất tạo nên từ các nguyên tố biến đổi tuần hoàn theo chiều tăng của:", "opts": ["Điện tích hạt nhân nguyên tử.", "Số khối nguyên tử.", "Số neutron trong hạt nhân.", "Nguyên tử khối tương đối."], "ans": 0, "exp": "• <b>Định luật tuần hoàn hiện đại:</b> 'Tính chất của các đơn chất cũng như thành phần và tính chất của các hợp chất biến đổi tuần hoàn theo chiều tăng dần của điện tích hạt nhân nguyên tử.'<br>• Nguyên nhân là do cấu hình electron lớp ngoài cùng của nguyên tử biến đổi tuần hoàn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Biết nguyên tố X có số hiệu nguyên tử Z = 16. Hóa trị cao nhất của X đối với oxygen và hóa trị của X trong hợp chất khí với hydrogen lần lượt là:", "opts": ["VI và II", "IV và II", "VI và IV", "II và VI"], "ans": 0, "exp": "• Sulfur (Z = 16) thuộc nhóm VIA có 6 electron hóa trị.<br>• Hóa trị cao nhất với oxygen = số thứ tự nhóm = VI (SO₃).<br>• Hóa trị trong hợp chất khí với H = 8 - 6 = II (H₂S).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các ứng dụng và ý nghĩa của bảng tuần hoàn các nguyên tố hóa học:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Biết oxide cao nhất của một nguyên tố R có dạng R₂O₅. Hợp chất khí của R với hydrogen có công thức là:", "opts": ["RH₃", "RH₂", "RH₄", "RH"], "ans": 0, "exp": "• R₂O₅ ⇒ Hóa trị cao nhất với O là V ⇒ R thuộc nhóm VA.<br>• Hóa trị trong hợp chất khí với H là: 8 - 5 = 3 (hóa trị III) ⇒ Công thức là RH₃ (ví dụ NH₃, PH₃).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép công thức oxide cao nhất (Cột A) với công thức hợp chất khí với hydrogen tương ứng của nguyên tố R (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. RO₂ (nhóm IVA) ➔ A. RH₄ (ví dụ CH₄, SiH₄).", "1. RO₂ (nhóm IVA) ➔ B. RH₃ (ví dụ NH₃, PH₃).", "1. RO₂ (nhóm IVA) ➔ C. H₂R (ví dụ H₂S, H₂Se).", "1. RO₂ (nhóm IVA) ➔ D. HR (ví dụ HCl, HBr)."], "ans": 0, "exp": "• Tổng hóa trị với O và hóa trị với H bằng 8 (đối với phi kim nhóm IVA đến VIIA).", "svgGraph": null}, {"q": "Cho các nguyên tố: Na, Mg, Al. Thứ tự sắp xếp theo chiều tính kim loại giảm dần là:", "opts": ["Na > Mg > Al", "Al > Mg > Na", "Mg > Na > Al", "Na > Al > Mg"], "ans": 0, "exp": "• Cùng chu kì 3, điện tích hạt nhân tăng dần: ₁₁Na < ₁₂Mg < ₁₃Al.<br>• Tính kim loại giảm dần từ trái sang phải: Na > Mg > Al.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét hợp chất oxide cao nhất và hydroxide của Chlorine (Z = 17, nhóm VIIA):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nguyên tố phi kim có độ âm điện lớn thứ hai trong bảng tuần hoàn (chỉ đứng sau Fluorine) là:", "opts": ["Oxygen (O, độ âm điện ≈ 3,44)", "Nitrogen (N, độ âm điện ≈ 3,04)", "Chlorine (Cl, độ âm điện ≈ 3,16)", "Bromine (Br, độ âm điện ≈ 2,96)"], "ans": 0, "exp": "• Độ âm điện: F (3,98) > O (3,44) > Cl (3,16) ≈ N (3,04) > Br (2,96).<br>• Oxygen là nguyên tố có độ âm điện lớn thứ 2 trong bảng tuần hoàn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hoàn thành nguyên nhân biến đổi tuần hoàn:<br>Sự biến đổi tuần hoàn về tính chất của các đơn chất và hợp chất là do sự biến đổi tuần hoàn của cấu hình [ ... ] của nguyên tử các nguyên tố, đặc biệt là số electron ở lớp [ ... ]. Số thứ tự chu kì bằng số [ ... ], số thứ tự nhóm A bằng số [ ... ].", "opts": ["electron — ngoài cùng — lớp electron — electron hóa trị", "electron hóa trị — lớp electron — ngoài cùng — electron", "ngoài cùng — lớp electron — electron hóa trị — electron", "lớp electron — electron hóa trị — electron — ngoài cùng"], "ans": 0, "exp": "• Cấu hình e biến đổi tuần hoàn.<br>• Lớp ngoài cùng quyết định tính chất.<br>• Chu kì = số lớp e.<br>• Nhóm A = e hóa trị (e ngoài cùng).", "svgGraph": null}, {"q": "Hợp chất khí với hydrogen của một nguyên tố R là RH₄. Trong oxide cao nhất của R thì oxygen chiếm 53,33% về khối lượng. Nguyên tố R là:", "opts": ["Silicon (Si, M = 28)", "Carbon (C, M = 12)", "Sulfur (S, M = 32)", "Germanium (Ge, M = 73)"], "ans": 0, "exp": "• Hợp chất khí RH₄ ⇒ R thuộc nhóm IVA ⇒ Oxide cao nhất là RO₂.<br>• Ta có %O = 32 / (M_R + 32) = 0,5333 ⇒ M_R + 32 = 60 ⇒ M_R = 28 (Silicon - Si).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "8": [{"q": "Hai nguyên tố X và Y đứng kế tiếp nhau trong cùng một chu kì của bảng tuần hoàn có tổng số proton trong hai hạt nhân là 25. Tên của hai nguyên tố X và Y là:", "opts": ["Magnesium (Mg, Z = 12) và Aluminium (Al, Z = 13)", "Sodium (Na, Z = 11) và Magnesium (Mg, Z = 12)", "Aluminium (Al, Z = 13) và Silicon (Si, Z = 14)", "Carbon (C, Z = 6) và Fluorine (F, Z = 9)"], "ans": 0, "exp": "• Kế tiếp nhau trong cùng chu kì: Z_Y - Z_X = 1.<br>• Tổng số proton: Z_X + Z_Y = 25.<br>• Giải hệ: Z_X = 12 (Mg) và Z_Y = 13 (Al).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nguyên tố X ở chu kì 3, nhóm IIA. Cấu hình electron của nguyên tử X là:", "opts": ["1s² 2s² 2p⁶ 3s² (Magnesium)", "1s² 2s² 2p⁶ 3s¹", "1s² 2s² 2p⁶ 3s² 3p²", "1s² 2s² 2p⁶ 4s²"], "ans": 0, "exp": "• Chu kì 3 ⇒ có 3 lớp electron.<br>• Nhóm IIA ⇒ có 2 electron ở phân lớp ngoài cùng 3s².<br>• Cấu hình e: 1s² 2s² 2p⁶ 3s² (Z = 12 - Magnesium).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho ba nguyên tố X (Z = 11, Na), Y (Z = 12, Mg) và Z (Z = 19, K):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Hydroxide nào sau đây có tính base mạnh nhất trong số: LiOH, NaOH, KOH, RbOH?", "opts": ["RbOH (Rubidium hydroxide)", "KOH (Potassium hydroxide)", "NaOH (Sodium hydroxide)", "LiOH (Lithium hydroxide)"], "ans": 0, "exp": "• Li, Na, K, Rb đều thuộc nhóm IA. Đi từ trên xuống dưới, tính kim loại tăng dần, khả năng nhường e tăng dần nên tính base của hydroxide tăng dần: LiOH < NaOH < KOH < RbOH.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép vị trí nguyên tố (Cột A) với cấu hình electron tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Chu kì 2, nhóm IVA ➔ A. 1s² 2s² 2p² (Carbon).", "1. Chu kì 2, nhóm IVA ➔ B. 1s² 2s² 2p⁶ 3s² 3p⁴ (Sulfur).", "1. Chu kì 2, nhóm IVA ➔ C. 1s² 2s² 2p⁶ 3s² 3p⁵ (Chlorine).", "1. Chu kì 2, nhóm IVA ➔ D. [Ar] 4s¹ (Potassium)."], "ans": 0, "exp": "• Đối chiếu số lớp e với chu kì và số e lớp ngoài cùng với nhóm A.", "svgGraph": null}, {"q": "Cho biết cấu hình electron của ion X²⁺ là [Ar] 3d⁶. Vị trí của nguyên tố X trong bảng tuần hoàn là:", "opts": ["Ô số 26, chu kì 4, nhóm VIIIB (Iron - Fe)", "Ô số 24, chu kì 4, nhóm VIB (Chromium)", "Ô số 28, chu kì 4, nhóm VIIIB (Nickel)", "Ô số 26, chu kì 3, nhóm VIIIB"], "ans": 0, "exp": "• X²⁺ nhường 2e để có cấu hình [Ar] 3d⁶ ⇒ Nguyên tử X có cấu hình [Ar] 3d⁶ 4s² (Z = 26 - Fe).<br>• Có 4 lớp e ⇒ Chu kì 4.<br>• Electron hóa trị = 6 (ở 3d) + 2 (ở 4s) = 8e ⇒ Nhóm VIIIB.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các quy luật biến đổi trong bảng tuần hoàn:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nguyên tố R tạo hợp chất với hydrogen có công thức RH₃. Trong oxide cao nhất của R, R chiếm 25,93% về khối lượng. Nguyên tố R là:", "opts": ["Nitrogen (N, M = 14)", "Phosphorus (P, M = 31)", "Arsenic (As, M = 75)", "Boron (B, M = 11)"], "ans": 0, "exp": "• Khí RH₃ ⇒ R thuộc nhóm VA ⇒ Oxide cao nhất là R₂O₅.<br>• Ta có: %R = 2R / (2R + 80) = 0,2593 ⇒ 2R = 0,5186R + 20,744 ⇒ 1,4814R = 20,744 ⇒ R = 14 (Nitrogen - N).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Định luật tuần hoàn là cơ sở để liên hệ giữa [ ... ] của nguyên tố trong bảng tuần hoàn với [ ... ] nguyên tử và [ ... ] hóa học của đơn chất và [ ... ] tương ứng.", "opts": ["vị trí — cấu tạo — tính chất — hợp chất", "hợp chất — tính chất — cấu tạo — vị trí", "cấu tạo — tính chất — hợp chất — vị trí", "tính chất — hợp chất — vị trí — cấu tạo"], "ans": 0, "exp": "• Tam giác quan hệ: Vị trí - Cấu tạo - Tính chất của đơn chất và hợp chất.", "svgGraph": null}, {"q": "Cho các nguyên tố: F, Cl, Br, I. Tính oxi hóa của các đơn chất giảm dần theo thứ tự:", "opts": ["F₂ > Cl₂ > Br₂ > I₂", "I₂ > Br₂ > Cl₂ > F₂", "Cl₂ > F₂ > Br₂ > I₂", "F₂ > Br₂ > Cl₂ > I₂"], "ans": 0, "exp": "• Trong nhóm VIIA (Halogen), từ trên xuống dưới độ âm điện giảm nên khả năng nhận e giảm ⇒ tính oxi hóa giảm dần: F₂ > Cl₂ > Br₂ > I₂.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "9": [{"q": "Theo quy tắc octet (bát tử), các nguyên tử của các nguyên tố nhóm A có xu hướng liên kết với các nguyên tử khác để đạt được cấu hình electron bền vững giống khí hiếm với bao nhiêu electron ở lớp ngoài cùng?", "opts": ["8 electron (hoặc 2 electron như Helium).", "18 electron.", "2 electron cho mọi nguyên tố.", "10 electron."], "ans": 0, "exp": "• <b>Quy tắc octet (G.N. Lewis):</b> Trong quá trình hình thành liên kết hóa học, nguyên tử các nguyên tố nhóm A có xu hướng nhường, nhận hoặc góp chung electron để đạt cấu hình electron bền vững của khí hiếm gần nhất với 8 electron ở lớp ngoài cùng (hoặc 2 electron như He).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nguyên tử Sodium (Na, Z = 11) có xu hướng đạt cấu hình octet bền vững bằng cách nào sau đây?", "opts": ["Nhường 1 electron để tạo thành ion Na⁺ có cấu hình giống Neon [Ne].", "Nhận 7 electron để tạo thành ion Na⁷⁻.", "Góp chung 3 cặp electron.", "Nhường 2 electron để tạo ion Na²⁺."], "ans": 0, "exp": "• Na có cấu hình [Ne] 3s¹. Để đạt octet, Na dễ dàng nhường 1 electron ở phân lớp 3s: Na -> Na⁺ + 1e.<br>• Ion Na⁺ có cấu hình [Ne] với 8 electron ở lớp 2 bền vững.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét xu hướng đạt cấu hình octet của các nguyên tử phi kim:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Để đạt cấu hình octet, nguyên tử Magnesium (Mg, Z = 12) sẽ biến đổi thành ion nào?", "opts": ["Mg²⁺", "Mg⁺", "Mg²⁻", "Mg⁴⁺"], "ans": 0, "exp": "• Mg có cấu hình [Ne] 3s². Mg nhường 2 electron ở lớp ngoài cùng: Mg -> Mg²⁺ + 2e.<br>• Ion Mg²⁺ có cấu hình bền vững của khí hiếm Ne.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các nguyên tử (Cột A) với xu hướng đạt cấu hình octet tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Potassium (K, Z = 19) ➔ A. Nhường 1 electron tạo cation K⁺ giống Ar.", "1. Potassium (K, Z = 19) ➔ B. Nhường 2 electron tạo cation Ca²⁺ giống Ar.", "1. Potassium (K, Z = 19) ➔ C. Nhận 1 electron tạo anion F⁻ giống Ne.", "1. Potassium (K, Z = 19) ➔ D. Nhận 2 electron tạo anion S²⁻ giống Ar."], "ans": 0, "exp": "• Kim loại nhường e (1, 2, 3e).<br>• Phi kim nhận e (1, 2, 3e) hoặc góp chung e.", "svgGraph": null}, {"q": "Phân tử nào sau đây có nguyên tử trung tâm KHÔNG tuân theo quy tắc octet (ngoại lệ octet)?", "opts": ["BF₃ (Boron trifluoride - quanh B chỉ có 6 electron)", "CH₄ (Methane)", "NH₃ (Ammonia)", "H₂O (Nước)"], "ans": 0, "exp": "• Trong phân tử BF₃, B có 3 electron hóa trị tạo 3 liên kết đơn với 3 nguyên tử F, do đó quanh nguyên tử B chỉ có 6 electron (chưa đủ octet 8e).<br>• CH₄, NH₃, H₂O đều có đủ 8 electron quanh nguyên tử trung tâm C, N, O.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về sự hình thành liên kết theo quy tắc octet:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Để biểu diễn electron hóa trị theo Lewis, xung quanh kí hiệu nguyên tố Carbon (C, Z = 6) người ta chấm bao nhiêu dấu chấm đại diện cho các electron hóa trị?", "opts": ["4 chấm", "6 chấm", "2 chấm", "8 chấm"], "ans": 0, "exp": "• C có cấu hình 1s² 2s² 2p², có 4 electron ở lớp ngoài cùng (electron hóa trị).<br>• Công thức Lewis biểu diễn 4 electron hóa trị bằng 4 dấu chấm xung quanh C.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Nguyên tử có xu hướng đạt cấu hình bền vững của [ ... ] với [ ... ] electron ở lớp ngoài cùng (hoặc 2 electron như [ ... ]). Kim loại có xu hướng [ ... ] electron, còn phi kim có xu hướng nhận hoặc góp chung electron.", "opts": ["khí hiếm — 8 — Helium — nhường", "nhường — Helium — 8 — khí hiếm", "8 — Helium — nhường — khí hiếm", "Helium — nhường — khí hiếm — 8"], "ans": 0, "exp": "• Quy tắc Octet (bát tử 8e) và Helium (duplet 2e).<br>• Kim loại nhường e, phi kim nhận/góp e.", "svgGraph": null}, {"q": "Ion nào sau đây KHÔNG có cấu hình electron của khí hiếm Neon (1s² 2s² 2p⁶)?", "opts": ["Cl⁻ (cấu hình của Argon [Ar])", "Na⁺", "Mg²⁺", "F⁻"], "ans": 0, "exp": "• Na⁺ (10e), Mg²⁺ (10e), F⁻ (10e), O²⁻ (10e) đều có cấu hình của Neon (10e).<br>• Cl⁻ có 17 + 1 = 18e, là cấu hình của Argon (Ar).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "10": [{"q": "Liên kết ion là loại liên kết hóa học được hình thành bởi yếu tố nào sau đây?", "opts": ["Lực hút tĩnh điện giữa các ion mang điện tích trái dấu (cation và anion).", "Sự dùng chung một hoặc nhiều cặp electron giữa hai nguyên tử.", "Lực hút giữa nguyên tử hydrogen mang điện dương và nguyên tử âm điện.", "Lực tương tác yếu giữa các phân tử phân cực."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 10:</b> Liên kết ion là liên kết được hình thành bởi lực hút tĩnh điện giữa các ion mang điện tích trái dấu (cation kim loại và anion phi kim).<br>• Ví dụ: Na⁺ + Cl⁻ -> NaCl.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Liên kết ion thường được hình thành giữa hai nguyên tử nào?", "opts": ["Một kim loại điển hình (nhóm IA, IIA) và một phi kim điển hình (nhóm VIIA, VIA).", "Hai nguyên tử phi kim giống nhau.", "Hai nguyên tử kim loại chuyển tiếp.", "Một nguyên tử phi kim và khí hiếm."], "ans": 0, "exp": "• Khi hiệu độ âm điện Δχ ≥ 1,7 (giữa kim loại mạnh và phi kim mạnh), electron chuyển hẳn từ kim loại sang phi kim tạo ion dương và ion âm hút nhau bằng liên kết ion.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các đặc điểm tính chất của các hợp chất ion (như NaCl, MgO, CaCl₂):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trong tinh thể muối ăn NaCl, xung quanh mỗi ion Na⁺ có bao nhiêu ion Cl⁻ bao quanh gần nhất?", "opts": ["6 ion Cl⁻", "8 ion Cl⁻", "4 ion Cl⁻", "12 ion Cl⁻"], "ans": 0, "exp": "• Tinh thể NaCl có cấu trúc lập phương tâm diện: Xung quanh mỗi ion Na⁺ có 6 ion Cl⁻ bao quanh theo hình bát diện đều, và ngược lại xung quanh mỗi ion Cl⁻ cũng có 6 ion Na⁺ bao quanh.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các chất (Cột A) với bản chất liên kết tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. NaCl (Muối ăn) ➔ A. Liên kết ion (Na⁺ và Cl⁻).", "1. NaCl (Muối ăn) ➔ B. Liên kết ion hai điện tích (Mg²⁺ và O²⁻).", "1. NaCl (Muối ăn) ➔ C. Liên kết ion (Ca²⁺ và 2Cl⁻).", "1. NaCl (Muối ăn) ➔ D. Liên kết cộng hóa trị không cực."], "ans": 0, "exp": "• NaCl, MgO, CaCl₂ là hợp chất ion.<br>• Cl₂ là đơn chất cộng hóa trị không cực.", "svgGraph": null}, {"q": "Cặp chất nào sau đây đều chứa liên kết ion trong phân tử?", "opts": ["NaCl và K₂O", "HCl và H₂O", "CO₂ và NH₃", "CH₄ và CCl₄"], "ans": 0, "exp": "• Na và K là kim loại kiềm điển hình, Cl và O là phi kim điển hình ⇒ hình thành liên kết ion.<br>• Các cặp còn lại gồm các phi kim liên kết với nhau bằng liên kết cộng hóa trị.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét quá trình tạo thành liên kết trong phân tử Magnesium oxide (MgO):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Đặc tính nào sau đây KHÔNG PHẢI là tính chất chung của hợp chất ion?", "opts": ["Dễ bay hơi, có nhiệt độ sôi thấp và có mùi đặc trưng.", "Khá rắn, giòn khi tác dụng lực cơ học.", "Có nhiệt độ nóng chảy cao.", "Tan tốt trong nước tạo dung dịch dẫn điện."], "ans": 0, "exp": "• Hợp chất ion rất khó bay hơi và có nhiệt độ nóng chảy, nhiệt độ sôi rất cao do lực hút tĩnh điện ion rất lớn.<br>• Dễ bay hơi là tính chất của hợp chất cộng hóa trị có liên kết phân tử yếu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Liên kết ion được hình thành do lực hút [ ... ] giữa các ion mang điện tích trái dấu. Tinh thể ion gồm các ion dương và ion âm sắp xếp luân phiên tạo thành mạng tinh thể [ ... ]. Các hợp chất ion dẫn điện khi [ ... ] hoặc khi [ ... ] trong nước.", "opts": ["tĩnh điện — không gian — nóng chảy — hòa tan", "hòa tan — nóng chảy — không gian — tĩnh điện", "không gian — nóng chảy — hòa tan — tĩnh điện", "nóng chảy — hòa tan — tĩnh điện — không gian"], "ans": 0, "exp": "• Lực hút tĩnh điện, mạng tinh thể không gian.<br>• Dẫn điện khi nóng chảy hoặc hòa tan trong nước.", "svgGraph": null}, {"q": "Biết độ âm điện của Na là 0,93 và Cl là 3,16. Hiệu độ âm điện Δχ trong phân tử NaCl là bao nhiêu và thuộc loại liên kết gì?", "opts": ["Δχ = 2,23 (liên kết ion)", "Δχ = 0,85 (liên kết CHT có cực)", "Δχ = 0,20 (liên kết CHT không cực)", "Δχ = 3,16 (liên kết kim loại)"], "ans": 0, "exp": "• Hiệu độ âm điện: Δχ = 3,16 - 0,93 = 2,23.<br>• Vì Δχ ≥ 1,7 nên liên kết giữa Na và Cl là liên kết ion.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "11": [{"q": "Liên kết cộng hóa trị là liên kết hóa học được hình thành giữa hai nguyên tử bằng:", "opts": ["Một hoặc nhiều cặp electron dùng chung.", "Lực hút tĩnh điện giữa các ion trái dấu.", "Lực hút giữa nguyên tử hydrogen và cặp e chưa chia.", "Sự dịch chuyển tự do của các electron tự do."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 10:</b> Liên kết cộng hóa trị (covalent bond) là liên kết được hình thành giữa hai nguyên tử bằng một hay nhiều cặp electron dùng chung.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Liên kết cộng hóa trị không phân cực được hình thành khi hiệu độ âm điện Δχ giữa hai nguyên tử liên kết thỏa mãn điều kiện nào?", "opts": ["0 ≤ Δχ < 0,4", "0,4 ≤ Δχ < 1,7", "Δχ ≥ 1,7", "Δχ = 2,5"], "ans": 0, "exp": "• Theo thang độ âm điện Pauling:<br>• 0 ≤ Δχ < 0,4: Liên kết cộng hóa trị không cực (ví dụ H₂, Cl₂, N₂, CH₄).<br>• 0,4 ≤ Δχ < 1,7: Liên kết cộng hóa trị có cực (ví dụ HCl, H₂O, NH₃).<br>• Δχ ≥ 1,7: Liên kết ion (ví dụ NaCl, KF).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phân tử: H₂, O₂, N₂:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Liên kết cho – nhận (liên kết phối trí) là trường hợp đặc biệt của liên kết cộng hóa trị, trong đó:", "opts": ["Cặp electron dùng chung chỉ do một nguyên tử đóng góp.", "Mỗi nguyên tử đóng góp 1 electron.", "Cặp electron chuyển hẳn từ nguyên tử này sang nguyên tử khác.", "Không có electron nào tham gia liên kết."], "ans": 0, "exp": "• Trong liên kết cho - nhận (kí hiệu A → B): nguyên tử A có cặp electron chưa chia (chất cho) đưa vào dùng chung với nguyên tử B có obitan trống (chất nhận).<br>• Ví dụ ion ammonium NH₄⁺: nguyên tử N trong NH₃ cho cặp e vào obitan trống của H⁺.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các loại liên kết (Cột A) với đặc điểm cấu tạo xen phủ obitan tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Liên kết sigma (σ) ➔ A. Tạo thành do sự xen phủ trục giữa 2 AO, rất bền vững.", "1. Liên kết sigma (σ) ➔ B. Tạo thành do sự xen phủ bên giữa 2 AO, kém bền hơn liên kết σ.", "1. Liên kết sigma (σ) ➔ C. Luôn là 1 liên kết σ.", "1. Liên kết sigma (σ) ➔ D. Gồm 1 liên kết σ và 2 liên kết π."], "ans": 0, "exp": "• Xen phủ trục -> liên kết sigma.<br>• Xen phủ bên -> liên kết pi.", "svgGraph": null}, {"q": "Năng lượng liên kết (Eb) là năng lượng cần thiết để phá vỡ một liên kết hóa học ở thể khí thành các nguyên tử riêng rẽ. Đại lượng Eb đặc trưng cho yếu tố nào?", "opts": ["Độ bền của liên kết hóa học (Eb càng lớn thì liên kết càng bền).", "Độ âm điện của nguyên tử.", "Khối lượng của phân tử.", "Bán kính nguyên tử."], "ans": 0, "exp": "• Eb (Bond energy) càng lớn thì liên kết càng bền, phân tử càng khó bị phân hủy nhiệt.<br>• Ví dụ Eb(N≡N) = 945 kJ/mol rất lớn khiến N₂ rất trơ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phân tử CO₂, H₂O và CH₄:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trong phân tử ethylene (C₂H₄, H₂C=CH₂), có bao nhiêu liên kết σ và bao nhiêu liên kết π?", "opts": ["5 liên kết σ và 1 liên kết π", "4 liên kết σ và 2 liên kết π", "6 liên kết σ và 0 liên kết π", "3 liên kết σ và 2 liên kết π"], "ans": 0, "exp": "• 4 liên kết đơn C–H: 4 liên kết σ.<br>• 1 liên kết đôi C=C: gồm 1 liên kết σ và 1 liên kết π.<br>• Tổng cộng: 4 + 1 = 5 liên kết σ và 1 liên kết π.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Sự xen phủ trục giữa các obitan nguyên tử tạo ra liên kết [ ... ], sự xen phủ bên tạo ra liên kết [ ... ]. Liên kết đơn luôn là liên kết [ ... ], trong khi liên kết đôi gồm một liên kết σ và một liên kết [ ... ].", "opts": ["sigma (σ) — pi (π) — sigma — pi", "pi — sigma — pi (π) — sigma (σ)", "pi (π) — sigma — pi — sigma (σ)", "sigma — pi — sigma (σ) — pi (π)"], "ans": 0, "exp": "• Trục -> sigma.<br>• Bên -> pi.<br>• Đơn = 1 sigma; Đôi = 1 sigma + 1 pi.", "svgGraph": null}, {"q": "Chất nào sau đây chứa liên kết cộng hóa trị có cực?", "opts": ["HCl (Hydrogen chloride)", "N₂ (Nitrogen)", "H₂ (Hydrogen)", "Cl₂ (Chlorine)"], "ans": 0, "exp": "• N₂, H₂, Cl₂ là các phân tử đồng hạch giữa hai nguyên tử giống nhau nên Δχ = 0 (CHT không cực).<br>• HCl tạo bởi H (2,20) và Cl (3,16), Δχ = 0,96 thuộc khoảng 0,4 - 1,7 nên là liên kết CHT có cực.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "12": [{"q": "Liên kết hydrogen được hình thành giữa nguyên tử hydrogen liên kết với nguyên tử có độ âm điện lớn (N, O, F) với:", "opts": ["Một nguyên tử khác có độ âm điện lớn (N, O, F) còn cặp electron chưa chia.", "Một nguyên tử kim loại kiềm.", "Một nguyên tử carbon mang điện tích âm.", "Bất kì nguyên tử nào khác trong cùng phân tử."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 10:</b> Liên kết hydrogen (kí hiệu dấu ba chấm ···) là lực hút tĩnh điện giữa nguyên tử H mang điện tích dương linh động (liên kết với N, O, F) với nguyên tử N, O, F mang điện tích âm có cặp electron chưa chia.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nhiệt độ sôi của nước (H₂O, 100 °C) cao bất thường so với hydrogen sulfide (H₂S, -60 °C) dù H₂O có khối lượng phân tử nhỏ hơn nhiều (18 so với 34 amu) là do:", "opts": ["Giữa các phân tử H₂O tạo được liên kết hydrogen liên phân tử bền vững.", "Khối lượng riêng của nước lớn hơn.", "Nước có độ nhớt cao hơn.", "Liên kết H–O bền hơn liên kết H–S."], "ans": 0, "exp": "• Phân tử H₂O có liên kết hydrogen liên phân tử mạnh mẽ tạo mạng lưới liên kết bền vững, cần cung cấp nhiều nhiệt lượng để phá vỡ nên nhiệt độ sôi cao vọt lên 100 °C.<br>• H₂S không có liên kết hydrogen nên sôi ở nhiệt độ rất thấp (-60 °C).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các ảnh hưởng của liên kết hydrogen đến tính chất vật lí của các chất:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Tương tác van der Waals là lực tương tác tĩnh điện yếu giữa các phân tử, được hình thành do:", "opts": ["Sự xuất hiện của các lưỡng cực tạm thời và lưỡng cực cảm ứng giữa các phân tử.", "Sự nhường nhận electron hoàn toàn giữa các nguyên tử.", "Sự dùng chung electron giữa các nguyên tử phi kim.", "Lực hút giữa hạt nhân nguyên tử này với hạt nhân nguyên tử khác."], "ans": 0, "exp": "• Tương tác van der Waals là lực hút giữa các lưỡng cực tạm thời (do electron chuyển động không đều) và các lưỡng cực cảm ứng xung quanh.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các hiện tượng đời sống (Cột A) với bản chất lực tương tác tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Khả năng bám dính của bàn chân thạch sùng (tắc kè) trên tường kính nhẵn ➔ A. Hàng triệu vi sợi tiếp xúc tạo tương tác van der Waals cực đại.", "1. Khả năng bám dính của bàn chân thạch sùng (tắc kè) trên tường kính nhẵn ➔ B. Liên kết hydrogen liên phân tử bền vững giữa các phân tử H₂O.", "1. Khả năng bám dính của bàn chân thạch sùng (tắc kè) trên tường kính nhẵn ➔ C. Hình thành liên kết hydrogen giữa phân tử ethanol và phân tử nước.", "1. Khả năng bám dính của bàn chân thạch sùng (tắc kè) trên tường kính nhẵn ➔ D. Khối lượng phân tử và bán kính tăng làm tương tác van der Waals tăng."], "ans": 0, "exp": "• Chân thạch sùng: van der Waals.<br>• Nhiệt độ sôi nước: Liên kết H.<br>• C₂H₅OH tan: Liên kết H với nước.<br>• Khí hiếm sôi: van der Waals tăng theo khối lượng.", "svgGraph": null}, {"q": "Trong các chất sau, chất nào KHÔNG CÓ liên kết hydrogen liên phân tử?", "opts": ["Methane (CH₄)", "Nước (H₂O)", "Ammonia (NH₃)", "Hydrogen fluoride (HF)"], "ans": 0, "exp": "• Trong CH₄, nguyên tử C không có độ âm điện đủ lớn (độ âm điện 2,55) và không còn cặp electron tự do, do đó không tạo được liên kết hydrogen.<br>• H₂O (O-H), NH₃ (N-H), HF (F-H) đều tạo được liên kết hydrogen mạnh.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét xu hướng biến đổi nhiệt độ sôi của các halogen đơn chất: F₂, Cl₂, Br₂, I₂:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khối lượng riêng của nước đá nhỏ hơn nước lỏng (nước đá nổi trên mặt nước lỏng) là do nguyên nhân nào sau đây?", "opts": ["Khi đóng băng, các liên kết hydrogen sắp xếp định hướng tạo cấu trúc tinh thể rỗng mở rộng thể tích.", "Nước đá có chứa các bọt khí bên trong.", "Nước lỏng nặng hơn do bay hơi bớt phân tử nhẹ.", "Liên kết cộng hóa trị O–H bị kéo dài ra."], "ans": 0, "exp": "• Trong nước đá, mỗi phân tử H₂O liên kết hydrogen với 4 phân tử H₂O khác tạo cấu trúc tinh thể tứ diện mở rỗng, làm thể tích tăng khoảng 9% so với thể lỏng ⇒ khối lượng riêng nhỏ hơn nước lỏng nên nước đá nổi.<br>• Đây là hiện tượng dị thường của nước có ý nghĩa sinh học to lớn đối với sinh vật dưới nước vào mùa đông.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Liên kết hydrogen được tạo thành giữa nguyên tử [ ... ] mang một phần điện tích dương với nguyên tử [ ... ] có độ âm điện lớn và còn cặp electron chưa chia. Tương tác van der Waals tăng khi [ ... ] phân tử và kích thước phân tử [ ... ].", "opts": ["hydrogen — N, O, F — khối lượng — tăng", "tăng — khối lượng — N, O, F — hydrogen", "N, O, F — khối lượng — tăng — hydrogen", "khối lượng — tăng — hydrogen — N, O, F"], "ans": 0, "exp": "• Liên kết H: H linh động với N, O, F.<br>• van der Waals tăng theo khối lượng và kích thước phân tử.", "svgGraph": null}, {"q": "Sắp xếp theo thứ tự độ bền liên kết giảm dần:", "opts": ["Liên kết cộng hóa trị > Liên kết hydrogen > Tương tác van der Waals", "Tương tác van der Waals > Liên kết hydrogen > Liên kết cộng hóa trị", "Liên kết hydrogen > Liên kết cộng hóa trị > Tương tác van der Waals", "Liên kết cộng hóa trị > Tương tác van der Waals > Liên kết hydrogen"], "ans": 0, "exp": "• Năng lượng liên kết: CHT (vài trăm kJ/mol) >> Liên kết hydrogen (10 - 40 kJ/mol) > Tương tác van der Waals (vài kJ/mol).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "13": [{"q": "Dãy chất nào sau đây gồm toàn các chất chỉ chứa liên kết cộng hóa trị?", "opts": ["H₂O, CO₂, NH₃, CH₄", "NaCl, H₂O, CO₂, HCl", "MgO, CaCl₂, K₂O, Al₂O₃", "NH₄Cl, H₂SO₄, NaNO₃, KOH"], "ans": 0, "exp": "• H₂O, CO₂, NH₃, CH₄ đều tạo bởi các phi kim với phi kim ⇒ chỉ chứa liên kết cộng hóa trị.<br>• NaCl, MgO, NH₄Cl... chứa liên kết ion.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Số lượng liên kết σ và liên kết π trong phân tử acetylene (C₂H₂, H–C≡C–H) lần lượt là:", "opts": ["3 liên kết σ và 2 liên kết π", "2 liên kết σ và 3 liên kết π", "4 liên kết σ và 1 liên kết π", "5 liên kết σ và 0 liên kết π"], "ans": 0, "exp": "• 2 liên kết đơn C–H: 2 liên kết σ.<br>• 1 liên kết ba C≡C: 1 liên kết σ và 2 liên kết π.<br>• Tổng: 2 + 1 = 3 liên kết σ và 2 liên kết π.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu tổng kết về liên kết hóa học:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Biết hiệu độ âm điện Δχ của các phân tử: Cl₂ (0,0); HCl (0,96); NaCl (2,23). Loại liên kết trong ba chất lần lượt là:", "opts": ["CHT không cực, CHT có cực, liên kết ion", "Liên kết ion, CHT có cực, CHT không cực", "CHT có cực, CHT không cực, liên kết ion", "CHT không cực, liên kết ion, CHT có cực"], "ans": 0, "exp": "• Cl₂: Δχ = 0 < 0,4 ⇒ CHT không cực.<br>• HCl: 0,4 ≤ Δχ = 0,96 < 1,7 ⇒ CHT có cực.<br>• NaCl: Δχ = 2,23 ≥ 1,7 ⇒ Liên kết ion.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép chất (Cột A) với loại lực liên kết / tương tác chủ yếu (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Muối ăn NaCl ➔ A. Liên kết ion.", "1. Muối ăn NaCl ➔ B. Liên kết cộng hóa trị ba (1σ, 2π).", "1. Muối ăn NaCl ➔ C. Liên kết hydrogen liên phân tử.", "1. Muối ăn NaCl ➔ D. Tương tác van der Waals."], "ans": 0, "exp": "• NaCl: ion.<br>• N₂: CHT ba.<br>• H₂O: liên kết H.<br>• Ar: van der Waals.", "svgGraph": null}, {"q": "Phân tử nào sau đây có moment lưỡng cực bằng 0 (phân tử không phân cực) do có cấu tạo đối xứng?", "opts": ["Methane (CH₄, hình tứ diện đều)", "Ammonia (NH₃, hình chóp tam giác)", "Nước (H₂O, hình góc)", "Hydrochloric acid (HCl, phân tử thẳng 2 nguyên tử khác nhau)"], "ans": 0, "exp": "• CH₄ có 4 liên kết C-H phân cực hướng về 4 đỉnh của tứ diện đều, tổng vector moment lưỡng cực triệt tiêu hoàn toàn bằng 0 ⇒ phân tử không phân cực.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các hợp chất của kim loại nhóm IA và IIA với phi kim nhóm VIIA:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Liên kết nào sau đây bị đứt gãy khi đun sôi nước lỏng chuyển thành hơi nước?", "opts": ["Liên kết hydrogen liên phân tử giữa các phân tử nước.", "Liên kết cộng hóa trị O–H trong phân tử nước.", "Liên kết ion giữa H⁺ và OH⁻.", "Cả liên kết O–H và liên kết hydrogen."], "ans": 0, "exp": "• Sự sôi và bay hơi là hiện tượng chuyển thể vật lí, chỉ làm đứt gãy các liên kết hydrogen liên phân tử yếu để giải phóng các phân tử H₂O tự do.<br>• Các liên kết cộng hóa trị O-H trong phân tử nước vẫn hoàn toàn nguyên vẹn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Phân tử N₂ có liên kết ba gồm [ ... ] liên kết σ và [ ... ] liên kết π. Năng lượng liên kết của N₂ rất lớn (%945 kJ/mol) giải thích tính trơ [ ... ] của nitrogen ở nhiệt độ [ ... ].", "opts": ["1 — 2 — hóa học — thường", "thường — hóa học — 2 — 1", "2 — hóa học — thường — 1", "hóa học — thường — 1 — 2"], "ans": 0, "exp": "• 1 sigma, 2 pi.<br>• Trơ hóa học ở nhiệt độ thường.", "svgGraph": null}, {"q": "Trong các chất sau: HF, HCl, HBr, HI. Chất có nhiệt độ sôi cao nhất là:", "opts": ["HF (do có liên kết hydrogen liên phân tử bền nhất)", "HI", "HBr", "HCl"], "ans": 0, "exp": "• Nhờ độ âm điện của Fluorine lớn nhất tạo liên kết hydrogen F–H···F rất mạnh, HF sôi ở 19,5 °C.<br>• Các acid còn lại không có liên kết hydrogen, nhiệt độ sôi tăng dần theo van der Waals: HCl (-85 °C) < HBr (-66 °C) < HI (-35 °C) < HF (19,5 °C).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "14": [{"q": "Phản ứng oxi hóa – khử là phản ứng hóa học trong đó có sự thay đổi đại lượng nào sau đây?", "opts": ["Số oxi hóa của một số nguyên tố hóa học (có sự chuyển dịch electron).", "Chỉ thay đổi màu sắc của dung dịch.", "Chỉ có sự thay đổi trạng thái tập hợp của các chất.", "Chỉ có sự phân li của các chất thành ion."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 10:</b> Phản ứng oxi hóa – khử là phản ứng hóa học có sự chuyển electron giữa các chất phản ứng, hay phản ứng có sự thay đổi số oxi hóa của một số nguyên tử nguyên tố.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Trong một phản ứng oxi hóa – khử, chất khử (chất bị oxi hóa) là chất có đặc điểm gì?", "opts": ["Chất nhường electron, có số oxi hóa tăng sau phản ứng ('Khử cho').", "Chất nhận electron, có số oxi hóa giảm sau phản ứng ('O nhận').", "Chất không thay đổi số oxi hóa.", "Chỉ là chất đóng vai trò môi trường."], "ans": 0, "exp": "• Quy tắc ghi nhớ sư phạm: <i>'Khử cho – O nhận'</i>:<br>• Chất khử: nhường e -> số oxi hóa tăng lên sau phản ứng.<br>• Chất oxi hóa: nhận e -> số oxi hóa giảm xuống sau phản ứng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho phản ứng hóa học: Zn + CuSO₄ -> ZnSO₄ + Cu:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Số oxi hóa của nguyên tố Manganese (Mn) trong hợp chất KMnO₄ (thuốc tím) là bao nhiêu?", "opts": ["+7", "+6", "+4", "+2"], "ans": 0, "exp": "• Trong KMnO₄: K có số oxi hóa +1, O có số oxi hóa -2.<br>• Ta có: (+1)·1 + x·1 + (-2)·4 = 0 ⇒ 1 + x - 8 = 0 ⇒ x = +7.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các quá trình (Cột A) với tên gọi tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Fe -> Fe³⁺ + 3e ➔ A. Quá trình oxi hóa sắt (sự oxi hóa).", "1. Fe -> Fe³⁺ + 3e ➔ B. Quá trình khử chlorine (sự khử).", "1. Fe -> Fe³⁺ + 3e ➔ C. Quá trình khử ion đồng (sự khử).", "1. Fe -> Fe³⁺ + 3e ➔ D. Quá trình khử ion hydrogen (sự khử)."], "ans": 0, "exp": "• Quá trình nhường e = Quá trình oxi hóa.<br>• Quá trình nhận e = Quá trình khử.", "svgGraph": null}, {"q": "Cho phương trình phản ứng cân bằng: aFe + bHNO₃ -> cFe(NO₃)₃ + dNO↑ + eH₂O. Tỉ lệ hệ số nguyên tối giản a : d là:", "opts": ["1 : 1", "1 : 2", "2 : 1", "3 : 1"], "ans": 0, "exp": "• Thăng bằng electron:<br>  Fe⁰ -> Fe⁺³ + 3e  (x1)<br>  N⁺⁵ + 3e -> N⁺² (NO) (x1)<br>• Phương trình cân bằng: Fe + 4HNO₃ -> Fe(NO₃)₃ + NO + 2H₂O.<br>• Hệ số a = 1, d = 1 ⇒ Tỉ lệ a : d = 1 : 1.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng sau có phải là phản ứng oxi hóa – khử hay không:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trong phản ứng: Cl₂ + 2NaOH -> NaCl + NaClO + H₂O. Vai trò của Cl₂ là:", "opts": ["Vừa là chất oxi hóa, vừa là chất khử (phản ứng tự oxi hóa – khử).", "Chỉ là chất oxi hóa.", "Chỉ là chất khử.", "Không phải chất oxi hóa cũng không phải chất khử."], "ans": 0, "exp": "• Trong phản ứng trên, nguyên tử Cl⁰ một phần giảm xuống Cl⁻¹ (trong NaCl) -> đóng vai trò chất oxi hóa.<br>• Một phần Cl⁰ tăng lên Cl⁺¹ (trong NaClO) -> đóng vai trò chất khử.<br>• Đây là phản ứng tự oxi hóa – khử (disproportionation).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống quy tắc cân bằng thăng bằng electron:<br>Trong phản ứng oxi hóa – khử, tổng số electron do chất khử [ ... ] phải bằng tổng số electron mà chất oxi hóa [ ... ]. Chất khử có số oxi hóa [ ... ], chất oxi hóa có số oxi hóa [ ... ].", "opts": ["nhường — nhận — tăng — giảm", "giảm — tăng — nhận — nhường", "nhận — tăng — giảm — nhường", "tăng — giảm — nhường — nhận"], "ans": 0, "exp": "• Định luật bảo toàn electron: Tổng e cho = Tổng e nhận.<br>• Khử tăng, O giảm.", "svgGraph": null}, {"q": "Cho phản ứng: 3Cu + 8HNO₃ -> 3Cu(NO₃)₂ + 2NO↑ + 4H₂O. Số phân tử HNO₃ đóng vai trò là chất oxi hóa trong phản ứng trên là:", "opts": ["2 phân tử", "8 phân tử", "6 phân tử", "3 phân tử"], "ans": 0, "exp": "• Trong 8 phân tử HNO₃ phản ứng:<br>• 2 phân tử bị khử thành NO (N⁺⁵ + 3e -> N⁺²) đóng vai trò chất oxi hóa.<br>• 6 phân tử HNO₃ giữ nguyên số oxi hóa N⁺⁵ trong muối Cu(NO₃)₂ đóng vai trò tạo môi trường.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "15": [{"q": "Phản ứng cháy của xăng dầu (hydrocarbon) trong động cơ xe máy, ô tô là một ứng dụng quan trọng của phản ứng nào?", "opts": ["Phản ứng oxi hóa – khử tỏa nhiều nhiệt sinh công.", "Phản ứng trung hòa acid - base.", "Phản ứng trao đổi ion tạo kết tủa.", "Phản ứng phân hủy thu nhiệt."], "ans": 0, "exp": "• Phản ứng đốt cháy: C_xH_y + (x + y/4)O₂ -> xCO₂ + (y/2)H₂O + Q.<br>• Đây là phản ứng oxi hóa - khử tỏa năng lượng lớn làm khí dãn nở đẩy piston sinh công cơ học.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hiện tượng sắt (iron) trong không khí ẩm bị gỉ sét tạo thành gỉ sắt Fe₂O₃·nH₂O là hiện tượng gì?", "opts": ["Sự ăn mòn kim loại (quá trình oxi hóa – khử tự nhiên phá hủy kim loại).", "Hiện tượng quang hợp.", "Hiện tượng lắng đọng cơ học.", "Sự bay hơi của kim loại."], "ans": 0, "exp": "• Sắt bị oxygen và hơi nước oxi hóa chậm thành các oxide và hydroxide sắt (gỉ sét).<br>• Đây là quá trình ăn mòn hóa học và điện hóa gây thiệt hại lớn cho các công trình, cầu cống, tàu bè.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét vai trò của các phản ứng oxi hóa – khử trong đời sống và sản xuất:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Biện pháp nào sau đây KHÔNG PHẢI là phương pháp bảo vệ kim loại khỏi sự ăn mòn điện hóa và oxi hóa?", "opts": ["Ngâm kim loại trong dung dịch muối ăn hoặc acid.", "Sơn phủ, mạ kim loại bền (như kẽm, crom, niken) lên bề mặt kim loại.", "Dùng phương pháp bảo vệ điện hóa (gắn khối kẽm vào vỏ tàu biển bằng thép).", "Bôi dầu mỡ lên các chi tiết máy bằng sắt thép sau khi sử dụng."], "ans": 0, "exp": "• Ngâm trong dung dịch chất điện li (muối, acid) làm tốc độ ăn mòn kim loại tăng vọt gấp nhiều lần.<br>• Các biện pháp còn lại là phương pháp phủ bề mặt và bảo vệ catot (điện hóa).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các ứng dụng thực tiễn (Cột A) với phản ứng oxi hóa – khử tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Luyện gang trong lò cao ➔ A. Khí CO khử quặng hematite: Fe₂O₃ + 3CO -> 2Fe + 3CO₂.", "1. Luyện gang trong lò cao ➔ B. Khí Cl₂ hoặc NaClO oxi hóa tiêu diệt vi khuẩn, mầm bệnh.", "1. Luyện gang trong lò cao ➔ C. Carbon bị oxi hóa: C + O₂ -> CO₂ + Q.", "1. Luyện gang trong lò cao ➔ D. Nhôm khử oxit sắt: 2Al + Fe₂O₃ -> Al₂O₃ + 2Fe."], "ans": 0, "exp": "• Các ứng dụng kinh điển của phản ứng oxi hóa khử trong công nghiệp.", "svgGraph": null}, {"q": "Tại sao người ta gắn các tấm kim loại Kẽm (Zinc) vào phần vỏ tàu biển bằng thép tiếp xúc với nước biển?", "opts": ["Vì kẽm có tính khử mạnh hơn sắt nên kẽm bị ăn mòn trước, bảo vệ vỏ thép của tàu (phương pháp bảo vệ điện hóa).", "Vì kẽm làm tăng độ bóng đẹp cho tàu.", "Vì kẽm làm giảm ma sát của nước biển với thân tàu.", "Vì kẽm ngăn cản sự phát triển của rong rêu."], "ans": 0, "exp": "• Khi tạo cặp điện cực Zn–Fe ngâm trong nước biển (chất điện li): Zn có thế điện cực âm hơn (tính khử mạnh hơn) đóng vai trò anode bị ăn mòn tan ra (Zn -> Zn²⁺ + 2e), còn Fe đóng vai trò catode được bảo vệ nguyên vẹn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các hiện tượng thực tiễn liên quan đến phản ứng oxi hóa – khử:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chất nào sau đây là chất chống oxi hóa (antioxidant) phổ biến có trong rau củ quả giúp bảo vệ cơ thể khỏi các gốc tự do có hại?", "opts": ["Vitamin C (ascorbic acid)", "Sulfuric acid", "Sodium chloride", "Potassium permanganate"], "ans": 0, "exp": "• Vitamin C, vitamin E, beta-carotene là các chất chống oxi hóa mạnh, chúng dễ dàng nhường electron cho các gốc tự do để vô hiệu hóa tác hại của gốc tự do đối với tế bào.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Phản ứng oxi hóa – khử có mặt khắp nơi trong đời sống và sản xuất: từ quá trình [ ... ] của sinh vật, sự [ ... ] nhiên liệu cung cấp năng lượng, sự [ ... ] kim loại gây tổn thất kinh tế cho đến ngành luyện kim thu hồi các [ ... ] quý giá.", "opts": ["hô hấp — cháy — ăn mòn — kim loại", "kim loại — ăn mòn — cháy — hô hấp", "cháy — ăn mòn — kim loại — hô hấp", "ăn mòn — kim loại — hô hấp — cháy"], "ans": 0, "exp": "• Hô hấp, cháy, ăn mòn, kim loại.", "svgGraph": null}, {"q": "Khí gas dùng để đun nấu hàng ngày (LPG) có thành phần chính là:", "opts": ["Propane (C₃H₈) và Butane (C₄H₁₀)", "Methane (CH₄) và Carbon monoxide (CO)", "Hydrogen (H₂) và Oxygen (O₂)", "Acetylene (C₂H₂) và Ethylene (C₂H₄)"], "ans": 0, "exp": "• LPG (Liquefied Petroleum Gas) gồm propane C₃H₈ và butane C₄H₁₀ được hóa lỏng dưới áp suất.<br>• Khi cháy tỏa lượng nhiệt rất lớn phục vụ đun nấu gia đình và công nghiệp.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "16": [{"q": "Cho phản ứng: 2KMnO₄ + 16HCl -> 2KCl + 2MnCl₂ + 5Cl₂↑ + 8H₂O. Tỉ lệ giữa số phân tử HCl đóng vai trò chất khử và số phân tử HCl tham gia phản ứng là:", "opts": ["10 : 16 (tức 5 : 8)", "16 : 16", "2 : 16", "5 : 16"], "ans": 0, "exp": "• Trong 16 phân tử HCl tham gia:<br>• Tạo 5 phân tử Cl₂ (tương ứng 10 nguyên tử Cl⁻ bị oxi hóa thành Cl₂⁰) ⇒ có 10 phân tử HCl đóng vai trò chất khử.<br>• 6 phân tử HCl còn lại tạo muối KCl và MnCl₂ giữ nguyên số oxi hóa Cl⁻ đóng vai trò tạo môi trường.<br>• Tỉ lệ = 10 : 16 = 5 : 8.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Trong các chất và ion sau: Fe²⁺, Fe³⁺, SO₂, Cl⁻. Chất hoặc ion vừa có tính oxi hóa vừa có tính khử là:", "opts": ["Fe²⁺ và SO₂", "Fe³⁺ và Cl⁻", "Chỉ có Fe²⁺", "Chỉ có SO₂"], "ans": 0, "exp": "• Fe²⁺ có số oxi hóa trung gian giữa 0 và +3: có thể tăng lên Fe³⁺ (tính khử) hoặc giảm xuống Fe⁰ (tính oxi hóa).<br>• SO₂ có S (+4) trung gian giữa -2, 0 và +6: có thể tăng lên S⁺⁶ (tính khử) hoặc giảm xuống S⁰ (tính oxi hóa).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng nhiệt nhôm: 2Al + Fe₂O₃ --t°--> Al₂O₃ + 2Fe:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Cho phản ứng: aFe₃O₄ + bHNO₃ -> cFe(NO₃)₃ + dNO↑ + eH₂O. Tổng hệ số nguyên tối giản (a + b + c + d + e) là:", "opts": ["55", "36", "48", "28"], "ans": 0, "exp": "• Quá trình oxi hóa: 3Fe⁺⁸/³ -> 3Fe⁺³ + 1e  (x3)<br>• Quá trình khử: N⁺⁵ + 3e -> N⁺² (NO)  (x1)<br>• Phương trình cân bằng:<br>  3Fe₃O₄ + 28HNO₃ -> 9Fe(NO₃)₃ + NO + 14H₂O.<br>• Tổng hệ số: a + b + c + d + e = 3 + 28 + 9 + 1 + 14 = 55.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các phản ứng (Cột A) với loại phản ứng oxi hóa – khử tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Cu + 2AgNO₃ -> Cu(NO₃)₂ + 2Ag ➔ A. Phản ứng oxi hóa – khử giữa các phân tử.", "1. Cu + 2AgNO₃ -> Cu(NO₃)₂ + 2Ag ➔ B. Phản ứng oxi hóa – khử nội phân tử (Cl và O trong cùng phân tử).", "1. Cu + 2AgNO₃ -> Cu(NO₃)₂ + 2Ag ➔ C. Phản ứng tự oxi hóa – tự khử (S vừa tăng vừa giảm).", "1. Cu + 2AgNO₃ -> Cu(NO₃)₂ + 2Ag ➔ D. Phản ứng trao đổi ion, không phải oxi hóa – khử."], "ans": 0, "exp": "• Phân loại các phản ứng oxi hóa khử và phản ứng trao đổi.", "svgGraph": null}, {"q": "Xác định số oxi hóa của nguyên tố Chromium (Cr) trong ion dichromate (Cr₂O₇²⁻):", "opts": ["+6", "+3", "+7", "+12"], "ans": 0, "exp": "• Trong ion đa nguyên tử Cr₂O₇²⁻: tổng số oxi hóa bằng điện tích của ion (-2).<br>• 2·x + 7·(-2) = -2 ⇒ 2x - 14 = -2 ⇒ 2x = 12 ⇒ x = +6.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định sau về phản ứng oxi hóa khử trong dung dịch:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khi cho khí H₂S lội qua dung dịch SO₂ thấy xuất hiện váng màu vàng. Phản ứng xảy ra là: 2H₂S + SO₂ -> 3S↓ + 2H₂O. Tỉ lệ giữa số phân tử chất khử và chất oxi hóa là:", "opts": ["2 : 1", "1 : 2", "3 : 1", "1 : 1"], "ans": 0, "exp": "• H₂S: S mang số oxi hóa -2 tăng lên 0 ⇒ H₂S là chất khử (hệ số 2).<br>• SO₂: S mang số oxi hóa +4 giảm xuống 0 ⇒ SO₂ là chất oxi hóa (hệ số 1).<br>• Tỉ lệ chất khử : chất oxi hóa = 2 : 1.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Phản ứng oxi hóa – khử gồm hai quá trình luôn diễn ra [ ... ]: chất khử nhường electron trong quá trình [ ... ], còn chất oxi hóa thu nhận electron trong quá trình [ ... ]. Dấu hiệu đặc trưng nhất là sự thay đổi [ ... ] của các nguyên tố.", "opts": ["đồng thời — oxi hóa — khử — số oxi hóa", "số oxi hóa — khử — oxi hóa — đồng thời", "oxi hóa — khử — số oxi hóa — đồng thời", "khử — số oxi hóa — đồng thời — oxi hóa"], "ans": 0, "exp": "• Diễn ra đồng thời.<br>• Quá trình oxi hóa, quá trình khử.<br>• Thay đổi số oxi hóa.", "svgGraph": null}, {"q": "Dung dịch nào sau đây dùng để nhận biết khí SO₂ do làm mất màu tím đặc trưng của dung dịch?", "opts": ["Dung dịch thuốc tím KMnO₄ trong môi trường H₂SO₄ loãng", "Dung dịch NaCl", "Dung dịch NaOH không màu", "Dung dịch CuSO₄ màu xanh"], "ans": 0, "exp": "• Khí SO₂ có tính khử mạnh, khử ion MnO₄⁻ (+7, màu tím) thành ion Mn²⁺ (không màu):<br>5SO₂ + 2KMnO₄ + 2H₂O -> K₂SO₄ + 2MnSO₄ + 2H₂SO₄.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "17": [{"q": "Phản ứng tỏa nhiệt là phản ứng hóa học có đặc điểm nào sau đây?", "opts": ["Giải phóng năng lượng dưới dạng nhiệt ra môi trường xung quanh, biến thiên enthalpy ΔrH°₂₉₈ < 0.", "Hấp thụ năng lượng nhiệt từ môi trường, biến thiên enthalpy ΔrH°₂₉₈ > 0.", "Biến thiên enthalpy ΔrH°₂₉₈ = 0.", "Làm nhiệt độ của môi trường xung quanh giảm đi."], "ans": 0, "exp": "• <b>Kiến thức SGK Hóa 10:</b><br>• Phản ứng tỏa nhiệt (exothermic): giải phóng nhiệt lượng, làm môi trường xung quanh nóng lên, ΔrH°₂₉₈ < 0.<br>• Phản ứng thu nhiệt (endothermic): hấp thụ nhiệt lượng, làm môi trường xung quanh lạnh đi, ΔrH°₂₉₈ > 0.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điều kiện chuẩn trong nhiệt hóa học ứng với nhiệt độ và áp suất nào?", "opts": ["298 K (25 °C) và áp suất 1 bar (10⁵ Pa).", "273 K (0 °C) và áp suất 1 atm.", "0 K và áp suất 1 bar.", "298 K và áp suất 1 atm."], "ans": 0, "exp": "• Theo IUPAC và SGK GDPT 2018: Điều kiện chuẩn ứng với áp suất 1 bar (đối với chất khí), nồng độ 1 mol/L (đối với dung dịch) và thường chọn nhiệt độ 298 K (25 °C). Kí hiệu kèm chỉ số ° (hoặc ⦵).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các hiện tượng sau thuộc loại tỏa nhiệt hay thu nhiệt:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nhiệt tạo thành chuẩn (Enthalpy tạo thành chuẩn, kí hiệu ΔfH°₂₉₈) của một chất là lượng nhiệt kèm theo phản ứng tạo thành 1 mol chất đó từ:", "opts": ["Các đơn chất bền nhất ở điều kiện chuẩn.", "Các hợp chất đơn giản nhất ở điều kiện chuẩn.", "Các nguyên tử ở thể khí.", "Các ion tương ứng trong dung dịch."], "ans": 0, "exp": "• <b>Định nghĩa:</b> Nhiệt tạo thành chuẩn ΔfH°₂₉₈ là biến thiên enthalpy của phản ứng tạo thành 1 mol chất từ các đơn chất ở dạng bền vững nhất ở điều kiện chuẩn (298 K, 1 bar).<br>• Nhiệt tạo thành chuẩn của các đơn chất bền nhất bằng 0 (ví dụ ΔfH°₂₉₈ của O₂(g), N₂(g), C(graphite) = 0).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các quá trình (Cột A) với dấu của biến thiên enthalpy tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Đốt cháy khí methane: CH₄ + 2O₂ -> CO₂ + 2H₂O ➔ A. ΔrH°₂₉₈ < 0 (Phản ứng tỏa nhiệt mạnh).", "1. Đốt cháy khí methane: CH₄ + 2O₂ -> CO₂ + 2H₂O ➔ B. ΔrH°₂₉₈ > 0 (Phản ứng thu nhiệt).", "1. Đốt cháy khí methane: CH₄ + 2O₂ -> CO₂ + 2H₂O ➔ C. ΔfH°₂₉₈ = 0 kJ/mol (Quy ước chuẩn).", "1. Đốt cháy khí methane: CH₄ + 2O₂ -> CO₂ + 2H₂O ➔ D. ΔrH°₂₉₈ < 0 (Tỏa nhiệt dữ dội làm nước sôi)."], "ans": 0, "exp": "• Tỏa nhiệt: ΔH < 0.<br>• Thu nhiệt: ΔH > 0.<br>• Đơn chất bền: ΔfH° = 0.", "svgGraph": null}, {"q": "Cho phương trình nhiệt hóa học sau:<br>N₂(g) + 3H₂(g) ⇌ 2NH₃(g)   ΔrH°₂₉₈ = -92,22 kJ.<br>Phản ứng tổng hợp ammonia từ N₂ và H₂ là phản ứng:", "opts": ["Tỏa nhiệt, khi tạo thành 2 mol NH₃ giải phóng nhiệt lượng 92,22 kJ.", "Thu nhiệt, khi tạo thành 2 mol NH₃ cần hấp thụ nhiệt lượng 92,22 kJ.", "Tỏa nhiệt, khi tạo thành 1 mol NH₃ giải phóng nhiệt lượng 92,22 kJ.", "Không kèm theo sự thay đổi năng lượng."], "ans": 0, "exp": "• Vì ΔrH°₂₉₈ = -92,22 kJ < 0 nên phản ứng là phản ứng tỏa nhiệt.<br>• Theo phương trình, hệ số của NH₃ là 2, nên khi tạo thành 2 mol NH₃ sẽ giải phóng ra môi trường một nhiệt lượng bằng 92,22 kJ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về phương trình nhiệt hóa học:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Một túi chườm lạnh y tế dùng sơ cứu chấn thương thể thao thường chứa chất nào sau đây hòa tan thu nhiệt mạnh làm giảm đau tức thì?", "opts": ["Ammonium nitrate (NH₄NO₃) hòa tan trong nước thu nhiệt mạnh.", "Sodium hydroxide (NaOH) hòa tan tỏa nhiệt.", "Calcium chloride (CaCl₂) hòa tan tỏa nhiệt.", "Muối ăn (NaCl)."], "ans": 0, "exp": "• NH₄NO₃ khi hòa tan trong nước có quá trình phá vỡ mạng tinh thể thu nhiệt rất lớn, làm nhiệt độ dung dịch giảm sâu xuống gần 0 °C, rất thích hợp làm túi chườm lạnh y tế sơ cứu bong gân, chấn thương.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Phản ứng tỏa nhiệt là phản ứng [ ... ] nhiệt lượng ra môi trường, có biến thiên enthalpy mang dấu [ ... ]. Phản ứng thu nhiệt là phản ứng [ ... ] nhiệt từ môi trường, có biến thiên enthalpy mang dấu [ ... ].", "opts": ["giải phóng — âm (< 0) — hấp thụ — dương (> 0)", "dương (> 0) — hấp thụ — âm (< 0) — giải phóng", "âm (< 0) — hấp thụ — dương (> 0) — giải phóng", "hấp thụ — dương (> 0) — giải phóng — âm (< 0)"], "ans": 0, "exp": "• Tỏa nhiệt: giải phóng nhiệt, dấu âm.<br>• Thu nhiệt: hấp thụ nhiệt, dấu dương.", "svgGraph": null}, {"q": "Biết nhiệt tạo thành chuẩn của H₂O(l) là -285,8 kJ/mol. Khi đốt cháy hoàn toàn 2 g khí H₂(g) trong khí O₂ dư tạo nước lỏng thì nhiệt lượng tỏa ra là bao nhiêu?", "opts": ["285,8 kJ", "571,6 kJ", "142,9 kJ", "28,58 kJ"], "ans": 0, "exp": "• Số mol H₂: n = 2 / 2 = 1 mol.<br>• Phản ứng: H₂(g) + 1/2 O₂(g) -> H₂O(l)   ΔrH°₂₉₈ = ΔfH°₂₉₈[H₂O(l)] = -285,8 kJ.<br>• Đốt cháy 1 mol H₂ tỏa ra đúng 285,8 kJ nhiệt lượng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "18": [{"q": "Biến thiên enthalpy chuẩn của phản ứng ΔrH°₂₉₈ được tính theo nhiệt tạo thành chuẩn của các chất theo công thức nào?", "opts": ["ΔrH°₂₉₈ = ∑ ΔfH°₂₉₈ (sản phẩm) - ∑ ΔfH°₂₉₈ (chất đầu)", "ΔrH°₂₉₈ = ∑ ΔfH°₂₉₈ (chất đầu) - ∑ ΔfH°₂₉₈ (sản phẩm)", "ΔrH°₂₉₈ = ∑ Eb (sản phẩm) - ∑ Eb (chất đầu)", "ΔrH°₂₉₈ = [∑ ΔfH°₂₉₈ (sản phẩm)] / [∑ ΔfH°₂₉₈ (chất đầu)]"], "ans": 0, "exp": "• <b>Công thức SGK Hóa 10:</b><br>• Theo nhiệt tạo thành: ΔrH°₂₉₈ = ∑ n·ΔfH°₂₉₈(sp) - ∑ m·ΔfH°₂₉₈(cđ).<br>• Theo năng lượng liên kết: ΔrH°₂₉₈ = ∑ Eb(cđ) - ∑ Eb(sp).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho phản ứng: CH₄(g) + 2O₂(g) -> CO₂(g) + 2H₂O(l). Biết ΔfH°₂₉₈ của CH₄ = -74,8 kJ/mol; CO₂ = -393,5 kJ/mol; H₂O = -285,8 kJ/mol. Biến thiên enthalpy chuẩn của phản ứng là:", "opts": ["-890,3 kJ", "-580,5 kJ", "+890,3 kJ", "-965,1 kJ"], "ans": 0, "exp": "• Áp dụng công thức:<br>ΔrH°₂₉₈ = [1·(-393,5) + 2·(-285,8)] - [1·(-74,8) + 2·0]<br>= (-393,5 - 571,6) - (-74,8) = -965,1 + 74,8 = -890,3 kJ.<br>• Phản ứng tỏa lượng nhiệt khổng lồ 890,3 kJ trên 1 mol CH₄.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về tính toán nhiệt phản ứng theo năng lượng liên kết (Eb):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Cho năng lượng liên kết: Eb(H–H) = 436 kJ/mol; Eb(Cl–Cl) = 243 kJ/mol; Eb(H–Cl) = 432 kJ/mol. Biến thiên enthalpy của phản ứng: H₂(g) + Cl₂(g) -> 2HCl(g) là:", "opts": ["-185 kJ", "+185 kJ", "-92,5 kJ", "-247 kJ"], "ans": 0, "exp": "• Phá vỡ liên kết ở chất đầu: 1 liên kết H-H và 1 liên kết Cl-Cl: Eb(cđ) = 436 + 243 = 679 kJ.<br>• Hình thành liên kết ở sản phẩm: 2 liên kết H-Cl: Eb(sp) = 2·432 = 864 kJ.<br>• ΔrH°₂₉₈ = Eb(cđ) - Eb(sp) = 679 - 864 = -185 kJ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các đại lượng (Cột A) với đơn vị đo tương ứng trong nhiệt hóa học (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Biến thiên enthalpy của phản ứng (ΔrH°₂₉₈) ➔ A. kJ (hoặc kcal).", "1. Biến thiên enthalpy của phản ứng (ΔrH°₂₉₈) ➔ B. kJ/mol.", "1. Biến thiên enthalpy của phản ứng (ΔrH°₂₉₈) ➔ C. kJ/mol.", "1. Biến thiên enthalpy của phản ứng (ΔrH°₂₉₈) ➔ D. J/(g·K) hoặc J/(g·°C)."], "ans": 0, "exp": "• ΔrH°: kJ.<br>• ΔfH°: kJ/mol.<br>• Eb: kJ/mol.<br>• Nhiệt dung riêng: J/(g·°C).", "svgGraph": null}, {"q": "Cho phản ứng: C(s) + H₂O(g) -> CO(g) + H₂(g)   ΔrH°₂₉₈ = +131,3 kJ. Phản ứng này là:", "opts": ["Phản ứng thu nhiệt, cần cung cấp nhiệt lượng 131,3 kJ để chuyển hóa hoàn toàn 1 mol C.", "Phản ứng tỏa nhiệt, giải phóng 131,3 kJ.", "Phản ứng tự diễn ra mãnh liệt ở điều kiện phòng mà không cần đốt nóng.", "Phản ứng không có sự trao đổi nhiệt lượng."], "ans": 0, "exp": "• ΔrH°₂₉₈ = +131,3 kJ > 0 ⇒ Phản ứng thu nhiệt, muốn phản ứng xảy ra ta phải duy trì nung nóng ở nhiệt độ cao (khoảng 1000 °C, phản ứng sản xuất khí than ướt).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét ý nghĩa thực tiễn của năng lượng hóa học đối với việc lựa chọn nhiên liệu:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Biết nhiệt tạo thành chuẩn của CO(g) là -110,5 kJ/mol và CO₂(g) là -393,5 kJ/mol. Biến thiên enthalpy của phản ứng: CO(g) + 1/2 O₂(g) -> CO₂(g) là:", "opts": ["-283,0 kJ", "-504,0 kJ", "+283,0 kJ", "-141,5 kJ"], "ans": 0, "exp": "• ΔrH°₂₉₈ = ΔfH°(CO₂) - [ΔfH°(CO) + 1/2 ΔfH°(O₂)]<br>= -393,5 - (-110,5 + 0) = -393,5 + 110,5 = -283,0 kJ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Biến thiên enthalpy phản ứng có thể tính bằng hai cách: Dựa vào hiệu số nhiệt [ ... ] của sản phẩm trừ chất đầu: ∑ ΔfH°(sp) - ∑ ΔfH°(cđ); hoặc dựa vào hiệu số năng lượng [ ... ] của chất đầu trừ sản phẩm: ∑ Eb(cđ) - ∑ Eb(sp). Quá trình bẻ gãy liên kết là quá trình [ ... ] nhiệt, còn hình thành liên kết là quá trình [ ... ] nhiệt.", "opts": ["tạo thành — liên kết — thu — tỏa", "tỏa — thu — liên kết — tạo thành", "liên kết — thu — tỏa — tạo thành", "thu — tỏa — tạo thành — liên kết"], "ans": 0, "exp": "• Nhiệt tạo thành, năng lượng liên kết.<br>• Bẻ gãy liên kết: thu nhiệt.<br>• Hình thành liên kết: tỏa nhiệt.", "svgGraph": null}, {"q": "Sơ đồ nào sau đây biểu diễn đúng một phản ứng tỏa nhiệt (ΔH < 0)?", "opts": ["Mức năng lượng (Enthalpy) của các chất phản ứng CAO HƠN mức năng lượng của các sản phẩm.", "Mức năng lượng của các chất phản ứng THẤP HƠN mức năng lượng của các sản phẩm.", "Mức năng lượng của chất phản ứng và sản phẩm bằng nhau.", "Không thể so sánh được mức năng lượng."], "ans": 0, "exp": "• Trong phản ứng tỏa nhiệt: Enthalpy giảm (ΔH = H_sp - H_cđ < 0) ⇒ Năng lượng chất đầu cao hơn năng lượng sản phẩm, phần năng lượng dư thừa được giải phóng ra môi trường dưới dạng nhiệt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "19": [{"q": "Tốc độ phản ứng hóa học là đại lượng đặc trưng cho yếu tố nào sau đây?", "opts": ["Độ nhanh hay chậm của một phản ứng hóa học (độ biến thiên nồng độ trong một đơn vị thời gian).", "Nhiệt lượng tỏa ra hay thu vào của phản ứng.", "Khối lượng sản phẩm thu được khi phản ứng kết thúc.", "Chiều chuyển dịch cân bằng của phản ứng."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 10:</b> Tốc độ phản ứng là đại lượng đặc trưng cho sự biến thiên nồng độ của một trong các chất phản ứng hoặc sản phẩm trong một đơn vị thời gian (giây, phút, giờ...).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho phản ứng tổng quát: aA + bB -> cC + dD. Biểu thức tốc độ trung bình của phản ứng theo độ giảm nồng độ của chất phản ứng A trong khoảng thời gian Δt là:", "opts": ["v̄ = - (1/a) · (ΔC_A / Δt)", "v̄ = + (1/a) · (ΔC_A / Δt)", "v̄ = - a · (ΔC_A / Δt)", "v̄ = (ΔC_A) / (a · Δt²)"], "ans": 0, "exp": "• Do chất phản ứng A bị tiêu hao nên nồng độ giảm dần (ΔC_A = C₂ - C₁ < 0). Dấu trừ (-) đặt phía trước để đảm bảo tốc độ phản ứng luôn mang giá trị dương.<br>• Chia cho hệ số tỉ lượng a để tốc độ phản ứng tính theo mọi chất là như nhau.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho phản ứng: 2N₂O₅(g) -> 4NO₂(g) + O₂(g). Sau 100 giây, nồng độ N₂O₅ giảm từ 0,020 M xuống còn 0,012 M:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Theo định luật tác dụng khối lượng (Guldberg & Waage), đối với phản ứng đơn giản: aA + bB -> sản phẩm, tốc độ tức thời của phản ứng tỉ lệ thuận với:", "opts": ["Tích số nồng độ của các chất phản ứng với số mũ bằng hệ số tỉ lượng: v = k · [A]ᵃ · [B]ᵇ.", "Tổng nồng độ của các chất phản ứng: v = k · ([A] + [B]).", "Tỉ số nồng độ: v = k · [A] / [B].", "Nồng độ của các sản phẩm sinh ra."], "ans": 0, "exp": "• Định luật tác dụng khối lượng: v = k · C_A^a · C_B^b.<br>• Trong đó k là hằng số tốc độ phản ứng, chỉ phụ thuộc vào bản chất chất phản ứng và nhiệt độ (không phụ thuộc vào nồng độ).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các khái niệm (Cột A) với ý nghĩa tương ứng trong động hóa học (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Tốc độ trung bình (v̄) ➔ A. Tốc độ tính trong một khoảng thời gian xác định Δt.", "1. Tốc độ trung bình (v̄) ➔ B. Tốc độ của phản ứng tại một thời điểm xác định.", "1. Tốc độ trung bình (v̄) ➔ C. Tốc độ của phản ứng khi nồng độ các chất phản ứng đều bằng 1 M.", "1. Tốc độ trung bình (v̄) ➔ D. Va chạm giữa các phân tử có năng lượng đủ lớn và định hướng đúng để tạo liên kết mới."], "ans": 0, "exp": "• Các khái niệm nền tảng của tốc độ phản ứng hóa học.", "svgGraph": null}, {"q": "Cho phản ứng đơn giản: 2NO(g) + O₂(g) -> 2NO₂(g). Biểu thức định luật tác dụng khối lượng của phản ứng là:", "opts": ["v = k · [NO]² · [O₂]", "v = k · [NO] · [O₂]", "v = k · [NO]² · [O₂]²", "v = k · [NO₂]² / ([NO]² · [O₂])"], "ans": 0, "exp": "• Phản ứng đơn giản 2NO + O₂ -> 2NO₂ có bậc 2 theo NO và bậc 1 theo O₂.<br>• Do đó: v = k · [NO]² · [O₂].<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét phản ứng đơn giản: CO(g) + Cl₂(g) -> COCl₂(g) có biểu thức tốc độ v = k · [CO] · [Cl₂]:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Một phản ứng hóa học xảy ra giữa chất rắn và chất lỏng: CaCO₃(s) + 2HCl(aq) -> CaCl₂(aq) + CO₂(g) + H₂O(l). Biểu thức tốc độ của phản ứng này theo định luật tác dụng khối lượng phụ thuộc vào:", "opts": ["Nồng độ dung dịch HCl (v = k · [HCl]²), nồng độ chất rắn nguyên chất CaCO₃ không xuất hiện trong biểu thức.", "Tích nồng độ cả CaCO₃ và HCl.", "Nồng độ khí CO₂ sinh ra.", "Chỉ phụ thuộc vào thể tích nước."], "ans": 0, "exp": "• Nồng độ của chất rắn nguyên chất được coi là hằng số và được gộp vào hằng số tốc độ k.<br>• Do đó nồng độ chất rắn không xuất hiện trong biểu thức tốc độ: v = k · [HCl]².<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Tốc độ phản ứng là độ biến thiên [ ... ] của một chất trong một đơn vị [ ... ]. Để phản ứng xảy ra, các phân tử phải có [ ... ] hiệu quả với nhau. Hằng số tốc độ k phụ thuộc vào [ ... ] và bản chất của chất phản ứng.", "opts": ["nồng độ — thời gian — va chạm — nhiệt độ", "nhiệt độ — va chạm — thời gian — nồng độ", "thời gian — va chạm — nhiệt độ — nồng độ", "va chạm — nhiệt độ — nồng độ — thời gian"], "ans": 0, "exp": "• Biến thiên nồng độ / thời gian.<br>• Va chạm hiệu quả.<br>• Hằng số k phụ thuộc nhiệt độ.", "svgGraph": null}, {"q": "Phản ứng nào sau đây diễn ra với tốc độ nhanh nhất ở điều kiện thường?", "opts": ["Phản ứng trao đổi ion: AgNO₃(aq) + NaCl(aq) -> AgCl↓ + NaNO₃(aq) (kết tủa xuất hiện tức thì)", "Sự ăn mòn sắt tạo gỉ trong không khí ẩm", "Sự lên men đường tạo rượu etylic", "Sự hình thành than đá và dầu mỏ trong lòng đất"], "ans": 0, "exp": "• Phản ứng trao đổi ion trong dung dịch giữa các ion tự do xảy ra gần như tức thời (tốc độ cực nhanh).<br>• Gỉ sắt xảy ra chậm (vài ngày/tháng); lên men cần vài ngày; tạo than đá mất hàng triệu năm.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "20": [{"q": "Có bao nhiêu yếu tố chính ảnh hưởng đến tốc độ của một phản ứng hóa học?", "opts": ["5 yếu tố: Nồng độ, nhiệt độ, áp suất (chất khí), diện tích bề mặt tiếp xúc (chất rắn) và chất xúc tác.", "Chỉ có 2 yếu tố: Nhiệt độ và nồng độ.", "Chỉ có 3 yếu tố: Áp suất, thể tích và khối lượng.", "Chỉ có chất xúc tác."], "ans": 0, "exp": "• 5 yếu tố ảnh hưởng đến tốc độ phản ứng: Nồng độ, Áp suất, Nhiệt độ, Diện tích bề mặt tiếp xúc, Chất xúc tác.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi tăng nồng độ của các chất phản ứng, tại sao tốc độ phản ứng lại tăng lên?", "opts": ["Vì số lượng phân tử trên một đơn vị thể tích tăng lên, làm tần số va chạm hiệu quả giữa các phân tử tăng lên.", "Vì năng lượng hoạt hóa của phản ứng bị giảm đi.", "Vì làm cho các phân tử chuyển động nhanh hơn.", "Vì làm phản ứng tỏa nhiều nhiệt hơn."], "ans": 0, "exp": "• Nồng độ tăng ⇒ mật độ phân tử tăng ⇒ số va chạm giữa các phân tử trong 1 đơn vị thời gian tăng lên ⇒ số va chạm hiệu quả tăng ⇒ tốc độ phản ứng tăng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét ảnh hưởng của diện tích bề mặt tiếp xúc và áp suất:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Theo quy tắc Van't Hoff, khi tăng nhiệt độ lên 10 °C thì tốc độ phản ứng tăng từ 2 đến 4 lần (hệ số nhiệt độ γ = 2 - 4). Nếu một phản ứng có hệ số γ = 3, khi tăng nhiệt độ từ 20 °C lên 50 °C thì tốc độ phản ứng tăng bao nhiêu lần?", "opts": ["27 lần", "9 lần", "30 lần", "81 lần"], "ans": 0, "exp": "• Công thức Van't Hoff: v₂ / v₁ = γ^((T₂ - T₁) / 10).<br>• Với ΔT = 50 - 20 = 30 °C ⇒ (50 - 20) / 10 = 3.<br>• Tỉ số tốc độ: v₂ / v₁ = 3³ = 27 lần.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các biện pháp thực tế (Cột A) với yếu tố ảnh hưởng tốc độ phản ứng được áp dụng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Bảo quản thức ăn trong tủ lạnh để lâu thiu hơn ➔ A. Hạ nhiệt độ để giảm tốc độ phân hủy.", "1. Bảo quản thức ăn trong tủ lạnh để lâu thiu hơn ➔ B. Tăng nồng độ chất phản ứng (khí O₂).", "1. Bảo quản thức ăn trong tủ lạnh để lâu thiu hơn ➔ C. Tăng áp suất làm tăng nhiệt độ sôi của nước (khoảng 120 °C).", "1. Bảo quản thức ăn trong tủ lạnh để lâu thiu hơn ➔ D. Dùng chất xúc tác sinh học làm tăng tốc độ phản ứng."], "ans": 0, "exp": "• Ứng dụng thực tiễn của 5 yếu tố ảnh hưởng đến tốc độ phản ứng.", "svgGraph": null}, {"q": "Chất xúc tác là chất có tác dụng làm tăng tốc độ phản ứng, đặc điểm nào sau đây của chất xúc tác là ĐÚNG?", "opts": ["Làm giảm năng lượng hoạt hóa của phản ứng và không bị tiêu hao sau phản ứng.", "Làm tăng biến thiên enthalpy ΔH của phản ứng.", "Làm biến đổi phản ứng thu nhiệt thành phản ứng tỏa nhiệt.", "Bị biến đổi hoàn toàn thành chất khác sau khi kết thúc phản ứng."], "ans": 0, "exp": "• Chất xúc tác mở ra một con đường phản ứng mới có năng lượng hoạt hóa (Ea) thấp hơn, giúp nhiều phân tử vượt qua rào cản năng lượng hơn ⇒ tăng tốc độ phản ứng.<br>• Lượng và bản chất hóa học của chất xúc tác không đổi sau phản ứng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các hiện tượng thực tiễn liên quan đến chất xúc tác và enzyme:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Tại sao khi nướng thịt trên than hoa người ta thường dùng quạt nan hoặc quạt điện thổi vào bếp than?", "opts": ["Để cung cấp liên tục khí O₂, làm tăng nồng độ O₂ tiếp xúc với than giúp than cháy nhanh và nhiệt lượng cao hơn.", "Để thổi tàn tro làm sạch miếng thịt.", "Để làm giảm nhiệt độ của than không bị cháy khét.", "Để tạo áp suất cao xung quanh bếp."], "ans": 0, "exp": "• Thổi khí làm tăng nồng độ O₂ tại bề mặt than, tăng số va chạm hiệu quả giữa C và O₂ ⇒ than cháy rực hơn tỏa nhiệt mạnh.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Tốc độ phản ứng tăng khi: [ ... ] nồng độ chất phản ứng, tăng [ ... ], tăng [ ... ] bề mặt tiếp xúc chất rắn hoặc sử dụng [ ... ] thích hợp.", "opts": ["tăng — nhiệt độ — diện tích — chất xúc tác", "chất xúc tác — diện tích — nhiệt độ — tăng", "nhiệt độ — diện tích — chất xúc tác — tăng", "diện tích — chất xúc tác — tăng — nhiệt độ"], "ans": 0, "exp": "• Tăng nồng độ, tăng nhiệt độ, tăng diện tích tiếp xúc, chất xúc tác.", "svgGraph": null}, {"q": "Một phản ứng ở 30 °C diễn ra trong 20 phút. Biết hệ số nhiệt độ Van't Hoff của phản ứng là γ = 2. Khi tăng nhiệt độ lên 50 °C thì thời gian phản ứng kết thúc là bao nhiêu?", "opts": ["5 phút", "10 phút", "2,5 phút", "40 phút"], "ans": 0, "exp": "• ΔT = 50 - 30 = 20 °C ⇒ Tốc độ phản ứng tăng: v₂ / v₁ = 2^(20/10) = 2² = 4 lần.<br>• Vì tốc độ phản ứng tăng 4 lần nên thời gian để phản ứng xảy ra hết giảm 4 lần:<br>t₂ = t₁ / 4 = 20 / 4 = 5 phút.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "21": [{"q": "Phát biểu nào sau đây về năng lượng hoạt hóa (Ea) là ĐÚNG?", "opts": ["Là năng lượng tối thiểu mà các phân tử va chạm cần có để phản ứng hóa học có thể xảy ra.", "Là nhiệt lượng tỏa ra khi phản ứng kết thúc hoàn toàn.", "Là năng lượng của chất xúc tác cung cấp cho phản ứng.", "Luôn bằng biến thiên enthalpy ΔH của phản ứng."], "ans": 0, "exp": "• Năng lượng hoạt hóa Ea (Activation energy) là rào cản năng lượng tối thiểu. Ea càng nhỏ thì phản ứng xảy ra càng nhanh ở nhiệt độ phòng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Một phản ứng hóa học ở 20 °C có tốc độ v₁. Để tốc độ phản ứng tăng lên 16 lần, biết hệ số Van't Hoff γ = 2, cần nâng nhiệt độ lên bao nhiêu?", "opts": ["60 °C", "40 °C", "50 °C", "80 °C"], "ans": 0, "exp": "• Ta có: v₂ / v₁ = 16 = 2⁴ = γ^(ΔT / 10).<br>• Với γ = 2 ⇒ ΔT / 10 = 4 ⇒ ΔT = 40 °C.<br>• Nhiệt độ cần nâng lên là: T₂ = T₁ + ΔT = 20 + 40 = 60 °C.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu tổng kết về tốc độ phản ứng:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trong thí nghiệm nghiên cứu tốc độ phản ứng giữa Na₂S₂O₃ và H₂SO₄ loãng (Na₂S₂O₃ + H₂SO₄ -> Na₂SO₄ + S↓ + SO₂↑ + H₂O), người ta đo thời gian từ khi bắt đầu trộn dung dịch đến khi:", "opts": ["Dung dịch trở nên đục do kết tủa lưu huỳnh (S) che khuất vạch dấu chữ thập dưới đáy bình tam giác.", "Toàn bộ chất lỏng bay hơi hết.", "Nhiệt độ dung dịch sôi lên 100 °C.", "Dung dịch chuyển sang màu xanh lam."], "ans": 0, "exp": "• Thí nghiệm kinh điển SGK Hóa 10: Quan sát sự đục của lưu huỳnh (S) kết tủa che khuất dấu chữ thập (+). Thời gian càng ngắn thì tốc độ phản ứng càng lớn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các trường hợp thí nghiệm (Cột A) với kết quả tốc độ phản ứng tương đối (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Kẽm hạt + dung dịch HCl 1M ở 25 °C ➔ A. Phản ứng xảy ra với tốc độ chuẩn.", "1. Kẽm hạt + dung dịch HCl 1M ở 25 °C ➔ B. Nhanh hơn do diện tích tiếp xúc lớn hơn nhiều.", "1. Kẽm hạt + dung dịch HCl 1M ở 25 °C ➔ C. Nhanh hơn do nồng độ acid cao hơn.", "1. Kẽm hạt + dung dịch HCl 1M ở 25 °C ➔ D. Nhanh hơn nhiều do nhiệt độ cao hơn."], "ans": 0, "exp": "• So sánh các yếu tố diện tích, nồng độ, nhiệt độ tác động lên phản ứng kim loại + acid.", "svgGraph": null}, {"q": "Khi thêm vài giọt dung dịch CuSO₄ vào cốc đựng dung dịch H₂SO₄ loãng tác dụng với kẽm Zn, tốc độ thoát khí H₂ tăng vọt dữ dội là do nguyên nhân nào?", "opts": ["Hình thành pin điện hóa Zn–Cu làm xảy ra quá trình ăn mòn điện hóa học rất nhanh.", "CuSO₄ là chất xúc tác đồng thể.", "Dung dịch bị nóng lên do tỏa nhiệt.", "CuSO₄ làm tăng nồng độ H⁺."], "ans": 0, "exp": "• Zn đẩy Cu ra khỏi CuSO₄: Zn + Cu²⁺ -> Zn²⁺ + Cu.<br>• Kim loại Cu sinh ra bám vào thanh Zn, cùng tiếp xúc với dung dịch điện li H₂SO₄ tạo thành vô số vi pin điện hóa Zn-Cu. Zn bị ăn mòn điện hóa cực nhanh và khí H₂ thoát ra ồ ạt trên bề mặt đồng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các biện pháp làm chậm tốc độ phản ứng có hại trong đời sống:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chất xúc tác có vai trò gì đối với phản ứng tổng hợp NH₃ từ N₂ và H₂ (phương pháp Haber-Bosch)?", "opts": ["Bột sắt (Fe) làm giảm nhiệt độ cần thiết và tăng tốc độ đạt trạng thái cân bằng.", "Làm tăng lượng NH₃ tối đa thu được ở trạng thái cân bằng.", "Làm phản ứng chuyển thành tỏa nhiệt.", "Làm tiêu hao khí N₂ nhanh hơn H₂."], "ans": 0, "exp": "• Xúc tác bột sắt Fe (chứa Al₂O₃, K₂O) giúp phản ứng Haber diễn ra ở nhiệt độ thực tế khoảng 450 °C với tốc độ chấp nhận được mà không cần nhiệt độ quá cao làm cân bằng chuyển dịch ngược lại.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Hệ số nhiệt độ Van't Hoff kí hiệu là [ ... ], cho biết tốc độ phản ứng tăng lên bao nhiêu lần khi nhiệt độ tăng thêm [ ... ] °C. Chất xúc tác làm tăng tốc độ phản ứng bằng cách làm giảm [ ... ] hoạt hóa, nhưng không làm thay đổi biến thiên [ ... ] của phản ứng.", "opts": ["γ — 10 — năng lượng — enthalpy (ΔH)", "enthalpy (ΔH) — năng lượng — 10 — γ", "10 — năng lượng — enthalpy (ΔH) — γ", "năng lượng — enthalpy (ΔH) — γ — 10"], "ans": 0, "exp": "• Hệ số Van't Hoff γ, 10 °C.<br>• Giảm năng lượng hoạt hóa, không đổi enthalpy ΔH.", "svgGraph": null}, {"q": "Cho phản ứng A + B -> C. Nồng độ ban đầu của A là 1,0 M. Sau 20 giây phản ứng, nồng độ của A còn lại 0,6 M. Tốc độ trung bình của phản ứng theo chất A trong 20 giây đầu là:", "opts": ["0,020 M/s", "0,030 M/s", "0,050 M/s", "0,010 M/s"], "ans": 0, "exp": "• Độ giảm nồng độ: ΔC = 1,0 - 0,6 = 0,4 M.<br>• Thời gian: Δt = 20 s.<br>• Tốc độ trung bình: v̄ = 0,4 / 20 = 0,020 mol/(L·s) (hay 0,020 M/s).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "22": [{"q": "Nhóm Halogen là tên gọi của nhóm nguyên tố nào trong bảng tuần hoàn các nguyên tố hóa học?", "opts": ["Nhóm VIIA (gồm Fluorine, Chlorine, Bromine, Iodine, Astatine).", "Nhóm IA (Kim loại kiềm).", "Nhóm IIA (Kim loại kiềm thổ).", "Nhóm VIIIA (Khí hiếm)."], "ans": 0, "exp": "• <b>Kiến thức SGK Hóa 10:</b> Nhóm Halogen là nhóm VIIA, tên gọi 'halogen' xuất phát từ tiếng Hy Lạp có nghĩa là 'sinh ra muối'.<br>• Gồm các nguyên tố: F (Fluorine), Cl (Chlorine), Br (Bromine), I (Iodine) và At (Astatine phóng xạ).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cấu hình electron lớp ngoài cùng của các nguyên tử nguyên tố halogen ở trạng thái cơ bản là gì?", "opts": ["ns² np⁵", "ns² np⁶", "ns² np⁴", "ns¹"], "ans": 0, "exp": "• Tất cả các nguyên tử halogen đều có 7 electron ở lớp ngoài cùng với cấu hình ns²np⁵.<br>• Có xu hướng nhận thêm 1 electron để đạt cấu hình octet bền vững của khí hiếm ns²np⁶.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét trạng thái tập hợp và màu sắc của các đơn chất halogen ở điều kiện thường (25 °C, 1 bar):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Theo chiều từ F₂ đến I₂, tính oxi hóa của các đơn chất halogen biến đổi như thế nào?", "opts": ["Giảm dần từ F₂ đến I₂ (F₂ > Cl₂ > Br₂ > I₂).", "Tăng dần từ F₂ đến I₂.", "Không đổi.", "Cl₂ có tính oxi hóa mạnh hơn F₂."], "ans": 0, "exp": "• Đi từ trên xuống dưới trong nhóm VIIA, bán kính nguyên tử tăng dần, độ âm điện giảm dần ⇒ khả năng nhận electron giảm ⇒ tính oxi hóa giảm dần: F₂ > Cl₂ > Br₂ > I₂.<br>• F₂ là phi kim có tính oxi hóa mạnh nhất, oxi hóa mãnh liệt nước ngay ở nhiệt độ thường.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép đơn chất halogen (Cột A) với trạng thái và màu sắc tương ứng ở điều kiện thường (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. F₂ (Fluorine) ➔ A. Khí màu lục nhạt.", "1. F₂ (Fluorine) ➔ B. Khí màu vàng lục, mùi xốc.", "1. F₂ (Fluorine) ➔ C. Lỏng màu nâu đỏ, dễ bay hơi.", "1. F₂ (Fluorine) ➔ D. Rắn màu tím đen, dễ thăng hoa."], "ans": 0, "exp": "• Trạng thái và màu sắc biến đổi tuần hoàn: Khí lục nhạt -> Khí vàng lục -> Lỏng nâu đỏ -> Rắn tím đen.", "svgGraph": null}, {"q": "Phản ứng nào sau đây chứng minh tính oxi hóa của Chlorine mạnh hơn Bromine?", "opts": ["Cl₂ + 2NaBr -> 2NaCl + Br₂", "Br₂ + 2NaCl -> 2NaBr + Cl₂", "Cl₂ + H₂ -> 2HCl", "Br₂ + H₂ -> 2HBr"], "ans": 0, "exp": "• Halogen mạnh hơn có khả năng oxi hóa ion halide của halogen yếu hơn ra khỏi dung dịch muối.<br>• Cl₂ đẩy được Br⁻ ra khỏi muối NaBr tạo Br₂ màu vàng nâu, chứng tỏ tính oxi hóa Cl₂ > Br₂.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng của halogen với nước:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Hiện tượng một chất rắn khi đun nóng chuyển trực tiếp thành thể hơi mà không qua thể lỏng được gọi là hiện tượng gì (đặc trưng của Iodine I₂)?", "opts": ["Hiện tượng thăng hoa (sublimation).", "Hiện tượng ngưng tụ.", "Hiện tượng nóng chảy.", "Hiện tượng đông đặc."], "ans": 0, "exp": "• Iodine (I₂) có mạng tinh thể phân tử liên kết yếu, khi đun nóng nhẹ thăng hoa trực tiếp thành hơi màu tím; khi gặp lạnh ngưng tụ lại thành tinh thể rắn màu tím đen.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Các nguyên tử halogen có [ ... ] electron ở lớp ngoài cùng (ns²np⁵), nên có tính [ ... ] mạnh đặc trưng. Đi từ F đến I, bán kính nguyên tử [ ... ] dần, độ âm điện [ ... ] dần.", "opts": ["7 — oxi hóa — tăng — giảm", "giảm — tăng — oxi hóa — 7", "oxi hóa — tăng — giảm — 7", "tăng — giảm — 7 — oxi hóa"], "ans": 0, "exp": "• 7 electron, tính oxi hóa mạnh.<br>• Bán kính tăng, độ âm điện giảm.", "svgGraph": null}, {"q": "Chất nào sau đây dùng để nhận biết hồ tinh bột do tạo thành hợp chất có màu xanh tím đặc trưng?", "opts": ["Dung dịch Iodine (I₂)", "Dung dịch Chlorine (Cl₂)", "Dung dịch Bromine (Br₂)", "Dung dịch Fluorine (F₂)"], "ans": 0, "exp": "• Các phân tử I₂ chui vào các xoắn của chuỗi amylose trong tinh bột tạo hợp chất bọc có màu xanh tím đặc trưng.<br>• Khi đun nóng màu xanh biến mất, để nguội lại xuất hiện trở lại.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "23": [{"q": "Dãy sắp xếp các hydrogen halide theo chiều tính acid TĂNG DẦN trong dung dịch nước là:", "opts": ["HF < HCl < HBr < HI", "HI < HBr < HCl < HF", "HCl < HBr < HI < HF", "HF < HI < HBr < HCl"], "ans": 0, "exp": "• Đi từ HF đến HI, bán kính nguyên tử halogen tăng làm độ dài liên kết H–X tăng và năng lượng liên kết Eb(H–X) giảm dần ⇒ liên kết H–X càng dễ phân li ra H⁺ trong nước ⇒ tính acid tăng dần.<br>• HF là acid yếu, còn HCl, HBr, HI là các acid mạnh (HI là hydrohalic acid mạnh nhất).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Acid nào sau đây có tính chất đặc biệt là ăn mòn được thủy tinh (silicon dioxide SiO₂), dùng để khắc chữ lên thủy tinh?", "opts": ["Hydrofluoric acid (HF)", "Hydrochloric acid (HCl)", "Sulfuric acid (H₂SO₄)", "Nitric acid (HNO₃)"], "ans": 0, "exp": "• HF hòa tan thủy tinh theo phản ứng: 4HF + SiO₂ -> SiF₄↑ + 2H₂O.<br>• Do đó không thể đựng dung dịch HF trong chai lọ bằng thủy tinh mà phải đựng trong bình bằng nhựa polyethylene (PE).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng nhận biết ion halide (Cl⁻, Br⁻, I⁻) bằng dung dịch bạc nitrat (AgNO₃):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nước Javel là dung dịch hỗn hợp chứa hai muối nào có tính tẩy màu và sát trùng mạnh?", "opts": ["NaCl và NaClO (Sodium hypochlorite)", "NaCl và NaClO₃", "KCl và KClO", "CaCl₂ và Ca(ClO)₂"], "ans": 0, "exp": "• Cho khí Cl₂ tác dụng với dung dịch NaOH ở nhiệt độ phòng:<br>Cl₂ + 2NaOH -> NaCl + NaClO + H₂O.<br>• Muối NaClO có tính oxi hóa rất mạnh nhờ gốc ClO⁻, dùng làm chất tẩy trắng vải sợi và sát trùng nước sinh hoạt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép ion halide (Cột A) với hiện tượng khi nhỏ dung dịch AgNO₃ vào dung dịch muối (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Ion F⁻ (NaF) ➔ A. Không có hiện tượng (AgF tan hoàn toàn).", "1. Ion F⁻ (NaF) ➔ B. Xuất hiện kết tủa màu trắng (AgCl).", "1. Ion F⁻ (NaF) ➔ C. Xuất hiện kết tủa màu vàng nhạt (AgBr).", "1. Ion F⁻ (NaF) ➔ D. Xuất hiện kết tủa màu vàng đậm (AgI)."], "ans": 0, "exp": "• Thuốc thử đặc trưng AgNO₃ phân biệt 4 ion halide.", "svgGraph": null}, {"q": "Clorua vôi là chất bột màu trắng, xốp, có mùi hắc của clo, có công thức hóa học là:", "opts": ["CaOCl₂ (muối hỗn tạp của ion Ca²⁺ với Cl⁻ và ClO⁻)", "CaCl₂", "Ca(ClO)₂", "CaCO₃"], "ans": 0, "exp": "• Clorua vôi điều chế bằng cách cho Cl₂ tác dụng với vôi tôi ẩm Ca(OH)₂ ở 30 °C:<br>Cl₂ + Ca(OH)₂ -> CaOCl₂ + H₂O.<br>• CaOCl₂ là muối hỗn tạp, có tính sát trùng tẩy trắng mạnh tương tự nước Javel nhưng rẻ tiền hơn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các tính chất hóa học của hydrochloric acid (HCl):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Muối iod dùng trong bữa ăn hàng ngày để phòng ngừa bệnh bướu cổ và thiểu năng trí tuệ là muối ăn (NaCl) được trộn thêm một lượng nhỏ chất nào?", "opts": ["KI hoặc KIO₃ (Potassium iodate)", "Iodine nguyên chất (I₂)", "NaI độc hại", "HI"], "ans": 0, "exp": "• Cơ thể cần iod để tuyến giáp tổng hợp hormone thyroxine. Thiếu iod gây bướu cổ và đần độn.<br>• Người ta trộn một lượng vi lượng muối KI hoặc KIO₃ bền vào muối ăn để bổ sung cho cộng đồng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Để nhận biết các ion halide trong dung dịch, người ta dùng thuốc thử dung dịch [ ... ]. Ion Cl⁻ tạo kết tủa màu [ ... ], ion Br⁻ tạo kết tủa màu [ ... ] và ion I⁻ tạo kết tủa màu [ ... ].", "opts": ["AgNO₃ — trắng — vàng nhạt — vàng đậm", "vàng đậm — vàng nhạt — trắng — AgNO₃", "trắng — vàng nhạt — vàng đậm — AgNO₃", "vàng nhạt — vàng đậm — AgNO₃ — trắng"], "ans": 0, "exp": "• Thuốc thử AgNO₃: Cl⁻ trắng, Br⁻ vàng nhạt, I⁻ vàng đậm.", "svgGraph": null}, {"q": "Trong dạ dày người, môi trường acid có pH từ 1,5 đến 2,5 giúp tiêu hóa protein và tiêu diệt vi khuẩn có hại là do chất nào tạo nên?", "opts": ["Hydrochloric acid (HCl)", "Sulfuric acid (H₂SO₄)", "Acetic acid (CH₃COOH)", "Nitric acid (HNO₃)"], "ans": 0, "exp": "• Dịch vị dạ dày chứa acid HCl với nồng độ khoảng 0,0001 - 0,001 M (pH ≈ 1,5 - 2,5), đóng vai trò hoạt hóa enzyme pepsinogen thành pepsin để tiêu hóa chất đạm.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}]}, "11": {"1": [{"q": "Cân bằng hóa học là trạng thái của một phản ứng thuận nghịch khi:", "opts": ["Tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch (v_t = v_n).", "Nồng độ của các chất phản ứng bằng nồng độ của các sản phẩm.", "Phản ứng dừng lại hoàn toàn không xảy ra nữa.", "Toàn bộ chất phản ứng đã chuyển hóa hết thành sản phẩm."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Cân bằng hóa học là trạng thái của phản ứng thuận nghịch khi tốc độ phản ứng thuận bằng tốc độ phản ứng nghịch (v_thuận = v_nghịch).<br>• Cân bằng hóa học là một cân bằng động (dynamic equilibrium): phản ứng vẫn diễn ra ở mức độ vi mô theo cả 2 chiều với tốc độ bằng nhau.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Đối với phản ứng thuận nghịch: aA + bB ⇌ cC + dD. Biểu thức của hằng số cân bằng nồng độ (K_C) ở trạng thái cân bằng là:", "opts": ["K_C = ([C]^c · [D]^d) / ([A]^a · [B]^b)", "K_C = ([A]^a · [B]^b) / ([C]^c · [D]^d)", "K_C = (c[C] + d[D]) / (a[A] + b[B])", "K_C = [C] · [D] / ([A] · [B])"], "ans": 0, "exp": "• Hằng số cân bằng K_C bằng tỉ số giữa tích nồng độ các sản phẩm với tích nồng độ các chất phản ứng, mỗi nồng độ được nâng lên lũy thừa bằng hệ số tỉ lượng tương ứng trong phương trình hóa học.<br>• K_C chỉ phụ thuộc vào bản chất của phản ứng và nhiệt độ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét nguyên lí chuyển dịch cân bằng Le Chatelier:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Cho phản ứng tổng hợp ammonia: N₂(g) + 3H₂(g) ⇌ 2NH₃(g)   ΔrH°₂₉₈ = -92 kJ. Để cân bằng chuyển dịch theo chiều thuận (tăng hiệu suất tạo NH₃), ta cần:", "opts": ["Tăng áp suất và giảm nhiệt độ của hệ.", "Giảm áp suất và tăng nhiệt độ.", "Tăng nhiệt độ và dùng thêm chất xúc tác.", "Giảm nồng độ khí N₂ và H₂."], "ans": 0, "exp": "• Chiều thuận là chiều tỏa nhiệt (ΔH < 0), muốn cân bằng dịch chuyển theo chiều thuận ta phải giảm nhiệt độ.<br>• Chiều thuận làm giảm số mol khí (từ 1 + 3 = 4 mol khí xuống 2 mol khí), muốn cân bằng chuyển dịch theo chiều thuận ta phải tăng áp suất.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các yếu tố tác động (Cột A) với sự chuyển dịch cân bằng của phản ứng: N₂O₄(khí không màu) ⇌ 2NO₂(khí màu nâu đỏ) ΔH > 0 (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Đun nóng bình (tăng nhiệt độ) ➔ A. Cân bằng dịch theo chiều thuận (màu nâu đỏ đậm lên).", "1. Đun nóng bình (tăng nhiệt độ) ➔ B. Cân bằng dịch theo chiều nghịch (màu nâu nhạt dần).", "1. Đun nóng bình (tăng nhiệt độ) ➔ C. Cân bằng dịch theo chiều nghịch (giảm số mol khí từ 2 về 1).", "1. Đun nóng bình (tăng nhiệt độ) ➔ D. Cân bằng không bị dịch chuyển."], "ans": 0, "exp": "• Phản ứng thu nhiệt (ΔH > 0): Tăng t° dịch chuyển sang phải (tạo NO₂ màu nâu đỏ).<br>• Tăng áp suất dịch chuyển về phía ít mol khí hơn (sang trái).", "svgGraph": null}, {"q": "Cho cân bằng: C(s) + CO₂(g) ⇌ 2CO(g)   ΔrH°₂₉₈ = +172,5 kJ. Khi biểu diễn hằng số cân bằng K_C, đại lượng nào KHÔNG xuất hiện trong biểu thức?", "opts": ["Nồng độ của Carbon rắn C(s).", "Nồng độ của CO₂(g).", "Nồng độ của CO(g).", "Cả CO và CO₂."], "ans": 0, "exp": "• Quy ước: Nồng độ chất rắn nguyên chất được coi là hằng số (bằng 1) nên không được đưa vào biểu thức K_C.<br>• Biểu thức chuẩn: K_C = [CO]² / [CO₂].<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét phản ứng thuận nghịch: H₂(g) + I₂(g) ⇌ 2HI(g) ở nhiệt độ 430 °C:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nếu ở nhiệt độ T, hằng số cân bằng K_C của phản ứng rất lớn (K_C >> 1) thì điều đó có ý nghĩa gì?", "opts": ["Ở trạng thái cân bằng, nồng độ các sản phẩm chiếm ưu thế lớn so với chất phản ứng (phản ứng xảy ra gần như hoàn toàn).", "Phản ứng xảy ra rất chậm.", "Nồng độ các chất đầu lớn hơn nhiều so với sản phẩm.", "Phản ứng không thể xảy ra được."], "ans": 0, "exp": "• K_C = [Sản phẩm] / [Chất đầu].<br>• K_C >> 1 chứng tỏ ở trạng thái cân bằng lượng sản phẩm rất lớn, phản ứng thuận diễn ra rất thuận lợi.<br>• K_C << 1 chứng tỏ phản ứng thuận khó xảy ra.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Phản ứng thuận nghịch là phản ứng xảy ra theo [ ... ] chiều trái ngược nhau trong cùng điều kiện. Cân bằng hóa học là cân bằng [ ... ]. Khi một hệ đang ở trạng thái cân bằng chịu một tác động từ bên ngoài, cân bằng sẽ chuyển dịch theo chiều làm [ ... ] tác động đó theo nguyên lí [ ... ].", "opts": ["hai — động — giảm — Le Chatelier", "Le Chatelier — giảm — động — hai", "động — giảm — Le Chatelier — hai", "giảm — Le Chatelier — hai — động"], "ans": 0, "exp": "• Hai chiều trái ngược, cân bằng động.<br>• Giảm tác động bên ngoài theo nguyên lí Le Chatelier.", "svgGraph": null}, {"q": "Ở nhiệt độ phòng, một lon nước ngọt có gas đóng kín chứa cân bằng: CO₂(aq) + H₂O(l) ⇌ H₂CO₃(aq) ⇌ H⁺(aq) + HCO₃⁻(aq). Khi mở nắp lon nước ngọt, hiện tượng sủi bọt khí CO₂ xảy ra là do:", "opts": ["Áp suất khí CO₂ trên bề mặt dung dịch giảm đột ngột làm cân bằng chuyển dịch theo chiều giải phóng khí CO₂.", "Nhiệt độ lon nước ngọt bị tăng lên tức thì.", "Dung dịch bị nhiễm khuẩn từ không khí.", "Nồng độ ion H⁺ tăng vọt."], "ans": 0, "exp": "• Khi mở nắp, áp suất CO₂ trong lon giảm từ 3-4 atm xuống bằng áp suất khí quyển (1 atm) làm độ tan của CO₂ giảm mạnh và cân bằng dịch chuyển theo chiều nghịch giải phóng bọt khí CO₂ trào ra.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "2": [{"q": "Sự điện li là quá trình phân li các chất trong nước tạo thành:", "opts": ["Các ion (cation mang điện dương và anion mang điện âm).", "Các nguyên tử trung hòa.", "Các phân tử khí.", "Chỉ các proton mang điện tích dương."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Sự điện li là quá trình phân li các chất khi tan trong nước tạo thành các ion dẫn điện.<br>• Chất điện li gồm acid, base và muối.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Theo thuyết acid – base của Brønsted – Lowry (1923), acid và base được định nghĩa là:", "opts": ["Acid là chất cho proton (H⁺), base là chất nhận proton (H⁺).", "Acid là chất phân li ra ion H⁺, base là chất phân li ra ion OH⁻.", "Acid là chất nhận electron, base là chất cho electron.", "Acid là hợp chất chứa oxygen, base là hợp chất chứa kim loại."], "ans": 0, "exp": "• <b>Thuyết Brønsted – Lowry:</b> Acid là chất có khả năng cho proton (H⁺); Base là chất có khả năng nhận proton (H⁺).<br>• Định nghĩa này tổng quát hơn thuyết Arrhenius vì áp dụng được cho dung dịch không chứa ion OH⁻ (như dung dịch NH₃, Na₂CO₃...).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét phản ứng trong dung dịch: NH₃ + H₂O ⇌ NH₄⁺ + OH⁻:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Đại lượng pH được xác định theo nồng độ ion H⁺ theo công thức nào sau đây?", "opts": ["pH = -lg[H⁺]", "pH = lg[H⁺]", "pH = 14 + lg[H⁺]", "pH = -ln[H⁺]"], "ans": 0, "exp": "• <b>Định nghĩa Sørensen:</b> pH = -lg[H⁺], tương đương [H⁺] = 10^(-pH).<br>• Ở 25 °C: Môi trường trung tính có pH = 7 ([H⁺] = 10⁻⁷ M); Môi trường acid có pH < 7 ([H⁺] > 10⁻⁷ M); Môi trường base có pH > 7 ([H⁺] < 10⁻⁷ M).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các dung dịch (Cột A) với khoảng giá trị pH tương ứng ở 25 °C (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Dung dịch HCl 0,01 M ➔ A. pH = 2 (môi trường acid mạnh).", "1. Dung dịch HCl 0,01 M ➔ B. pH = 7 (môi trường trung tính).", "1. Dung dịch HCl 0,01 M ➔ C. pH = 12 (môi trường base mạnh).", "1. Dung dịch HCl 0,01 M ➔ D. pH ≈ 1,5 - 2,5 (acid mạnh nhờ HCl)."], "ans": 0, "exp": "• HCl 0,01 M: [H⁺] = 10⁻² M -> pH = 2.<br>• Nước cất: pH = 7.<br>• NaOH 0,01 M: [OH⁻] = 10⁻² M -> pOH = 2 -> pH = 12.<br>• Dạ dày: pH 1,5 - 2,5.", "svgGraph": null}, {"q": "Chất nào sau đây là chất điện li YẾU, chỉ phân li một phần thành ion trong dung dịch nước?", "opts": ["Acetic acid (CH₃COOH)", "Hydrochloric acid (HCl)", "Sodium hydroxide (NaOH)", "Sodium chloride (NaCl)"], "ans": 0, "exp": "• CH₃COOH là acid hữu cơ yếu, trong dung dịch chỉ có một phần nhỏ phân tử phân li: CH₃COOH ⇌ CH₃COO⁻ + H⁺.<br>• HCl, NaOH, NaCl là các chất điện li mạnh, phân li hoàn toàn 100% thành ion.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các chất chỉ thị màu pH phổ biến trong phòng thí nghiệm:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chuẩn độ acid – base là phương pháp dùng để xác định đại lượng nào của một dung dịch acid hoặc base chưa biết?", "opts": ["Nồng độ mol chính xác của dung dịch.", "Khối lượng riêng của dung dịch.", "Nhiệt độ sôi của dung dịch.", "Độ dẫn điện tuyệt đối."], "ans": 0, "exp": "• Chuẩn độ acid - base là kĩ thuật chuẩn độ thể tích: dùng một dung dịch chuẩn đã biết chính xác nồng độ (trên buret) để chuẩn độ thể tích xác định của dung dịch cần xác định nồng độ (dưới bình tam giác) đến điểm tương đương (nhận biết qua chất chỉ thị màu).<br>• Áp dụng công thức: C_A · V_A = C_B · V_B.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Theo thuyết Brønsted – Lowry, acid là chất [ ... ] proton H⁺, base là chất [ ... ] proton H⁺. Tích số ion của nước ở 25 °C là K_w = [H⁺] · [OH⁻] = [ ... ]. Thang đo pH tiện dụng thường có giá trị từ [ ... ].", "opts": ["cho — nhận — 10⁻¹⁴ — 0 đến 14", "0 đến 14 — 10⁻¹⁴ — nhận — cho", "nhận — 10⁻¹⁴ — 0 đến 14 — cho", "10⁻¹⁴ — 0 đến 14 — cho — nhận"], "ans": 0, "exp": "• Acid cho, base nhận.<br>• K_w = 10⁻¹⁴.<br>• Thang pH từ 0 đến 14.", "svgGraph": null}, {"q": "Trộn 50 mL dung dịch HCl 0,1 M với 50 mL dung dịch NaOH 0,1 M ở 25 °C. Giá trị pH của dung dịch thu được sau phản ứng là:", "opts": ["7 (trung tính)", "2", "12", "1"], "ans": 0, "exp": "• Số mol H⁺ = 0,05 · 0,1 = 0,005 mol.<br>• Số mol OH⁻ = 0,05 · 0,1 = 0,005 mol.<br>• Phản ứng trung hòa hoàn toàn: H⁺ + OH⁻ -> H₂O.<br>• Hai chất phản ứng vừa đủ tạo dung dịch muối ăn NaCl trung tính có pH = 7.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "3": [{"q": "Cho phản ứng tổng hợp lưu huỳnh trioxide trong công nghiệp: 2SO₂(g) + O₂(g) ⇌ 2SO₃(g)   ΔrH°₂₉₈ = -198 kJ. Biện pháp nào sau đây làm tăng hiệu suất tạo SO₃?", "opts": ["Tăng áp suất và dùng dư không khí (tăng nồng độ O₂).", "Tăng nhiệt độ của lò phản ứng lên rất cao.", "Giảm nồng độ khí SO₂.", "Giảm áp suất chung của hệ."], "ans": 0, "exp": "• Phản ứng theo chiều thuận làm giảm số mol khí (từ 3 mol xuống 2 mol) ⇒ Tăng áp suất làm cân bằng dịch chuyển sang chiều thuận.<br>• Dùng dư O₂ (không khí) làm cân bằng chuyển dịch sang chiều thuận để tiêu thụ bớt O₂.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Biết hằng số cân bằng K_C của phản ứng H₂(g) + I₂(g) ⇌ 2HI(g) ở 430 °C là 50. Nếu nồng độ cân bằng của H₂ và I₂ đều là 0,1 M thì nồng độ cân bằng của HI là:", "opts": ["≈ 0,71 M (√0,5 M)", "5,0 M", "0,5 M", "0,25 M"], "ans": 0, "exp": "• Biểu thức: K_C = [HI]² / ([H₂] · [I₂]) = 50.<br>• Thay số: [HI]² / (0,1 · 0,1) = 50 ⇒ [HI]² = 50 · 0,01 = 0,5 ⇒ [HI] = √0,5 ≈ 0,707 M.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu tổng kết về pH và cân bằng điện li:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Một học sinh thực hiện chuẩn độ 20,0 mL dung dịch HCl chưa biết nồng độ bằng dung dịch chuẩn NaOH 0,10 M với chỉ thị phenolphthalein. Khi màu dung dịch vừa chuyển sang hồng nhạt bền trong 30 giây thì thể tích NaOH trên buret đã dùng là 25,0 mL. Nồng độ mol của dung dịch HCl là:", "opts": ["0,125 M", "0,080 M", "0,100 M", "0,250 M"], "ans": 0, "exp": "• Phản ứng: HCl + NaOH -> NaCl + H₂O.<br>• Tại điểm tương đương: n_HCl = n_NaOH<br>⇒ C_HCl · V_HCl = C_NaOH · V_NaOH<br>⇒ C_HCl = (0,10 · 25,0) / 20,0 = 0,125 M.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các loại muối (Cột A) với môi trường dung dịch tương ứng trong nước do sự thủy phân (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. NaCl (tạo bởi base mạnh và acid mạnh) ➔ A. pH = 7 (môi trường trung tính).", "1. NaCl (tạo bởi base mạnh và acid mạnh) ➔ B. pH < 7 (môi trường acid do NH₄⁺ thủy phân tạo H⁺).", "1. NaCl (tạo bởi base mạnh và acid mạnh) ➔ C. pH > 7 (môi trường base do CH₃COO⁻ nhận H⁺ tạo OH⁻).", "1. NaCl (tạo bởi base mạnh và acid mạnh) ➔ D. pH > 7 (môi trường base khá mạnh, quỳ hóa xanh)."], "ans": 0, "exp": "• Hiện tượng thủy phân của muối theo bản chất ion acid/base liên hợp.", "svgGraph": null}, {"q": "Chất nào sau đây khi hòa tan trong nước đóng vai trò là một chất lưỡng tính (amphoteric) theo Brønsted – Lowry (vừa có thể cho H⁺ vừa có thể nhận H⁺)?", "opts": ["Ion bicarbonate (HCO₃⁻)", "Ion sulfate (SO₄²⁻)", "Ion ammonium (NH₄⁺)", "Ion chloride (Cl⁻)"], "ans": 0, "exp": "• HCO₃⁻ + H⁺ ⇌ H₂CO₃ (nhận H⁺ -> thể hiện tính base).<br>• HCO₃⁻ ⇌ H⁺ + CO₃²⁻ (cho H⁺ -> thể hiện tính acid).<br>• Do đó HCO₃⁻ là ion lưỡng tính theo thuyết Brønsted.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về cân bằng hóa học trong tự nhiên và công nghiệp:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Giá trị pH của dung dịch Ba(OH)₂ 0,005 M ở 25 °C là bao nhiêu?", "opts": ["12", "11", "2", "7"], "ans": 0, "exp": "• Ba(OH)₂ -> Ba²⁺ + 2OH⁻.<br>• [OH⁻] = 2 · 0,005 = 0,01 M = 10⁻² M.<br>• pOH = -lg[OH⁻] = 2.<br>• pH = 14 - pOH = 14 - 2 = 12.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Hằng số cân bằng nồng độ K_C cho biết mức độ xảy ra của phản ứng [ ... ]. Chuẩn độ acid – base dựa trên phản ứng [ ... ] giữa ion H⁺ và ion OH⁻. Điểm mà tại đó lượng acid và lượng base vừa đủ tác dụng hết với nhau gọi là điểm [ ... ], được nhận biết bằng chất [ ... ].", "opts": ["thuận nghịch — trung hòa — tương đương — chỉ thị màu", "chỉ thị màu — tương đương — trung hòa — thuận nghịch", "trung hòa — tương đương — chỉ thị màu — thuận nghịch", "tương đương — chỉ thị màu — thuận nghịch — trung hòa"], "ans": 0, "exp": "• Phản ứng thuận nghịch.<br>• Phản ứng trung hòa.<br>• Điểm tương đương, chất chỉ thị màu.", "svgGraph": null}, {"q": "Cho phản ứng tỏa nhiệt: 2CO(g) + O₂(g) ⇌ 2CO₂(g)   ΔH < 0. Để thu được nhiều CO₂ nhất ở trạng thái cân bằng, cần khống chế điều kiện như thế nào?", "opts": ["Nhiệt độ thấp và áp suất cao.", "Nhiệt độ cao và áp suất thấp.", "Nhiệt độ cao và áp suất cao.", "Nhiệt độ thấp và áp suất thấp."], "ans": 0, "exp": "• Chiều thuận tỏa nhiệt (ΔH < 0) ⇒ cần hạ thấp nhiệt độ.<br>• Chiều thuận giảm số mol khí (từ 3 mol xuống 2 mol) ⇒ cần tăng áp suất cao.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "4": [{"q": "Khí Nitrogen chiếm khoảng bao nhiêu phần trăm thể tích của khí quyển Trái Đất?", "opts": ["Khoảng 78%", "Khoảng 21%", "Khoảng 1%", "Khoảng 50%"], "ans": 0, "exp": "• Khí quyển Trái Đất chứa khoảng 78% N₂, 21% O₂ và 1% các khí khác (Ar, CO₂, hơi nước...).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ở nhiệt độ thường, đơn chất nitrogen khá trơ về mặt hóa học là do nguyên nhân nào sau đây?", "opts": ["Phân tử N₂ có liên kết ba N≡N rất bền với năng lượng liên kết rất lớn (945 kJ/mol).", "Nguyên tử nitrogen có bán kính quá lớn.", "Nitrogen không có electron độc thân.", "Nitrogen là chất khí không màu, không mùi."], "ans": 0, "exp": "• Liên kết ba N≡N gồm 1 liên kết σ và 2 liên kết π có năng lượng liên kết 945 kJ/mol cực lớn, do đó ở điều kiện thường rất khó bị phân cắt, làm N₂ rất trơ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng hóa học thể hiện tính chất của nitrogen:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Hiện tượng sấm sét trong cơn mưa dông cung cấp một lượng phân đạm tự nhiên cho cây trồng dưới dạng ion nào?", "opts": ["Ion nitrate (NO₃⁻)", "Ion ammonium (NH₄⁺)", "Khí N₂ hòa tan", "Ion nitrite (NO₂⁻)"], "ans": 0, "exp": "• Tia sét kích hoạt: N₂ + O₂ -> 2NO.<br>• 2NO + O₂ -> 2NO₂.<br>• 4NO₂ + O₂ + 2H₂O -> 4HNO₃.<br>• HNO₃ rơi xuống đất tạo muối nitrate (NO₃⁻) là nguồn phân đạm tự nhiên vô cùng quý giá cho cây trồng ('Lúa chiêm lấp ló đầu bờ / Hễ nghe tiếng sấm phất cờ mà lên').<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các ứng dụng của nitrogen (Cột A) với nguyên nhân / đặc tính tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Bơm khí N₂ vào gói bim bim, bánh kẹo ➔ A. Môi trường trơ đẩy O₂, ngăn oxi hóa dầu mỡ và giữ giòn thực phẩm.", "1. Bơm khí N₂ vào gói bim bim, bánh kẹo ➔ B. Nhiệt độ sôi rất thấp (-196 °C) dùng để bảo quản tinh trùng, mô, phôi.", "1. Bơm khí N₂ vào gói bim bim, bánh kẹo ➔ C. Nguyên liệu sản xuất phân bón đạm cho nông nghiệp.", "1. Bơm khí N₂ vào gói bim bim, bánh kẹo ➔ D. Khí trơ, ít bị dãn nở nhiệt theo nhiệt độ giúp áp suất lốp ổn định."], "ans": 0, "exp": "• Các ứng dụng quan trọng của khí N₂ và N₂ lỏng.", "svgGraph": null}, {"q": "Trong phòng thí nghiệm, khí nitrogen tinh khiết thường được điều chế bằng cách nhiệt phân muối nào sau đây?", "opts": ["Ammonium nitrite: NH₄NO₂ --t°--> N₂↑ + 2H₂O", "Ammonium nitrate: NH₄NO₃ --t°--> N₂O + 2H₂O", "Ammonium carbonate: (NH₄)₂CO₃ --t°--> 2NH₃ + CO₂ + H₂O", "Ammonium chloride: NH₄Cl --t°--> NH₃ + HCl"], "ans": 0, "exp": "• Nhiệt phân dung dịch bão hòa hỗn hợp NaNO₂ và NH₄Cl (tạo NH₄NO₂) tạo khí N₂:<br>NH₄NO₂ --t°--> N₂↑ + 2H₂O.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các số oxi hóa có thể có của nguyên tố Nitrogen trong các hợp chất:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Kim loại nào sau đây tác dụng với khí N₂ ngay ở nhiệt độ thường mà không cần đun nóng?", "opts": ["Lithium (Li)", "Magnesium (Mg)", "Aluminium (Al)", "Iron (Fe)"], "ans": 0, "exp": "• Lithium là kim loại duy nhất tác dụng với N₂ ở nhiệt độ phòng: 6Li + N₂ -> 2Li₃N.<br>• Các kim loại khác như Mg, Al chỉ tác dụng với N₂ ở nhiệt độ rất cao.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Phân tử nitrogen gồm hai nguyên tử liên kết với nhau bằng một liên kết [ ... ]. Ở điều kiện thường, nitrogen là chất khí [ ... ] màu, không mùi, nhẹ hơn không khí và rất [ ... ] về mặt hóa học. Ở nhiệt độ cao, nitrogen vừa thể hiện tính [ ... ] vừa thể hiện tính khử.", "opts": ["ba (N≡N) — không — trơ — oxi hóa", "oxi hóa — trơ — không — ba (N≡N)", "không — trơ — oxi hóa — ba (N≡N)", "trơ — oxi hóa — ba (N≡N) — không"], "ans": 0, "exp": "• Liên kết ba N≡N, không màu, trơ hóa học, tính oxi hóa.", "svgGraph": null}, {"q": "Nhiệt độ sôi của nitrogen lỏng ở áp suất tiêu chuẩn là bao nhiêu?", "opts": ["-196 °C", "-78,5 °C", "0 °C", "-273 °C"], "ans": 0, "exp": "• Nitrogen hóa lỏng ở -195,8 °C (xấp xỉ -196 °C), là môi trường siêu lạnh dùng trong bảo quản sinh học và công nghệ lạnh sâu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "5": [{"q": "Phân tử ammonia (NH₃) có cấu trúc hình học và đặc điểm liên kết nào sau đây?", "opts": ["Hình chóp tam giác, phân tử phân cực mạnh, nguyên tử N còn một cặp electron chưa liên kết.", "Hình tam giác đều phẳng, không phân cực.", "Hình tứ diện đều, không phân cực.", "Cấu trúc đường thẳng đối xứng."], "ans": 0, "exp": "• Nguyên tử N lai hóa sp³, 3 obitan lai hóa xen phủ với 3 nguyên tử H tạo hình chóp tam giác, đỉnh là cặp electron tự do chưa chia của N.<br>• Cặp electron tự do này quyết định tính base và khả năng tạo phức của NH₃.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khí ammonia tan cực kì nhiều trong nước (ở 20 °C, 1 lít nước hòa tan khoảng 700 lít khí NH₃) chủ yếu là do:", "opts": ["Phân tử NH₃ phân cực mạnh và tạo được liên kết hydrogen bền với phân tử nước.", "Khí NH₃ nhẹ hơn không khí.", "Khí NH₃ phản ứng hoàn toàn tạo kết tủa.", "Do áp suất không khí nén khí vào nước."], "ans": 0, "exp": "• Nhờ tạo liên kết hydrogen mạnh giữa N–H···O và O–H···N với nước, NH₃ có độ tan khổng lồ trong nước, tạo dung dịch có tính base yếu.<br>• Thí nghiệm đài phun nước ammonia chứng minh tính tan siêu việt này.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các tính chất hóa học của khí ammonia (NH₃):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khi sục từ từ khí NH₃ đến dư vào dung dịch Copper(II) sulfate (CuSO₄), hiện tượng quan sát được là gì?", "opts": ["Ban đầu xuất hiện kết tủa xanh nhạt Cu(OH)₂, sau đó kết tủa tan dần tạo dung dịch phức chất màu xanh lam thẫm [Cu(NH₃)₄]SO₄.", "Xuất hiện kết tủa màu nâu đỏ không tan.", "Không có hiện tượng gì xảy ra.", "Dung dịch chuyển sang màu đỏ rực."], "ans": 0, "exp": "• Giai đoạn 1: 2NH₃ + 2H₂O + CuSO₄ -> Cu(OH)₂↓ (xanh lam nhạt) + (NH₄)₂SO₄.<br>• Giai đoạn 2: Cu(OH)₂ + 4NH₃ -> [Cu(NH₃)₄](OH)₂ (dung dịch phức chất màu xanh lam thẫm đặc trưng).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các muối ammonium (Cột A) với sản phẩm phân hủy nhiệt tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. NH₄Cl --t°--> ➔ A. NH₃↑ + HCl↑ (khí bay lên rồi tái kết hợp thành muối bám ở miệng ống nghiệm).", "1. NH₄Cl --t°--> ➔ B. NH₃↑ + CO₂↑ + H₂O (làm bánh phồng xốp).", "1. NH₄Cl --t°--> ➔ C. N₂↑ + 2H₂O.", "1. NH₄Cl --t°--> ➔ D. N₂O↑ + 2H₂O."], "ans": 0, "exp": "• Đặc tính nhiệt phân của các muối ammonium.", "svgGraph": null}, {"q": "Thuốc thử dùng để nhận biết ion ammonium (NH₄⁺) trong dung dịch là:", "opts": ["Dung dịch kiềm mạnh (như NaOH, KOH), đun nóng nhẹ sinh khí có mùi khai làm xanh quỳ tím ẩm.", "Dung dịch BaCl₂ tạo kết tủa trắng.", "Dung dịch AgNO₃ tạo kết tủa vàng.", "Dung dịch acid HCl sinh khí không màu."], "ans": 0, "exp": "• Phản ứng nhận biết: NH₄⁺ + OH⁻ --t°--> NH₃↑ (mùi khai) + H₂O.<br>• Đặt mẩu quỳ tím ẩm ở miệng ống nghiệm thấy quỳ chuyển sang màu xanh.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các đặc điểm của muối ammonium (NH₄⁺):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chất nào sau đây được dùng làm bột nở trong sản xuất bánh bao, bánh quy nhờ khi nung nóng sinh ra các khí làm nở bột mà không để lại cặn độc?", "opts": ["Ammonium hydrogen carbonate (NH₄HCO₃)", "Ammonium nitrate (NH₄NO₃)", "Sodium chloride (NaCl)", "Calcium carbonate (CaCO₃)"], "ans": 0, "exp": "• NH₄HCO₃ (bột khai) bị nhiệt phân hoàn toàn ở 60 °C: NH₄HCO₃ --t°--> NH₃↑ + CO₂↑ + H₂O↑ giải phóng hoàn toàn thành các chất khí làm bánh nở xốp không để lại cặn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Khí ammonia có công thức phân tử là [ ... ], có mùi [ ... ] đặc trưng, nhẹ hơn không khí. Do còn một cặp electron chưa liên kết trên nguyên tử nitrogen nên ammonia có tính [ ... ] yếu và có khả năng tạo phức chất. Trong phân tử ammonia, nitrogen có số oxi hóa -3 nên thể hiện tính [ ... ].", "opts": ["NH₃ — khai — base — khử", "khử — base — khai — NH₃", "khai — base — khử — NH₃", "base — khử — NH₃ — khai"], "ans": 0, "exp": "• NH₃, mùi khai, tính base, tính khử.", "svgGraph": null}, {"q": "Trong quá trình sản xuất nitric acid (HNO₃) từ ammonia theo phương pháp Ostwald, giai đoạn đầu tiên là oxi hóa NH₃ bằng O₂ không khí có xúc tác lưới platin (Pt) ở 850 °C tạo ra khí nào?", "opts": ["Khí Nitrogen monoxide (NO): 4NH₃ + 5O₂ --Pt, 850°C--> 4NO + 6H₂O", "Khí Nitrogen dioxide (NO₂)", "Khí Dinitrogen monoxide (N₂O)", "Khí Nitrogen (N₂)"], "ans": 0, "exp": "• 4NH₃ + 5O₂ --Pt, 850°C--> 4NO + 6H₂O.<br>• Sau đó: 2NO + O₂ -> 2NO₂ và 4NO₂ + O₂ + 2H₂O -> 4HNO₃.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "6": [{"q": "Các oxide của nitrogen như NO, NO₂ được gọi chung là NOx. Nguồn phát sinh NOx chủ yếu trong đời sống và công nghiệp là từ:", "opts": ["Khí thải từ các phương tiện giao thông đốt nhiên liệu ở nhiệt độ cao và các nhà máy nhiệt điện.", "Quá trình quang hợp của cây xanh.", "Sự bay hơi của nước biển.", "Quá trình hô hấp của động vật."], "ans": 0, "exp": "• Ở nhiệt độ cao trong buồng đốt động cơ xe máy, ô tô và lò đốt nhiệt điện, N₂ và O₂ trong không khí phản ứng tạo NO, sau đó bị oxi hóa thành NO₂.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Mưa acid là hiện tượng nước mưa có độ pH nhỏ hơn bao nhiêu?", "opts": ["pH < 5,6", "pH < 7,0", "pH < 3,0", "pH < 8,0"], "ans": 0, "exp": "• Nước mưa bình thường có pH khoảng 5,6 do hòa tan CO₂ khí quyển tạo acid yếu H₂CO₃.<br>• Khi nước mưa hòa tan các khí ô nhiễm SO₂ và NOx tạo H₂SO₄ và HNO₃ làm pH rơi xuống dưới 5,6 thì được gọi là mưa acid.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các tác hại nghiêm trọng của hiện tượng mưa acid:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nitric acid (HNO₃) tinh khiết là chất lỏng không màu, bốc khói mạnh trong không khí ẩm. Dung dịch HNO₃ đậm đặc để lâu ngày trong phòng thí nghiệm thường có màu vàng là do nguyên nhân nào?", "opts": ["HNO₃ bị phân hủy chậm dưới ánh sáng tạo khí NO₂ màu nâu đỏ hòa tan vào acid: 4HNO₃ -> 4NO₂ + O₂ + 2H₂O.", "Do acid bị nhiễm bụi bẩn từ môi trường.", "Do acid tác dụng với thủy tinh chai đựng.", "Do acid hút ẩm từ không khí."], "ans": 0, "exp": "• Dưới tác dụng của ánh sáng và nhiệt độ: 4HNO₃ -> 4NO₂ + O₂ + 2H₂O.<br>• Khí NO₂ màu nâu đỏ tan lại trong acid lỏng làm dung dịch chuyển sang màu vàng nâu.<br>• Do đó cần bảo quản HNO₃ trong chai thủy tinh tối màu (màu nâu).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các phản ứng của kim loại với dung dịch acid HNO₃ (Cột A) với sản phẩm khử tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Cu + 4HNO₃ đặc -> Cu(NO₃)₂ + ... + 2H₂O ➔ A. 2NO₂↑ (khí màu nâu đỏ).", "1. Cu + 4HNO₃ đặc -> Cu(NO₃)₂ + ... + 2H₂O ➔ B. 2NO↑ (khí không màu hóa nâu ngoài không khí).", "1. Cu + 4HNO₃ đặc -> Cu(NO₃)₂ + ... + 2H₂O ➔ C. NH₄NO₃ (muối ammonium không có khí thoát ra).", "1. Cu + 4HNO₃ đặc -> Cu(NO₃)₂ + ... + 2H₂O ➔ D. Bị thụ động hóa (tạo màng oxit bền bảo vệ kim loại)."], "ans": 0, "exp": "• Đặc tính oxi hóa cực mạnh của HNO₃ và hiện tượng thụ động hóa Fe, Al.", "svgGraph": null}, {"q": "Kim loại nào sau đây KHÔNG tác dụng được với dung dịch acid nitric (HNO₃) ở bất kì nồng độ nào?", "opts": ["Vàng (Gold - Au) và Bạch kim (Platinum - Pt)", "Đồng (Copper - Cu)", "Bạc (Silver - Ag)", "Sắt (Iron - Fe)"], "ans": 0, "exp": "• HNO₃ oxi hóa được hầu hết kim loại trừ Au và Pt.<br>• Để hòa tan Au và Pt người ta phải dùng hỗn hợp nước cường toan (Aqua regia gồm 1 thể tích HNO₃ đặc và 3 thể tích HCl đặc).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính chất hóa học của acid nitric (HNO₃):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khói quang hóa (photochemical smog) xuất hiện ở các thành phố lớn vào buổi sáng nhiều nắng là do phản ứng của khí NOx với:", "opts": ["Hợp chất hữu cơ dễ bay hơi (VOCs) dưới tác dụng của ánh sáng mặt trời tạo ozone tầng đối lưu và PAN gây cay mắt.", "Khí O₂ tạo sương mù tự nhiên.", "Bụi cát sa mạc.", "Hơi nước đóng băng."], "ans": 0, "exp": "• Khói quang hóa là hỗn hợp chất ô nhiễm thứ cấp (O₃, PAN, aldehyde...) hình thành khi NOx và hydrocarbon (VOC) phản ứng quang hóa dưới ánh nắng, gây ngạt thở, cay mắt và kích ứng đường hô hấp.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Mưa acid có giá trị pH nhỏ hơn [ ... ], được hình thành chủ yếu do hai khí ô nhiễm là [ ... ] và các oxide của nitrogen (NOx). Acid nitric HNO₃ là một acid mạnh và là chất [ ... ] rất mạnh. Sắt và nhôm bị [ ... ] trong dung dịch HNO₃ đặc, nguội.", "opts": ["5,6 — SO₂ — oxi hóa — thụ động hóa", "thụ động hóa — oxi hóa — SO₂ — 5,6", "SO₂ — oxi hóa — thụ động hóa — 5,6", "oxi hóa — thụ động hóa — 5,6 — SO₂"], "ans": 0, "exp": "• pH < 5,6, SO₂, chất oxi hóa mạnh, thụ động hóa.", "svgGraph": null}, {"q": "Cho 1,92 gam Cu tác dụng hết với dung dịch HNO₃ loãng dư thu được V lít khí NO (đktc, sản phẩm khử duy nhất). Giá trị của V là:", "opts": ["0,4958 L (0,02 mol)", "0,448 L", "0,224 L", "0,896 L"], "ans": 0, "exp": "• n_Cu = 1,92 / 64 = 0,03 mol.<br>• Phản ứng: 3Cu + 8HNO₃ -> 3Cu(NO₃)₂ + 2NO + 4H₂O.<br>• n_NO = (2/3) · n_Cu = 0,02 mol.<br>• Theo chuẩn SGK 2018 (1 bar, 25 °C): V = 0,02 · 24,79 = 0,4958 L.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "7": [{"q": "Đơn chất sulfur (lưu huỳnh) ở điều kiện thường là chất rắn màu gì và có bao nhiêu dạng thù hình tinh thể chính?", "opts": ["Chất rắn màu vàng, có 2 dạng thù hình chính là sulfur tà phương (S_α) và sulfur đơn tà (S_β).", "Chất rắn màu đen, chỉ có 1 dạng thù hình.", "Chất lỏng màu nâu đỏ.", "Chất khí màu lục nhạt."], "ans": 0, "exp": "• Sulfur là chất rắn màu vàng, không tan trong nước, tan tốt trong dung môi không phân cực như benzen, CS₂.<br>• Có 2 dạng thù hình tinh thể chuyển hóa qua lại ở 95,5 °C: S_α (tà phương) và S_β (đơn tà).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Kim loại nào sau đây có thể phản ứng với bột lưu huỳnh (sulfur) ngay ở nhiệt độ thường, được dùng để thu gom thủy ngân bị rơi vỡ nhiệt kế?", "opts": ["Thủy ngân (Mercury - Hg): Hg + S -> HgS", "Sắt (Iron - Fe)", "Đồng (Copper - Cu)", "Nhôm (Aluminium - Al)"], "ans": 0, "exp": "• Thủy ngân là kim loại lỏng rất độc, dễ bay hơi. Khi nhiệt kế thủy ngân bị vỡ, người ta rắc bột lưu huỳnh lên để tạo chất rắn HgS không bay hơi và không độc, thu gom an toàn: Hg + S -> HgS.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính chất hóa học của sulfur (S, Z = 16, số oxi hóa 0):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khí sulfur dioxide (SO₂) có tính chất hóa học đặc trưng nào sau đây?", "opts": ["Vừa có tính khử, vừa có tính oxi hóa và là một acidic oxide.", "Chỉ có tính oxi hóa mạnh.", "Chỉ có tính khử mạnh.", "Là một basic oxide."], "ans": 0, "exp": "• Trong SO₂, nguyên tử S có số oxi hóa +4 (trung gian giữa -2, 0 và +6):<br>• Tác dụng với chất oxi hóa (như Br₂, KMnO₄, O₂): S⁺⁴ -> S⁺⁶ (tính khử).<br>• Tác dụng với chất khử mạnh (như H₂S, Mg): S⁺⁴ -> S⁰ (tính oxi hóa).<br>• Tác dụng với nước tạo acid H₂SO₃ (acidic oxide).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các hiện tượng thí nghiệm với khí SO₂ (Cột A) với bản chất hóa học tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Dẫn SO₂ vào dung dịch nước bromine (Br₂ màu vàng nâu) ➔ A. Dung dịch Br₂ bị mất màu hoàn toàn (SO₂ thể hiện tính khử).", "1. Dẫn SO₂ vào dung dịch nước bromine (Br₂ màu vàng nâu) ➔ B. Xuất hiện váng kết tủa màu vàng (S) (SO₂ thể hiện tính oxi hóa).", "1. Dẫn SO₂ vào dung dịch nước bromine (Br₂ màu vàng nâu) ➔ C. Xuất hiện kết tủa trắng đục CaSO₃ (tính acidic oxide).", "1. Dẫn SO₂ vào dung dịch nước bromine (Br₂ màu vàng nâu) ➔ D. Tác dụng tẩy trắng và diệt nấm mốc, chống ôi thiu."], "ans": 0, "exp": "• Các phản ứng đặc trưng của SO₂.", "svgGraph": null}, {"q": "Dung dịch nước của khí SO₂ (dung dịch sulfurous acid H₂SO₃) làm đổi màu giấy quỳ tím như thế nào?", "opts": ["Làm quỳ tím hóa đỏ, sau đó có thể bị tẩy màu nhạt dần.", "Làm quỳ tím hóa xanh.", "Không đổi màu quỳ tím.", "Làm quỳ tím chuyển sang màu tím sẫm."], "ans": 0, "exp": "• SO₂ tan trong nước tạo acid yếu H₂SO₃ làm quỳ tím hóa đỏ.<br>• Do SO₂ có tính tẩy màu nhẹ nên để lâu mẩu quỳ tím có thể bị nhạt màu dần.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các ứng dụng và tác hại của khí sulfur dioxide (SO₂):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trong phản ứng: SO₂ + Br₂ + 2H₂O -> H₂SO₄ + 2HBr. Vai trò của SO₂ là:", "opts": ["Chất khử (số oxi hóa tăng từ +4 lên +6).", "Chất oxi hóa.", "Môi trường acid.", "Chất xúc tác."], "ans": 0, "exp": "• Số oxi hóa của S trong SO₂ là +4 tăng lên +6 trong H₂SO₄ ⇒ SO₂ là chất khử.<br>• Br₂ có số oxi hóa 0 giảm xuống -1 trong HBr ⇒ Br₂ là chất oxi hóa.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Sulfur là chất rắn màu [ ... ], có hai dạng thù hình là sulfur tà phương và sulfur đơn tà. Khí sulfur dioxide có công thức là [ ... ], mùi xốc độc hại, vừa có tính khử vừa có tính [ ... ]. Một trong những nguồn sinh ra SO₂ lớn nhất trong khí quyển là từ các nhà máy nhiệt điện đốt [ ... ].", "opts": ["vàng — SO₂ — oxi hóa — than đá", "than đá — oxi hóa — SO₂ — vàng", "SO₂ — oxi hóa — than đá — vàng", "oxi hóa — than đá — vàng — SO₂"], "ans": 0, "exp": "• Màu vàng, SO₂, tính oxi hóa, than đá.", "svgGraph": null}, {"q": "Hiện tượng ngộ độc khí SO₂ biểu hiện rõ nhất ở cơ quan nào của cơ thể?", "opts": ["Đường hô hấp (gây co thắt phế quản, khó thở, ho và cay mắt).", "Hệ tiêu hóa.", "Hệ vận động xương khớp.", "Hệ bài tiết thận."], "ans": 0, "exp": "• Khí SO₂ khi hít vào gặp niêm mạc ẩm tạo acid H₂SO₃ gây bỏng rát, co thắt phế quản nghiêm trọng, phù phổi cấp ở nồng độ cao.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "8": [{"q": "Quy tắc an toàn TUYỆT ĐỐI khi pha loãng dung dịch acid sulfuric đậm đặc (H₂SO₄ đặc) trong phòng thí nghiệm là:", "opts": ["Rót từ từ acid đặc vào nước dọc theo đũa thủy tinh và khuấy nhẹ; TUYỆT ĐỐI KHÔNG làm ngược lại.", "Rót nhanh nước vào acid đặc.", "Đổ đồng thời cả nước và acid vào cốc cùng lúc.", "Đun nóng nước trước khi đổ acid vào."], "ans": 0, "exp": "• H₂SO₄ đặc tan trong nước tỏa nhiệt cực kì lớn. Nếu rót nước vào acid đặc, nước nhẹ hơn nổi lên trên bị sôi đột ngột bắn tung tóe kèm theo các giọt acid đặc gây bỏng hóa chất cực kì nguy hiểm.<br>• Phải rót từ từ acid vào lượng lớn nước để nhiệt tỏa ra được nước hấp thụ dần.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Dung dịch acid sulfuric đặc có hai tính chất hóa học nổi bật khác hẳn với acid sulfuric loãng là:", "opts": ["Tính oxi hóa rất mạnh và tính háo nước mãnh liệt.", "Tính khử mạnh và tính bay hơi nhanh.", "Tính base mạnh và tính tẩy màu.", "Chỉ có tính acid yếu."], "ans": 0, "exp": "• H₂SO₄ đặc: S có số oxi hóa cao nhất (+6) nên có tính oxi hóa rất mạnh (oxi hóa được cả Cu, C, S...) và có tính háo nước mãnh liệt (chiếm nước của các hợp chất carbohydrate như đường saccarose làm hóa than đen).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét hiện tượng khi nhỏ H₂SO₄ đặc vào cốc chứa đường kính (saccharose C₁₂H₂₂O₁₁):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Thuốc thử đặc trưng dùng để nhận biết ion sulfate (SO₄²⁻) trong dung dịch là dung dịch chứa ion nào?", "opts": ["Ion Barium (Ba²⁺, như BaCl₂ hoặc Ba(OH)₂) tạo kết tủa trắng BaSO₄ không tan trong acid mạnh.", "Ion Ag⁺ tạo kết tủa vàng.", "Ion Cu²⁺ tạo dung dịch màu xanh.", "Ion Na⁺ không màu."], "ans": 0, "exp": "• Phản ứng nhận biết: Ba²⁺ + SO₄²⁻ -> BaSO₄↓ (màu trắng).<br>• Kết tủa BaSO₄ bền vững không tan trong dung dịch acid mạnh (như HCl, HNO₃).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các muối sulfate (Cột A) với ứng dụng thực tế quan trọng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. CaSO₄·2H₂O (Thạch cao sống) ➔ A. Sản xuất thạch cao nung đúc tượng, bó bột gãy xương, làm trần thạch cao.", "1. CaSO₄·2H₂O (Thạch cao sống) ➔ B. Làm chất cản quang trong chụp X-quang đường tiêu hóa y tế.", "1. CaSO₄·2H₂O (Thạch cao sống) ➔ C. Diệt nấm mốc, rêu tảo trong bể bơi và pha chế thuốc bảo vệ thực vật Bordeaux.", "1. CaSO₄·2H₂O (Thạch cao sống) ➔ D. Dùng làm muối tắm thư giãn cơ bắp và thuốc nhuận tràng y học."], "ans": 0, "exp": "• Các ứng dụng đời sống của các muối sulfate.", "svgGraph": null}, {"q": "Khi cho thanh kim loại Đồng (Cu) vào ống nghiệm chứa dung dịch H₂SO₄ đặc, đun nóng, hiện tượng quan sát được là:", "opts": ["Dung dịch chuyển dần sang màu xanh lam, có bọt khí mùi hắc (SO₂) thoát ra làm mất màu cánh hoa hồng.", "Có khí không màu không mùi (H₂) thoát ra mãnh liệt.", "Thanh đồng tan ra sinh kết tủa màu đỏ gạch.", "Không có bất kì hiện tượng gì xảy ra."], "ans": 0, "exp": "• Phản ứng: Cu + 2H₂SO₄(đặc) --t°--> CuSO₄ (dung dịch xanh) + SO₂↑ (mùi hắc) + 2H₂O.<br>• Đồng tan ra, dung dịch có màu xanh của ion Cu²⁺, khí SO₂ sinh ra có tính tẩy màu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét quá trình sản xuất acid sulfuric trong công nghiệp bằng phương pháp tiếp xúc (Contact process):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Kim loại nào sau đây bị thụ động hóa (không tác dụng) trong dung dịch H₂SO₄ đặc, nguội?", "opts": ["Aluminium (Al) và Iron (Fe)", "Copper (Cu) và Silver (Ag)", "Zinc (Zn) và Magnesium (Mg)", "Calcium (Ca) và Barium (Ba)"], "ans": 0, "exp": "• Al, Fe, Cr bị thụ động hóa trong H₂SO₄ đặc nguội và HNO₃ đặc nguội do tạo màng oxide siêu mỏng, bền vững bảo vệ kim loại.<br>• Do đó có thể dùng xe bồn hoặc thùng chứa bằng thép để vận chuyển H₂SO₄ đặc nguội an toàn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Khi pha loãng acid sulfuric đặc, phải luôn rót từ từ [ ... ] vào [ ... ], không được làm ngược lại. Dung dịch H₂SO₄ đặc có tính [ ... ] rất mạnh và tính háo nước mãnh liệt. Thuốc thử để nhận biết ion SO₄²⁻ là dung dịch muối của [ ... ].", "opts": ["acid — nước — oxi hóa — barium (Ba²⁺)", "barium (Ba²⁺) — oxi hóa — nước — acid", "nước — oxi hóa — barium (Ba²⁺) — acid", "oxi hóa — barium (Ba²⁺) — acid — nước"], "ans": 0, "exp": "• Rót acid vào nước.<br>• Tính oxi hóa mạnh, háo nước.<br>• Thuốc thử Ba²⁺.", "svgGraph": null}, {"q": "Thạch cao nung (CaSO₄·H₂O hoặc CaSO₄·0,5H₂O) khi nhào với nước sẽ đóng rắn nhanh sau vài phút, được ứng dụng nhiều nhất trong lĩnh vực nào sau đây?", "opts": ["Bó bột cố định xương gãy trong y tế và đúc khuôn, nặn tượng mỹ thuật.", "Làm chất tẩy trắng quần áo.", "Làm phân bón kali cho cây trồng.", "Làm pin năng lượng mặt trời."], "ans": 0, "exp": "• CaSO₄·0,5H₂O + 1,5H₂O -> CaSO₄·2H₂O (đóng rắn chắc chắn, dãn nở nhẹ chèn khít khuôn).<br>• Rất phổ biến trong y tế để bó bột định hình xương gãy và làm phào chỉ, trần thạch cao kiến trúc.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "9": [{"q": "Trong các khí sau: N₂, NH₃, NO₂, SO₂. Khí có tính base duy nhất và làm xanh giấy quỳ tím ẩm là:", "opts": ["Ammonia (NH₃)", "Nitrogen (N₂)", "Nitrogen dioxide (NO₂)", "Sulfur dioxide (SO₂)"], "ans": 0, "exp": "• NH₃ là khí duy nhất có tính base trong chương trình hóa học phổ thông, tan trong nước tạo OH⁻ làm quỳ tím hóa xanh.<br>• NO₂ và SO₂ tan trong nước tạo môi trường acid (làm đỏ quỳ). N₂ trơ trung tính.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho phản ứng: 4Zn + 5H₂SO₄(đặc) --t°--> 4ZnSO₄ + H₂S↑ + 4H₂O. Tỉ lệ giữa số phân tử H₂SO₄ đóng vai trò chất oxi hóa và số phân tử H₂SO₄ tham gia phản ứng là:", "opts": ["1 : 5", "5 : 5", "4 : 5", "1 : 4"], "ans": 0, "exp": "• Trong 5 phân tử H₂SO₄ tham gia phản ứng:<br>• 1 phân tử bị khử xuống H₂S (S⁺⁶ + 8e -> S⁻²) đóng vai trò chất oxi hóa.<br>• 4 phân tử H₂SO₄ giữ nguyên số oxi hóa S⁺⁶ tạo 4 phân tử muối ZnSO₄ đóng vai trò môi trường.<br>• Tỉ lệ = 1 : 5.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các cặp chất sau có thể cùng tồn tại trong một dung dịch hay không:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Cho mẩu kim loại Đồng (Cu) lần lượt vào 4 ống nghiệm chứa: (1) Dung dịch HCl; (2) Dung dịch HNO₃ loãng; (3) Dung dịch H₂SO₄ loãng; (4) Dung dịch H₂SO₄ đặc nóng. Đồng tan ra trong các ống nghiệm nào?", "opts": ["Ống (2) và ống (4)", "Ống (1) và ống (3)", "Cả 4 ống nghiệm", "Chỉ ống (2)"], "ans": 0, "exp": "• Cu đứng sau H trong dãy hoạt động hóa học nên không tan trong acid loại 1 (HCl, H₂SO₄ loãng).<br>• Cu tan được trong acid có tính oxi hóa mạnh của gốc acid: HNO₃ loãng (ống 2 sinh NO) và H₂SO₄ đặc nóng (ống 4 sinh SO₂).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các hóa chất ô nhiễm (Cột A) với tác hại môi trường tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Khí SO₂ và NOx ➔ A. Gây hiện tượng mưa acid tàn phá rừng và công trình kiến trúc.", "1. Khí SO₂ và NOx ➔ B. Gây hiện tượng phú dưỡng (Eutrophication) làm tảo nở hoa, cá chết ngạt.", "1. Khí SO₂ và NOx ➔ C. Chiếm hemoglobin trong hồng cầu gây ngạt thở tử vong nhanh chóng.", "1. Khí SO₂ và NOx ➔ D. Kim loại nặng tích tụ sinh học phá hủy hệ thần kinh."], "ans": 0, "exp": "• Các vấn đề môi trường trọng tâm trong Chương 2 Hóa 11.", "svgGraph": null}, {"q": "Phú dưỡng (Eutrophication) là hiện tượng ao, hồ bị ô nhiễm do chứa quá nhiều chất dinh dưỡng khoáng nào?", "opts": ["Nitrogen (dạng NO₃⁻, NH₄⁺) và Phosphorus (dạng PO₄³⁻)", "Chất béo và protein", "Khí Oxygen và Hydrogen", "Muối ăn NaCl"], "ans": 0, "exp": "• Nguồn thải phân bón dư thừa và nước thải sinh hoạt chứa N và P làm tảo, vi khuẩn lam sinh sôi bùng nổ (nở hoa nước), che phủ mặt nước và khi chết thối rữa tiêu thụ hết oxy hòa tan làm cá chết hàng loạt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng oxi hóa – khử của hợp chất chứa nitrogen và sulfur:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chất nào sau đây dùng để nhận biết dung dịch muối ammonium NH₄⁺ và dung dịch muối sắt(III) Fe³⁺ cùng lúc bằng một thuốc thử?", "opts": ["Dung dịch NaOH (NH₄⁺ sinh khí mùi khai, Fe³⁺ sinh kết tủa nâu đỏ Fe(OH)₃)", "Dung dịch BaCl₂", "Dung dịch AgNO₃", "Dung dịch HCl"], "ans": 0, "exp": "• Với NH₄⁺: sinh khí NH₃ mùi khai làm xanh quỳ tím ẩm.<br>• Với Fe³⁺: xuất hiện kết tủa nâu đỏ Fe(OH)₃: Fe³⁺ + 3OH⁻ -> Fe(OH)₃↓.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Nguyên tố nitrogen và sulfur là hai phi kim quan trọng của nhóm [ ... ] và VIA. Khí ammonia có tính [ ... ] yếu. Acid nitric và acid sulfuric đặc đều là những acid có tính [ ... ] rất mạnh. Ion sulfate được nhận biết đặc trưng bằng dung dịch chứa ion [ ... ].", "opts": ["VA — base — oxi hóa — barium (Ba²⁺)", "barium (Ba²⁺) — oxi hóa — base — VA", "base — oxi hóa — barium (Ba²⁺) — VA", "oxi hóa — barium (Ba²⁺) — VA — base"], "ans": 0, "exp": "• Nhóm VA, tính base yếu, oxi hóa mạnh, ion Ba²⁺.", "svgGraph": null}, {"q": "Trong tự nhiên, khoáng vật pirit sắt có công thức hóa học là:", "opts": ["FeS₂ (iron disulfide)", "FeS", "Fe₂O₃", "Fe₃O₄"], "ans": 0, "exp": "• Quặng pyrite sắt có thành phần chính là FeS₂, có ánh kim màu vàng óng ánh như vàng (còn gọi là 'vàng của kẻ ngốc' - fool's gold), là nguyên liệu truyền thống đốt sản xuất SO₂ và H₂SO₄.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "10": [{"q": "Hợp chất hữu cơ là hợp chất của nguyên tố nào sau đây (ngoại trừ CO, CO₂, muối carbonate, cyanide, carbide...)?", "opts": ["Hợp chất của carbon.", "Hợp chất của nitrogen.", "Hợp chất của hydrogen.", "Hợp chất của oxygen."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Hợp chất hữu cơ là hợp chất của carbon (trừ các chất vô cơ đơn giản như CO, CO₂, H₂CO₃, muối carbonate, các muối cyanide, carbide...).<br>• Hóa học hữu cơ là ngành hóa học nghiên cứu các hợp chất hữu cơ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Đặc điểm chung về liên kết hóa học trong phân tử các hợp chất hữu cơ là:", "opts": ["Chủ yếu là liên kết cộng hóa trị (không cực hoặc phân cực ít).", "Chủ yếu là liên kết ion vững chắc.", "Chủ yếu là liên kết kim loại.", "Chỉ gồm liên kết hydrogen."], "ans": 0, "exp": "• Các nguyên tử trong hợp chất hữu cơ (C, H, O, N, S, halogen...) đều là các phi kim nên liên kết giữa chúng chủ yếu là liên kết cộng hóa trị.<br>• Do đó các hợp chất hữu cơ thường có nhiệt độ nóng chảy, nhiệt độ sôi thấp và dễ cháy hơn hợp chất vô cơ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về phân loại hợp chất hữu cơ:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nhóm nguyên tử gây ra những phản ứng hóa học đặc trưng cho một phân tử hợp chất hữu cơ được gọi là:", "opts": ["Nhóm chức (Functional group).", "Mạch carbon.", "Gốc hydrocarbon.", "Đồng phân."], "ans": 0, "exp": "• Nhóm chức là nhóm nguyên tử quyết định tính chất hóa học đặc trưng của phân tử hữu cơ.<br>• Ví dụ: nhóm -OH (alcohol), nhóm -CHO (aldehyde), nhóm -COOH (carboxylic acid), nhóm -NH₂ (amine)...<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép công thức nhóm chức (Cột A) với tên gọi loại hợp chất hữu cơ tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Nhóm –OH ➔ A. Alcohol (rượu).", "1. Nhóm –OH ➔ B. Aldehyde.", "1. Nhóm –OH ➔ C. Carboxylic acid.", "1. Nhóm –OH ➔ D. Ester."], "ans": 0, "exp": "• Các nhóm chức cơ bản của hóa học hữu cơ.", "svgGraph": null}, {"q": "Phương pháp phổ hồng ngoại (IR - Infrared Spectroscopy) dùng để xác định đại lượng nào trong nghiên cứu cấu trúc hợp chất hữu cơ?", "opts": ["Xác định các nhóm chức có mặt trong phân tử dựa trên tín hiệu số sóng hấp thụ đặc trưng.", "Xác định chính xác số lượng nguyên tử carbon.", "Xác định nhiệt độ sôi của chất.", "Xác định khối lượng mol phân tử."], "ans": 0, "exp": "• Phổ IR ghi nhận dao động hóa trị của các liên kết: dải hấp thụ rộng quanh 3300 cm⁻¹ đặc trưng cho nhóm -OH; đỉnh nhọn mạnh quanh 1700 cm⁻¹ đặc trưng cho nhóm carbonyl >C=O.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các hợp chất sau: CH₄, C₂H₅OH, NaHCO₃, CaCO₃, C₆H₁₂O₆ (glucose):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chất nào sau đây thuộc loại hợp chất hydrocarbon no mạch hở?", "opts": ["Propane (C₃H₈)", "Ethylene (C₂H₄)", "Acetylene (C₂H₂)", "Benzene (C₆H₆)"], "ans": 0, "exp": "• Propane C₃H₈ có công thức CnH2n+2 (n = 3), trong phân tử chỉ chứa các liên kết đơn C–C và C–H ⇒ hydrocarbon no (alkane).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Hợp chất hữu cơ là hợp chất của [ ... ]. Liên kết trong phân tử hữu cơ chủ yếu là liên kết [ ... ]. Nhóm nguyên tử quyết định tính chất hóa học đặc trưng của phân tử gọi là [ ... ]. Phương pháp phổ [ ... ] (IR) giúp xác định các nhóm chức có mặt trong phân tử.", "opts": ["carbon — cộng hóa trị — nhóm chức — hồng ngoại", "hồng ngoại — nhóm chức — cộng hóa trị — carbon", "cộng hóa trị — nhóm chức — hồng ngoại — carbon", "nhóm chức — hồng ngoại — carbon — cộng hóa trị"], "ans": 0, "exp": "• Carbon, cộng hóa trị, nhóm chức, hồng ngoại IR.", "svgGraph": null}, {"q": "Chất hữu cơ đầu tiên được tổng hợp nhân tạo trong phòng thí nghiệm từ các chất vô cơ (bởi Friedrich Wöhler năm 1828) đánh đổ thuyết 'lực sống' là:", "opts": ["Urea ((NH₂)₂CO)", "Methane (CH₄)", "Acetic acid (CH₃COOH)", "Ethanol (C₂H₅OH)"], "ans": 0, "exp": "• Năm 1828, Wöhler nhiệt phân ammonium cyanate NH₄OCN (chất vô cơ) thu được urea (NH₂)₂CO (chất hữu cơ có trong nước tiểu).<br>• Đây là mốc lịch sử vĩ đại khai sinh ngành tổng hợp hữu cơ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "11": [{"q": "Phương pháp chưng cất (distillation) dùng để tách các chất lỏng ra khỏi hỗn hợp dựa trên sự khác nhau về yếu tố nào?", "opts": ["Nhiệt độ sôi của các chất trong hỗn hợp ở một áp suất xác định.", "Độ tan trong các dung môi không trộn lẫn.", "Kích thước hạt phân tử.", "Màu sắc của các chất."], "ans": 0, "exp": "• <b>Nguyên tắc chưng cất:</b> Dựa vào sự khác nhau về nhiệt độ sôi của các chất lỏng trong hỗn hợp. Chất có nhiệt độ sôi thấp hơn sẽ chuyển thành hơi trước, được dẫn qua ống sinh hàn ngưng tụ thành chất lỏng tinh khiết.<br>• Ví dụ: Chưng cất cồn ethanol (sôi ở 78,3 °C) ra khỏi hỗn hợp rượu lên men với nước (100 °C).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phương pháp chiết (extraction) lỏng – lỏng dựa trên nguyên tắc nào sau đây?", "opts": ["Sự phân bố khác nhau của một chất tan giữa hai chất lỏng không trộn lẫn vào nhau (dùng phễu chiết).", "Sự khác nhau về điểm nóng chảy.", "Sự bay hơi của dung môi.", "Sự khác nhau về khối lượng nguyên tử."], "ans": 0, "exp": "• Phương pháp chiết lỏng - lỏng dùng phễu chiết: Chất tan hòa tan nhiều hơn vào dung môi chiết không trộn lẫn với dung môi ban đầu, sau đó tách 2 lớp chất lỏng ra.<br>• Ví dụ: Dùng hexane hoặc ether để chiết tinh dầu, chất béo ra khỏi dung dịch nước.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phương pháp tách biệt và tinh chế trong thực tiễn:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Để tách tinh dầu tràm, sả, hoa bưởi ra khỏi lá hoặc vỏ quả trong dân gian, người ta thường dùng phương pháp nào?", "opts": ["Chưng cất lôi cuốn hơi nước.", "Chưng cất áp suất thấp.", "Phương pháp lọc li tâm.", "Phương pháp sắc kí mỏng."], "ans": 0, "exp": "• Tinh dầu không tan trong nước, dễ bay hơi theo hơi nước sôi ở nhiệt độ dưới 100 °C. Hơi nước cuốn theo tinh dầu qua ống làm lạnh ngưng tụ, tinh dầu nhẹ hơn nổi lên trên mặt nước và được vớt tách ra dễ dàng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các công việc thực tế (Cột A) với phương pháp tách tinh chế tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Nấu rượu gạo từ bỗng rượu lên men ➔ A. Phương pháp chưng cất.", "1. Nấu rượu gạo từ bỗng rượu lên men ➔ B. Phương pháp chiết lỏng – rắn.", "1. Nấu rượu gạo từ bỗng rượu lên men ➔ C. Phương pháp kết tinh (làm bay hơi nước).", "1. Nấu rượu gạo từ bỗng rượu lên men ➔ D. Phương pháp sắc kí cột (hoặc sắc kí bản mỏng)."], "ans": 0, "exp": "• Ứng dụng thực tế của 4 phương pháp tách biệt và tinh chế hữu cơ.", "svgGraph": null}, {"q": "Phương pháp kết tinh lại (recrystallization) dùng để tinh chế chất hữu cơ ở trạng thái nào?", "opts": ["Chất rắn (dựa trên sự thay đổi độ tan theo nhiệt độ của dung môi thích hợp).", "Chất khí dễ bay hơi.", "Chất lỏng nhớt.", "Dung dịch keo."], "ans": 0, "exp": "• Hòa tan chất rắn bẩn trong dung môi sôi đến bão hòa, lọc nóng bỏ tạp chất không tan, sau đó để nguội cho chất tinh khiết kết tinh ra thành tinh thể đẹp, lọc hút thu lấy tinh thể sạch.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các thao tác sử dụng phễu chiết trong phương pháp chiết lỏng – lỏng:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trong phương pháp sắc kí cột (Column Chromatography), pha tĩnh thường là chất hấp phụ rắn nào được nhồi trong cột thủy tinh?", "opts": ["Silica gel (SiO₂) hoặc Alumina (Al₂O₃)", "Than hoạt tính thô", "Bột đá vôi CaCO₃", "Bột lưu huỳnh S"], "ans": 0, "exp": "• Pha tĩnh (stationary phase) trong sắc kí cột là các hạt silica gel hoặc alumina có bề mặt phân cực hấp phụ các chất với lực khác nhau. Pha động (dung môi rửa giải) chảy qua sẽ kéo các chất di chuyển với tốc độ khác nhau và tách rời nhau.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Có 4 phương pháp tách biệt và tinh chế hợp chất hữu cơ quan trọng: Phương pháp [ ... ] dựa trên độ sôi khác nhau; Phương pháp [ ... ] dựa trên độ tan trong các dung môi không trộn lẫn; Phương pháp [ ... ] áp dụng cho chất rắn; và Phương pháp [ ... ] cột dùng để tách các hỗn hợp tinh vi.", "opts": ["chưng cất — chiết — kết tinh — sắc kí", "sắc kí — kết tinh — chiết — chưng cất", "chiết — kết tinh — sắc kí — chưng cất", "kết tinh — sắc kí — chưng cất — chiết"], "ans": 0, "exp": "• Chưng cất, chiết, kết tinh, sắc kí.", "svgGraph": null}, {"q": "Khi làm sữa đậu nành, người ta xay nhuyễn hạt đậu nành với nước rồi vắt lấy phần nước sữa, bỏ phần bã đậu. Quá trình này ứng dụng phương pháp gì?", "opts": ["Chiết lỏng – rắn kết hợp lọc", "Chưng cất lôi cuốn hơi nước", "Kết tinh phân đoạn", "Sắc kí trao đổi ion"], "ans": 0, "exp": "• Nước đóng vai trò dung môi chiết hòa tan protein và chất dinh dưỡng từ hạt đậu (chất rắn), sau đó dùng vải lọc để tách dịch sữa ra khỏi bã đậu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "12": [{"q": "Công thức đơn giản nhất (Empirical formula) của một hợp chất hữu cơ cho biết thông tin gì?", "opts": ["Tỉ lệ số lượng nguyên tử tối giản của các nguyên tố có trong phân tử.", "Số lượng chính xác của từng nguyên tử trong phân tử.", "Trật tự liên kết giữa các nguyên tử trong phân tử.", "Khối lượng mol phân tử chính xác của chất."], "ans": 0, "exp": "• <b>Định nghĩa:</b> Công thức đơn giản nhất cho biết tỉ lệ số nguyên tử của các nguyên tố trong phân tử dưới dạng các số nguyên tối giản (x : y : z = n_C : n_H : n_O).<br>• Ví dụ: Glucose có công thức phân tử là C₆H₁₂O₆, công thức đơn giản nhất là CH₂O.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phương pháp phổ khối lượng (MS - Mass Spectrometry) giúp xác định đại lượng nào của hợp chất hữu cơ dựa vào pic ion phân tử [M⁺] có giá trị m/z lớn nhất?", "opts": ["Khối lượng mol phân tử (phân tử khối M) của hợp chất.", "Nhiệt độ nóng chảy của hợp chất.", "Số lượng liên kết đôi trong phân tử.", "Độ tan của chất trong nước."], "ans": 0, "exp": "• Trên phổ khối lượng MS, pic của ion phân tử [M⁺] (thường có m/z lớn nhất trừ các pic đồng vị rất nhỏ) cho biết trực tiếp phân tử khối M của hợp chất hữu cơ.<br>• Từ công thức đơn giản nhất (C_xH_yO_z)_n và M = M(đgn) · n ta suy ra giá trị n và công thức phân tử.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Đốt cháy hoàn toàn 4,4 gam một hợp chất hữu cơ X (chứa C, H, O) thu được 8,8 gam CO₂ và 3,6 gam H₂O:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Một hợp chất hữu cơ Y có % khối lượng các nguyên tố: %C = 52,17%, %H = 13,04%, còn lại là %O = 34,79%. Công thức đơn giản nhất của Y là:", "opts": ["C₂H₆O", "CH₃O", "C₂H₄O", "CH₄O"], "ans": 0, "exp": "• Tỉ lệ: n_C : n_H : n_O = (52,17/12) : (13,04/1) : (34,79/16)<br>= 4,3475 : 13,04 : 2,174 = 2 : 6 : 1.<br>• Công thức đơn giản nhất là C₂H₆O (đây là ethanol hoặc dimethyl ether).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép công thức phân tử (Cột A) với công thức đơn giản nhất tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Benzene (C₆H₆) ➔ A. CH.", "1. Benzene (C₆H₆) ➔ B. CH₂.", "1. Benzene (C₆H₆) ➔ C. CH₂O.", "1. Benzene (C₆H₆) ➔ D. C₂H₆O (trùng với công thức phân tử)."], "ans": 0, "exp": "• Rút gọn tỉ lệ các nguyên tử để tìm công thức đơn giản nhất.", "svgGraph": null}, {"q": "Một hydrocarbon A có công thức đơn giản nhất là CH. Biết phân tử khối của A xác định từ phổ MS là 78. Công thức phân tử của A là:", "opts": ["C₆H₆ (Benzene)", "C₂H₂ (Acetylene)", "C₄H₄", "C₈H₈ (Styrene)"], "ans": 0, "exp": "• Công thức phân tử có dạng (CH)_n ⇒ Khối lượng mol: (12 + 1)·n = 13n = 78 ⇒ n = 6.<br>• Công thức phân tử là C₆H₆.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về phương pháp phân tích nguyên tố trong hóa hữu cơ:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trên phổ khối lượng MS của một dẫn xuất halogen, người ta thấy xuất hiện hai pic ion phân tử có m/z là 108 và 110 với cường độ vạch xấp xỉ bằng nhau (tỉ lệ 1 : 1). Điều này chứng tỏ phân tử chứa nguyên tố nào?", "opts": ["Bromine (Br, có 2 đồng vị bền ⁷⁹Br và ⁸¹Br với tỉ lệ xấp xỉ 1 : 1)", "Chlorine (Cl, tỉ lệ 3 : 1)", "Iodine (I)", "Fluorine (F)"], "ans": 0, "exp": "• Bromine có 2 đồng vị bền là ⁷⁹Br (50,7%) và ⁸¹Br (49,3%) xấp xỉ 1 : 1, do đó các hợp chất chứa 1 nguyên tử Br luôn cho 2 pic ion phân tử cách nhau 2 đơn vị khối với tỉ lệ cường độ gần bằng nhau.<br>• Với Chlorine thì tỉ lệ là 3 : 1 (do ³⁵Cl chiếm 75% và ³⁷Cl chiếm 25%).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Công thức [ ... ] cho biết tỉ lệ số nguyên tử tối giản của các nguyên tố. Công thức [ ... ] cho biết số lượng nguyên tử chính xác của mỗi nguyên tố trong một phân tử. Phổ khối lượng [ ... ] (MS) cho biết giá trị [ ... ] phân tử M của hợp chất.", "opts": ["đơn giản nhất — phân tử — khối lượng — khối lượng mol", "khối lượng mol — khối lượng — phân tử — đơn giản nhất", "phân tử — khối lượng — khối lượng mol — đơn giản nhất", "khối lượng — khối lượng mol — đơn giản nhất — phân tử"], "ans": 0, "exp": "• Đơn giản nhất, phân tử, phổ khối lượng, khối lượng mol.", "svgGraph": null}, {"q": "Chất X có công thức phân tử là C₃H₆O₂. Phân tử khối của X là:", "opts": ["74 amu", "60 amu", "88 amu", "46 amu"], "ans": 0, "exp": "• M = 3·12 + 6·1 + 2·16 = 36 + 6 + 32 = 74 amu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "13": [{"q": "Theo thuyết cấu tạo hóa học của Butlerov (1861), các nguyên tử trong phân tử hợp chất hữu cơ liên kết với nhau theo đặc điểm nào?", "opts": ["Theo một thứ tự nhất định và theo đúng hóa trị của từng nguyên tố (carbon luôn có hóa trị IV).", "Theo thứ tự ngẫu nhiên không cố định.", "Chỉ có nguyên tử carbon liên kết với nhau.", "Tất cả các nguyên tố đều có hóa trị I."], "ans": 0, "exp": "• <b>Luận điểm Butlerov:</b> Các nguyên tử liên kết với nhau theo một trật tự nhất định và đúng hóa trị (C hóa trị IV, H và halogen hóa trị I, O hóa trị II, N hóa trị III). Thứ tự liên kết đó được gọi là cấu tạo hóa học. Sự thay đổi thứ tự liên kết sẽ tạo ra chất mới.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hiện tượng các chất có cùng công thức phân tử nhưng có cấu tạo hóa học khác nhau nên tính chất khác nhau được gọi là:", "opts": ["Hiện tượng đồng phân (Isomerism).", "Hiện tượng đồng đẳng (Homology).", "Hiện tượng trùng hợp.", "Hiện tượng dị thể."], "ans": 0, "exp": "• Đồng phân (Isomer): Cùng công thức phân tử nhưng khác cấu tạo hóa học (hoặc khác cấu trúc không gian), dẫn đến tính chất vật lí và hóa học khác nhau.<br>• Ví dụ: C₂H₆O có 2 đồng phân là Ethanol CH₃CH₂OH (chất lỏng, tác dụng Na) và Dimethyl ether CH₃OCH₃ (chất khí, không tác dụng Na).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các loại đồng phân trong hóa học hữu cơ:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chất nào sau đây CÓ đồng phân hình học cis – trans?", "opts": ["But-2-ene (CH₃–CH=CH–CH₃)", "Propene (CH₂=CH–CH₃)", "But-1-ene (CH₂=CH–CH₂–CH₃)", "2-Methylpropene (CH₂=C(CH₃)₂)"], "ans": 0, "exp": "• But-2-ene: C(1) liên kết với -H và -CH₃ (khác nhau); C(2) liên kết với -H và -CH₃ (khác nhau) ⇒ thỏa mãn điều kiện có đồng phân hình học cis-but-2-ene và trans-but-2-ene.<br>• Các chất còn lại có đầu =CH₂ (chứa 2 nguyên tử H giống nhau ở 1 nguyên tử C) nên không có đồng phân hình học.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép cặp chất (Cột A) với loại đồng phân tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. CH₃CH₂CH₂OH và CH₃CH(OH)CH₃ ➔ A. Đồng phân vị trí nhóm chức.", "1. CH₃CH₂CH₂OH và CH₃CH(OH)CH₃ ➔ B. Đồng phân mạch carbon.", "1. CH₃CH₂CH₂OH và CH₃CH(OH)CH₃ ➔ C. Đồng phân nhóm chức (alcohol và ether).", "1. CH₃CH₂CH₂OH và CH₃CH(OH)CH₃ ➔ D. Đồng phân hình học (đồng phân lập thể không gian)."], "ans": 0, "exp": "• Phân loại chính xác các kiểu đồng phân thường gặp.", "svgGraph": null}, {"q": "Số lượng đồng phân cấu tạo ứng với công thức phân tử C₄H₁₀ (alkane) là bao nhiêu?", "opts": ["2 đồng phân (butane và isobutane)", "3 đồng phân", "4 đồng phân", "1 đồng phân"], "ans": 0, "exp": "• C₄H₁₀ có 2 đồng phân cấu tạo:<br>1. CH₃–CH₂–CH₂–CH₃ (butane, mạch thẳng).<br>2. CH₃–CH(CH₃)–CH₃ (2-methylpropane hay isobutane, mạch phân nhánh).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét khái niệm đồng đẳng (Homology) trong hóa học hữu cơ:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Bậc của một nguyên tử carbon trong phân tử hydrocarbon no bằng:", "opts": ["Số nguyên tử carbon liên kết trực tiếp với nguyên tử carbon đó.", "Số nguyên tử hydrogen liên kết với nó.", "Hóa trị của carbon.", "Số electron độc thân của carbon."], "ans": 0, "exp": "• Bậc của carbon trong phân tử alkane bằng số nguyên tử carbon liên kết trực tiếp với nguyên tử carbon đó.<br>• Carbon bậc I: liên kết với 1 C; Bậc II: liên kết với 2 C; Bậc III: liên kết với 3 C; Bậc IV: liên kết với 4 C.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Thuyết cấu tạo hóa học chỉ ra rằng trong phân tử hữu cơ, carbon luôn có hóa trị [ ... ]. Các nguyên tử carbon có thể liên kết với nhau tạo thành [ ... ] carbon (mạch thẳng, mạch nhánh hoặc mạch vòng). Những chất có cùng công thức phân tử nhưng khác nhau về cấu tạo hóa học gọi là các [ ... ]. Đồng phân hình học gồm hai dạng là [ ... ] và trans.", "opts": ["IV — mạch — đồng phân — cis", "cis — đồng phân — mạch — IV", "mạch — đồng phân — cis — IV", "đồng phân — cis — IV — mạch"], "ans": 0, "exp": "• Hóa trị IV, mạch carbon, đồng phân, dạng cis và trans.", "svgGraph": null}, {"q": "Số lượng đồng phân cấu tạo ứng với công thức phân tử C₅H₁₂ (pentane) là bao nhiêu?", "opts": ["3 đồng phân (pentane, isopentane, neopentane)", "2 đồng phân", "4 đồng phân", "5 đồng phân"], "ans": 0, "exp": "• C₅H₁₂ có 3 đồng phân cấu tạo:<br>1. CH₃–CH₂–CH₂–CH₂–CH₃ (pentane).<br>2. CH₃–CH(CH₃)–CH₂–CH₃ (2-methylbutane hay isopentane).<br>3. C(CH₃)₄ (2,2-dimethylpropane hay neopentane).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "14": [{"q": "Phương pháp phổ nào sau đây được dùng phổ biến để xác định cấu trúc nhóm chức và liên kết hóa học trong phân tử hữu cơ?", "opts": ["Phổ hồng ngoại (IR - Infrared)", "Phổ khối lượng (MS)", "Phổ hấp thụ nguyên tử (AAS)", "Phổ phát xạ ngọn lửa"], "ans": 0, "exp": "• Phổ IR: xác định các liên kết và nhóm chức (dựa trên số sóng hấp thụ cm⁻¹).<br>• Phổ MS: xác định phân tử khối M và mảnh ion.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi đốt cháy hoàn toàn một hydrocarbon X thu được n_CO₂ = n_H₂O. Hydrocarbon X có thể thuộc dãy đồng đẳng nào?", "opts": ["Alkene (CnH2n, n ≥ 2) hoặc Monocycloalkane", "Alkane (CnH2n+2)", "Alkyne (CnH2n-2)", "Arene (CnH2n-6)"], "ans": 0, "exp": "• Phương trình cháy tổng quát: CnH2n + (3n/2)O₂ -> nCO₂ + nH₂O.<br>• Số mol CO₂ bằng số mol H₂O chứng tỏ tỉ lệ C : H = 1 : 2 ⇒ Công thức CnH2n (alkene hoặc cycloalkane).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định tổng kết Chương 3 Đại cương hóa hữu cơ:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trên phổ IR của một hợp chất hữu cơ X thấy có một dải hấp thụ rất rộng và mạnh ở vùng 3300 cm⁻¹. Tín hiệu này đặc trưng cho nhóm chức nào?", "opts": ["Nhóm hydroxyl –O–H (alcohol)", "Nhóm carbonyl >C=O (aldehyde, ketone)", "Liên kết ba C≡C", "Liên kết đơn C–C"], "ans": 0, "exp": "• Dải hấp thụ dạng chân voi rộng ở 3200 - 3500 cm⁻¹ là tín hiệu vân tay đặc trưng cho dao động hóa trị của liên kết O–H có liên kết hydrogen liên phân tử của alcohol.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các công thức cấu tạo (Cột A) với tên gọi tương ứng theo danh pháp IUPAC (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. CH₃–CH₂–OH ➔ A. Ethanol.", "1. CH₃–CH₂–OH ➔ B. Acetaldehyde (ethanal).", "1. CH₃–CH₂–OH ➔ C. Acetic acid (ethanoic acid).", "1. CH₃–CH₂–OH ➔ D. Methyl formate."], "ans": 0, "exp": "• Tên gọi chuẩn IUPAC của các hợp chất hữu cơ đơn giản.", "svgGraph": null}, {"q": "Khối lượng mol phân tử của hợp chất hữu cơ có công thức đơn giản nhất là CH₂O và có phân tử khối bằng 60 là:", "opts": ["C₂H₄O₂ (Acetic acid hoặc Methyl formate, M = 60)", "CH₂O (Formaldehyde, M = 30)", "C₃H₆O₃ (M = 90)", "C₆H₁₂O₆ (Glucose, M = 180)"], "ans": 0, "exp": "• M(CH₂O) = 12 + 2 + 16 = 30.<br>• n = 60 / 30 = 2 ⇒ Công thức phân tử là C₂H₄O₂.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các tính chất vật lí cơ bản của hợp chất hữu cơ:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trong phòng thí nghiệm, để tách hai chất lỏng không trộn lẫn vào nhau (như dầu ăn và nước), người ta dùng dụng cụ thủy tinh nào?", "opts": ["Phễu chiết (separatory funnel)", "Ống đong", "Buret", "Bình cầu đáy tròn"], "ans": 0, "exp": "• Phễu chiết quả lê có khóa ở đáy dùng để tách hai lớp chất lỏng phân lớp do không tan vào nhau và có khối lượng riêng khác nhau.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Phân tích nguyên tố gồm phân tích [ ... ] để biết thành phần các nguyên tố và phân tích [ ... ] để tìm tỉ lệ khối lượng. Từ phổ MS ta tìm được [ ... ] phân tử. Từ phổ IR ta xác định được các [ ... ] có mặt trong phân tử.", "opts": ["định tính — định lượng — khối lượng — nhóm chức", "nhóm chức — khối lượng — định lượng — định tính", "định lượng — khối lượng — nhóm chức — định tính", "khối lượng — nhóm chức — định tính — định lượng"], "ans": 0, "exp": "• Định tính, định lượng, khối lượng phân tử, nhóm chức.", "svgGraph": null}, {"q": "Đồng phân nào sau đây của C₄H₈ làm mất màu dung dịch nước bromine?", "opts": ["But-1-ene (CH₂=CH–CH₂–CH₃, chứa liên kết đôi C=C)", "Cyclobutane (vòng 4 cạnh no bền)", "Methylcyclopropane", "Cả butane và isobutane"], "ans": 0, "exp": "• But-1-ene có liên kết đôi C=C kém bền nên dễ dàng tham gia phản ứng cộng làm mất màu nước bromine ngay nhiệt độ phòng: CH₂=CH–CH₂–CH₃ + Br₂ -> CH₂Br–CHBr–CH₂–CH₃.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "15": [{"q": "Alkane (paraffin) là các hydrocarbon no, mạch hở có công thức chung là gì?", "opts": ["C_n H_{2n+2} (với n ≥ 1)", "C_n H_{2n} (với n ≥ 2)", "C_n H_{2n-2} (với n ≥ 2)", "C_n H_{2n-6} (với n ≥ 6)"], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Alkane là hydrocarbon no mạch hở, trong phân tử chỉ chứa liên kết đơn C–C và C–H, có công thức chung C_n H_{2n+2} (n ≥ 1).<br>• Đại diện đơn giản nhất là methane (CH₄).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phản ứng hóa học đặc trưng nhất của alkane là phản ứng nào sau đây?", "opts": ["Phản ứng thế halogen (khi có ánh sáng hoặc đun nóng).", "Phản ứng cộng với nước bromine.", "Phản ứng trùng hợp tạo polymer.", "Phản ứng tráng bạc."], "ans": 0, "exp": "• Do trong phân tử chỉ có các liên kết đơn C-C và C-H bền vững nên alkane trơ về mặt hóa học, không tham gia phản ứng cộng.<br>• Phản ứng đặc trưng là phản ứng thế gốc (SR) với halogen (Cl₂, Br₂) dưới tác dụng của ánh sáng tử ngoại (as): CH₄ + Cl₂ --as--> CH₃Cl + HCl.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét quy tắc thế halogen vào phân tử alkane (như propane CH₃–CH₂–CH₃ + Cl₂ theo tỉ lệ mol 1 : 1):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khí thiên nhiên và khí mỏ dầu được khai thác từ lòng đất có thành phần chính là khí nào?", "opts": ["Khí Methane (CH₄, chiếm khoảng 85 - 95%)", "Khí Hydrogen (H₂)", "Khí Acetylene (C₂H₂)", "Khí Carbon monoxide (CO)"], "ans": 0, "exp": "• Khí thiên nhiên chứa chủ yếu là methane CH₄ (85 - 95%), phần còn lại là ethane, propane, butane và các khí vô cơ.<br>• Methane là nguồn nhiên liệu sạch và nguyên liệu quan trọng cho ngành hóa chất.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các phản ứng của alkane (Cột A) với tên loại phản ứng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. CH₄ + Cl₂ --as--> CH₃Cl + HCl ➔ A. Phản ứng thế halogen.", "1. CH₄ + Cl₂ --as--> CH₃Cl + HCl ➔ B. Phản ứng cracking (bẻ gãy mạch carbon).", "1. CH₄ + Cl₂ --as--> CH₃Cl + HCl ➔ C. Phản ứng tách hydrogen (dehydrogenation).", "1. CH₄ + Cl₂ --as--> CH₃Cl + HCl ➔ D. Phản ứng oxi hóa hoàn toàn (phản ứng cháy)."], "ans": 0, "exp": "• Các phản ứng hóa học quan trọng của alkane trong đời sống và lọc dầu.", "svgGraph": null}, {"q": "Chỉ số octane (Octane rating) của xăng là đại lượng đặc trưng cho yếu tố nào của nhiên liệu?", "opts": ["Khả năng chống kích nổ của nhiên liệu xăng khi nén trong động cơ đốt trong.", "Tốc độ bay hơi của xăng.", "Nhiệt độ đông đặc của xăng.", "Hàm lượng chì còn sót lại trong xăng."], "ans": 0, "exp": "• Chỉ số octane đo khả năng chống kích nổ: 2,2,4-trimethylpentane (isooctane) chống kích nổ tuyệt hảo được quy ước bằng 100; n-heptane dễ kích nổ quy ước bằng 0.<br>• Xăng RON 95 có chất lượng chống kích nổ tương đương hỗn hợp chứa 95% isooctane và 5% n-heptane.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các tính chất vật lí và an toàn khi sử dụng alkane (khí gas LPG, xăng dầu):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khi clo hóa 2-methylbutane theo tỉ lệ mol 1 : 1 có chiếu sáng, sản phẩm chính thu được là chất nào?", "opts": ["2-chloro-2-methylbutane (thế vào carbon bậc 3)", "1-chloro-2-methylbutane", "2-chloro-3-methylbutane", "1-chloro-3-methylbutane"], "ans": 0, "exp": "• 2-methylbutane: CH₃–CH(CH₃)–CH₂–CH₃. Nguyên tử C ở vị trí số 2 là carbon bậc III (bậc cao nhất).<br>• Theo quy tắc thế, nguyên tử clo ưu tiên thế vào C bậc III tạo sản phẩm chính 2-chloro-2-methylbutane.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Alkane là các hydrocarbon [ ... ] mạch hở có công thức chung là CnH2n+2. Phản ứng đặc trưng của alkane là phản ứng [ ... ] halogen. Trong công nghiệp dầu mỏ, quá trình [ ... ] dùng để bẻ gãy các phân tử alkane mạch dài thành các alkane và alkene mạch ngắn hơn có giá trị kinh tế cao, làm tăng chỉ số [ ... ] của xăng.", "opts": ["no — thế — cracking — octane", "octane — cracking — thế — no", "thế — cracking — octane — no", "cracking — octane — no — thế"], "ans": 0, "exp": "• Hydrocarbon no, phản ứng thế, cracking, chỉ số octane.", "svgGraph": null}, {"q": "Đốt cháy hoàn toàn 1 mol alkane X thu được 3 mol CO₂ và 4 mol H₂O. Công thức phân tử của X là:", "opts": ["C₃H₈ (Propane)", "C₄H₁₀ (Butane)", "C₂H₆ (Ethane)", "CH₄ (Methane)"], "ans": 0, "exp": "• Số nguyên tử C = n_CO₂ / n_X = 3 / 1 = 3.<br>• Số nguyên tử H = 2 · n_H₂O / n_X = 2 · 4 / 1 = 8.<br>• Công thức phân tử của X là C₃H₈ (Propane).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "16": [{"q": "Alkene và Alkyne lần lượt là các hydrocarbon không no mạch hở chứa liên kết bội nào trong phân tử?", "opts": ["Alkene chứa 1 liên kết đôi C=C (CnH2n); Alkyne chứa 1 liên kết ba C≡C (CnH2n-2).", "Alkene chứa 1 liên kết ba; Alkyne chứa 1 liên kết đôi.", "Cả hai đều chỉ chứa liên kết đơn.", "Alkene chứa vòng benzen."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b><br>• Alkene: CnH2n (n ≥ 2), chứa 1 liên kết đôi C=C (1 liên kết σ bền và 1 liên kết π kém bền).<br>• Alkyne: CnH2n-2 (n ≥ 2), chứa 1 liên kết ba C≡C (1 liên kết σ bền và 2 liên kết π kém bền).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phản ứng hóa học đặc trưng nhất của alkene và alkyne là phản ứng nào?", "opts": ["Phản ứng cộng (vào liên kết π kém bền làm đứt liên kết π).", "Phản ứng thế gốc tự do.", "Phản ứng thủy phân trong kiềm.", "Phản ứng trao đổi ion."], "ans": 0, "exp": "• Do chứa liên kết π kém bền trong liên kết đôi hoặc ba, alkene và alkyne dễ dàng tham gia phản ứng cộng (cộng H₂, halogen X₂, acid HX, H₂O) làm no hóa phân tử.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét quy tắc cộng Markovnikov khi cộng tác nhân bất đối xứng (như HBr, H₂O) vào alkene bất đối xứng (như propene CH₂=CH–CH₃):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Thuốc thử nào sau đây dùng để phân biệt nhanh giữa alkane (khí methane CH₄) và alkene (khí ethylene C₂H₄)?", "opts": ["Dung dịch nước bromine (Br₂ màu nâu đỏ) hoặc dung dịch thuốc tím KMnO₄", "Dung dịch quỳ tím", "Dung dịch muối ăn NaCl", "Dung dịch NaOH không màu"], "ans": 0, "exp": "• Ethylene C₂H₄ chứa liên kết đôi C=C làm mất màu nâu đỏ của dung dịch nước Br₂ (CH₂=CH₂ + Br₂ -> CH₂Br–CH₂Br không màu) và làm mất màu tím của KMnO₄ sinh kết tủa nâu đen MnO₂.<br>• Methane CH₄ không phản ứng ở điều kiện thường nên không làm mất màu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các phản ứng hóa học (Cột A) với ứng dụng / hiện tượng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Trùng hợp ethylene: nCH₂=CH₂ --p, xt, t°--> (-CH₂-CH₂-)n ➔ A. Sản xuất nhựa polyethylene (PE) làm màng bọc, túi nilon, chai lọ.", "1. Trùng hợp ethylene: nCH₂=CH₂ --p, xt, t°--> (-CH₂-CH₂-)n ➔ B. Xuất hiện kết tủa màu vàng nhạt bạc acetylide (CAg≡CAg↓).", "1. Trùng hợp ethylene: nCH₂=CH₂ --p, xt, t°--> (-CH₂-CH₂-)n ➔ C. Tỏa nhiệt trên 3000 °C dùng để hàn cắt kim loại.", "1. Trùng hợp ethylene: nCH₂=CH₂ --p, xt, t°--> (-CH₂-CH₂-)n ➔ D. Hoocmon thực vật kích thích hoa mau nở và trái cây mau chín."], "ans": 0, "exp": "• Các phản ứng và ứng dụng tiêu biểu của ethylene và acetylene.", "svgGraph": null}, {"q": "Alkyne nào sau đây CÓ phản ứng tạo kết tủa màu vàng nhạt khi tác dụng với dung dịch AgNO₃ trong NH₃ (phản ứng thế nguyên tử H linh động ở liên kết ba đầu mạch)?", "opts": ["Prop-1-yne (CH≡C–CH₃, alk-1-yne)", "But-2-yne (CH₃–C≡C–CH₃)", "Pent-2-yne (CH₃–C≡C–CH₂–CH₃)", "Ethylene (CH₂=CH₂)"], "ans": 0, "exp": "• Chỉ những alkyne có liên kết ba ở đầu mạch (terminal alkyne - alk-1-yne có nhóm CH≡C–) mới có nguyên tử H linh động bị ion Ag⁺ thay thế tạo kết tủa vàng nhạt: CH≡C–CH₃ + AgNO₃ + NH₃ -> CAg≡C–CH₃↓ + NH₄NO₃.<br>• But-2-yne có liên kết ba ở giữa mạch nên không có H linh động, không phản ứng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng oxi hóa của alkene:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Trùng hợp chất nào sau đây thu được polymer dùng để sản xuất ống nhựa dẫn nước PVC chịu lực, cách điện tốt?", "opts": ["Vinyl chloride (CH₂=CH–Cl)", "Ethylene (CH₂=CH₂)", "Propene (CH₂=CH–CH₃)", "Styrene (C₆H₅–CH=CH₂)"], "ans": 0, "exp": "• Trùng hợp vinyl chloride: nCH₂=CHCl --t°, p, xt--> (-CH₂-CHCl-)n (polyvinyl chloride - PVC).<br>• PVC là một trong những loại nhựa nhiệt dẻo sản xuất ống nước, dây cáp điện phổ biến nhất thế giới.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Alkene có công thức chung là [ ... ], alkyne có công thức chung là [ ... ]. Cả hai đều làm mất màu dung dịch nước [ ... ]. Các alk-1-yne có nguyên tử H linh động ở đầu mạch phản ứng với dung dịch AgNO₃ trong NH₃ tạo kết tủa màu [ ... ].", "opts": ["CnH2n — CnH2n-2 — bromine — vàng nhạt", "vàng nhạt — bromine — CnH2n-2 — CnH2n", "CnH2n-2 — bromine — vàng nhạt — CnH2n", "bromine — vàng nhạt — CnH2n — CnH2n-2"], "ans": 0, "exp": "• CnH2n, CnH2n-2, nước bromine, kết tủa vàng nhạt.", "svgGraph": null}, {"q": "Khí acetylene (C₂H₂) được điều chế trong phòng thí nghiệm và công nghiệp bằng cách cho chất nào sau đây tác dụng với nước?", "opts": ["Canxi cacbua (Đất đèn - CaC₂): CaC₂ + 2H₂O -> C₂H₂↑ + Ca(OH)₂", "Nhôm cacbua (Al₄C₃)", "Đá vôi (CaCO₃)", "Vôi sống (CaO)"], "ans": 0, "exp": "• CaC₂ + 2H₂O -> C₂H₂↑ + Ca(OH)₂.<br>• Phản ứng sinh khí acetylene sủi bọt mãnh liệt và tỏa nhiều nhiệt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "17": [{"q": "Benzene có công thức phân tử là C₆H₆, cấu trúc phân tử của benzene có đặc điểm nào sau đây?", "opts": ["Hình lục giác đều phẳng, 6 nguyên tử C và 6 nguyên tử H cùng nằm trên một mặt phẳng, có hệ 6 electron π liên hợp bền vững.", "Mạch hở chứa 3 liên kết đôi cô lập.", "Hình lập phương không gian.", "Hình bát diện đều."], "ans": 0, "exp": "• Vòng benzene là một hình lục giác đều phẳng với độ dài các liên kết C–C hoàn toàn bằng nhau (0,139 nm), nằm trung gian giữa liên kết đơn và liên kết đôi.<br>• Hệ liên hợp electron π khép kín giải thích cho tính thơm: 'Dễ thế, khó cộng, bền vững với chất oxi hóa'.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phản ứng nào sau đây thể hiện tính chất hóa học đặc trưng của nhân thơm benzene (tính thơm)?", "opts": ["Dễ tham gia phản ứng thế (thế halogen, nitro hóa), khó tham gia phản ứng cộng và không làm mất màu dung dịch KMnO₄ ở điều kiện thường.", "Làm mất màu dung dịch nước bromine ngay nhiệt độ phòng như alkene.", "Dễ bị oxi hóa bởi dung dịch KMnO₄ ngay ở nhiệt độ thường.", "Chỉ tham gia phản ứng trùng hợp."], "ans": 0, "exp": "• Nhân thơm rất bền vững nên không làm mất màu nước bromine hay dung dịch KMnO₄ ở điều kiện thường.<br>• Phản ứng thế nguyên tử H của vòng thơm xảy ra dễ dàng khi có xúc tác acid Lewis (như FeBr₃, AlCl₃, H₂SO₄ đặc).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng thế trên nhân thơm của benzene và toluene (C₆H₅CH₃):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khi đun nóng toluene (C₆H₅CH₃) với dung dịch thuốc tím KMnO₄ rồi acid hóa dung dịch thu được kết tủa màu trắng của hợp chất nào?", "opts": ["Benzoic acid (C₆H₅COOH)", "Phenol (C₆H₅OH)", "Benzaldehyde (C₆H₅CHO)", "Benzene (C₆H₆)"], "ans": 0, "exp": "• C₆H₅CH₃ + 2KMnO₄ --t°--> C₆H₅COOK + 2MnO₂↓ + KOH + H₂O.<br>• Acid hóa: C₆H₅COOK + HCl -> C₆H₅COOH↓ (tinh thể màu trắng hình kim, làm chất bảo quản thực phẩm).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các arene (Cột A) với ứng dụng thực tế quan trọng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Benzene (C₆H₆) ➔ A. Dung môi công nghiệp và nguyên liệu tổng hợp styrene, phenol, nylon.", "1. Benzene (C₆H₆) ➔ B. Dung môi pha sơn, mực in và sản xuất thuốc nổ TNT (2,4,6-trinitrotoluene).", "1. Benzene (C₆H₆) ➔ C. Trùng hợp sản xuất nhựa xốp Polystyrene (PS) cách nhiệt, hộp xốp.", "1. Benzene (C₆H₆) ➔ D. Chất rắn màu trắng thăng hoa, dùng xua đuổi gián, côn trùng và chống ẩm mốc tủ quần áo."], "ans": 0, "exp": "• Ứng dụng thực tế của các hydrocarbon thơm phổ biến.", "svgGraph": null}, {"q": "Thuốc nổ TNT được điều chế bằng phản ứng nitro hóa hoàn toàn chất nào sau đây với hỗn hợp acid HNO₃ đặc và H₂SO₄ đặc?", "opts": ["Toluene (methylbenzene)", "Benzene", "Phenol", "Methane"], "ans": 0, "exp": "• C₆H₅CH₃ + 3HNO₃ --H₂SO₄ đ, t°--> C₆H₂(NO₂)₃CH₃ (2,4,6-trinitrotoluene hay TNT) + 3H₂O.<br>• TNT là thuốc nổ quân dụng và công nghiệp khai thác đá rất nổi tiếng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng cộng của benzene:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Để phân biệt 3 chất lỏng không màu: Benzene, Toluene và Styrene đựng trong 3 lọ mất nhãn, người ta dùng thuốc thử duy nhất là:", "opts": ["Dung dịch thuốc tím KMnO₄ (ở nhiệt độ thường và đun nóng)", "Dung dịch nước bromine", "Dung dịch AgNO₃/NH₃", "Kim loại Na"], "ans": 0, "exp": "• Ở nhiệt độ thường: Chỉ có Styrene làm mất màu tím dung dịch KMnO₄ (do có liên kết đôi mạch nhánh).<br>• Đun nóng: Toluene làm mất màu dung dịch KMnO₄ (oxi hóa nhánh -CH₃). Còn Benzene hoàn toàn không làm mất màu kể cả khi đun nóng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Benzene có công thức phân tử là [ ... ], có tính thơm đặc trưng: [ ... ] tham gia phản ứng thế, [ ... ] tham gia phản ứng cộng và bền vững với các chất oxi hóa. Khi nitro hóa toluene thu được thuốc nổ [ ... ].", "opts": ["C₆H₆ — dễ — khó — TNT", "TNT — khó — dễ — C₆H₆", "dễ — khó — TNT — C₆H₆", "khó — TNT — C₆H₆ — dễ"], "ans": 0, "exp": "• C₆H₆, dễ thế, khó cộng, thuốc nổ TNT.", "svgGraph": null}, {"q": "Số đồng phân arene (chứa vòng benzene) ứng với công thức phân tử C₈H₁₀ là:", "opts": ["4 đồng phân (ethylbenzene, o-xylene, m-xylene, p-xylene)", "3 đồng phân", "2 đồng phân", "5 đồng phân"], "ans": 0, "exp": "• C₈H₁₀ có 4 đồng phân arene:<br>1. C₆H₅–CH₂–CH₃ (ethylbenzene).<br>2. 1,2-dimethylbenzene (ortho-xylene).<br>3. 1,3-dimethylbenzene (meta-xylene).<br>4. 1,4-dimethylbenzene (para-xylene).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "18": [{"q": "Dãy các chất nào sau đây đều làm mất màu dung dịch nước bromine ở nhiệt độ thường?", "opts": ["Ethylene, Acetylene, Styrene", "Methane, Ethane, Propane", "Benzene, Toluene, Methane", "Cyclohexane, Butane, Benzene"], "ans": 0, "exp": "• Ethylene (C=C), Acetylene (C≡C), Styrene (-CH=CH₂) đều chứa liên kết π kém bền ở mạch hở nên phản ứng cộng làm mất màu nước bromine ngay nhiệt độ thường.<br>• Alkane và vòng benzen không làm mất màu nước bromine ở điều kiện này.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho 0,1 mol hỗn hợp gồm acetylene và ethylene lội qua dung dịch AgNO₃ trong NH₃ dư thấy có 12,0 gam kết tủa vàng nhạt CAg≡CAg. Thành phần phần trăm thể tích của acetylene trong hỗn hợp là:", "opts": ["50%", "25%", "75%", "40%"], "ans": 0, "exp": "• Chỉ có C₂H₂ phản ứng tạo kết tủa: C₂H₂ + 2AgNO₃ + 2NH₃ -> CAg≡CAg↓ + 2NH₄NO₃.<br>• M(CAg≡CAg) = 108·2 + 24 = 240 g/mol.<br>• n(kết tủa) = 12,0 / 240 = 0,05 mol ⇒ n_C₂H₂ = 0,05 mol.<br>• % thể tích C₂H₂ = (0,05 / 0,1) · 100% = 50%.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng điều chế và tính chất của hydrocarbon:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khi dẫn khí ethylene vào dung dịch nước bromine, màu nâu đỏ của dung dịch nhạt dần rồi biến mất. Sản phẩm thu được là chất nào?", "opts": ["1,2-dibromoethane (CH₂Br–CH₂Br)", "Bromoethane (CH₃–CH₂Br)", "1,1-dibromoethane", "1,1,2,2-tetrabromoethane"], "ans": 0, "exp": "• Phản ứng cộng: CH₂=CH₂ + Br₂ -> CH₂Br–CH₂Br.<br>• Liên kết đôi chuyển thành liên kết đơn, tạo hợp chất không màu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các hydrocarbon (Cột A) với đặc điểm cấu tạo tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Methane (CH₄) ➔ A. Cấu trúc tứ diện đều, 4 liên kết đơn C–H.", "1. Methane (CH₄) ➔ B. Cấu trúc phẳng, 1 liên kết đôi C=C (1σ, 1π).", "1. Methane (CH₄) ➔ C. Cấu trúc đường thẳng, 1 liên kết ba C≡C (1σ, 2π).", "1. Methane (CH₄) ➔ D. Cấu trúc lục giác đều phẳng, hệ 6e π liên hợp thơm."], "ans": 0, "exp": "• 4 cấu trúc kinh điển của 4 nhóm hydrocarbon cơ bản.", "svgGraph": null}, {"q": "Polyethylene (nhựa PE) được sản xuất từ monomer nào sau đây?", "opts": ["Ethylene (CH₂=CH₂)", "Propylene (CH₂=CH–CH₃)", "Vinyl chloride (CH₂=CH–Cl)", "Styrene (C₆H₅–CH=CH₂)"], "ans": 0, "exp": "• n CH₂=CH₂ --t°, p, xt--> (-CH₂-CH₂-)n (PE).<br>• Nhựa PE chiếm sản lượng lớn nhất trong tất cả các loại chất dẻo thế giới.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các vấn đề môi trường liên quan đến nhiên liệu hóa thạch (than đá, xăng dầu, khí đốt):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Để dập tắt đám cháy nhỏ do xăng dầu gây ra trong gia đình, cách xử lí nào sau đây là ĐÚNG và AN TOÀN nhất?", "opts": ["Dùng chăn dạ nhúng ướt trùm kín lên ngọn lửa hoặc dùng bình chữa cháy bột / CO₂ cát khô.", "Dùng xô nước tạt thật mạnh vào ngọn lửa.", "Dùng quạt thổi mạnh để ngọn lửa tản bớt nhiệt.", "Đổ thêm dầu ăn để làm loãng xăng."], "ans": 0, "exp": "• Trùm chăn ướt hoặc phủ cát/bột cách ly hoàn toàn chất cháy với oxy không khí để ngọn lửa tự tắt.<br>• TUYỆT ĐỐI KHÔNG dùng nước vì xăng dầu nhẹ hơn nước nổi lên trên mặt nước làm đám cháy lan rộng dữ dội.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Hydrocarbon no chỉ chứa liên kết [ ... ], phản ứng đặc trưng là phản ứng [ ... ]. Hydrocarbon không no chứa liên kết [ ... ], phản ứng đặc trưng là phản ứng [ ... ]. Arene có vòng benzen thể hiện tính thơm.", "opts": ["đơn — thế — bội (đôi, ba) — cộng", "cộng — bội (đôi, ba) — thế — đơn", "thế — bội (đôi, ba) — cộng — đơn", "bội (đôi, ba) — cộng — đơn — thế"], "ans": 0, "exp": "• Liên kết đơn, phản ứng thế, liên kết bội, phản ứng cộng.", "svgGraph": null}, {"q": "Chất nào sau đây được dùng để ủ chín trái cây nhân tạo an toàn trong nông nghiệp hiện đại?", "opts": ["Khí Ethylene (kích thích sinh tổng hợp enzyme làm chín trái)", "Khí Methane", "Khí Sulfur dioxide độc hại", "Khí Chlorine"], "ans": 0, "exp": "• Khí ethylene là phytohormone tự nhiên của thực vật, kích thích quả tăng hô hấp và chuyển hóa tinh bột thành đường, giúp trái cây chín đều, thơm ngon và hoàn toàn không độc hại.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "19": [{"q": "Dẫn xuất halogen của hydrocarbon là hợp chất thu được khi:", "opts": ["Thay thế một hay nhiều nguyên tử hydrogen trong phân tử hydrocarbon bằng nguyên tử halogen (F, Cl, Br, I).", "Cộng phân tử halogen vào vòng benzen.", "Oxi hóa hydrocarbon bằng clo.", "Tách phân tử halogen ra khỏi hợp chất."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Khi thay thế một hay nhiều nguyên tử hydrogen trong phân tử hydrocarbon bằng một hay nhiều nguyên tử halogen, ta thu được dẫn xuất halogen của hydrocarbon (R–X).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phản ứng thủy phân dẫn xuất halogen trong dung dịch kiềm (như bromoethane CH₃CH₂Br + NaOH, đun nóng) thu được sản phẩm hữu cơ thuộc loại nào?", "opts": ["Alcohol (rượu): CH₃CH₂Br + NaOH --t°--> CH₃CH₂OH + NaBr", "Alkene", "Aldehyde", "Ester"], "ans": 0, "exp": "• Phản ứng thế nhóm halogen (-X) bằng nhóm hydroxyl (-OH) trong môi trường kiềm nóng:<br>R–X + NaOH --t°--> R–OH + NaX.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét quy tắc tách Zaitsev khi tách hydrogen halide (HX) ra khỏi dẫn xuất halogen (với xúc tác KOH trong cồn, đun nóng):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Hợp chất Teflon (-CF₂-CF₂-)n có khả năng chống dính, chịu nhiệt, cách điện và trơ với hóa chất cực tốt dùng làm lớp chống dính chảo rán, được trùng hợp từ monomer nào?", "opts": ["Tetrafluoroethylene (CF₂=CF₂)", "Vinyl chloride (CH₂=CHCl)", "Ethylene (CH₂=CH₂)", "Trichloroethylene"], "ans": 0, "exp": "• Trùng hợp CF₂=CF₂ tạo poly(tetrafluoroethylene) hay Teflon.<br>• Liên kết C–F cực bền vững làm Teflon chịu được nhiệt độ cao trên 300 °C và không phản ứng với acid kiềm đặc.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các dẫn xuất halogen (Cột A) với ứng dụng quan trọng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Chloroform (CHCl₃) ➔ A. Thuốc gây mê lịch sử trong y học và dung môi hòa tan chất béo, sáp.", "1. Chloroform (CHCl₃) ➔ B. Lớp phủ chống dính chảo chiên rán và van chịu hóa chất.", "1. Chloroform (CHCl₃) ➔ C. Hóa chất xông hơi khử trùng nông sản (hiện bị hạn chế).", "1. Chloroform (CHCl₃) ➔ D. Thuốc xịt gây tê cục bộ giảm đau chấn thương thể thao."], "ans": 0, "exp": "• Ứng dụng thực tế của các dẫn xuất halogen.", "svgGraph": null}, {"q": "Tại sao các cầu thủ bóng đá khi bị chấn thương đau đớn trên sân thường được nhân viên y tế xịt một luồng hơi lạnh làm đông cứng tạm thời (thuốc xịt lạnh ethyl chloride C₂H₅Cl)?", "opts": ["Vì ethyl chloride có nhiệt độ sôi thấp (12,3 °C), khi xịt lên da bay hơi cực nhanh thu nhiệt mạnh làm đóng băng mô tạm thời, phong bế dẫn truyền thần kinh cảm giác đau.", "Vì thuốc khử trùng tiêu diệt vi khuẩn vết thương.", "Vì làm tan máu bầm tức thì.", "Vì làm giãn cơ bắp."], "ans": 0, "exp": "• C₂H₅Cl sôi ở 12,3 °C. Khi xịt lên da người (37 °C) nó lập tức sôi và bay hơi mãnh liệt, thu nhiệt làm nhiệt độ da tụt xuống dưới 0 °C làm tê liệt tạm thời đầu mút dây thần kinh cảm giác.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét phản ứng nhận biết nguyên tố halogen trong dẫn xuất halogen R–X:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Nghị định thư Montreal (1987) là một thỏa ước quốc tế lịch sử nhằm mục đích bảo vệ môi trường toàn cầu bằng cách loại bỏ hoàn toàn việc sản xuất và sử dụng chất nào?", "opts": ["Các chất CFC (chlorofluorocarbon) phá hủy tầng ozone", "Khí Carbon dioxide (CO₂)", "Chất thải phóng xạ", "Thuốc trừ sâu hữu cơ"], "ans": 0, "exp": "• Nghị định thư Montreal thành công rực rỡ trong việc cấm triệt để CFC (như CF₂Cl₂) trong môi chất lạnh tủ lạnh, điều hòa, giúp lỗ thủng tầng ozone Nam Cực đang dần tự phục hồi.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Dẫn xuất halogen tham gia hai phản ứng hóa học quan trọng: phản ứng [ ... ] nguyên tử halogen bằng nhóm -OH trong môi trường kiềm đun nóng; và phản ứng [ ... ] hydrogen halide (HX) tuân theo quy tắc [ ... ]. Khí CFC trước đây dùng làm chất làm lạnh đã bị cấm do phá hủy [ ... ] của khí quyển.", "opts": ["thế — tách — Zaitsev — tầng ozone", "tầng ozone — Zaitsev — tách — thế", "tách — Zaitsev — tầng ozone — thế", "Zaitsev — tầng ozone — thế — tách"], "ans": 0, "exp": "• Phản ứng thế, phản ứng tách, quy tắc Zaitsev, tầng ozone.", "svgGraph": null}, {"q": "Sản phẩm chính của phản ứng tách HBr từ 2-bromopentane (CH₃–CHBr–CH₂–CH₂–CH₃) với xúc tác KOH trong cồn đun nóng là:", "opts": ["Pent-2-ene (CH₃–CH=CH–CH₂–CH₃)", "Pent-1-ene (CH₂=CH–CH₂–CH₂–CH₃)", "Pentane", "Pentyne"], "ans": 0, "exp": "• Nguyên tử Br ở C(2). Hai carbon kề bên là C(1) bậc I và C(3) bậc II.<br>• Theo quy tắc Zaitsev: H bị tách ưu tiên ở C(3) bậc cao hơn ⇒ tạo sản phẩm chính là pent-2-ene.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "20": [{"q": "Alcohol là hợp chất hữu cơ trong phân tử có chứa nhóm chức nào liên kết trực tiếp với nguyên tử carbon no?", "opts": ["Nhóm hydroxyl (–OH)", "Nhóm carboxyl (–COOH)", "Nhóm aldehyde (–CHO)", "Nhóm amino (–NH₂)"], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Alcohol là hợp chất hữu cơ trong phân tử có nhóm hydroxyl (–OH) liên kết trực tiếp với nguyên tử carbon no (C lai hóa sp³).<br>• Công thức chung của alcohol no, đơn chức, mạch hở: CnH2n+1OH (n ≥ 1).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nhiệt độ sôi của alcohol cao hơn nhiều so với các hydrocarbon, dẫn xuất halogen hoặc ether có khối lượng phân tử tương đương là do nguyên nhân nào?", "opts": ["Giữa các phân tử alcohol tạo được liên kết hydrogen liên phân tử bền vững.", "Alcohol có khối lượng phân tử nặng hơn.", "Alcohol có liên kết ion trong phân tử.", "Do alcohol dễ bay hơi."], "ans": 0, "exp": "• Nhóm –OH phân cực mạnh tạo liên kết hydrogen liên phân tử giữa R–O–H···O(H)–R, cần cung cấp nhiệt lượng lớn để phá vỡ nên nhiệt độ sôi của alcohol cao vọt so với các chất không có liên kết H.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét phản ứng của alcohol với kim loại kiềm Na:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Đun nóng ethanol với H₂SO₄ đặc ở 170 °C thu được khí nào?", "opts": ["Ethylene (C₂H₄): C₂H₅OH --H₂SO₄ đ, 170°C--> C₂H₄↑ + H₂O", "Diethyl ether ((C₂H₅)₂O)", "Methane (CH₄)", "Acetylene (C₂H₂)"], "ans": 0, "exp": "• Ở 170 °C: Xảy ra phản ứng tách nước nội phân tử tạo alkene tương ứng: C₂H₅OH --H₂SO₄ đ, 170°C--> CH₂=CH₂↑ + H₂O.<br>• Ở 140 °C: Xảy ra phản ứng tách nước liên phân tử tạo ether: 2C₂H₅OH --H₂SO₄ đ, 140°C--> C₂H₅OC₂H₅ + H₂O.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép bậc của alcohol (Cột A) với sản phẩm oxi hóa không hoàn toàn bằng CuO nung nóng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Alcohol bậc I (R–CH₂OH) ➔ A. Tạo Aldehyde (R–CHO) và Cu kim loại màu đỏ gạch.", "1. Alcohol bậc I (R–CH₂OH) ➔ B. Tạo Ketone (R–CO–R') và Cu kim loại màu đỏ gạch.", "1. Alcohol bậc I (R–CH₂OH) ➔ C. Bền vững, không bị oxi hóa ở điều kiện này.", "1. Alcohol bậc I (R–CH₂OH) ➔ D. Thu được CO₂ và H₂O với n_H₂O > n_CO₂."], "ans": 0, "exp": "• Phản ứng oxi hóa đặc trưng phân biệt 3 bậc alcohol.", "svgGraph": null}, {"q": "Hợp chất polyalcohol nào sau đây có 3 nhóm –OH liền kề, có vị ngọt thanh, dùng trong mỹ phẩm dưỡng ẩm và pha chế thuốc nổ nitroglycerin?", "opts": ["Glycerol (Glycerin - C₃H₅(OH)₃ hay propan-1,2,3-triol)", "Ethylene glycol (C₂H₄(OH)₂)", "Ethanol (C₂H₅OH)", "Phenol (C₆H₅OH)"], "ans": 0, "exp": "• Glycerol có công thức CH₂OH–CHOH–CH₂OH, là chất lỏng sánh không màu, giữ ẩm tuyệt vời cho da trong kem dưỡng mỹ phẩm, và tác dụng với HNO₃ đặc tạo thuốc nổ nitroglycerin.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét phản ứng đặc trưng phân biệt polyalcohol có các nhóm -OH liền kề:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chất độc methanol (CH₃OH) có trong rượu giả nấu bằng cồn công nghiệp khi uống vào cơ thể bị enzyme gan chuyển hóa thành chất nào cực độc làm mù mắt và tử vong nhanh chóng?", "opts": ["Formaldehyde (HCHO) và Formic acid (HCOOH)", "Acetic acid (CH₃COOH)", "Acetaldehyde", "Glucose"], "ans": 0, "exp": "• Enzyme alcohol dehydrogenase ở gan chuyển methanol thành formaldehyde và acid formic gây nhiễm toan chuyển hóa máu nặng, phá hủy dây thần kinh thị giác làm mù vĩnh viễn và suy đa tạng tử vong.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Alcohol có nhiệt độ sôi cao và tan nhiều trong nước nhờ khả năng tạo liên kết [ ... ]. Phản ứng đặc trưng của alcohol gồm phản ứng với kim loại [ ... ], phản ứng tách nước tạo [ ... ] ở 170 °C hoặc tạo ether ở 140 °C. Oxi hóa alcohol bậc I bằng CuO nung nóng thu được [ ... ].", "opts": ["hydrogen — kiềm (Na, K) — alkene — aldehyde", "aldehyde — alkene — kiềm (Na, K) — hydrogen", "kiềm (Na, K) — alkene — aldehyde — hydrogen", "alkene — aldehyde — hydrogen — kiềm (Na, K)"], "ans": 0, "exp": "• Liên kết hydrogen, kim loại kiềm, alkene, aldehyde.", "svgGraph": null}, {"q": "Độ cồn (độ rượu) ghi trên nhãn chai rượu (ví dụ rượu 40°) cho biết điều gì?", "opts": ["Số mililit ethanol nguyên chất có trong 100 mililit dung dịch rượu ở 20 °C.", "Khối lượng ethanol có trong 100 gam dung dịch rượu.", "Nhiệt độ sôi của chai rượu.", "Hàm lượng đường có trong rượu."], "ans": 0, "exp": "• Độ rượu = (V_ethanol / V_dung dịch) · 100.<br>• Rượu 40° nghĩa là trong 100 mL dung dịch rượu có chứa đúng 40 mL ethanol nguyên chất.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "21": [{"q": "Phenol là hợp chất hữu cơ trong phân tử có nhóm hydroxyl (–OH) liên kết như thế nào?", "opts": ["Liên kết trực tiếp với nguyên tử carbon của vòng benzene.", "Liên kết với mạch nhánh no của arene.", "Liên kết với nguyên tử carbon không no của alkene.", "Liên kết với nguyên tử oxygen khác."], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Phenol là những hợp chất hữu cơ trong phân tử có nhóm –OH liên kết trực tiếp với nguyên tử carbon của vòng benzene.<br>• Phân tử đơn giản nhất là C₆H₅OH (phenol). Nếu nhóm –OH gắn vào mạch nhánh (như C₆H₅–CH₂–OH) thì thuộc loại thơm alcohol (benzyl alcohol), không phải phenol.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Do ảnh hưởng qua lại giữa vòng benzene và nhóm –OH, tính acid của phenol so với alcohol và carbonic acid (H₂CO₃) là:", "opts": ["Mạnh hơn alcohol nhưng yếu hơn acid carbonic (H₂CO₃), không làm đổi màu quỳ tím.", "Mạnh hơn H₂SO₄ làm quỳ tím đỏ rực.", "Yếu hơn alcohol.", "Phenol có tính base mạnh."], "ans": 0, "exp": "• Cặp electron p của O liên hợp vào hệ electron π của vòng benzene làm liên kết O–H phân cực mạnh hơn alcohol ⇒ phenol có tính acid yếu, tác dụng được với dung dịch kiềm NaOH tạo muối C₆H₅ONa tan.<br>• Nhưng tính acid yếu hơn H₂CO₃ nên không làm đổi màu quỳ tím và bị CO₂ đẩy ra khỏi muối: C₆H₅ONa + CO₂ + H₂O -> C₆H₅OH↓ (vẩn đục) + NaHCO₃.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng hóa học đặc trưng của phenol:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Hiện tượng khi nhỏ dung dịch nước bromine vào ống nghiệm chứa dung dịch phenol là gì?", "opts": ["Nước bromine bị mất màu và xuất hiện ngay kết tủa màu trắng của 2,4,6-tribromophenol.", "Dung dịch chuyển sang màu tím sẫm.", "Có sủi bọt khí không màu.", "Không có hiện tượng gì xảy ra."], "ans": 0, "exp": "• C₆H₅OH + 3Br₂ -> C₆H₂(OH)Br₃↓ (kết tủa trắng) + 3HBr.<br>• Nhóm –OH đẩy electron hoạt hóa vị trí ortho và para của vòng benzene giúp phản ứng thế xảy ra tức thì không cần xúc tác hay đun nóng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các hóa chất (Cột A) với hiện tượng khi cho tác dụng với phenol C₆H₅OH (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Dung dịch NaOH ➔ A. Dung dịch phenol vẩn đục tan hoàn toàn thành dung dịch trong suốt.", "1. Dung dịch NaOH ➔ B. Xuất hiện kết tủa màu trắng 2,4,6-tribromophenol.", "1. Dung dịch NaOH ➔ C. Xuất hiện kết tủa màu vàng tinh thể acid picric.", "1. Dung dịch NaOH ➔ D. Dung dịch bị vẩn đục trở lại do phenol ít tan bị giải phóng."], "ans": 0, "exp": "• Các hiện tượng thí nghiệm cốt lõi của bài Phenol.", "svgGraph": null}, {"q": "Phenol có ứng dụng lớn nhất trong công nghiệp hóa chất để sản xuất loại vật liệu nào?", "opts": ["Nhựa phenol-formaldehyde (nhựa bakelite, keo dán gỗ ép) và dược phẩm (aspirin).", "Sản xuất cao su nhân tạo.", "Sản xuất xà phòng gia đình.", "Sản xuất nước ngọt có gas."], "ans": 0, "exp": "• Hàng triệu tấn phenol được dùng hàng năm để ngưng tụ với formaldehyde sản xuất nhựa bakelite (vỏ thiết bị điện, keo dán gỗ) và tổng hợp salicylic acid để sản xuất thuốc giảm đau hạ sốt aspirin.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính chất vật lí và độc tính của phenol:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Để phân biệt 2 lọ mất nhãn chứa: Cồn ethanol (C₂H₅OH) và Phenol (C₆H₅OH lỏng), người ta dùng thuốc thử đơn giản nhất là:", "opts": ["Dung dịch nước bromine (phenol tạo kết tủa trắng, ethanol không hiện tượng)", "Mẩu kim loại Na", "Dung dịch quỳ tím", "Dung dịch NaCl"], "ans": 0, "exp": "• Phenol tác dụng với nước bromine tạo ngay kết tủa trắng 2,4,6-tribromophenol.<br>• Ethanol không tác dụng với nước bromine, dung dịch vẫn giữ nguyên màu vàng nâu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Phenol có công thức phân tử là [ ... ]. Nhóm –OH liên kết trực tiếp với vòng [ ... ]. Phenol có tính acid yếu hơn H₂CO₃ nên không làm đổi màu [ ... ]. Thuốc thử đặc trưng để nhận biết phenol là dung dịch nước [ ... ] cho kết tủa trắng.", "opts": ["C₆H₅OH — benzene — quỳ tím — bromine", "bromine — quỳ tím — benzene — C₆H₅OH", "benzene — quỳ tím — bromine — C₆H₅OH", "quỳ tím — bromine — C₆H₅OH — benzene"], "ans": 0, "exp": "• C₆H₅OH, vòng benzene, quỳ tím, nước bromine.", "svgGraph": null}, {"q": "Trong y học cổ truyền và dược phẩm, phenol và các dẫn xuất của phenol thường được dùng làm chất gì nhờ khả năng diệt khuẩn mạnh?", "opts": ["Chất sát trùng, khử khuẩn phòng mổ và dụng cụ y tế", "Thuốc bổ sung vitamin", "Chất tạo ngọt không đường", "Dung dịch truyền dinh dưỡng"], "ans": 0, "exp": "• Joseph Lister (1865) là người đầu tiên dùng dung dịch phenol (carbolic acid) làm chất sát trùng rửa tay và dụng cụ phẫu thuật, cứu sống hàng triệu bệnh nhân khỏi nhiễm trùng huyết.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "22": [{"q": "Sắp xếp theo thứ tự nhiệt độ sôi TĂNG DẦN của các chất có phân tử khối tương đương: C₂H₆ (ethane, M=30), CH₃OCH₃ (dimethyl ether, M=46), C₂H₅OH (ethanol, M=46):", "opts": ["C₂H₆ < CH₃OCH₃ < C₂H₅OH", "C₂H₅OH < CH₃OCH₃ < C₂H₆", "CH₃OCH₃ < C₂H₆ < C₂H₅OH", "C₂H₆ < C₂H₅OH < CH₃OCH₃"], "ans": 0, "exp": "• C₂H₆ không phân cực, sôi ở -88,6 °C.<br>• CH₃OCH₃ phân cực nhẹ nhưng không có liên kết hydrogen liên phân tử, sôi ở -24 °C.<br>• C₂H₅OH có liên kết hydrogen liên phân tử bền vững, sôi ở 78,3 °C.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho 4 chất: (1) C₂H₅Cl; (2) C₂H₅OH; (3) C₆H₅OH (phenol); (4) C₆H₅CH₂OH (benzyl alcohol). Chất nào tác dụng được với dung dịch kiềm NaOH ở điều kiện thường?", "opts": ["Chỉ có (3) C₆H₅OH (Phenol)", "Chỉ có (2) và (3)", "Chỉ có (1) và (4)", "Cả 4 chất"], "ans": 0, "exp": "• Ở nhiệt độ thường: Chỉ có Phenol có tính acid tác dụng với dung dịch NaOH tạo muối C₆H₅ONa.<br>• C₂H₅Cl chỉ phản ứng với NaOH khi đun sôi.<br>• Alcohol (C₂H₅OH, C₆H₅CH₂OH) không tác dụng với dung dịch kiềm NaOH.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các thí nghiệm nhận biết các chất hữu cơ chứa nhóm –OH:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Chất nào sau đây khi đun nóng với H₂SO₄ đặc ở 170 °C thu được alkene duy nhất là but-2-ene?", "opts": ["Butan-2-ol (CH₃–CH(OH)–CH₂–CH₃, sản phẩm chính theo Zaitsev)", "Butan-1-ol", "2-methylpropan-2-ol", "Ethanol"], "ans": 0, "exp": "• Butan-2-ol tách nước theo quy tắc Zaitsev ưu tiên tách H ở C(3) bậc II tạo but-2-ene (CH₃–CH=CH–CH₃) là sản phẩm chính chiếm ưu thế lớn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các chất (Cột A) với thuốc thử đặc trưng để nhận biết (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Phenol (C₆H₅OH) ➔ A. Dung dịch nước bromine (xuất hiện kết tủa trắng).", "1. Phenol (C₆H₅OH) ➔ B. Dung dịch Cu(OH)₂ ở nhiệt độ thường (tạo dung dịch xanh lam thẫm).", "1. Phenol (C₆H₅OH) ➔ C. Bột CuO nung nóng (tạo Cu màu đỏ và hơi làm mất màu quỳ tím).", "1. Phenol (C₆H₅OH) ➔ D. Đun với kiềm, acid hóa bằng HNO₃ rồi thêm dung dịch AgNO₃ (kết tủa trắng AgCl)."], "ans": 0, "exp": "• Các thuốc thử nhận biết đặc trưng từng chất.", "svgGraph": null}, {"q": "Cho 9,2 gam ethanol (C₂H₅OH) tác dụng hoàn toàn với kim loại Na dư. Thể tích khí H₂ thu được ở điều kiện chuẩn (25 °C, 1 bar) là bao nhiêu?", "opts": ["2,479 L (0,1 mol)", "2,24 L", "1,12 L", "4,958 L"], "ans": 0, "exp": "• n_ethanol = 9,2 / 46 = 0,2 mol.<br>• 2C₂H₅OH + 2Na -> 2C₂H₅ONa + H₂↑.<br>• n_H₂ = n_ethanol / 2 = 0,1 mol.<br>• Thể tích khí ở 25 °C, 1 bar: V = 0,1 · 24,79 = 2,479 L.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các ảnh hưởng qua lại giữa các nhóm nguyên tử trong phân tử phenol:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Khi đun nóng hỗn hợp gồm ethanol và methanol với H₂SO₄ đặc ở 140 °C, số lượng ether tối đa có thể thu được là:", "opts": ["3 ether (CH₃–O–CH₃, C₂H₅–O–C₂H₅, CH₃–O–C₂H₅)", "2 ether", "1 ether", "4 ether"], "ans": 0, "exp": "• Phản ứng tách nước liên phân tử giữa 2 alcohol:<br>1. CH₃OH + CH₃OH -> CH₃OCH₃ + H₂O (dimethyl ether).<br>2. C₂H₅OH + C₂H₅OH -> C₂H₅OC₂H₅ + H₂O (diethyl ether).<br>3. CH₃OH + C₂H₅OH -> CH₃OC₂H₅ + H₂O (ethyl methyl ether).<br>• Tổng cộng thu được tối đa 3 ether.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Alcohol và phenol đều có nhóm [ ... ] (–OH) trong phân tử. Nhưng phenol có nhóm –OH gắn trực tiếp vào vòng [ ... ] nên thể hiện tính [ ... ] yếu và phản ứng được với dung dịch kiềm NaOH. Dung dịch nước bromine là thuốc thử dùng để nhận biết [ ... ] nhờ tạo kết tủa trắng.", "opts": ["hydroxyl — benzene — acid — phenol", "phenol — acid — benzene — hydroxyl", "benzene — acid — phenol — hydroxyl", "acid — phenol — hydroxyl — benzene"], "ans": 0, "exp": "• Nhóm hydroxyl, vòng benzene, tính acid, nhận biết phenol.", "svgGraph": null}, {"q": "Thuốc sát khuẩn cồn y tế dùng vệ sinh vết thương và diệt virus vi khuẩn hiệu quả nhất có nồng độ cồn là bao nhiêu độ?", "opts": ["70° (cồn 70 độ)", "90°", "100° tuyệt đối", "40°"], "ans": 0, "exp": "• Cồn 70° có tỉ lệ nước và cồn tối ưu: cồn làm biến tính protein của vi khuẩn và virus, trong khi hàm lượng nước 30% giúp cồn không bị bay hơi quá nhanh và duy trì độ ẩm đủ lâu để ngấm sâu vào màng tế bào tiêu diệt mầm bệnh.<br>• Cồn 90° bay hơi quá nhanh và làm đông cứng màng protein bên ngoài tạo vỏ bọc bảo vệ vi khuẩn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "23": [{"q": "Hợp chất carbonyl là các hợp chất hữu cơ trong phân tử có chứa nhóm chức nào sau đây?", "opts": ["Nhóm carbonyl (>C=O)", "Nhóm carboxyl (–COOH)", "Nhóm hydroxyl (–OH)", "Nhóm amino (–NH₂)"], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Hợp chất carbonyl là hợp chất hữu cơ trong phân tử chứa nhóm carbonyl >C=O.<br>• Nếu nhóm >C=O liên kết với ít nhất 1 nguyên tử H thì là Aldehyde (R–CHO).<br>• Nếu nhóm >C=O liên kết với 2 gốc hydrocarbon thì là Ketone (R–CO–R').<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Thuốc thử Tollens (phức bạc trong dung dịch ammonia [Ag(NH₃)₂]OH) dùng để nhận biết aldehyde nhờ phản ứng tạo ra lớp tráng gương sáng bóng của kim loại nào?", "opts": ["Bạc (Silver - Ag kim loại, phản ứng tráng bạc)", "Đồng (Copper - Cu đỏ)", "Vàng (Gold - Au)", "Chì (Lead - Pb)"], "ans": 0, "exp": "• Phản ứng tráng bạc (Silver mirror test):<br>R–CHO + 2[Ag(NH₃)₂]OH --t°--> R–COONH₄ + 2Ag↓ (bám sáng bóng vào thành ống nghiệm) + 3NH₃ + H₂O.<br>• Ketone thông thường không tham gia phản ứng này.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng khử và oxi hóa hợp chất carbonyl:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Phản ứng tạo Iodoform (phản ứng với I₂ trong dung dịch NaOH đun nóng tạo kết tủa vàng nhạt CHI₃ có mùi sát trùng) dùng để nhận biết hợp chất có cấu trúc nào?", "opts": ["Hợp chất chứa nhóm methyl ketone (CH₃–C=O) hoặc nhóm CH₃–CH(OH)–", "Mọi hợp chất aldehyde", "Mọi hợp chất carboxylic acid", "Mọi hydrocarbon no"], "ans": 0, "exp": "• Phản ứng iodoform đặc trưng: CH₃–CO–R + 3I₂ + 4NaOH -> R–COONa + CHI₃↓ (triiodomethane màu vàng) + 3NaI + 3H₂O.<br>• Acetone (CH₃COCH₃), acetaldehyde (CH₃CHO), ethanol (CH₃CH₂OH) đều cho kết tủa vàng CHI₃.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các hợp chất carbonyl (Cột A) với ứng dụng thực tế quan trọng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Formaldehyde (HCHO / dung dịch fomalin 37-40%) ➔ A. Ngâm ướp mẫu bệnh phẩm sinh học và sản xuất keo dán gỗ, nhựa bakelite.", "1. Formaldehyde (HCHO / dung dịch fomalin 37-40%) ➔ B. Dung môi tẩy sơn móng tay, pha sơn và hòa tan chất béo trong phòng thí nghiệm.", "1. Formaldehyde (HCHO / dung dịch fomalin 37-40%) ➔ C. Tinh dầu hạnh nhân, hương liệu tạo mùi thơm trong bánh kẹo, mỹ phẩm.", "1. Formaldehyde (HCHO / dung dịch fomalin 37-40%) ➔ D. Hương vani tự nhiên tạo hương vị hấp dẫn cho bánh ngọt, kem, sữa chua."], "ans": 0, "exp": "• Các ứng dụng rất quen thuộc của aldehyde và ketone trong đời sống.", "svgGraph": null}, {"q": "Formol (hay formalin) là dung dịch bão hòa trong nước chứa khoảng 37% - 40% chất nào sau đây?", "opts": ["Methanal (Formaldehyde - HCHO)", "Ethanal (Acetaldehyde - CH₃CHO)", "Acetone (CH₃COCH₃)", "Formic acid (HCOOH)"], "ans": 0, "exp": "• Formol là dung dịch 37 - 40% formaldehyde trong nước, có tác dụng làm đông tụ protein để diệt khuẩn mạnh và chống thối rữa, dùng để ngâm giữ tiêu bản giải phẫu động vật và người.<br>• Cấm tuyệt đối lạm dụng formol để bảo quản bánh phở, bún, thực phẩm.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về tính chất vật lí của aldehyde và ketone:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Cho 2,9 gam một aldehyde no, đơn chức, mạch hở X tác dụng với lượng dư thuốc thử Tollens đun nóng thu được 10,8 gam Ag kết tủa. Công thức phân tử của X là:", "opts": ["C₂H₅–CHO (Propionaldehyde, M = 58)", "CH₃–CHO (Acetaldehyde, M = 44)", "HCHO (Formaldehyde, M = 30)", "C₃H₇–CHO (M = 72)"], "ans": 0, "exp": "• n_Ag = 10,8 / 108 = 0,1 mol.<br>• RCHO + 2Ag⁺ -> 2Ag ⇒ n_RCHO = 0,1 / 2 = 0,05 mol.<br>• Khối lượng mol: M = 2,9 / 0,05 = 58 g/mol (R + 29 = 58 ⇒ R = 29: gốc C₂H₅–).<br>• CTPT của X là C₂H₅CHO (propanal).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Aldehyde và ketone đều chứa nhóm [ ... ] (>C=O). Aldehyde có tính [ ... ] khi tác dụng với thuốc thử Tollens tạo kết tủa [ ... ] sáng bóng và tác dụng với Cu(OH)₂ trong kiềm nóng tạo kết tủa đỏ gạch [ ... ].", "opts": ["carbonyl — khử — bạc (Ag) — Cu₂O", "Cu₂O — bạc (Ag) — khử — carbonyl", "khử — bạc (Ag) — Cu₂O — carbonyl", "bạc (Ag) — Cu₂O — carbonyl — khử"], "ans": 0, "exp": "• Nhóm carbonyl, tính khử của aldehyde, kết tủa Ag và Cu₂O.", "svgGraph": null}, {"q": "Chất nào sau đây KHÔNG THAM GIA phản ứng tráng bạc với thuốc thử Tollens?", "opts": ["Acetone (CH₃COCH₃, ketone)", "Formaldehyde (HCHO)", "Acetaldehyde (CH₃CHO)", "Benzaldehyde (C₆H₅CHO)"], "ans": 0, "exp": "• Acetone là ketone thông thường không có nhóm –CHO nên không bị oxi hóa bởi thuốc thử Tollens, không tạo gương bạc.<br>• Các chất còn lại đều là aldehyde nên đều tráng bạc.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "24": [{"q": "Carboxylic acid là hợp chất hữu cơ trong phân tử có chứa nhóm chức nào liên kết với gốc hydrocarbon hoặc nguyên tử hydrogen?", "opts": ["Nhóm carboxyl (–COOH)", "Nhóm carbonyl (>C=O)", "Nhóm hydroxyl (–OH)", "Nhóm ester (–COO–)"], "ans": 0, "exp": "• <b>Định nghĩa SGK Hóa 11:</b> Carboxylic acid là những hợp chất hữu cơ trong phân tử có nhóm carboxyl (–COOH) liên kết trực tiếp với nguyên tử carbon hoặc nguyên tử hydrogen.<br>• Công thức chung của acid no, đơn chức, mạch hở: CnH2n+1COOH (n ≥ 0) hay C_m H_{2m} O₂ (m ≥ 1).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Tại sao nhiệt độ sôi của carboxylic acid cao hơn hẳn so với alcohol có cùng khối lượng phân tử (ví dụ CH₃COOH sôi ở 118 °C trong khi C₃H₇OH sôi ở 97 °C)?", "opts": ["Vì giữa các phân tử acid tạo được liên kết hydrogen liên phân tử dạng dimer bền vững hơn nhiều so với alcohol.", "Vì acid có khối lượng riêng lớn hơn.", "Vì acid phân li hoàn toàn thành ion ở thể hơi.", "Vì acid có nhóm –COOH cồng kềnh hơn."], "ans": 0, "exp": "• Hai phân tử carboxylic acid tạo thành liên kết hydrogen đôi khép kín (dạng dimer) hoặc polymer mạch dài rất bền vững, đòi hỏi năng lượng rất lớn để bẻ gãy nên nhiệt độ sôi của carboxylic acid cao nhất trong các dẫn xuất chứa oxy.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các tính chất hóa học chung của carboxylic acid (tính acid):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Phản ứng ester hóa giữa acetic acid và ethanol có xúc tác acid H₂SO₄ đặc đun nóng là phản ứng:", "opts": ["Thuận nghịch (hai chiều) tỏa nhiệt nhẹ, sinh ra ethyl acetate có mùi thơm hoa quả.", "Hoàn toàn một chiều.", "Tạo ra kết tủa màu trắng.", "Giải phóng khí hydrogen mãnh liệt."], "ans": 0, "exp": "• CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ (ethyl acetate) + H₂O (xúc tác H₂SO₄ đặc, t°).<br>• Đây là phản ứng thuận nghịch, H₂SO₄ đặc vừa là chất xúc tác vừa hút nước để làm cân bằng chuyển dịch sang phải tăng hiệu suất.<br>• Ethyl acetate là chất lỏng nhẹ hơn nước, có mùi thơm hoa quả đặc trưng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các carboxylic acid (Cột A) với nguồn gốc tự nhiên / ứng dụng đặc trưng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Acetic acid (CH₃COOH) ➔ A. Thành phần chính tạo vị chua của giấm ăn (nồng độ 2 - 5%).", "1. Acetic acid (CH₃COOH) ➔ B. Có trong nọc kiến, nọc ong, vòi chích của sâu róm gây bỏng rát da.", "1. Acetic acid (CH₃COOH) ➔ C. Tạo vị chua thanh mát đặc trưng của quả chanh, cam, bưởi.", "1. Acetic acid (CH₃COOH) ➔ D. Có trong khế chua, lá me và tạo sỏi thận canxi oxalat nếu dư thừa."], "ans": 0, "exp": "• Các carboxylic acid rất quen thuộc trong ẩm thực và đời sống tự nhiên.", "svgGraph": null}, {"q": "Trong các carboxylic acid sau, acid duy nhất CÓ THAM GIA phản ứng tráng bạc với thuốc thử Tollens là:", "opts": ["Formic acid (HCOOH, do trong cấu tạo chứa nhóm aldehyde –CHO)", "Acetic acid (CH₃COOH)", "Propionic acid (C₂H₅COOH)", "Benzoic acid (C₆H₅COOH)"], "ans": 0, "exp": "• Phân tử HCOOH có công thức cấu tạo H–C(=O)–OH, vừa chứa nhóm carboxyl –COOH vừa chứa nhóm aldehyde H–C(=O)–.<br>• Do đó HCOOH vừa có tính acid vừa có tính khử tham gia phản ứng tráng bạc tạo Ag sáng bóng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các ứng dụng đời sống của giấm ăn (dung dịch acid acetic 2 - 5%):<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Để trung hòa hoàn toàn 100 mL dung dịch acid acetic (CH₃COOH) 0,1 M cần dùng vừa đủ bao nhiêu mililit dung dịch NaOH 0,2 M?", "opts": ["50 mL", "100 mL", "200 mL", "25 mL"], "ans": 0, "exp": "• n_acid = 0,1 · 0,1 = 0,01 mol.<br>• Phản ứng: CH₃COOH + NaOH -> CH₃COONa + H₂O.<br>• n_NaOH = n_acid = 0,01 mol.<br>• V_NaOH = n / C = 0,01 / 0,2 = 0,05 L = 50 mL.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Carboxylic acid chứa nhóm chức [ ... ] (–COOH). Acid có nhiệt độ sôi cao nhất nhờ liên kết hydrogen liên phân tử dạng [ ... ]. Acid tác dụng với alcohol tạo [ ... ] trong phản ứng este hóa thuận nghịch. Acid [ ... ] (HCOOH) là acid duy nhất tham gia phản ứng tráng bạc.", "opts": ["carboxyl — dimer — ester — formic", "formic — ester — dimer — carboxyl", "dimer — ester — formic — carboxyl", "ester — formic — carboxyl — dimer"], "ans": 0, "exp": "• Nhóm carboxyl, dạng dimer, tạo ester, acid formic.", "svgGraph": null}, {"q": "Phương pháp lên men giấm truyền thống từ rượu vang hoặc rượu nếp để sản xuất acid acetic được thực hiện nhờ vi khuẩn nào?", "opts": ["Vi khuẩn giấm (Acetobacter): C₂H₅OH + O₂ --men giấm--> CH₃COOH + H₂O", "Men rượu (Saccharomyces)", "Vi khuẩn lactic", "Vi khuẩn E. coli"], "ans": 0, "exp": "• Quá trình lên men giấm là quá trình oxi hóa sinh học ethanol nhờ vi khuẩn Acetobacter có oxy không khí: C₂H₅OH + O₂ --men giấm--> CH₃COOH + H₂O.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "25": [{"q": "Sắp xếp theo thứ tự nhiệt độ sôi TĂNG DẦN của các chất có phân tử khối tương đương: C₃H₈ (propane, M=44), CH₃CHO (acetaldehyde, M=44), C₂H₅OH (ethanol, M=46), HCOOH (formic acid, M=46):", "opts": ["C₃H₈ < CH₃CHO < C₂H₅OH < HCOOH", "HCOOH < C₂H₅OH < CH₃CHO < C₃H₈", "CH₃CHO < C₃H₈ < C₂H₅OH < HCOOH", "C₃H₈ < C₂H₅OH < CH₃CHO < HCOOH"], "ans": 0, "exp": "• C₃H₈ không phân cực, sôi ở -42 °C.<br>• CH₃CHO có nhóm >C=O phân cực nhưng không tạo liên kết H, sôi ở 21 °C.<br>• C₂H₅OH có liên kết hydrogen liên phân tử, sôi ở 78,3 °C.<br>• HCOOH có liên kết hydrogen dạng dimer cực bền, sôi ở 100,8 °C.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Chất nào sau đây phản ứng được với cả 4 chất/dung dịch: kim loại Na, dung dịch NaOH, dung dịch Na₂CO₃ và alcohol C₂H₅OH (xúc tác H₂SO₄ đặc, đun nóng)?", "opts": ["Acetic acid (CH₃COOH)", "Ethanol (C₂H₅OH)", "Acetaldehyde (CH₃CHO)", "Phenol (C₆H₅OH)"], "ans": 0, "exp": "• Acetic acid là carboxylic acid nên:<br>1. Tác dụng Na giải phóng H₂.<br>2. Tác dụng NaOH (phản ứng trung hòa).<br>3. Tác dụng Na₂CO₃ sủi bọt khí CO₂.<br>4. Tác dụng C₂H₅OH tạo ester ethyl acetate.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng phân biệt các nhóm chức hữu cơ:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Cho 6,0 gam acid acetic tác dụng với 4,6 gam ethanol có H₂SO₄ đặc xúc tác đun nóng. Sau phản ứng thu được 5,28 gam ethyl acetate (CH₃COOC₂H₅). Hiệu suất của phản ứng este hóa là:", "opts": ["60%", "75%", "80%", "50%"], "ans": 0, "exp": "• n_acid = 6,0 / 60 = 0,1 mol; n_alcohol = 4,6 / 46 = 0,1 mol (tỉ lệ 1 : 1).<br>• Theo lý thuyết thu được tối đa 0,1 mol ester (M = 88 g/mol) = 8,8 gam.<br>• Khối lượng thực tế thu được = 5,28 gam.<br>• Hiệu suất H = (5,28 / 8,8) · 100% = 60%.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ghép các thuốc thử (Cột A) với hiện tượng đặc trưng nhận biết chất hữu cơ (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["1. Thuốc thử Tollens [Ag(NH₃)₂]OH ➔ A. Nhận biết aldehyde nhờ tạo lớp gương bạc sáng bóng Ag.", "1. Thuốc thử Tollens [Ag(NH₃)₂]OH ➔ B. Nhận biết aldehyde nhờ tạo kết tủa màu đỏ gạch Cu₂O.", "1. Thuốc thử Tollens [Ag(NH₃)₂]OH ➔ C. Nhận biết carboxylic acid nhờ sủi bọt khí CO₂ mãnh liệt.", "1. Thuốc thử Tollens [Ag(NH₃)₂]OH ➔ D. Nhận biết methyl ketone nhờ tạo kết tủa vàng CHI₃."], "ans": 0, "exp": "• Các thuốc thử định tính cốt lõi của Chương 6 Hóa 11.", "svgGraph": null}, {"q": "Hai chất nào sau đây là đồng phân nhóm chức của nhau ứng với công thức phân tử C₃H₆O?", "opts": ["Propanal (CH₃CH₂CHO) và Acetone (CH₃COCH₃)", "Ethanol và Dimethyl ether", "Acetic acid và Methyl formate", "Propanoic acid và Ethyl acetate"], "ans": 0, "exp": "• C₃H₆O: aldehyde no đơn chức CnH2nO (propanal CH₃CH₂CHO) và ketone no đơn chức (acetone CH₃COCH₃) là cặp đồng phân nhóm chức kinh điển.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu tổng kết về dẫn xuất chứa oxygen của hydrocarbon:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Phương án khác", "Phương án khác", "Phương án khác", "Phương án khác"], "ans": 0, "exp": "", "svgGraph": null}, {"q": "Để loại bỏ mùi tanh của cá mè, cá chép (gây ra bởi các amine như trimethylamine có tính base) trước khi nấu, bà nội trợ thường dùng biện pháp dân gian nào?", "opts": ["Rửa cá bằng nước giấm ăn, nước chanh hoặc nấu canh chua với me, khế (chứa acid hữu cơ).", "Rửa cá bằng dung dịch xà phòng kiềm.", "Rửa cá bằng nước đường ngọt.", "Phơi nắng cá thật lâu."], "ans": 0, "exp": "• Amine có tính base phản ứng với acid hữu cơ (acetic acid trong giấm, citric acid trong chanh) tạo thành các muối ammonium không bay hơi và tan vào nước, bị rửa trôi hoàn toàn giúp cá hết sạch mùi tanh.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Điền vào chỗ trống:<br>Hợp chất carbonyl gồm [ ... ] và ketone. Aldehyde tham gia phản ứng tráng bạc với thuốc thử [ ... ]. Carboxylic acid có nhóm chức [ ... ] (–COOH), có tính acid và tham gia phản ứng [ ... ] với alcohol tạo ester có mùi thơm.", "opts": ["aldehyde — Tollens — carboxyl — este hóa", "este hóa — carboxyl — Tollens — aldehyde", "Tollens — carboxyl — este hóa — aldehyde", "carboxyl — este hóa — aldehyde — Tollens"], "ans": 0, "exp": "• Aldehyde, thuốc thử Tollens, nhóm carboxyl, phản ứng este hóa.", "svgGraph": null}, {"q": "Chất nào sau đây là thành phần chính của dầu chuối nhân tạo dùng tạo mùi thơm cho chè sen, bánh kẹo?", "opts": ["Isoamyl acetate (CH₃COOCH₂CH₂CH(CH₃)₂)", "Ethyl formate", "Benzyl acetate", "Methyl salicylate"], "ans": 0, "exp": "• Isoamyl acetate (ester điều chế từ acetic acid và isoamyl alcohol) có mùi thơm ngọt ngào đặc trưng của chuối tiêu chín, được gọi là dầu chuối nhân tạo.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}]}, "12": {"1": [{"q": "Ester no, đơn chức, mạch hở có công thức phân tử chung là gì (với n ≥ 2)?", "opts": ["C<sub>n</sub>H<sub>2n</sub>O<sub>2</sub> (n ≥ 2)", "C<sub>n</sub>H<sub>2n-2</sub>O<sub>2</sub> (n ≥ 3)", "C<sub>n</sub>H<sub>2n+2</sub>O<sub>2</sub> (n ≥ 2)", "C<sub>n</sub>H<sub>2n</sub>O (n ≥ 2)"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Phân tử ester no, đơn chức, mạch hở được tạo thành từ 1 gốc carboxylic acid no đơn chức (C<sub>m</sub>H<sub>2m+1</sub>COOH) và 1 gốc alcohol no đơn chức (C<sub>k</sub>H<sub>2k+1</sub>OH).<br>• <b>Công thức tổng quát:</b> C<sub>m</sub>H<sub>2m+1</sub>COOC<sub>k</sub>H<sub>2k+1</sub> tương đương C<sub>n</sub>H<sub>2n</sub>O<sub>2</sub> với n = m + k + 1 ≥ 2 (do m ≥ 0, k ≥ 1).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"32\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"15\" font-weight=\"800\">CẤU TẠO NHÓM CHỨC ESTER VÀ PHẢN ỨNG ESTE HÓA</text>\n  <!-- Acid + Alcohol -->\n  <rect x=\"25\" y=\"60\" width=\"140\" height=\"90\" rx=\"8\" fill=\"rgba(14,165,233,0.12)\" stroke=\"#0ea5e9\" stroke-width=\"1.5\"/>\n  <text x=\"95\" y=\"85\" text-anchor=\"middle\" fill=\"#7dd3fc\" font-size=\"13\" font-weight=\"700\">R-COOH</text>\n  <text x=\"95\" y=\"105\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"11\">+ Carboxylic Acid</text>\n  <text x=\"95\" y=\"132\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12\">R'-OH (Alcohol)</text>\n  <!-- Reversible Arrow with H2SO4, t -->\n  <path d=\"M 180 98 L 255 98 M 245 92 L 255 98 M 255 112 L 180 112 M 190 118 L 180 112\" stroke=\"#fbbf24\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n  <text x=\"217\" y=\"86\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"700\">H₂SO₄ đ, t°</text>\n  <!-- Ester + Water -->\n  <rect x=\"270\" y=\"60\" width=\"225\" height=\"90\" rx=\"8\" fill=\"rgba(52,211,153,0.12)\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n  <text x=\"382\" y=\"88\" text-anchor=\"middle\" fill=\"#6ee7b7\" font-size=\"14\" font-weight=\"800\">R–COO–R'</text>\n  <text x=\"382\" y=\"110\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"12\">Ester + H₂O</text>\n  <text x=\"382\" y=\"134\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"11\">Phản ứng thuận nghịch</text>\n  <!-- Footnote -->\n  <rect x=\"25\" y=\"165\" width=\"470\" height=\"48\" rx=\"6\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.1)\"/>\n  <text x=\"260\" y=\"185\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11.5\">H₂SO₄ đặc vừa là chất <tspan fill=\"#fbbf24\" font-weight=\"bold\">xúc tác</tspan>, vừa <tspan fill=\"#34d399\" font-weight=\"bold\">hút nước</tspan> làm cân bằng chuyển dịch sang phải</text>\n  <text x=\"260\" y=\"202\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"11\">Tăng hiệu suất tổng hợp ester</text>\n</svg>"}, {"q": "Chất nào sau đây là triester của glycerol với các acid béo (triglyceride)?", "opts": ["(C<sub>17</sub>H<sub>35</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> (tristearin)", "(C<sub>17</sub>H<sub>35</sub>COO)<sub>2</sub>C<sub>2</sub>H<sub>4</sub> (ethylene stearate)", "C<sub>15</sub>H<sub>31</sub>COOCH<sub>3</sub> (methyl palmitate)", "CH<sub>3</sub>COOC<sub>3</sub>H<sub>5</sub>(OH)<sub>2</sub> (monoacetin)"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Chất béo (triglyceride) là triester của glycerol C<sub>3</sub>H<sub>5</sub>(OH)<sub>3</sub> với các carboxylic acid mạch carbon dài, không phân nhánh (acid béo).<br>• <b>Công thức chung:</b> (RCOO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub>. Tristearin có công thức (C<sub>17</sub>H<sub>35</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> là chất béo no, ở thể rắn ở nhiệt độ thường.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nhiệt độ sôi của ester thường thấp hơn nhiều so với alcohol và carboxylic acid có cùng khối lượng mol phân tử vì nguyên nhân nào sau đây?", "opts": ["Giữa các phân tử ester không tạo được liên kết hydrogen liên phân tử với nhau.", "Ester có khối lượng phân tử nhẹ hơn không khí.", "Liên kết C–O trong nhóm chức ester phân cực quá mạnh.", "Phân tử ester có cấu trúc mạch vòng cản trở bay hơi."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Trong phân tử ester, nguyên tử H không liên kết trực tiếp với nguyên tử O có độ âm điện lớn, nên giữa các phân tử ester không hình thành được liên kết hydrogen liên phân tử như alcohol (R–OH) và carboxylic acid (R–COOH).<br>• Lực hút giữa các phân tử ester chỉ là lực tương tác van der Waals yếu, do đó ester dễ bay hơi và có nhiệt độ sôi thấp hơn hẳn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi tiến hành thí nghiệm điều chế ethyl acetate bằng phản ứng giữa ethanol và acetic acid (xúc tác H<sub>2</sub>SO<sub>4</sub> đặc), xét tính Đúng/Sai của các nhận định sau:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Acid H₂SO₄ đặc đóng vai trò vừa là chất xúc tác, vừa hút nước làm chuyển dịch cân bằng hoá học theo chiều tạo ester.", "Dùng dung dịch NaCl bão hoà cho vào hỗn hợp sau phản ứng để làm tăng khối lượng riêng của lớp chất lỏng phía dưới, giúp ester nhẹ hơn nổi lên tách lớp rõ ràng.", "Có thể thay thế acid H₂SO₄ đặc bằng dung dịch HCl đặc hoặc HNO₃ đặc mà hiệu suất phản ứng vẫn không thay đổi.", "Phản ứng este hoá là phản ứng hoàn toàn một chiều, hỗn hợp sau khi đun sôi chỉ chứa ethyl acetate và nước."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> H<sub>2</sub>SO<sub>4</sub> đặc vừa xúc tác cho phản ứng thuận nghịch, vừa hút nước để chuyển dịch cân bằng sang phải theo nguyên lí Le Chatelier.<br>• <b>Ý b [Đúng]:</b> Dung dịch NaCl bão hòa làm tăng khối lượng riêng của pha nước và làm giảm độ tan của ethyl acetate, giúp este tách lớp nổi lên trên bề mặt.<br>• <b>Ý c [Sai]:</b> Không thể thay bằng HCl (dễ bay hơi) hay HNO<sub>3</sub> đặc (tính oxi hóa mạnh gây cháy/phân hủy các chất hữu cơ).<br>• <b>Ý d [Sai]:</b> Phản ứng este hoá là phản ứng thuận nghịch, không bao giờ xảy ra hoàn toàn một chiều.", "svgGraph": null}, {"q": "Ghép tên mỗi ester đặc trưng (Cột A) với mùi thơm hoa quả / ứng dụng tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Isoamyl acetate ➔ Mùi chuối chín đặc trưng", "Isoamyl acetate ➔ Mùi hoa nhài thơm ngát (dùng trong sản xuất nước hoa)", "Isoamyl acetate ➔ Mùi hoa hồng nồng nàn", "Isoamyl acetate ➔ Mùi dứa (thơm) ngọt thanh"], "ans": 0, "exp": "• <b>1 - B:</b> Isoamyl acetate CH<sub>3</sub>COOCH<sub>2</sub>CH<sub>2</sub>CH(CH<sub>3</sub>)<sub>2</sub> có mùi chuối chín.<br>• <b>2 - A:</b> Benzyl acetate CH<sub>3</sub>COOCH<sub>2</sub>C<sub>6</sub>H<sub>5</sub> có mùi hoa nhài thoang thoảng quý phái.<br>• <b>3 - D:</b> Ethyl butyrate C<sub>3</sub>H<sub>7</sub>COOC<sub>2</sub>H<sub>5</sub> mang hương dứa chín thơm ngọt.<br>• <b>4 - C:</b> Geranyl acetate mang mùi hoa hồng nồng nàn.", "svgGraph": null}, {"q": "Chọn các từ khóa phù hợp để hoàn thành nội dung về khái niệm và phân loại chất béo:<br><i>\"Chất béo là  [ ... ]  của glycerol với các acid béo, gọi chung là  [ ... ] . Ở nhiệt độ phòng, dầu thực vật ở trạng thái  [ ... ]  do chứa chủ yếu các gốc acid béo không no; mỡ động vật ở trạng thái  [ ... ]  do chứa chủ yếu các gốc acid béo no.\"</i>", "opts": ["triester — triglyceride — lỏng — rắn", "rắn — lỏng — triglyceride — triester", "diester — triglyceride — lỏng — rắn", "triglyceride — lỏng — rắn — khí"], "ans": 0, "exp": "• <b>Định nghĩa SGK:</b> Chất béo là triester của glycerol với các acid béo (triglyceride).<br>• Gốc acid béo không no (như oleic, linoleic) có liên kết đôi C=C làm nhiệt độ nóng chảy thấp → thể lỏng.<br>• Gốc acid béo no (như palmitic, stearic) xếp chặt chẽ làm nhiệt độ nóng chảy cao → thể rắn.", "svgGraph": null}, {"q": "Thuỷ phân hoàn toàn 1 mol triolein trong dung dịch NaOH dư, thu được m gam muối của acid béo (sodium oleate). Giá trị khối lượng muối thu được từ 1 mol triolein là bao nhiêu (biết C=12, H=1, O=16, Na=23)?", "opts": ["912 gam", "304 gam", "608 gam", "884 gam"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>(C<sub>17</sub>H<sub>33</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> + 3NaOH → 3C<sub>17</sub>H<sub>33</sub>COONa + C<sub>3</sub>H<sub>5</sub>(OH)<sub>3</sub><br>• <b>Tính toán đại số:</b><br>1 mol triolein sinh ra 3 mol C<sub>17</sub>H<sub>33</sub>COONa.<br>M(C<sub>17</sub>H<sub>33</sub>COONa) = 17·12 + 33 + 12 + 32 + 23 = 304 g/mol.<br>m<sub>muối</sub> = 3 · 304 = 912 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hiện tượng dầu mỡ để lâu ngày trong không khí bị ôi thiu là do quá trình hoá học nào chủ yếu gây ra?", "opts": ["Gốc acid béo không no bị oxi hoá chậm bởi oxygen không khí tạo thành các hợp chất peroxide, sau đó phân huỷ thành các aldehyde và ketone có mùi khó chịu.", "Chất béo bị vi khuẩn lên men tạo thành khí methane và khí carbonic.", "Chất béo phản ứng với hơi nước trong không khí tạo ra glycerol và acid béo tự do.", "Gốc acid béo no bị bẻ gãy mạch carbon dưới tác dụng của ánh sáng mặt trời."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Dầu mỡ chứa các liên kết đôi C=C của gốc acid béo không no rất nhạy cảm với oxygen trong không khí.<br>• Oxygen oxi hoá chậm liên kết C=C tạo hydroperoxide, sau đó các peroxide phân huỷ thành các chất aldehyde, ketone mạch ngắn có mùi nồng, chua gắt đặc trưng của dầu mỡ ôi thiu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho các nhận định về tính chất hoá học của ester và lipid, hãy xác định tính Đúng/Sai của từng phát biểu:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Phản ứng thuỷ phân ester trong môi trường kiềm (dung dịch NaOH, đun nóng) là phản ứng một chiều và được gọi là phản ứng xà phòng hoá.", "Hydro hoá chất béo lỏng (như triolein) với xúc tác Ni ở nhiệt độ cao thu được chất béo rắn (như tristearin) dùng để sản xuất bơ nhân tạo.", "Tất cả các ester khi thuỷ phân trong môi trường kiềm đều chỉ tạo ra muối carboxylate và alcohol.", "Chất béo nhẹ hơn nước, không tan trong nước nhưng tan tốt trong các dung môi hữu cơ không phân cực như benzene, chloroform, ether."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Phản ứng xà phòng hoá este là phản ứng một chiều không thuận nghịch.<br>• <b>Ý b [Đúng]:</b> Triolein (C<sub>17</sub>H<sub>33</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> + 3H<sub>2</sub> → (C<sub>17</sub>H<sub>35</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> (tristearin rắn) dùng sản xuất shortening, bơ thực vật margarin.<br>• <b>Ý c [Sai]:</b> Ester của phenol khi thủy phân trong dung dịch kiềm sinh ra 2 muối (ví dụ CH<sub>3</sub>COOC<sub>6</sub>H<sub>5</sub> + 2NaOH → CH<sub>3</sub>COONa + C<sub>6</sub>H<sub>5</sub>ONa + H<sub>2</sub>O) chứ không sinh ra alcohol.<br>• <b>Ý d [Đúng]:</b> Tính chất vật lí chuẩn của lipid.", "svgGraph": null}, {"q": "Hợp chất hữu cơ X có công thức phân tử C<sub>4</sub>H<sub>8</sub>O<sub>2</sub>. Khi cho X phản ứng với dung dịch NaOH đun nóng, thu được muối sodium acetate và alcohol Y. Tên gọi của X là gì?", "opts": ["Ethyl acetate", "Methyl propionate", "Propyl acetate", "Ethyl propionate"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Muối sodium acetate là CH<sub>3</sub>COONa.<br>• Do X có công thức C<sub>4</sub>H<sub>8</sub>O<sub>2</sub>, ester có dạng CH<sub>3</sub>COO–R'.<br>• Tổng số carbon là 4 → Gốc R' có 4 - 2 = 2 carbon → R' là –C<sub>2</sub>H<sub>5</sub>.<br>• Công thức cấu tạo của X là CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub> (ethyl acetate). Alcohol Y là C<sub>2</sub>H<sub>5</sub>OH (ethanol).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "2": [{"q": "Xà phòng truyền thống là hỗn hợp muối sodium hoặc potassium của các chất nào sau đây?", "opts": ["Các acid béo cao (như palmitic acid, stearic acid)", "Các acid vô cơ mạnh (như sulfuric acid, nitric acid)", "Các alcohol đa chức mạch hở (như glycerol, ethylene glycol)", "Các amino acid thiên nhiên"], "ans": 0, "exp": "• <b>Định nghĩa SGK:</b> Xà phòng thường dùng là hỗn hợp muối sodium hoặc potassium của các acid béo (thường là palmitic acid C<sub>15</sub>H<sub>31</sub>COOH, stearic acid C<sub>17</sub>H<sub>35</sub>COOH, oleic acid C<sub>17</sub>H<sub>33</sub>COOH).<br>• Muối sodium tạo xà phòng bánh (rắn); muối potassium tạo xà phòng mềm, lỏng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"30\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14.5\" font-weight=\"800\">CƠ CHẾ TẨY RỬA VÀ CẤU TRÚC PHÂN TỬ XÀ PHÒNG</text>\n  <!-- Single Molecule Model -->\n  <g transform=\"translate(40, 50)\">\n    <!-- Hydrophobic tail zigzag -->\n    <path d=\"M 0 35 L 20 20 L 40 35 L 60 20 L 80 35 L 100 20 L 120 35 L 140 20 L 160 35\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n    <!-- Hydrophilic head circle -->\n    <circle cx=\"180\" cy=\"35\" r=\"16\" fill=\"#0284c7\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <text x=\"180\" y=\"40\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"10\" font-weight=\"bold\">-COO⁻</text>\n    <circle cx=\"206\" cy=\"22\" r=\"8\" fill=\"#10b981\"/>\n    <text x=\"206\" y=\"26\" text-anchor=\"middle\" fill=\"#000\" font-size=\"9\" font-weight=\"bold\">Na⁺</text>\n    <!-- Labels -->\n    <text x=\"80\" y=\"62\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"700\">ĐUÔI KỊ NƯỚC (Ưa dầu)</text>\n    <text x=\"80\" y=\"76\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Gốc hydrocarbon dài C₁₇H₃₅-</text>\n    <text x=\"190\" y=\"62\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"700\">ĐẦU ƯA NƯỚC</text>\n    <text x=\"190\" y=\"76\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Nhóm ion phân cực</text>\n  </g>\n  <!-- Micelle grease cleaning diagram -->\n  <g transform=\"translate(370, 125)\">\n    <!-- Oil droplet -->\n    <circle cx=\"0\" cy=\"0\" r=\"32\" fill=\"#fbbf24\" opacity=\"0.85\"/>\n    <text x=\"0\" y=\"4\" text-anchor=\"middle\" fill=\"#000\" font-size=\"11\" font-weight=\"bold\">VẾT DẦU</text>\n    <!-- Tails pointing in, heads pointing out -->\n    <g stroke=\"#f43f5e\" stroke-width=\"2\">\n      <line x1=\"0\" y1=\"-32\" x2=\"0\" y2=\"-55\"/><circle cx=\"0\" cy=\"-55\" r=\"6\" fill=\"#0284c7\" stroke=\"#38bdf8\"/>\n      <line x1=\"32\" y1=\"0\" x2=\"55\" y2=\"0\"/><circle cx=\"55\" cy=\"0\" r=\"6\" fill=\"#0284c7\" stroke=\"#38bdf8\"/>\n      <line x1=\"0\" y1=\"32\" x2=\"0\" y2=\"55\"/><circle cx=\"0\" cy=\"55\" r=\"6\" fill=\"#0284c7\" stroke=\"#38bdf8\"/>\n      <line x1=\"-32\" y1=\"0\" x2=\"-55\" y2=\"0\"/><circle cx=\"-55\" cy=\"0\" r=\"6\" fill=\"#0284c7\" stroke=\"#38bdf8\"/>\n      <line x1=\"23\" y1=\"23\" x2=\"40\" y2=\"40\"/><circle cx=\"40\" cy=\"40\" r=\"6\" fill=\"#0284c7\" stroke=\"#38bdf8\"/>\n      <line x1=\"-23\" y1=\"23\" x2=\"-40\" y2=\"40\"/><circle cx=\"-40\" cy=\"40\" r=\"6\" fill=\"#0284c7\" stroke=\"#38bdf8\"/>\n      <line x1=\"23\" y1=\"-23\" x2=\"40\" y2=\"-40\"/><circle cx=\"40\" cy=\"-40\" r=\"6\" fill=\"#0284c7\" stroke=\"#38bdf8\"/>\n      <line x1=\"-23\" y1=\"-23\" x2=\"-40\" y2=\"-40\"/><circle cx=\"-40\" cy=\"-40\" r=\"6\" fill=\"#0284c7\" stroke=\"#38bdf8\"/>\n    </g>\n    <text x=\"0\" y=\"80\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"11\" font-weight=\"700\">Hạt keo Micelle lơ lửng</text>\n  </g>\n  <!-- Summary Box -->\n  <rect x=\"25\" y=\"150\" width=\"230\" height=\"65\" rx=\"8\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.1)\"/>\n  <text x=\"140\" y=\"172\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11.5\">Đuôi cắm sâu vào vết dầu mỡ</text>\n  <text x=\"140\" y=\"190\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"11\">Đầu hướng ra ngoài pha nước</text>\n  <text x=\"140\" y=\"206\" text-anchor=\"middle\" fill=\"#a7f3d0\" font-size=\"10.5\">Vết bẩn bị lôi cuốn rửa trôi theo nước</text>\n</svg>"}, {"q": "Cấu tạo phân tử chất giặt rửa và xà phòng gồm hai phần có đặc tính trái ngược nhau là:", "opts": ["Đầu ưa nước (phân cực hoặc mang điện tích) và đuôi kị nước (ưa dầu mỡ, không phân cực).", "Đầu ưa dầu (mang điện tích âm) và đuôi ưa nước (mang điện tích dương).", "Đầu axit mạnh và đuôi base mạnh trung hoà lẫn nhau.", "Hai đầu đều kị nước để đẩy các hạt bụi bẩn bay hơi."], "ans": 0, "exp": "• <b>Bản chất cấu tạo:</b> Phân tử xà phòng và chất giặt rửa tổng hợp gồm:<br>1. <b>Đuôi kị nước:</b> Gốc hydrocarbon dài không phân cực (C<sub>15</sub>H<sub>31</sub>–, C<sub>17</sub>H<sub>35</sub>–, gốc alkylbenzenesulfonate), dễ tan trong dầu mỡ.<br>2. <b>Đầu ưa nước:</b> Nhóm phân cực hoặc mang điện tích âm (–COO<sup>-</sup>, –SO<sub>3</sub><sup>-</sup>, –OSO<sub>3</sub><sup>-</sup>), dễ tạo liên kết với nước.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Tại sao xà phòng thông thường bị giảm tác dụng tẩy rửa đáng kể khi giặt trong môi trường nước cứng (chứa nhiều ion Ca<sup>2+</sup> và Mg<sup>2+</sup>)?", "opts": ["Ion Ca<sup>2+</sup> và Mg<sup>2+</sup> tạo kết tủa không tan với các ion carboxylate của xà phòng, làm mất hoạt tính tẩy rửa và bám bẩn vào sợi vải.", "Nước cứng làm biến tính nhóm hydrocarbon thành chất dễ cháy.", "Xà phòng bị oxi hoá giải phóng khí clo gây mục vải.", "Ion Ca<sup>2+</sup> và Mg<sup>2+</sup> xúc tác phản ứng thuỷ phân xà phòng thành glycerol."], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>2C<sub>17</sub>H<sub>35</sub>COO<sup>-</sup> + Ca<sup>2+</sup> → (C<sub>17</sub>H<sub>35</sub>COO)<sub>2</sub>Ca ↓ (kết tủa trắng)<br>• Kết tủa bám vào sợi vải làm ố vàng, xơ cứng vải và làm tiêu hao một lượng lớn xà phòng.<br>• Ngược lại, chất giặt rửa tổng hợp (muối sulfonate) có muối của Ca<sup>2+</sup>, Mg<sup>2+</sup> tan tốt nên giặt được trong nước cứng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về quy trình sản xuất xà phòng và chất giặt rửa trong công nghiệp, hãy xác định tính Đúng/Sai:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Trong quá trình nấu xà phòng, người ta thêm dung dịch NaCl bão hoà vào để tách muối của acid béo ra khỏi hỗn hợp lỏng.", "Phần chất lỏng còn lại sau khi vớt xà phòng chứa glycerol được tinh chế để ứng dụng trong ngành dược phẩm và mỹ phẩm.", "Chất giặt rửa tổng hợp được sản xuất từ dầu mỏ và hoàn toàn không gây ô nhiễm môi trường nguồn nước.", "Xà phòng gốc tự nhiên có ưu điểm vượt trội là dễ bị phân huỷ sinh học bởi vi sinh vật trong tự nhiên hơn các chất giặt rửa tổng hợp có nhánh."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> NaCl bão hòa làm tăng tỉ trọng pha lỏng và giảm độ tan của muối carboxylate (hiệu ứng muối kết), xà phòng nhẹ hơn nổi lên trên.<br>• <b>Ý b [Đúng]:</b> Dung dịch phía dưới chứa glycerol, NaCl và NaOH dư; tách glycerol để sản xuất thuốc nổ, kem dưỡng da, dung dịch sát khuẩn.<br>• <b>Ý c [Sai]:</b> Các chất giặt rửa tổng hợp gốc alkylbenzene có mạch nhánh khó phân huỷ sinh học, gây bọt xốp ô nhiễm nguồn nước sông hồ.<br>• <b>Ý d [Đúng]:</b> Xà phòng có mạch thẳng tự nhiên nên vi sinh vật dễ dàng phân hủy sinh học.", "svgGraph": null}, {"q": "Ghép từng thành phần / phụ gia trong chất giặt rửa (Cột A) với vai trò tương ứng trong quá trình tẩy rửa (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Chất hoạt động bề mặt (Surfactant) ➔ Làm giảm sức căng bề mặt của nước, thâm nhập và cuốn trôi vết dầu mỡ", "Chất hoạt động bề mặt (Surfactant) ➔ Hấp thụ tia tử ngoại và phát ánh sáng xanh dương giúp sợi vải trông trắng sáng hơn", "Chất hoạt động bề mặt (Surfactant) ➔ Thu giữ các cation Ca²⁺, Mg²⁺ để tăng hiệu quả giặt rửa", "Chất hoạt động bề mặt (Surfactant) ➔ Thuỷ phân đặc hiệu các vết bẩn hữu cơ từ protein (máu, sữa) và tinh bột"], "ans": 0, "exp": "• <b>1 - B:</b> Chất hoạt động bề mặt làm giảm sức căng bề mặt của nước, tạo micelle nhũ tương hoá dầu mỡ.<br>• <b>2 - A:</b> Chất tăng trắng huỳnh quang chuyển hoá ánh sáng UV thành ánh sáng xanh lam làm mắt nhìn thấy vải trắng tinh khôi.<br>• <b>3 - D:</b> Enzyme sinh học thuỷ phân chọn lọc các vết bẩn hữu cơ bám chặt (thức ăn, máu, mồ hôi).<br>• <b>4 - C:</b> Zeolite và phosphate làm mềm nước cứng, ngăn chặn kết tủa.", "svgGraph": null}, {"q": "Hoàn thành đoạn văn bản mô tả cơ chế làm sạch của xà phòng:<br><i>\"Khi giặt, đuôi  [ ... ]  của phân tử xà phòng cắm sâu vào giọt dầu mỡ bẩn, còn đầu  [ ... ]  hướng ra ngoài dung dịch nước. Nhiều phân tử tập hợp lại tạo thành các hạt keo  [ ... ]  phân tán giọt dầu vào nước. Dưới tác dụng vò xát và dòng nước, các hạt bẩn bị  [ ... ]  và trôi đi.\"</i>", "opts": ["kị nước — ưa nước — micelle — cuốn trôi", "cuốn trôi — micelle — ưa nước — kị nước", "ưa dầu — ưa nước — micelle — cuốn trôi", "ưa nước — micelle — cuốn trôi — đông đặc"], "ans": 0, "exp": "• <b>Cơ chế micelle chuẩn SGK:</b> Đuôi kị nước (ưa dầu) cắm vào dầu; đầu ưa nước quay ra ngoài tạo hạt micelle hình cầu lơ lửng, ngăn không cho các giọt dầu tụ tập lại và bị dòng nước xối rửa sạch sẽ.", "svgGraph": null}, {"q": "Một loại mỡ lợn chứa 89% tristearin về khối lượng (các tạp chất còn lại không tham gia phản ứng xà phòng hoá). Để xà phòng hoá hoàn toàn 100 kg loại mỡ lợn này cần tối thiểu bao nhiêu kg NaOH tinh khiết (cho C=12, H=1, O=16, Na=23)?", "opts": ["12,0 kg", "13,5 kg", "4,0 kg", "36,0 kg"], "ans": 0, "exp": "• <b>Tính toán đại số:</b><br>Khối lượng tristearin nguyên chất: m = 100 · 89% = 89 kg = 89000 g.<br>M((C<sub>17</sub>H<sub>35</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub>) = 890 g/mol.<br>Số mol tristearin: n = 89000 / 890 = 100 mol.<br>• <b>Phương trình phản ứng:</b><br>(C<sub>17</sub>H<sub>35</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> + 3NaOH → 3C<sub>17</sub>H<sub>35</sub>COONa + C<sub>3</sub>H<sub>5</sub>(OH)<sub>3</sub><br>Số mol NaOH cần dùng = 3 · 100 = 300 mol.<br>Khối lượng NaOH = 300 · 40 = 12000 g = 12,0 kg.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Chất nào sau đây là chất hoạt động bề mặt mang điện tích âm (anionic surfactant) được sử dụng phổ biến trong bột giặt gia dụng hiện đại?", "opts": ["Sodium alkylbenzenesulfonate (CH<sub>3</sub>(CH<sub>2</sub>)<sub>11</sub>–C<sub>6</sub>H<sub>4</sub>–SO<sub>3</sub>Na)", "Cetyltrimethylammonium bromide (CH<sub>3</sub>(CH<sub>2</sub>)<sub>15</sub>–N⁺(CH<sub>3</sub>)<sub>3</sub>Br⁻)", "Polyethylene glycol (HO–(CH<sub>2</sub>CH<sub>2</sub>O)<sub>n</sub>–H)", "Glycerol trinitrate"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Sodium linear alkylbenzenesulfonate (LAS) là chất hoạt động bề mặt anion phổ biến nhất, có nhóm ưa nước mang điện tích âm –SO<sub>3</sub><sup>-</sup> liên kết với ion Na<sup>+</sup>.<br>• Chất này tạo nhiều bọt, tẩy rửa dầu mỡ rất mạnh và giá thành sản xuất hợp lí.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi so sánh tính chất và ứng dụng giữa xà phòng và chất giặt rửa tổng hợp, xét tính Đúng/Sai của các nhận xét sau:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Xà phòng có thể dùng tốt và hiệu quả như nhau trong mọi môi trường nước cứng, nước nhiễm phèn hoặc nước chua acid.", "Chất giặt rửa tổng hợp có thể dùng để giặt giũ trong cả nước cứng vì muối của ion Ca²⁺, Mg²⁺ với gốc sulfonate tan tốt trong nước.", "Khi dùng xà phòng trong môi trường acid (pH < 7), xà phòng bị chuyển thành acid béo tự do kết tủa làm mất khả năng tẩy rửa.", "Nước thải chứa chất giặt rửa tổng hợp có nhánh khó bị vi sinh vật phân huỷ, có thể tạo màng bọt gây nghẹt oxy của thuỷ sinh vật."], "ans": 0, "exp": "• <b>Ý a [Sai]:</b> Xà phòng tạo kết tủa với Ca<sup>2+</sup>, Mg<sup>2+</sup> trong nước cứng và bị acid chuyển thành acid béo không tan: RCOO<sup>-</sup> + H<sup>+</sup> → RCOOH ↓.<br>• <b>Ý b [Đúng]:</b> Muối sulfonate của Ca và Mg tan tốt trong nước, không làm giảm tác dụng giặt tẩy.<br>• <b>Ý c [Đúng]:</b> Môi trường acid làm proton hóa gốc carboxylate thành acid béo tự do kết tủa.<br>• <b>Ý d [Đúng]:</b> Bọt của chất giặt rửa tổng hợp trơ sinh học che phủ mặt nước, giảm hòa tan O<sub>2</sub> gây chết cá và sinh vật.", "svgGraph": null}, {"q": "Để loại bỏ vết dầu mỡ động thực vật bám trên quần áo, biện pháp nào sau đây mang lại hiệu quả tẩy sạch cao nhất dựa trên nguyên lí hoá học?", "opts": ["Giặt với nước ấm có hoà tan bột giặt hoặc nước rửa chén.", "Ngâm và giặt quần áo hoàn toàn trong nước đá thật lạnh.", "Chỉ xả qua nhiều lần với nước muối sinh lí NaCl 0,9%.", "Ngâm quần áo vào dung dịch giấm ăn acid đặc nóng."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Nước ấm làm giảm độ nhớt và làm tan chảy các giọt dầu mỡ bám trên thớ vải.<br>• Kết hợp với chất hoạt động bề mặt trong bột giặt giúp quá trình tạo micelle và phân tán nhũ tương dầu mỡ vào nước diễn ra cực kì nhanh chóng và triệt để.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "3": [{"q": "Xà phòng hoá hoàn toàn 17,6 gam ethyl acetate (CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub>) bằng 250 mL dung dịch NaOH 1M. Sau khi phản ứng kết thúc, cô cạn dung dịch thì thu được m gam chất rắn khan. Giá trị của m là bao nhiêu (cho C=12, H=1, O=16, Na=23)?", "opts": ["18,4 gam", "16,4 gam", "20,4 gam", "17,6 gam"], "ans": 0, "exp": "• <b>Số mol các chất:</b><br>n(CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub>) = 17,6 / 88 = 0,2 mol.<br>n(NaOH ban đầu) = 0,25 · 1 = 0,25 mol.<br>• <b>Phương trình phản ứng:</b><br>CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub> + NaOH → CH<sub>3</sub>COONa + C<sub>2</sub>H<sub>5</sub>OH<br>Phản ứng tỉ lệ 1:1 → NaOH dư: 0,25 - 0,2 = 0,05 mol; sinh ra 0,2 mol CH<sub>3</sub>COONa.<br>• <b>Khối lượng chất rắn khan sau khi cô cạn:</b> (C<sub>2</sub>H<sub>5</sub>OH bay hơi)<br>m<sub>chất rắn</sub> = m(CH<sub>3</sub>COONa) + m(NaOH dư)<br>m<sub>chất rắn</sub> = 0,2 · 82 + 0,05 · 40 = 16,4 + 2,0 = 18,4 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Chất nào sau đây khi thuỷ phân trong môi trường kiềm đun nóng sinh ra glycerol?", "opts": ["Trilinolein", "Methyl acetate", "Benzyl formate", "Phenyl benzoate"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Trilinolein (C<sub>17</sub>H<sub>31</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> là chất béo (triester của glycerol với linoleic acid), khi thuỷ phân trong dung dịch kiềm tạo sodium linoleate và glycerol C<sub>3</sub>H<sub>5</sub>(OH)<sub>3</sub>.<br>• Các chất còn lại chỉ là ester đơn chức sinh ra các alcohol hoặc phenol đơn chức.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Đốt cháy hoàn toàn 0,1 mol một ester đơn chức, no, mạch hở X thu được bao nhiêu lít khí CO<sub>2</sub> (ở đkc, 1 bar và 25°C ứng với 24,79 L/mol) nếu X là methyl acetate?", "opts": ["7,437 lít", "4,958 lít", "2,479 lít", "9,916 lít"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>Methyl acetate: CH<sub>3</sub>COOCH<sub>3</sub> (C<sub>3</sub>H<sub>6</sub>O<sub>2</sub>).<br>C<sub>3</sub>H<sub>6</sub>O<sub>2</sub> + 3,5 O<sub>2</sub> → 3 CO<sub>2</sub> + 3 H<sub>2</sub>O<br>• <b>Tính toán:</b><br>Số mol CO<sub>2</sub> = 3 · n(ester) = 3 · 0,1 = 0,3 mol.<br>Thể tích CO<sub>2</sub> ở điều kiện chuẩn (đkc): V = 0,3 · 24,79 = 7,437 lít.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi nghiên cứu cấu tạo và tính chất của các ester và chất béo, xác định tính Đúng/Sai của các mệnh đề sau:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Tất cả các chất béo đều nhẹ hơn nước và không tan trong nước do phân tử có gốc hydrocarbon rất lớn không phân cực.", "Ester no đơn chức mạch hở có số nguyên tử H luôn gấp đôi số nguyên tử C trong phân tử.", "Có thể dùng nước bromine để phân biệt chất béo lỏng (như triolein) và chất béo rắn (như tristearin).", "Chỉ số xà phòng hoá là số miligam NaOH cần để xà phòng hoá hoàn toàn 1 gam chất béo."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Đặc tính chung của lipid.<br>• <b>Ý b [Đúng]:</b> Ester no đơn chức mạch hở C<sub>n</sub>H<sub>2n</sub>O<sub>2</sub> luôn có số H = 2n = 2 lần số C.<br>• <b>Ý c [Đúng]:</b> Triolein chứa liên kết đôi C=C làm mất màu nước bromine, tristearin no không phản ứng.<br>• <b>Ý d [Sai]:</b> Theo quy ước chuẩn quốc tế, chỉ số xà phòng hoá là số miligam <b>KOH</b> (chứ không phải NaOH) cần dùng để trung hoà acid tự do và xà phòng hoá este trong 1 gam chất béo.", "svgGraph": null}, {"q": "Ghép từng acid béo thông dụng (Cột A) với công thức phân tử và đặc điểm trạng thái tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Palmitic acid ➔ C₁₅H₃₁COOH (Acid béo no, mạch thẳng 16 carbon)", "Palmitic acid ➔ C₁₇H₃₃COOH (Acid béo không no, chứa 1 liên kết đôi C=C dạng cis)", "Palmitic acid ➔ C₁₇H₃₁COOH (Acid béo không no, chứa 2 liên kết đôi C=C)", "Palmitic acid ➔ C₁₇H₃₅COOH (Acid béo no, mạch thẳng 18 carbon)"], "ans": 0, "exp": "• <b>1 - B:</b> Palmitic acid: C<sub>15</sub>H<sub>31</sub>COOH (no, 16C).<br>• <b>2 - D:</b> Stearic acid: C<sub>17</sub>H<sub>35</sub>COOH (no, 18C).<br>• <b>3 - A:</b> Oleic acid: C<sub>17</sub>H<sub>33</sub>COOH (1 nối đôi C=C, 18C).<br>• <b>4 - C:</b> Linoleic acid: C<sub>17</sub>H<sub>31</sub>COOH (2 nối đôi C=C, 18C, omega-6).", "svgGraph": null}, {"q": "Hoàn thiện nội dung tóm tắt kiến thức cốt lõi của Chương 1:<br><i>\"Ester được tạo thành khi thay thế nhóm -OH ở nhóm carboxyl của carboxylic acid bằng nhóm  [ ... ] . Thuỷ phân ester trong môi trường acid là phản ứng  [ ... ] , còn trong môi trường kiềm là phản ứng  [ ... ] . Chất béo là triester của  [ ... ]  với các acid béo.\"</i>", "opts": ["-OR' — thuận nghịch — một chiều — glycerol", "glycerol — một chiều — thuận nghịch — -OR'", "-NH₂ — thuận nghịch — một chiều — glycerol", "thuận nghịch — một chiều — glycerol — ethylene glycol"], "ans": 0, "exp": "• Định nghĩa ester: R–CO–OR'.<br>• Thuỷ phân trong môi trường acid là phản ứng thuận nghịch (hai chiều).<br>• Thuỷ phân trong dung dịch kiềm (xà phòng hoá) là phản ứng một chiều.<br>• Chất béo luôn là triester của glycerol.", "svgGraph": null}, {"q": "Chất X có công thức cấu tạo CH<sub>2</sub>=CH–COOCH<sub>3</sub> (methyl acrylate). Phát biểu nào sau đây về X là SAI?", "opts": ["X không có khả năng tham gia phản ứng trùng hợp tạo polymer.", "X làm mất màu dung dịch bromine ở nhiệt độ phòng.", "Thuỷ phân X trong dung dịch NaOH đun nóng thu được sodium acrylate và methanol.", "X là ester không no, đơn chức, mạch hở."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Methyl acrylate có liên kết đôi C=C ở gốc acid, do đó rất dễ tham gia phản ứng trùng hợp mở liên kết đôi tạo poly(methyl acrylate) dùng làm chất dẻo.<br>• Do đó nhận định 'X không có khả năng tham gia phản ứng trùng hợp' là SAI.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho sơ đồ chuyển hoá: Triolein + H<sub>2</sub> (dư, Ni, t°) → X; X + NaOH (dư, t°) → Y + Z. Tên gọi của chất Y là gì nếu Y là muối của acid béo?", "opts": ["Sodium stearate", "Sodium oleate", "Sodium palmitate", "Sodium linoleate"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>1. (C<sub>17</sub>H<sub>33</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> (triolein) + 3H<sub>2</sub> → (C<sub>17</sub>H<sub>35</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> (tristearin - chất X).<br>2. (C<sub>17</sub>H<sub>35</sub>COO)<sub>3</sub>C<sub>3</sub>H<sub>5</sub> + 3NaOH → 3C<sub>17</sub>H<sub>35</sub>COONa (sodium stearate - chất Y) + C<sub>3</sub>H<sub>5</sub>(OH)<sub>3</sub> (glycerol - chất Z).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu ứng dụng thực tế của ester và lipid trong đời sống:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Poly(methyl methacrylate) được điều chế từ methyl methacrylate là chất dẻo trong suốt, bền cơ học, được dùng làm kính máy bay và thuỷ tinh hữu cơ plexiglas.", "Dầu mỡ sau khi rán ở nhiệt độ cao nhiều lần vẫn giữ nguyên giá trị dinh dưỡng và an toàn tuyệt đối cho sức khoẻ con người.", "Chất béo là nguồn cung cấp năng lượng quan trọng cho cơ thể và dung môi hoà tan các vitamin thiết yếu như A, D, E, K.", "Xà phòng bánh sản xuất từ mỡ động vật thân thiện với môi trường tự nhiên hơn chất giặt rửa tổng hợp có nhánh."], "ans": 1, "exp": "• <b>Ý a [Đúng]:</b> Ứng dụng quan trọng của thuỷ tinh hữu cơ plexiglas.<br>• <b>Ý b [Sai]:</b> Dầu mỡ rán đi rán lại nhiều lần ở nhiệt độ cao bị nhiệt phân và oxi hoá tạo ra các chất độc hại, aldehyde và hợp chất thơm đa vòng có nguy cơ gây ung thư.<br>• <b>Ý c [Đúng]:</b> 1 gam lipid cung cấp khoảng 9 kcal năng lượng và là dung môi hấp thu vitamin tan trong dầu.<br>• <b>Ý d [Đúng]:</b> Xà phòng tự nhiên phân huỷ sinh học nhanh hơn chất giặt tổng hợp mạch nhánh.", "svgGraph": null}, {"q": "Đun nóng 0,1 mol một ester X đơn chức với dung dịch NaOH vừa đủ, thu được 9,6 gam muối sodium carboxylate và 3,2 gam alcohol. Tên gọi của ester X là gì?", "opts": ["Methyl propionate", "Ethyl acetate", "Methyl acetate", "Propyl formate"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>RCOOR' + NaOH → RCOONa + R'OH<br>• <b>Tính toán:</b><br>n(alcohol) = n(ester) = 0,1 mol → M(alcohol) = 3,2 / 0,1 = 32 g/mol → R'OH là CH<sub>3</sub>OH (methanol) → R' là –CH<sub>3</sub>.<br>n(muối) = 0,1 mol → M(muối) = 9,6 / 0,1 = 96 g/mol.<br>M(RCOONa) = R + 67 = 96 → R = 29 (–C<sub>2</sub>H<sub>5</sub>).<br>Công thức cấu tạo của X là C<sub>2</sub>H<sub>5</sub>COOCH<sub>3</sub> (methyl propionate).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "4": [{"q": "Glucose và fructose là hai chất đồng phân của nhau, cùng có công thức phân tử là gì?", "opts": ["C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>", "C<sub>12</sub>H<sub>22</sub>O<sub>11</sub>", "(C<sub>6</sub>H<sub>10</sub>O<sub>5</sub>)<sub>n</sub>", "C<sub>5</sub>H<sub>10</sub>O<sub>5</sub>"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Glucose và fructose đều thuộc loại monosaccharide đơn giản nhất, có cùng công thức phân tử C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (M = 180 g/mol).<br>• Glucose là polyhydroxy aldehyde (aldose), còn fructose là polyhydroxy ketone (ketose).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"28\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14.5\" font-weight=\"800\">CẤU TRÚC VÒNG VÀ MẠCH HỞ CỦA GLUCOSE (C₆H₁₂O₆)</text>\n  <!-- Cyclic alpha-glucose Haworth Projection -->\n  <g transform=\"translate(130, 115)\">\n    <!-- Hexagonal ring -->\n    <polygon points=\"0,-40 45,-20 45,30 0,50 -45,30 -45,-20\" fill=\"rgba(14,165,233,0.15)\" stroke=\"#38bdf8\" stroke-width=\"2.2\"/>\n    <!-- Oxygen at top right position -->\n    <circle cx=\"28\" cy=\"-30\" r=\"12\" fill=\"#070a14\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n    <text x=\"28\" y=\"-26\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">O</text>\n    <!-- Substituents -->\n    <!-- C1 -->\n    <line x1=\"45\" y1=\"-20\" x2=\"68\" y2=\"-20\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <text x=\"75\" y=\"-16\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">-OH (α)</text>\n    <!-- C2 -->\n    <line x1=\"45\" y1=\"30\" x2=\"65\" y2=\"45\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n    <text x=\"68\" y=\"55\" fill=\"#cbd5e1\" font-size=\"10\">-OH</text>\n    <!-- C3 -->\n    <line x1=\"0\" y1=\"50\" x2=\"0\" y2=\"70\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n    <text x=\"0\" y=\"82\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"10\">-OH</text>\n    <!-- C4 -->\n    <line x1=\"-45\" y1=\"30\" x2=\"-65\" y2=\"45\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n    <text x=\"-70\" y=\"55\" text-anchor=\"end\" fill=\"#cbd5e1\" font-size=\"10\">-OH</text>\n    <!-- C6 CH2OH at C5 -->\n    <line x1=\"-45\" y1=\"-20\" x2=\"-65\" y2=\"-45\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n    <text x=\"-68\" y=\"-48\" text-anchor=\"end\" fill=\"#fbbf24\" font-size=\"10.5\" font-weight=\"bold\">-CH₂OH</text>\n    <text x=\"0\" y=\"10\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">α-Glucose</text>\n  </g>\n  <!-- Open chain info -->\n  <g transform=\"translate(300, 50)\">\n    <rect width=\"195\" height=\"150\" rx=\"8\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.12)\"/>\n    <text x=\"98\" y=\"24\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"12.5\" font-weight=\"bold\">DẠNG MẠCH HỞ</text>\n    <text x=\"20\" y=\"50\" fill=\"#f8fafc\" font-size=\"11\">• Cấu tạo tạp chức:</text>\n    <text x=\"30\" y=\"70\" fill=\"#34d399\" font-size=\"11.5\" font-weight=\"bold\">5 nhóm –OH kề nhau</text>\n    <text x=\"30\" y=\"90\" fill=\"#f43f5e\" font-size=\"11.5\" font-weight=\"bold\">1 nhóm –CH=O (aldehyde)</text>\n    <text x=\"20\" y=\"115\" fill=\"#cbd5e1\" font-size=\"10.5\">• Trong dung dịch nước:</text>\n    <text x=\"20\" y=\"132\" fill=\"#7dd3fc\" font-size=\"10\">Chủ yếu tồn tại ở dạng vòng</text>\n    <text x=\"20\" y=\"145\" fill=\"#94a3b8\" font-size=\"9.5\">α-glucose và β-glucose cân bằng</text>\n  </g>\n</svg>"}, {"q": "Để chứng minh trong phân tử glucose có nhiều nhóm hydroxy (–OH) ở các vị trí liền kề nhau, người ta dùng thuốc thử nào ở nhiệt độ phòng?", "opts": ["Cu(OH)<sub>2</sub> trong môi trường kiềm (tạo dung dịch xanh lam thẫm)", "Dung dịch AgNO<sub>3</sub> trong NH<sub>3</sub> đun nóng (thuốc thử Tollens)", "Dung dịch nước bromine (Br<sub>2</sub>/H<sub>2</sub>O)", "Kim loại Cu ở nhiệt độ cao"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Các hợp chất hữu cơ có từ 2 nhóm –OH liền kề (polyalcohol) có khả năng hoà tan Cu(OH)<sub>2</sub> ở nhiệt độ thường tạo phức chất đồng có màu xanh lam thẫm đặc trưng.<br>• Phản ứng chứng minh glucose là alcohol đa chức có nhiều nhóm –OH liền kề nhau.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Chất nào sau đây phản ứng được với dung dịch nước bromine (làm mất màu nâu đỏ của bromine), dùng để phân biệt glucose và fructose?", "opts": ["Glucose (bị oxi hoá nhóm –CHO thành acid)", "Fructose (chứa nhóm C=O trơ với nước bromine)", "Cả glucose và fructose đều làm mất màu bromine", "Không chất nào phản ứng được với bromine"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Nước bromine có môi trường acid nhẹ. Trong môi trường acid, fructose không thể chuyển hoá thành glucose, và nhóm ketone của fructose không bị oxi hoá bởi nước bromine.<br>• Ngược lại, nhóm –CHO của glucose bị nước bromine oxi hoá thành gluconic acid và làm mất màu dung dịch Br<sub>2</sub>:<br>CH<sub>2</sub>OH(CHOH)<sub>4</sub>CHO + Br<sub>2</sub> + H<sub>2</sub>O → CH<sub>2</sub>OH(CHOH)<sub>4</sub>COOH + 2HBr.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi tiến hành thí nghiệm tráng bạc của glucose và fructose với thuốc thử Tollens [Ag(NH<sub>3</sub>)<sub>2</sub>]OH, xét tính Đúng/Sai:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Glucose bị oxi hoá bởi thuốc thử Tollens đun nóng, giải phóng bạc kim loại bám sáng bóng trên thành ống nghiệm.", "Fructose mặc dù là polyhydroxy ketone nhưng vẫn tham gia phản ứng tráng bạc vì trong môi trường kiềm, fructose chuyển hoá thành glucose.", "1 mol glucose khi phản ứng tráng bạc hoàn toàn với thuốc thử Tollens dư sinh ra tối đa 1 mol Ag kim loại.", "Thuốc thử Tollens có thể dùng để phân biệt hoàn toàn giữa glucose và fructose trong phòng thí nghiệm."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Nhóm –CHO của glucose bị oxi hoá thành muối ammonium gluconate và kết tủa bạc bám trên thành ống nghiệm.<br>• <b>Ý b [Đúng]:</b> Cân bằng chuyển hoá giữa glucose và fructose qua trung gian enediol diễn ra thuận lợi trong môi trường kiềm của NH<sub>3</sub>.<br>• <b>Ý c [Sai]:</b> 1 mol glucose có 1 nhóm –CHO, nhường 2e nên sinh ra đúng <b>2 mol Ag</b>: C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> → 2Ag.<br>• <b>Ý d [Sai]:</b> Do cả hai đều tráng bạc nên không thể dùng thuốc thử Tollens để phân biệt glucose và fructose (phải dùng nước bromine).", "svgGraph": null}, {"q": "Ghép từng loại đường đơn (Cột A) với nguồn gốc tự nhiên và tên gọi phổ biến (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Glucose ➔ Có nhiều trong quả nho chín, nồng độ ổn định trong máu người khoảng 0,1% (4,4 - 7,2 mmol/L)", "Glucose ➔ Chiếm khoảng 40% khối lượng mật ong, là loại đường ngọt nhất trong các carbohydrate tự nhiên", "Glucose ➔ Tên gọi y học chỉ glucose hoà tan trong máu động vật có vú", "Glucose ➔ Hỗn hợp giàu fructose tạo nên vị ngọt đậm đà thanh mát của mật ong tự nhiên"], "ans": 0, "exp": "• <b>1 - A:</b> Glucose còn gọi là đường nho, nồng độ trong máu người khoẻ mạnh khoảng 0,1%.<br>• <b>2 - B:</b> Fructose ngọt nhất trong các loại đường tự nhiên, có nhiều trong mật ong và trái cây chín.<br>• <b>3 - C:</b> 'Đường huyết' (blood sugar) là glucose máu.<br>• <b>4 - D:</b> Mật ong chứa khoảng 40% fructose và 30% glucose.", "svgGraph": null}, {"q": "Hoàn thành nội dung phản ứng lên men rượu của glucose trong sản xuất đồ uống có cồn:<br><i>\"Dưới tác dụng của enzyme có trong men rượu ở nhiệt độ 30 - 35°C, glucose bị lên men tạo thành  [ ... ]  và khí  [ ... ] . Phương trình phản ứng là C₆H₁₂O₆ → 2  [ ... ]  + 2  [ ... ] .\"</i>", "opts": ["ethanol — carbon dioxide — C₂H₅OH — CO₂", "CO₂ — C₂H₅OH — carbon dioxide — ethanol", "acetic acid — carbon dioxide — C₂H₅OH — CO₂", "carbon dioxide — C₂H₅OH — CO₂ — CH₄"], "ans": 0, "exp": "• <b>Phương trình lên men rượu:</b><br>C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> ⎯(men rượu, 30-35°C)→ 2C<sub>2</sub>H<sub>5</sub>OH + 2CO<sub>2</sub> ↑.<br>Phản ứng cổ truyền ứng dụng sản xuất rượu vang, bia, cồn sinh học bio-ethanol.", "svgGraph": null}, {"q": "Đun nóng 18 gam glucose với lượng dư dung dịch AgNO<sub>3</sub> trong NH<sub>3</sub>, hiệu suất phản ứng đạt 80%. Khối lượng bạc kim loại kết tủa thu được là bao nhiêu (cho C=12, H=1, O=16, Ag=108)?", "opts": ["17,28 gam", "21,60 gam", "10,80 gam", "8,64 gam"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Số mol glucose: n = 18 / 180 = 0,1 mol.<br>Phương trình phản ứng: C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 2AgNO<sub>3</sub> + 3NH<sub>3</sub> + H<sub>2</sub>O → C<sub>6</sub>H<sub>11</sub>O<sub>7</sub>NH<sub>4</sub> + 2Ag ↓ + 2NH<sub>4</sub>NO<sub>3</sub><br>Số mol Ag lý thuyết = 2 · 0,1 = 0,2 mol.<br>Do hiệu suất H = 80%, số mol Ag thực tế = 0,2 · 0,8 = 0,16 mol.<br>Khối lượng Ag = 0,16 · 108 = 17,28 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi khử hoàn toàn glucose bằng khí hydrogen (xúc tác Ni, đun nóng), thu được hợp chất hữu cơ nào sau đây?", "opts": ["Sorbitol (alcohol 6 chức: HOCH<sub>2</sub>(CHOH)<sub>4</sub>CH<sub>2</sub>OH)", "Gluconic acid", "Glucaric acid", "Glycerol"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>CH<sub>2</sub>OH(CHOH)<sub>4</sub>CHO + H<sub>2</sub> ⎯(Ni, t°)→ CH<sub>2</sub>OH(CHOH)<sub>4</sub>CH<sub>2</sub>OH (sorbitol).<br>• Nhóm –CHO bị khử thành alcohol bậc I (–CH<sub>2</sub>OH).<br>• Sorbitol dùng làm chất tạo ngọt cho người ăn kiêng, tiểu đường và trong sản xuất mỹ phẩm.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về trạng thái tự nhiên và vai trò sinh học của glucose:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Glucose được tổng hợp trong cây xanh nhờ quá trình quang hợp dưới tác dụng của ánh sáng mặt trời và chất diệp lục.", "Dung dịch glucose 5% trong y học được dùng làm dịch truyền tĩnh mạch để cung cấp năng lượng trực tiếp cho người bệnh suy nhược.", "Ở người bình thường, lượng glucose dư thừa trong máu được gan chuyển hoá và tích luỹ dưới dạng glycogen.", "Fructose không thể chuyển hoá thành năng lượng trong cơ thể người vì tế bào không hấp thu được loại đường này."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> 6CO<sub>2</sub> + 6H<sub>2</sub>O ⎯(as, diệp lục)→ C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6O<sub>2</sub>.<br>• <b>Ý b [Đúng]:</b> Glucose 5% là dung dịch đẳng trương truyền trực tiếp nuôi cơ thể.<br>• <b>Ý c [Đúng]:</b> Tuyến tụy tiết insulin giúp gan chuyển hóa glucose thành glycogen dự trữ.<br>• <b>Ý d [Sai]:</b> Fructose được gan chuyển hóa thành glucose và tham gia chu trình hô hấp tế bào sinh năng lượng bình thường.", "svgGraph": null}, {"q": "Hiện tượng nào sau đây chứng tỏ glucose có cấu tạo dạng mạch vòng trong dung dịch nước?", "opts": ["Glucose phản ứng với CH<sub>3</sub>OH khi có mặt khí HCl khan chỉ tạo ra methyl glucoside (thay thế 1 nhóm –OH hemiacetal duy nhất).", "Glucose tạo kết tủa Cu<sub>2</sub>O đỏ gạch khi đun với Cu(OH)<sub>2</sub>.", "Glucose tác dụng với anhydride acetic tạo ester chứa 5 gốc acetate.", "Glucose tác dụng với AgNO<sub>3</sub>/NH<sub>3</sub> tạo lớp tráng bạc."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Khi cho glucose tác dụng với CH<sub>3</sub>OH (xúc tác HCl khan), chỉ có nhóm –OH ở C1 (nhóm –OH hemiacetal ở dạng vòng) phản ứng tạo ether liên kết glycoside (methyl glucoside).<br>• Nếu ở dạng mạch hở thì cả 5 nhóm –OH đều phản ứng như nhau. Thí nghiệm này khẳng định glucose tồn tại dạng vòng khép kín.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "5": [{"q": "Saccharose (đường mía) là disaccharide được cấu tạo từ một gốc α-glucose và một gốc β-fructose liên kết với nhau qua loại liên kết nào?", "opts": ["Liên kết α-1,2-glycoside", "Liên kết α-1,4-glycoside", "Liên kết β-1,4-glycoside", "Liên kết peptide –CO–NH–"], "ans": 0, "exp": "• <b>Cấu tạo phân tử saccharose:</b> Phân tử saccharose liên kết từ C1 (nhóm –OH hemiacetal) của gốc α-glucose với C2 (nhóm –OH hemiketal) của gốc β-fructose qua cầu nối nguyên tử oxygen: liên kết α-1,2-glycoside.<br>• Vì cả 2 nhóm chức tạo tính khử đều đã tham gia tạo liên kết glycoside nên saccharose không còn nhóm –CHO tự do và không mở vòng được → không có tính khử.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"28\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14.5\" font-weight=\"800\">CẤU TRÚC PHÂN TỬ SACCHAROSE (C₁₂H₂₂O₁₁)</text>\n  <!-- Glucose unit -->\n  <g transform=\"translate(80, 110)\">\n    <polygon points=\"0,-35 40,-18 40,25 0,42 -40,25 -40,-18\" fill=\"rgba(14,165,233,0.18)\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <text x=\"0\" y=\"5\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">α-Glucose</text>\n    <circle cx=\"40\" cy=\"-18\" r=\"4\" fill=\"#fbbf24\"/>\n    <text x=\"40\" y=\"-26\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10\">C1</text>\n  </g>\n  <!-- Glycosidic Bridge O -->\n  <g transform=\"translate(190, 92)\">\n    <line x1=\"-70\" y1=\"0\" x2=\"-15\" y2=\"20\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n    <line x1=\"15\" y1=\"20\" x2=\"70\" y2=\"0\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n    <circle cx=\"0\" cy=\"20\" r=\"12\" fill=\"#070a14\" stroke=\"#f43f5e\" stroke-width=\"2.2\"/>\n    <text x=\"0\" y=\"25\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">O</text>\n    <text x=\"0\" y=\"48\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10.5\" font-weight=\"bold\">Cầu α-1,2-glycoside</text>\n  </g>\n  <!-- Fructose unit (5-membered ring) -->\n  <g transform=\"translate(340, 110)\">\n    <polygon points=\"0,-35 42,-5 26,38 -26,38 -42,-5\" fill=\"rgba(52,211,153,0.18)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"0\" y=\"5\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">β-Fructose</text>\n    <circle cx=\"-42\" cy=\"-5\" r=\"4\" fill=\"#fbbf24\"/>\n    <text x=\"-48\" y=\"-12\" text-anchor=\"end\" fill=\"#fbbf24\" font-size=\"10\">C2</text>\n  </g>\n  <!-- Property callout -->\n  <rect x=\"25\" y=\"172\" width=\"470\" height=\"42\" rx=\"6\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.12)\"/>\n  <text x=\"260\" y=\"190\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11.5\">Không còn nhóm –OH hemiacetal tự do → <tspan fill=\"#f43f5e\" font-weight=\"bold\">KHÔNG TRÁNG BẠC</tspan></text>\n  <text x=\"260\" y=\"206\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"10.5\">Thuỷ phân sinh ra cả α-glucose và β-fructose (đường nghịch đảo)</text>\n</svg>"}, {"q": "Tại sao dung dịch saccharose tinh khiết KHÔNG tham gia phản ứng tráng bạc với thuốc thử Tollens?", "opts": ["Trong phân tử không còn nhóm –OH hemiacetal tự do nên không thể mở vòng để tạo nhóm aldehyde –CHO.", "Saccharose có khối lượng phân tử quá lớn cản trở tiếp xúc với ion Ag⁺.", "Saccharose bị ion Ag⁺ kết tủa làm trơ hoá bề mặt.", "Saccharose chỉ tác dụng với chất oxi hoá ở môi trường acid mạnh."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Trong phân tử saccharose, cả nhóm –OH hemiacetal của gốc glucose và nhóm –OH hemiketal của gốc fructose đều đã liên kết qua cầu oxygen C1–O–C2.<br>• Do đó phân tử không thể mở vòng dạng mạch hở để tạo nhóm –CHO có tính khử, dẫn đến không tráng bạc và không khử Cu(OH)<sub>2</sub>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Maltose (đường mạch nha) khác với saccharose ở đặc điểm cấu tạo và tính chất nào sau đây?", "opts": ["Maltose được cấu tạo từ 2 gốc α-glucose và có khả năng tráng bạc với thuốc thử Tollens.", "Maltose không phản ứng được với Cu(OH)₂ ở nhiệt độ thường.", "Maltose không bị thuỷ phân trong môi trường acid.", "Maltose có công thức phân tử là C₆H₁₂O₆."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Phân tử maltose gồm 2 gốc α-glucose liên kết với nhau qua liên kết α-1,4-glycoside.<br>• Gốc glucose thứ hai vẫn còn 1 nhóm –OH hemiacetal tự do ở C1 nên trong dung dịch có thể mở vòng tạo nhóm –CHO.<br>• Vì vậy maltose có tính khử: tham gia phản ứng tráng bạc và khử Cu(OH)<sub>2</sub> đun nóng thành Cu<sub>2</sub>O đỏ gạch.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Tiến hành thuỷ phân hoàn toàn saccharose trong môi trường acid đun nóng (sau đó trung hoà acid bằng dung dịch kiềm) rồi chia làm 2 phần, xét tính Đúng/Sai:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Hỗn hợp sau phản ứng thuỷ phân chứa số mol glucose bằng số mol fructose.", "Hỗn hợp các chất sau thuỷ phân (đường nghịch đảo) có khả năng tham gia phản ứng tráng bạc tạo kết tủa kim loại Ag.", "Nếu không trung hoà acid trước khi thêm thuốc thử Tollens thì phản ứng tráng bạc vẫn diễn ra bình thường với hiệu suất cao.", "Phản ứng thuỷ phân saccharose có thể xúc tác bằng enzyme sucrase (invertase) ở nhiệt độ phòng."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> C<sub>12</sub>H<sub>22</sub>O<sub>11</sub> + H<sub>2</sub>O ⎯(H+, t°)→ C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (glucose) + C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (fructose) với tỉ lệ mol 1:1.<br>• <b>Ý b [Đúng]:</b> Cả glucose và fructose sinh ra đều có phản ứng tráng bạc.<br>• <b>Ý c [Sai]:</b> Thuốc thử Tollens hoạt động trong môi trường kiềm NH<sub>3</sub>; nếu còn acid dư sẽ trung hoà NH<sub>3</sub> và phá vỡ phức bạc, làm phản ứng tráng bạc không xảy ra.<br>• <b>Ý d [Đúng]:</b> Enzyme sucrase xúc tác đặc hiệu phản ứng thuỷ phân saccharose.", "svgGraph": null}, {"q": "Ghép từng loại nguyên liệu / cây trồng (Cột A) với loại disaccharide tương ứng được chiết xuất hoặc sản xuất chủ yếu (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Cây mía, củ cải đường, hoa thốt nốt ➔ Nguồn nguyên liệu tự nhiên giàu saccharose nhất", "Cây mía, củ cải đường, hoa thốt nốt ➔ Saccharose độ tinh khiết cao (> 99,5%)", "Cây mía, củ cải đường, hoa thốt nốt ➔ Hỗn hợp kết tinh của fructose và glucose", "Cây mía, củ cải đường, hoa thốt nốt ➔ Maltose (đường mạch nha)"], "ans": 0, "exp": "• <b>1 - B:</b> Mía và củ cải đường là nguồn cung cấp saccharose chủ yếu cho nhân loại.<br>• <b>2 - D:</b> Mầm lúa mạch thuỷ phân tinh bột sinh ra maltose.<br>• <b>3 - A:</b> Đường tinh luyện công nghiệp là saccharose độ sạch cao.<br>• <b>4 - C:</b> Mật ong tự nhiên giàu hỗn hợp monosaccharide.", "svgGraph": null}, {"q": "Điền các từ khóa chính xác vào vị trí trống về phản ứng thuỷ phân và tính chất của saccharose:<br><i>\"Saccharose có công thức phân tử là  [ ... ] . Khi hoà tan vào nước, saccharose hoà tan Cu(OH)₂ ở nhiệt độ thường tạo phức màu  [ ... ] . Khi đun nóng với acid vô cơ loãng, 1 phân tử saccharose bị thuỷ phân thành 1 phân tử  [ ... ]  và 1 phân tử  [ ... ] .\"</i>", "opts": ["C₁₂H₂₂O₁₁ — xanh lam — glucose — fructose", "fructose — glucose — xanh lam — C₁₂H₂₂O₁₁", "C₆H₁₂O₆ — xanh lam — đỏ gạch — glucose", "xanh lam — đỏ gạch — glucose — fructose"], "ans": 0, "exp": "• CTPT saccharose: C<sub>12</sub>H<sub>22</sub>O<sub>11</sub>.<br>• Hoà tan Cu(OH)<sub>2</sub> tạo dung dịch xanh lam đặc trưng của polyalcohol.<br>• Thuỷ phân hoàn toàn tạo hỗn hợp đồng phân glucose và fructose.", "svgGraph": null}, {"q": "Thuỷ phân hoàn toàn 34,2 gam saccharose trong môi trường acid với hiệu suất 100%, sau đó trung hoà acid rồi cho toàn bộ sản phẩm tác dụng với thuốc thử Tollens dư đun nóng. Khối lượng bạc kim loại thu được tối đa là bao nhiêu (cho C=12, H=1, O=16, Ag=108)?", "opts": ["43,2 gam", "21,6 gam", "10,8 gam", "32,4 gam"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Số mol saccharose: n = 34,2 / 342 = 0,1 mol.<br>C<sub>12</sub>H<sub>22</sub>O<sub>11</sub> + H<sub>2</sub>O → C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (glucose: 0,1 mol) + C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (fructose: 0,1 mol).<br>Khi tráng bạc trong môi trường kiềm NH<sub>3</sub>:<br>1 mol glucose → 2 mol Ag (0,1 mol → 0,2 mol Ag)<br>1 mol fructose → 2 mol Ag (0,1 mol → 0,2 mol Ag)<br>Tổng số mol Ag sinh ra = 0,2 + 0,2 = 0,4 mol.<br>Khối lượng Ag = 0,4 · 108 = 43,2 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Thuật ngữ 'đường nghịch đảo' (invert sugar) dùng để chỉ hỗn hợp sản phẩm thu được sau quá trình nào sau đây?", "opts": ["Thuỷ phân saccharose bằng acid hoặc enzyme, làm góc quay cực đổi từ quay phải sang quay trái.", "Oxi hoá glucose bằng nước bromine.", "Lên men tinh bột thành ethanol.", "Đun nóng glucose để tạo thành caramel."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Saccharose có góc quay cực riêng quay sang phải (+66,5°).<br>• Khi bị thuỷ phân tạo ra hỗn hợp glucose (quay phải +52,7°) và fructose (quay trái mạnh -92,4°).<br>• Kết quả là dung dịch hỗn hợp quay cực sang trái (-20°), đảo ngược hướng quay cực ban đầu, nên được gọi là đường nghịch đảo.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về ứng dụng thực tiễn của saccharose và maltose trong công nghiệp thực phẩm:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Saccharose được sử dụng rộng rãi làm chất tạo ngọt trong sản xuất bánh kẹo, đồ hộp, nước giải khát và làm thuốc điều vị trong y học.", "Maltose được sản xuất bằng cách dùng enzyme amylase thuỷ phân tinh bột gạo nếp, dùng làm kẹo mạch nha truyền thống.", "Saccharose tráng bạc tốt hơn glucose nên thường được dùng làm ruột phích nước nóng trong công nghiệp.", "Saccharose là nguyên liệu để sản xuất cồn sinh học và mì chính (monosodium glutamate) qua phương pháp lên men vi sinh."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Ứng dụng phổ biến của đường ăn mía.<br>• <b>Ý b [Đúng]:</b> Mạch nha truyền thống làm từ gạo nếp và mầm mạ lúa.<br>• <b>Ý c [Sai]:</b> Saccharose không hề có phản ứng tráng bạc; để tráng ruột phích người ta dùng glucose hoặc saccharose đã qua thuỷ phân trước.<br>• <b>Ý d [Đúng]:</b> Rỉ đường mía là nguồn carbon rẻ tiền để lên men sản xuất acid glutamic và ethanol.", "svgGraph": null}, {"q": "Để phân biệt hai dung dịch không màu đựng trong hai lọ riêng biệt mất nhãn: Saccharose và Maltose, thuốc thử duy nhất cần dùng là gì?", "opts": ["Dung dịch AgNO<sub>3</sub> trong NH<sub>3</sub> đun nóng (hoặc Cu(OH)<sub>2</sub> đun nóng)", "Dung dịch Cu(OH)<sub>2</sub> ở nhiệt độ phòng", "Quỳ tím", "Dung dịch phenolphthalein"], "ans": 0, "exp": "• <b>Hiện tượng nhận biết:</b><br>- Dung dịch AgNO<sub>3</sub> trong NH<sub>3</sub> đun nóng: Maltose sinh kết tủa bạc bám sáng bóng thành ống nghiệm; Saccharose không có hiện tượng gì.<br>- Cả hai chất đều hoà tan Cu(OH)<sub>2</sub> ở nhiệt độ thường tạo dung dịch xanh lam nên không thể phân biệt ở nhiệt độ thường.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "6": [{"q": "Tinh bột và cellulose đều có công thức phân tử là (C<sub>6</sub>H<sub>10</sub>O<sub>5</sub>)<sub>n</sub> nhưng không phải là đồng phân của nhau vì lý do nào sau đây?", "opts": ["Hệ số polymer hoá n của cellulose lớn hơn rất nhiều so với tinh bột và các gốc mắt xích cấu tạo khác nhau.", "Tinh bột chứa nguyên tố nitrogen còn cellulose chỉ chứa carbon, hydro, oxy.", "Cellulose tan tốt trong nước lạnh còn tinh bột hoàn toàn không tan.", "Tinh bột có mạch hở còn cellulose có mạch nhánh đa tầng."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Đồng phân là các chất có cùng công thức phân tử (cùng M).<br>• Tinh bột có n khoảng hàng trăm đến vài nghìn gốc α-glucose.<br>• Cellulose có n từ hàng nghìn đến hàng vạn gốc β-glucose (M rất lớn so với tinh bột). Do hệ số n không cố định và khác nhau nên công thức phân tử không giống nhau → không phải đồng phân.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"28\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">SO SÁNH CẤU TRÚC PHÂN TỬ TINH BỘT VÀ CELLULOSE</text>\n  <!-- Amylose helical spiral -->\n  <g transform=\"translate(40, 50)\">\n    <rect width=\"205\" height=\"110\" rx=\"8\" fill=\"rgba(14,165,233,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n    <text x=\"102\" y=\"24\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12.5\" font-weight=\"bold\">TINH BỘT (AMYLOSE)</text>\n    <!-- Coil line -->\n    <path d=\"M 25 65 Q 45 40 65 65 T 105 65 T 145 65 T 185 65\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    <text x=\"102\" y=\"95\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10.5\">Mạch xoắn lò xo (α-1,4-glycoside)</text>\n    <text x=\"102\" y=\"105\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"9.5\">Hấp phụ I₂ cho màu xanh tím đặc trưng</text>\n  </g>\n  <!-- Cellulose linear bundle -->\n  <g transform=\"translate(275, 50)\">\n    <rect width=\"205\" height=\"110\" rx=\"8\" fill=\"rgba(52,211,153,0.12)\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"102\" y=\"24\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"12.5\" font-weight=\"bold\">CELLULOSE</text>\n    <!-- Parallel lines with H-bonds -->\n    <line x1=\"25\" y1=\"52\" x2=\"185\" y2=\"52\" stroke=\"#34d399\" stroke-width=\"2.5\"/>\n    <line x1=\"25\" y1=\"72\" x2=\"185\" y2=\"72\" stroke=\"#34d399\" stroke-width=\"2.5\"/>\n    <!-- Hydrogen bonds between chains -->\n    <g stroke=\"#f43f5e\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\">\n      <line x1=\"50\" y1=\"52\" x2=\"50\" y2=\"72\"/>\n      <line x1=\"90\" y1=\"52\" x2=\"90\" y2=\"72\"/>\n      <line x1=\"130\" y1=\"52\" x2=\"130\" y2=\"72\"/>\n      <line x1=\"170\" y1=\"52\" x2=\"170\" y2=\"72\"/>\n    </g>\n    <text x=\"102\" y=\"95\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10.5\">Mạch kéo dài không phân nhánh (β-1,4)</text>\n    <text x=\"102\" y=\"105\" text-anchor=\"middle\" fill=\"#6ee7b7\" font-size=\"9.5\">Tập hợp thành sợi bền chắc</text>\n  </g>\n  <!-- Reaction summary -->\n  <rect x=\"40\" y=\"170\" width=\"440\" height=\"45\" rx=\"6\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.1)\"/>\n  <text x=\"260\" y=\"188\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11\">Thuỷ phân hoàn toàn cả 2 polysaccharide đều thu được <tspan fill=\"#38bdf8\" font-weight=\"bold\">GLUCOSE</tspan></text>\n  <text x=\"260\" y=\"204\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"10.5\">Cellulose tan trong nước Schweizer [Cu(NH₃)₄](OH)₂ và phản ứng tạo thuốc súng không khói</text>\n</svg>"}, {"q": "Nhỏ vài giọt dung dịch iodine (I<sub>2</sub>) vào hồ tinh bột ở nhiệt độ thường, xuất hiện màu gì đặc trưng?", "opts": ["Màu xanh tím đặc trưng (đun nóng mất màu, để nguội lại xuất hiện)", "Màu đỏ gạch", "Màu vàng tươi", "Màu tím thẫm không bao giờ biến đổi khi đun nóng"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Các phân tử amylose trong tinh bột cuộn thành hình xoắn lò xo có kích thước vừa khít để các phân tử iodine (I<sub>2</sub>) chui vào tạo hợp chất bọc có màu xanh tím.<br>• Khi đun nóng, chuỗi xoắn duỗi thẳng ra, phân tử I<sub>2</sub> giải phóng làm mất màu.<br>• Để nguội, cấu trúc xoắn phục hồi và màu xanh tím xuất hiện trở lại.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cellulose trinitrate được dùng làm thuốc súng không khói trong quân sự, được điều chế bằng phản ứng giữa cellulose với chất nào sau đây?", "opts": ["Dung dịch HNO<sub>3</sub> đặc có xúc tác H<sub>2</sub>SO<sub>4</sub> đặc, đun nóng", "Khí NO<sub>2</sub> ở nhiệt độ cao", "Dung dịch NaNO<sub>3</sub> trong môi trường kiềm", "Dung dịch NH<sub>3</sub> đậm đặc"], "ans": 0, "exp": "• <b>Phương trình phản ứng ester hoá:</b><br>[C<sub>6</sub>H<sub>7</sub>O<sub>2</sub>(OH)<sub>3</sub>]<sub>n</sub> + 3n HNO<sub>3</sub> ⎯(H<sub>2</sub>SO<sub>4</sub> đ, t°)→ [C<sub>6</sub>H<sub>7</sub>O<sub>2</sub>(ONO<sub>2</sub>)<sub>3</sub>]<sub>n</sub> + 3n H<sub>2</sub>O.<br>• Sản phẩm cellulose trinitrate rất dễ cháy nổ mạnh không tạo khói.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về cấu trúc và tính chất của tinh bột và cellulose, xác định tính Đúng/Sai:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Amylopectin trong tinh bột có cấu trúc mạch phân nhánh nhờ có liên kết α-1,4-glycoside và α-1,6-glycoside.", "Cellulose tan tốt trong dung dịch nước Schweizer (phức chất của Cu²⁺ với NH₃) tạo dung dịch keo nhớt dùng sản xuất tơ đồng - amoniac.", "Cả tinh bột và cellulose khi nhai kĩ trong miệng người đều bị enzyme amylase thuỷ phân thành đường ngọt.", "Cellulose là thành phần cấu tạo nên màng tế bào thực vật, tạo nên bộ khung cơ học chắc chắn cho cây cối."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Amylose chỉ có liên kết α-1,4 (không nhánh), amylopectin có thêm liên kết α-1,6 tại các điểm phân nhánh.<br>• <b>Ý b [Đúng]:</b> Dung dịch Schweizer [Cu(NH<sub>3</sub>)<sub>4</sub>](OH)<sub>2</sub> hoà tan cellulose.<br>• <b>Ý c [Sai]:</b> Nước bọt người chỉ chứa enzyme amylase thuỷ phân liên kết α-glycoside của tinh bột, con người không có enzyme cellulase nên không thể tiêu hoá được cellulose.<br>• <b>Ý d [Đúng]:</b> Vai trò cấu trúc sinh học chuẩn của cellulose.", "svgGraph": null}, {"q": "Ghép từng ứng dụng / sản phẩm (Cột A) với loại polysaccharide hoặc dẫn xuất tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Thuốc súng không khói (guncotton) ➔ Cellulose trinitrate", "Thuốc súng không khói (guncotton) ➔ Sản xuất từ cellulose gỗ qua chế hoá hoá học", "Thuốc súng không khói (guncotton) ➔ Tinh bột (hỗn hợp amylose và amylopectin)", "Thuốc súng không khói (guncotton) ➔ Cellulose sợi tự nhiên trong gỗ và bông nõn"], "ans": 0, "exp": "• <b>1 - A:</b> Cellulose trinitrate dùng chế tạo thuốc súng.<br>• <b>2 - B:</b> Tơ visco và tơ acetate là tơ bán tổng hợp (nhân tạo) chế tạo từ cellulose.<br>• <b>3 - C:</b> Tinh bột cung cấp năng lượng nuôi dưỡng loài người.<br>• <b>4 - D:</b> Gỗ chứa 50% cellulose là nguyên liệu ngành giấy.", "svgGraph": null}, {"q": "Hoàn thành đoạn văn bản mô tả cấu tạo của cellulose:<br><i>\"Cellulose là một  [ ... ]  thiên nhiên, mạch kéo dài không phân nhánh gồm nhiều gốc  [ ... ]  liên kết với nhau qua liên kết  [ ... ] . Mỗi mắt xích C₆H₁₀O₅ của cellulose còn lại  [ ... ]  nhóm hydroxy (-OH) tự do.\"</i>", "opts": ["polysaccharide — β-glucose — β-1,4-glycoside — 3", "3 — β-1,4-glycoside — β-glucose — polysaccharide", "β-glucose — α-glucose — β-1,4-glycoside — 3", "α-glucose — β-1,4-glycoside — 3 — 5"], "ans": 0, "exp": "• CTPT dạng nhóm chức của cellulose: [C<sub>6</sub>H<sub>7</sub>O<sub>2</sub>(OH)<sub>3</sub>]<sub>n</sub>.<br>• Mắt xích là β-glucose liên kết bởi cầu β-1,4-glycoside.<br>• Mỗi mắt xích có 3 nhóm –OH tự do.", "svgGraph": null}, {"q": "Để sản xuất 29,7 kg cellulose trinitrate với hiệu suất đạt 90%, cần dùng tối thiểu bao nhiêu kg cellulose tinh khiết (cho C=12, H=1, O=16, N=14)?", "opts": ["18,0 kg", "16,2 kg", "20,0 kg", "14,58 kg"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>[C<sub>6</sub>H<sub>7</sub>O<sub>2</sub>(OH)<sub>3</sub>]<sub>n</sub> + 3n HNO<sub>3</sub> → [C<sub>6</sub>H<sub>7</sub>O<sub>2</sub>(ONO<sub>2</sub>)<sub>3</sub>]<sub>n</sub> + 3n H<sub>2</sub>O<br>• Cứ 162n gam cellulose tạo ra 297n gam cellulose trinitrate.<br>Theo lý thuyết: Khối lượng cellulose cần = 29,7 · (162 / 297) = 16,2 kg.<br>Do hiệu suất H = 90%, khối lượng cellulose thực tế cần dùng = 16,2 / 0,9 = 18,0 kg.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Trong quá trình quang hợp của cây xanh, năng lượng ánh sáng mặt trời được tích lũy vào liên kết hoá học của tinh bột. Phương trình hoá học tổng quát của quá trình quang hợp tạo tinh bột là gì?", "opts": ["6n CO<sub>2</sub> + 5n H<sub>2</sub>O ⎯(ánh sáng, diệp lục)→ (C<sub>6</sub>H<sub>10</sub>O<sub>5</sub>)<sub>n</sub> + 6n O<sub>2</sub>", "6n CO<sub>2</sub> + 6n H<sub>2</sub>O ⎯(ánh sáng, diệp lục)→ (C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>)<sub>n</sub> + 6n O<sub>2</sub>", "n C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> → (C<sub>6</sub>H<sub>10</sub>O<sub>5</sub>)<sub>n</sub> + n H<sub>2</sub>O", "CO<sub>2</sub> + H<sub>2</sub>O → HCHO + O<sub>2</sub>"], "ans": 0, "exp": "• <b>Bản chất quang hợp:</b> Cây xanh hấp thu CO<sub>2</sub> từ khí quyển và H<sub>2</sub>O từ rễ nhờ chất diệp lục hấp thu photon ánh sáng mặt trời để tổng hợp tinh bột và giải phóng khí O<sub>2</sub> duy trì sự sống trên Trái Đất.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về khả năng phản ứng và sự biến đổi của carbohydrate trong môi trường cơ thể:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Thuỷ phân tinh bột bằng acid vô cơ hoặc enzyme thu được sản phẩm cuối cùng duy nhất là α-glucose.", "Động vật ăn cỏ như trâu, bò tiêu hoá được cỏ rơm nhờ hệ vi sinh vật sống cộng sinh trong dạ cỏ tiết ra enzyme cellulase.", "Hạt cơm nguội khi nhai lâu trong miệng thấy có vị ngọt thanh là do enzyme amylase trong nước bọt thuỷ phân một phần tinh bột thành maltose.", "Cellulose và tinh bột đều có phản ứng tráng bạc vì đầu mạch phân tử vẫn còn chứa nhóm aldehyde tự do."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Quá trình thuỷ phân hoàn toàn tinh bột cho glucose.<br>• <b>Ý b [Đúng]:</b> Vi sinh vật cộng sinh dạ cỏ tiết enzyme cellulase cắt liên kết β-1,4-glycoside.<br>• <b>Ý c [Đúng]:</b> Tinh bột bị thuỷ phân từng bước qua dextrin rồi thành maltose có vị ngọt.<br>• <b>Ý d [Sai]:</b> Khối lượng phân tử polymer quá lớn, tỉ lệ nhóm khử ở đầu mạch là vô cùng nhỏ không đáng kể nên thực tế không có phản ứng tráng bạc.", "svgGraph": null}, {"q": "Một sợi dây bằng sợi bông tự nhiên và một sợi dây tơ tằm nhân tạo được đốt cháy trên ngọn lửa. Hiện tượng nào giúp khẳng định sợi dây làm từ cellulose tự nhiên?", "opts": ["Cháy nhanh, có tàn tro màu xám mịn và không có mùi khét tóc cháy.", "Cháy sùi bọt, có mùi khét lẹt như tóc cháy và vón cục đen cứng.", "Không cháy khi hơ trên ngọn lửa đèn cồn.", "Cháy phát ra ánh sáng chói loà màu đỏ tía."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Sợi bông là cellulose nguyên chất (gần 98%), khi cháy giống như đốt giấy: ngọn lửa vàng, cháy êm dịu, khói nhẹ, tro mịn xốp, không có mùi khét.<br>• Còn tơ tằm là protein (chứa N, S) khi cháy bốc mùi khét đặc trưng của tóc hoặc lông vũ cháy và vón cục tròn màu đen giòn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "7": [{"q": "Chất nào sau đây thuộc loại disaccharide?", "opts": ["Saccharose", "Glucose", "Fructose", "Cellulose"], "ans": 0, "exp": "• <b>Phân loại carbohydrate:</b><br>- Monosaccharide: Glucose, Fructose.<br>- Disaccharide: Saccharose, Maltose.<br>- Polysaccharide: Tinh bột, Cellulose.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Dãy gồm các chất đều có khả năng tham gia phản ứng tráng bạc với thuốc thử Tollens là:", "opts": ["Glucose, fructose, maltose", "Glucose, saccharose, tinh bột", "Fructose, saccharose, cellulose", "Maltose, saccharose, glycerol"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Glucose và maltose có nhóm –CHO nên tráng bạc.<br>• Fructose trong môi trường kiềm NH<sub>3</sub> chuyển hoá thành glucose nên cũng tráng bạc.<br>• Saccharose, tinh bột, cellulose không tham gia phản ứng tráng bạc.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho các carbohydrate sau: glucose, fructose, saccharose, tinh bột, cellulose. Số chất khi thuỷ phân hoàn toàn trong môi trường acid chỉ thu được một loại monosaccharide duy nhất là:", "opts": ["2 (tinh bột và cellulose)", "3 (saccharose, tinh bột, cellulose)", "1 (tinh bột)", "4"], "ans": 0, "exp": "• <b>Phân tích:</b><br>- Glucose và fructose là monosaccharide nên không bị thuỷ phân.<br>- Saccharose thuỷ phân cho <b>2 loại monosaccharide</b>: glucose và fructose.<br>- Tinh bột thuỷ phân hoàn toàn chỉ cho <b>glucose</b>.<br>- Cellulose thuỷ phân hoàn toàn chỉ cho <b>glucose</b>.<br>Vậy có đúng 2 chất chỉ thu được 1 loại monosaccharide duy nhất.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính Đúng/Sai của các nhận định tổng kết về carbohydrate:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Glucose và saccharose đều hoà tan được Cu(OH)₂ ở nhiệt độ thường tạo dung dịch màu xanh lam thẫm.", "Tinh bột và cellulose đều có phản ứng thuỷ phân xúc tác acid tạo ra sản phẩm có khả năng tráng bạc.", "Để phân biệt hồ tinh bột và dung dịch glucose có thể dùng thuốc thử dung dịch iodine.", "Fructose có vị ngọt kém hơn glucose và saccharose."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Đều là polyalcohol có nhiều nhóm –OH kề nhau.<br>• <b>Ý b [Đúng]:</b> Thuỷ phân tạo glucose có khả năng tráng bạc.<br>• <b>Ý c [Đúng]:</b> Tinh bột cho màu xanh tím với iodine, glucose không phản ứng.<br>• <b>Ý d [Sai]:</b> Độ ngọt: Fructose > Saccharose > Glucose (Fructose ngọt gấp 1,5 lần saccharose).", "svgGraph": null}, {"q": "Ghép từng carbohydrate (Cột A) với phản ứng hoá học đặc trưng nhất để nhận biết (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Hồ tinh bột ➔ Dung dịch iodine (xuất hiện màu xanh tím đặc trưng)", "Hồ tinh bột ➔ Dung dịch nước bromine (làm mất màu nâu đỏ của dung dịch Br₂)", "Hồ tinh bột ➔ Hoà tan trong dung dịch nước Schweizer [Cu(NH₃)₄](OH)₂", "Hồ tinh bột ➔ Hoà tan Cu(OH)₂ ở nhiệt độ thường nhưng không tráng bạc với thuốc thử Tollens"], "ans": 0, "exp": "• <b>1 - A:</b> Tinh bột nhận biết bằng I<sub>2</sub>.<br>• <b>2 - B:</b> Glucose phân biệt với fructose bằng nước Br<sub>2</sub>.<br>• <b>3 - C:</b> Cellulose tan trong nước Schweizer.<br>• <b>4 - D:</b> Saccharose hoà tan Cu(OH)<sub>2</sub> tạo xanh lam nhưng không tráng bạc.", "svgGraph": null}, {"q": "Hoàn thiện nội dung phân loại và bản chất cấu tạo carbohydrate:<br><i>\"Carbohydrate là những hợp chất hữu cơ  [ ... ] , thường có công thức chung là C<sub>n</sub>(H<sub>2</sub>O)<sub>m</sub>. Monosaccharide là carbohydrate đơn giản nhất  [ ... ]  bị thuỷ phân. Polysaccharide là polymer thiên nhiên gồm nhiều mắt xích  [ ... ]  liên kết với nhau qua liên kết  [ ... ] .\"</i>", "opts": ["tạp chức — không — monosaccharide — glycoside", "glycoside — monosaccharide — không — tạp chức", "đa chức — không — monosaccharide — glycoside", "không — monosaccharide — glycoside — peptide"], "ans": 0, "exp": "• Carbohydrate là hợp chất hữu cơ tạp chức.<br>• Monosaccharide không bị thuỷ phân.<br>• Polysaccharide gồm các gốc monosaccharide nối bằng liên kết glycoside.", "svgGraph": null}, {"q": "Lên men m gam glucose thành ethanol với hiệu suất 75%. Khí CO<sub>2</sub> sinh ra được hấp thụ hoàn toàn vào dung dịch Ca(OH)<sub>2</sub> dư thu được 50 gam kết tủa trắng. Giá trị của m là bao nhiêu (cho C=12, H=1, O=16, Ca=40)?", "opts": ["60,0 gam", "45,0 gam", "33,75 gam", "90,0 gam"], "ans": 0, "exp": "• <b>Tính toán:</b><br>n(CaCO<sub>3</sub>) = 50 / 100 = 0,5 mol.<br>Ca(OH)<sub>2</sub> dư nên n(CO<sub>2</sub>) = n(CaCO<sub>3</sub>) = 0,5 mol.<br>Phương trình lên men: C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> → 2C<sub>2</sub>H<sub>5</sub>OH + 2CO<sub>2</sub><br>Số mol glucose phản ứng = 0,5 / 2 = 0,25 mol.<br>Do hiệu suất H = 75%, số mol glucose ban đầu = 0,25 / 0,75 = 1/3 mol.<br>Khối lượng glucose m = (1/3) · 180 = 60,0 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Carbohydrate nào sau đây đóng vai trò là chất dự trữ dinh dưỡng năng lượng ngắn hạn trong gan và cơ bắp của người và động vật?", "opts": ["Glycogen (còn gọi là tinh bột động vật)", "Cellulose", "Saccharose", "Maltose"], "ans": 0, "exp": "• <b>Bản chất sinh học:</b> Glycogen là polysaccharide phân nhánh rất dày đặc gồm các gốc α-glucose, được tổng hợp và dự trữ trong gan và cơ bắp động vật để nhanh chóng giải phóng glucose vào máu khi cơ thể cần năng lượng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính Đúng/Sai của các phát biểu về phương pháp sản xuất và ứng dụng thực tiễn của carbohydrate:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Trong công nghiệp đường mía, người ta dùng vôi sữa Ca(OH)₂ và khí CO₂ để lọc trong nước mía và loại bỏ tạp chất acid hữu cơ.", "Cellulose acetate được dùng để sản xuất sợi tơ acetate và chế tạo phim ảnh an toàn không cháy.", "Có thể dùng glucose để tráng gương, tráng ruột phích nước nóng thay cho aldehyde formic độc hại.", "Ăn quá nhiều đường saccharose hàng ngày hoàn toàn không ảnh hưởng gì tới sức khoẻ và không gây nguy cơ béo phì, tiểu đường."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Quy trình tinh chế nước mía công nghiệp dùng vôi sữa và CO<sub>2</sub>.<br>• <b>Ý b [Đúng]:</b> Cellulose acetate là tơ nhân tạo và chất dẻo chống cháy.<br>• <b>Ý c [Đúng]:</b> Glucose thân thiện, không độc hại như formaldehyde HCHO.<br>• <b>Ý d [Sai]:</b> Lạm dụng đường ngọt là nguyên nhân hàng đầu gây sâu răng, béo phì và tiểu đường tuýp 2.", "svgGraph": null}, {"q": "Cho sơ đồ chuyển hoá: Tinh bột → X → Y → Ethyl acetate. Các chất X, Y lần lượt là:", "opts": ["Glucose, ethanol", "Glucose, acetic acid", "Maltose, ethanol", "Fructose, ethylene glycol"], "ans": 0, "exp": "• <b>Chuỗi phản ứng:</b><br>1. (C<sub>6</sub>H<sub>10</sub>O<sub>5</sub>)<sub>n</sub> + nH<sub>2</sub>O ⎯(H+, t°)→ nC<sub>6</sub>H<sub>12</sub>O<sub>6</sub> (X là glucose).<br>2. C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> ⎯(men rượu)→ 2C<sub>2</sub>H<sub>5</sub>OH (Y là ethanol) + 2CO<sub>2</sub>.<br>3. C<sub>2</sub>H<sub>5</sub>OH + CH<sub>3</sub>COOH ⎯(H<sub>2</sub>SO<sub>4</sub> đ, t°)⇌ CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub> (ethyl acetate) + H<sub>2</sub>O.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "8": [{"q": "Amine nào sau đây thuộc loại amine bậc hai (secondary amine)?", "opts": ["Dimethylamine (CH<sub>3</sub>–NH–CH<sub>3</sub>)", "Methylamine (CH<sub>3</sub>–NH<sub>2</sub>)", "Trimethylamine ((CH<sub>3</sub>)<sub>3</sub>N)", "Ethylamine (C<sub>2</sub>H<sub>5</sub>–NH<sub>2</sub>)"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Bậc của amine bằng số nguyên tử H trong phân tử NH<sub>3</sub> bị thay thế bởi gốc hydrocarbon:<br>- Bậc 1: R–NH<sub>2</sub> (Methylamine, Ethylamine)<br>- Bậc 2: R–NH–R' (Dimethylamine)<br>- Bậc 3: R<sub>3</sub>N (Trimethylamine)<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"28\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14.5\" font-weight=\"800\">PHÂN LOẠI VÀ BẬC CỦA AMINE</text>\n  <!-- 3 Boxes for 3 degrees -->\n  <!-- Degree 1 -->\n  <g transform=\"translate(25, 50)\">\n    <rect width=\"145\" height=\"110\" rx=\"8\" fill=\"rgba(14,165,233,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n    <text x=\"72\" y=\"24\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">BẬC 1 (1°)</text>\n    <text x=\"72\" y=\"55\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"15\" font-weight=\"bold\">R–NH₂</text>\n    <text x=\"72\" y=\"80\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10.5\">CH₃–NH₂</text>\n    <text x=\"72\" y=\"96\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"10\">Methylamine</text>\n  </g>\n  <!-- Degree 2 -->\n  <g transform=\"translate(185, 50)\">\n    <rect width=\"150\" height=\"110\" rx=\"8\" fill=\"rgba(52,211,153,0.12)\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"75\" y=\"24\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">BẬC 2 (2°)</text>\n    <text x=\"75\" y=\"55\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"14\" font-weight=\"bold\">R–NH–R'</text>\n    <text x=\"75\" y=\"80\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10.5\">CH₃–NH–CH₃</text>\n    <text x=\"75\" y=\"96\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"10\">Dimethylamine</text>\n  </g>\n  <!-- Degree 3 -->\n  <g transform=\"translate(350, 50)\">\n    <rect width=\"145\" height=\"110\" rx=\"8\" fill=\"rgba(244,63,94,0.12)\" stroke=\"#f43f5e\" stroke-width=\"1.5\"/>\n    <text x=\"72\" y=\"24\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">BẬC 3 (3°)</text>\n    <text x=\"72\" y=\"55\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"15\" font-weight=\"bold\">R₃N</text>\n    <text x=\"72\" y=\"80\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10.5\">(CH₃)₃N</text>\n    <text x=\"72\" y=\"96\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"10\">Trimethylamine</text>\n  </g>\n  <!-- Note bottom -->\n  <rect x=\"25\" y=\"170\" width=\"470\" height=\"45\" rx=\"6\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.1)\"/>\n  <text x=\"260\" y=\"188\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11\">Nguyên tử N còn <tspan fill=\"#fbbf24\" font-weight=\"bold\">cặp electron tự do</tspan> mang tính base đặc trưng</text>\n  <text x=\"260\" y=\"204\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"10.5\">Lực base: Dimethylamine > Methylamine > NH₃ > Aniline (C₆H₅NH₂)</text>\n</svg>"}, {"q": "So sánh lực base nào sau đây là đúng theo chiều giảm dần?", "opts": ["(CH<sub>3</sub>)<sub>2</sub>NH > CH<sub>3</sub>NH<sub>2</sub> > NH<sub>3</sub> > C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub>", "C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub> > NH<sub>3</sub> > CH<sub>3</sub>NH<sub>2</sub> > (CH<sub>3</sub>)<sub>2</sub>NH", "NH<sub>3</sub> > (CH<sub>3</sub>)<sub>2</sub>NH > CH<sub>3</sub>NH<sub>2</sub> > C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub>", "CH<sub>3</sub>NH<sub>2</sub> > (CH<sub>3</sub>)<sub>2</sub>NH > C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub> > NH<sub>3</sub>"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b><br>- Gốc alkyl (–CH<sub>3</sub>) là nhóm đẩy electron làm tăng mật độ electron trên nguyên tử N → tăng khả năng nhận proton H⁺ → tăng tính base.<br>- Vòng phenyl (–C<sub>6</sub>H<sub>5</sub>) hút electron qua hiệu ứng liên hợp làm giảm mật độ electron trên N → tính base của aniline rất yếu (yếu hơn NH<sub>3</sub>, không làm đổi màu quỳ tím).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi cho aniline (C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub>) tác dụng với dung dịch nước bromine (Br<sub>2</sub>/H<sub>2</sub>O) ở nhiệt độ phòng, hiện tượng quan sát được là gì?", "opts": ["Nước bromine mất màu và xuất hiện kết tủa trắng 2,4,6-tribromoaniline.", "Có khí màu nâu đỏ bay ra mãnh liệt.", "Xuất hiện kết tủa màu xanh lam thẫm.", "Không có hiện tượng gì xảy ra vì nhân benzen rất trơ."], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub> + 3Br<sub>2</sub> → C<sub>6</sub>H<sub>2</sub>Br<sub>3</sub>NH<sub>2</sub> ↓ (trắng) + 3HBr<br>• Nhóm –NH<sub>2</sub> hoạt hoá nhân thơm mạnh ở các vị trí ortho và para, phản ứng thế xảy ra dễ dàng ở điều kiện thường dùng để nhận biết aniline.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về tính chất vật lí và hoá học của các amine, xác định tính Đúng/Sai:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Methylamine, dimethylamine, trimethylamine và ethylamine là các chất khí ở nhiệt độ phòng, mùi khai khó chịu, độc và tan nhiều trong nước.", "Aniline là chất lỏng không màu, ít tan trong nước, nặng hơn nước và lắng xuống đáy ống nghiệm.", "Dung dịch ethylamine làm quỳ tím chuyển sang màu đỏ vì chứa nguyên tố nitrogen mang tính acid.", "Aniline dễ bị oxi hoá bởi oxygen trong không khí chuyển dần từ không màu sang màu đen nâu."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> 4 amine khí đầu dãy có mùi khai giống amoniac.<br>• <b>Ý b [Đúng]:</b> Aniline d = 1,02 g/cm<sup>3</sup> nặng hơn nước và ít tan.<br>• <b>Ý c [Sai]:</b> Dung dịch ethylamine có tính base, làm quỳ tím hoá xanh (hoá hồng phenolphthalein).<br>• <b>Ý d [Đúng]:</b> Aniline để trong không khí bị oxi hoá thành hợp chất có màu đen nâu.", "svgGraph": null}, {"q": "Ghép từng amine (Cột A) với công thức cấu tạo tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Aniline ➔ C₆H₅NH₂ (phenylamine)", "Aniline ➔ C₂H₅NH₂ (ethanamine)", "Aniline ➔ CH₃–NH–CH₃ (N-methylmethanamine)", "Aniline ➔ H₂N–(CH₂)₆–NH₂ (hexane-1,6-diamine dùng sản xuất nylon-6,6)"], "ans": 0, "exp": "• <b>1 - A:</b> Aniline C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub>.<br>• <b>2 - B:</b> Ethylamine C<sub>2</sub>H<sub>5</sub>NH<sub>2</sub>.<br>• <b>3 - C:</b> Dimethylamine (CH<sub>3</sub>)<sub>2</sub>NH.<br>• <b>4 - D:</b> Hexamethylenediamine là monomer trùng ngưng tạo nylon-6,6.", "svgGraph": null}, {"q": "Điền các từ khóa chính xác vào chỗ trống về tính base của amine:<br><i>\"Do nguyên tử nitrogen trong nhóm amino còn  [ ... ]  tự do, các amine có tính  [ ... ] . Dung dịch các amine béo làm quỳ tím chuyển sang màu  [ ... ] . Khi tác dụng với acid mạnh như HCl, amine tạo thành  [ ... ]  tan tốt trong nước.\"</i>", "opts": ["cặp electron — base — xanh — muối ammonium", "muối ammonium — xanh — base — cặp electron", "base — acid — xanh — đỏ", "acid — xanh — đỏ — muối ammonium"], "ans": 0, "exp": "• Bản chất tính base là khả năng nhận H<sup>+</sup> nhờ cặp electron tự do trên N.<br>• Làm quỳ tím hoá xanh.<br>• Phản ứng với acid: R–NH<sub>2</sub> + HCl → R–NH<sub>3</sub>Cl (muối ammonium).", "svgGraph": null}, {"q": "Cho 9,0 gam ethylamine (C<sub>2</sub>H<sub>5</sub>NH<sub>2</sub>) tác dụng hoàn toàn với lượng dư dung dịch HCl. Khối lượng muối ethylammonium chloride thu được là bao nhiêu (cho C=12, H=1, N=14, Cl=35,5)?", "opts": ["16,3 gam", "14,5 gam", "8,15 gam", "18,1 gam"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>C<sub>2</sub>H<sub>5</sub>NH<sub>2</sub> + HCl → C<sub>2</sub>H<sub>5</sub>NH<sub>3</sub>Cl<br>• <b>Tính toán:</b><br>M(C<sub>2</sub>H<sub>5</sub>NH<sub>2</sub>) = 45 g/mol.<br>Số mol amine: n = 9,0 / 45 = 0,2 mol.<br>Khối lượng muối = 0,2 · (45 + 36,5) = 0,2 · 81,5 = 16,3 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Để rửa sạch ống nghiệm dính bám aniline không tan trong nước, phương pháp hoá học nào sau đây là hiệu quả nhất?", "opts": ["Tráng trước bằng dung dịch HCl để chuyển aniline thành muối tan, sau đó rửa lại bằng nước sạch.", "Rửa nhiều lần bằng nước cất đun sôi.", "Rửa bằng dung dịch kiềm đậm đặc NaOH.", "Rửa bằng nước muối sinh lí NaCl."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Aniline là amine thơm ít tan trong nước.<br>• Khi cho HCl vào: C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub> + HCl → C<sub>6</sub>H<sub>5</sub>NH<sub>3</sub>Cl (phenylammonium chloride là muối tan hoàn toàn trong nước).<br>• Sau đó xả nước sạch thì toàn bộ muối trôi đi hoàn toàn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu ứng dụng và độc tính của amine trong thực tiễn đời sống:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Trimethylamine là chất có mùi tanh đặc trưng của cá mè, cá biển để lâu ngày.", "Để khử mùi tanh của cá khi nấu ăn, người ta có thể thêm một chút giấm ăn hoặc nước cốt chanh chứa acid.", "Nicotine trong khói thuốc lá là một amine độc hại gây nghiện và ảnh hưởng nghiêm trọng đến tim mạch, phổi.", "Aniline là hợp chất hoàn toàn vô hại, được dùng làm phẩm màu nhuộm an toàn trong bánh kẹo thực phẩm cho trẻ em."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Trimethylamine (CH<sub>3</sub>)<sub>3</sub>N tạo mùi tanh cá.<br>• <b>Ý b [Đúng]:</b> Acid acetic (giấm) hoặc citric acid (chanh) phản ứng với amine tạo muối không bay hơi, làm mất mùi tanh.<br>• <b>Ý c [Đúng]:</b> Nicotine là alkaloid amine cực độc trong thuốc lá.<br>• <b>Ý d [Sai]:</b> Aniline rất độc, gây ung thư và phá huỷ hồng cầu máu, tuyệt đối cấm dùng trong thực phẩm.", "svgGraph": null}, {"q": "Đốt cháy hoàn toàn 0,1 mol một amine no đơn chức mạch hở X thu được 0,2 mol CO<sub>2</sub>. Công thức cấu tạo của X là gì?", "opts": ["C<sub>2</sub>H<sub>5</sub>NH<sub>2</sub> (hoặc (CH<sub>3</sub>)<sub>2</sub>NH)", "CH<sub>3</sub>NH<sub>2</sub>", "C<sub>3</sub>H<sub>7</sub>NH<sub>2</sub>", "C<sub>4</sub>H<sub>9</sub>NH<sub>2</sub>"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Số nguyên tử carbon trong phân tử amine = n(CO<sub>2</sub>) / n(amine) = 0,2 / 0,1 = 2.<br>Amine no đơn chức mạch hở có CTPT C<sub>n</sub>H<sub>2n+3</sub>N.<br>Với n = 2 → C<sub>2</sub>H<sub>7</sub>N (gồm ethylamine CH<sub>3</sub>CH<sub>2</sub>NH<sub>2</sub> và dimethylamine (CH<sub>3</sub>)<sub>2</sub>NH).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "9": [{"q": "Amino acid là loại hợp chất hữu cơ tạp chức trong phân tử chứa đồng thời hai nhóm chức nào sau đây?", "opts": ["Nhóm amino (–NH<sub>2</sub>) và nhóm carboxyl (–COOH)", "Nhóm hydroxy (–OH) và nhóm aldehyde (–CHO)", "Nhóm carbonyl (>C=O) và nhóm ester (–COO–)", "Nhóm amino (–NH<sub>2</sub>) và nhóm sulfonic acid (–SO<sub>3</sub>H)"], "ans": 0, "exp": "• <b>Định nghĩa SGK:</b> Amino acid là hợp chất hữu cơ tạp chức, trong phân tử chứa đồng thời nhóm chức amino (–NH<sub>2</sub>) mang tính base và nhóm carboxyl (–COOH) mang tính acid.<br>• α-amino acid là đơn vị cấu trúc nền tảng cấu tạo nên protein.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"28\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14.5\" font-weight=\"800\">CẤU TRÚC α-AMINO ACID VÀ LIÊN KẾT PEPTIDE</text>\n  <!-- Alpha-amino acid formula -->\n  <g transform=\"translate(35, 55)\">\n    <rect width=\"210\" height=\"95\" rx=\"8\" fill=\"rgba(14,165,233,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n    <text x=\"105\" y=\"24\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">CẤU TRÚC α-AMINO ACID</text>\n    <text x=\"35\" y=\"60\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"bold\">H₂N</text>\n    <text x=\"80\" y=\"60\" fill=\"#cbd5e1\" font-size=\"14\">–CH(R)–</text>\n    <text x=\"150\" y=\"60\" fill=\"#34d399\" font-size=\"14\" font-weight=\"bold\">COOH</text>\n    <text x=\"45\" y=\"82\" fill=\"#f43f5e\" font-size=\"10\">Base</text>\n    <text x=\"165\" y=\"82\" fill=\"#34d399\" font-size=\"10\">Acid</text>\n    <text x=\"105\" y=\"82\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"9.5\">Carbon α</text>\n  </g>\n  <!-- Peptide bond -->\n  <g transform=\"translate(265, 55)\">\n    <rect width=\"225\" height=\"95\" rx=\"8\" fill=\"rgba(52,211,153,0.12)\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"112\" y=\"24\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">LIÊN KẾT PEPTIDE</text>\n    <text x=\"45\" y=\"60\" fill=\"#cbd5e1\" font-size=\"13\">...–CO</text>\n    <!-- Highlighted box for -CO-NH- -->\n    <rect x=\"85\" y=\"40\" width=\"60\" height=\"28\" rx=\"4\" fill=\"rgba(244,63,94,0.25)\" stroke=\"#f43f5e\" stroke-width=\"1.8\"/>\n    <text x=\"115\" y=\"60\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"13.5\" font-weight=\"800\">–NH–</text>\n    <text x=\"155\" y=\"60\" fill=\"#cbd5e1\" font-size=\"13\">CH(R)...</text>\n    <text x=\"112\" y=\"84\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10\">Nhóm amide giữa 2 α-amino acid</text>\n  </g>\n  <!-- Footnote -->\n  <rect x=\"25\" y=\"165\" width=\"470\" height=\"50\" rx=\"6\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.1)\"/>\n  <text x=\"260\" y=\"185\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11.5\">Tồn tại ở dạng <tspan fill=\"#fbbf24\" font-weight=\"bold\">ion lưỡng cực</tspan> H₃N⁺–CH(R)–COO⁻ → Nhiệt độ nóng chảy cao, tan tốt trong nước</text>\n  <text x=\"260\" y=\"202\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"11\">Có tính chất <tspan fill=\"#38bdf8\" font-weight=\"bold\">lưỡng tính</tspan> (tác dụng với cả acid mạnh và base mạnh)</text>\n</svg>"}, {"q": "Amino acid nào sau đây có tên thay thế là 2-aminoethanoic acid (tên bán hệ thống là aminoacetic acid)?", "opts": ["Glycine (H<sub>2</sub>N–CH<sub>2</sub>–COOH, M = 75)", "Alanine (CH<sub>3</sub>–CH(NH<sub>2</sub>)–COOH, M = 89)", "Valine ((CH<sub>3</sub>)<sub>2</sub>CH–CH(NH<sub>2</sub>)–COOH, M = 117)", "Lysine (H<sub>2</sub>N–(CH<sub>2</sub>)<sub>4</sub>–CH(NH<sub>2</sub>)–COOH, M = 146)"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Glycine có công thức cấu tạo đơn giản nhất trong các amino acid: H<sub>2</sub>N–CH<sub>2</sub>–COOH.<br>• Phân tử gồm 2 carbon, tên thay thế là 2-aminoethanoic acid.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Dung dịch chất nào sau đây làm quỳ tím chuyển sang màu hồng đỏ?", "opts": ["Glutamic acid (HOOC–CH<sub>2</sub>–CH<sub>2</sub>–CH(NH<sub>2</sub>)–COOH)", "Lysine (H<sub>2</sub>N–(CH<sub>2</sub>)<sub>4</sub>–CH(NH<sub>2</sub>)–COOH)", "Glycine (H<sub>2</sub>N–CH<sub>2</sub>–COOH)", "Alanine (CH<sub>3</sub>–CH(NH<sub>2</sub>)–COOH)"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b><br>- Glutamic acid có 2 nhóm –COOH và 1 nhóm –NH<sub>2</sub> → số nhóm acid nhiều hơn base → môi trường acid yếu → quỳ tím hoá hồng.<br>- Lysine có 2 nhóm –NH<sub>2</sub> và 1 nhóm –COOH → môi trường base → quỳ tím hoá xanh.<br>- Glycine và Alanine có 1 nhóm –NH<sub>2</sub> và 1 nhóm –COOH → môi trường gần trung tính → không đổi màu quỳ tím.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về tính chất hoá học và cấu trúc của amino acid và peptide:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Amino acid là hợp chất lưỡng tính, vừa tác dụng được với dung dịch acid mạnh vừa tác dụng được với dung dịch kiềm mạnh.", "Ở trạng thái tinh thể và trong dung dịch nước, amino acid tồn tại chủ yếu ở dạng phân tử trung hoà không mang điện.", "Peptide là hợp chất chứa từ 2 đến 50 gốc α-amino acid liên kết với nhau bằng các liên kết peptide –CO–NH–.", "Dipeptide tạo từ glycine và alanine (Gly–Ala) tham gia phản ứng màu biuret tạo dung dịch màu tím đặc trưng với Cu(OH)₂."], "ans": 1, "exp": "• <b>Ý a [Đúng]:</b> Nhóm –NH<sub>2</sub> nhận proton (tính base), nhóm –COOH nhường proton (tính acid).<br>• <b>Ý b [Sai]:</b> Amino acid tồn tại chủ yếu ở dạng <b>ion lưỡng cực</b> H<sub>3</sub>N⁺–CH(R)–COO⁻ do tương tác nội phân tử.<br>• <b>Ý c [Đúng]:</b> Định nghĩa peptide chuẩn SGK.<br>• <b>Ý d [Sai]:</b> Chỉ những peptide có từ 2 liên kết peptide trở lên (tức là từ <b>tripeptide</b> trở lên) mới có phản ứng màu biuret; dipeptide không có phản ứng này.", "svgGraph": null}, {"q": "Ghép từng amino acid thiết yếu (Cột A) với số lượng nhóm chức trong phân tử (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Glycine ➔ 1 nhóm –NH₂ và 1 nhóm –COOH (phân tử khối 75)", "Glycine ➔ 1 nhóm –NH₂ và 1 nhóm –COOH (mạch phân nhánh)", "Glycine ➔ 1 nhóm –NH₂ và 2 nhóm –COOH (tính acid trội hơn)", "Glycine ➔ 2 nhóm –NH₂ và 1 nhóm –COOH (tính base trội hơn)"], "ans": 0, "exp": "• <b>1 - D:</b> Glycine: 1 nhóm –NH<sub>2</sub>, 1 nhóm –COOH (M=75).<br>• <b>2 - B:</b> Glutamic acid: 1 nhóm –NH<sub>2</sub>, 2 nhóm –COOH.<br>• <b>3 - C:</b> Lysine: 2 nhóm –NH<sub>2</sub>, 1 nhóm –COOH.<br>• <b>4 - A:</b> Valine: 1 nhóm –NH<sub>2</sub>, 1 nhóm –COOH mạch nhánh.", "svgGraph": null}, {"q": "Hoàn thiện các vị trí trống về liên kết peptide và phản ứng màu biuret:<br><i>\"Liên kết của nhóm  [ ... ]  với nhóm  [ ... ]  giữa hai gốc α-amino acid được gọi là liên kết peptide. Phản ứng màu biuret xảy ra khi cho peptide có từ  [ ... ]  liên kết peptide trở lên tác dụng với  [ ... ]  trong môi trường kiềm tạo phức màu tím.\"</i>", "opts": ["-CO- — -NH- — 2 — Cu(OH)₂", "Cu(OH)₂ — 2 — -NH- — -CO-", "-NH- — 2 — 1 — Cu(OH)₂", "2 — 1 — Cu(OH)₂ — AgNO₃"], "ans": 0, "exp": "• Liên kết peptide là liên kết –CO–NH– giữa 2 đơn vị α-amino acid.<br>• Để tạo phức biuret tím cần tối thiểu 2 liên kết peptide kề nhau (từ tripeptide trở lên) tương tác với ion Cu<sup>2+</sup> trong môi trường kiềm.", "svgGraph": null}, {"q": "Cho 7,5 gam glycine (H<sub>2</sub>N–CH<sub>2</sub>–COOH) tác dụng vừa đủ với dung dịch NaOH. Khối lượng muối sodium glycinate thu được sau phản ứng là bao nhiêu (cho C=12, H=1, O=16, N=14, Na=23)?", "opts": ["9,7 gam", "8,5 gam", "11,1 gam", "10,2 gam"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>H<sub>2</sub>N–CH<sub>2</sub>–COOH + NaOH → H<sub>2</sub>N–CH<sub>2</sub>–COONa + H<sub>2</sub>O<br>• <b>Tính toán:</b><br>n(Gly) = 7,5 / 75 = 0,1 mol.<br>M(muối) = 75 - 1 + 23 = 97 g/mol.<br>Khối lượng muối = 0,1 · 97 = 9,7 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Thuỷ phân hoàn toàn 1 mol tripeptide Ala–Gly–Val bằng dung dịch HCl dư, thu được số mol amino acid là:", "opts": ["1 mol Ala, 1 mol Gly và 1 mol Val", "2 mol Ala và 1 mol Gly", "3 mol Gly", "1 mol dipeptide và 1 mol amino acid"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Tripeptide Ala–Gly–Val gồm 3 gốc α-amino acid khác nhau liên kết qua 2 liên kết peptide.<br>• Khi thuỷ phân hoàn toàn, cả 2 liên kết peptide bị bẻ gãy giải phóng đúng 1 mol Alanine, 1 mol Glycine và 1 mol Valine.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về điểm đẳng điện (pI) và sự di chuyển của amino acid trong điện trường:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Điểm đẳng điện (pI) là giá trị pH mà tại đó nồng độ ion lưỡng cực của amino acid đạt cực đại và tổng điện tích bằng 0.", "Tại pH = pI, nếu đặt amino acid trong một điện trường, amino acid sẽ không di chuyển về bất kì điện cực nào.", "Khi pH < pI (môi trường acid), amino acid tồn tại chủ yếu ở dạng cation mang điện tích dương và di chuyển về cực âm (cathode).", "Tất cả các amino acid thiên nhiên đều có điểm đẳng điện pI hoàn toàn bằng nhau và bằng 7,00."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Định nghĩa chuẩn về điểm đẳng điện pI.<br>• <b>Ý b [Đúng]:</b> Tại pI, phân tử trung hoà điện nên không di chuyển trong điện trường (ứng dụng trong điện di tách protein).<br>• <b>Ý c [Đúng]:</b> pH < pI, nhóm –COO<sup>-</sup> nhận proton thành –COOH, ion mang điện + di chuyển về cực âm.<br>• <b>Ý d [Sai]:</b> Mỗi amino acid có pI riêng biệt tuỳ thuộc cấu trúc gốc R (ví dụ pI của glycine = 5,97; glutamic acid = 3,22; lysine = 9,74).", "svgGraph": null}, {"q": "Số đồng phân tripeptide tối đa được tạo thành từ hỗn hợp gồm 2 α-amino acid là Glycine và Alanine (chứa cả 2 gốc amino acid này trong phân tử) là:", "opts": ["6 tripeptide", "4 tripeptide", "8 tripeptide", "2 tripeptide"], "ans": 0, "exp": "• <b>Phân tích tổ hợp:</b><br>Tripeptide chứa cả Gly và Ala gồm 2 trường hợp:<br>1. Có 2 gốc Gly và 1 gốc Ala: Gly–Gly–Ala, Gly–Ala–Gly, Ala–Gly–Gly (3 chất).<br>2. Có 1 gốc Gly và 2 gốc Ala: Ala–Ala–Gly, Ala–Gly–Ala, Gly–Ala–Ala (3 chất).<br>Tổng cộng có 3 + 3 = 6 đồng phân tripeptide.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "10": [{"q": "Protein là những hợp chất cao phân tử (polypeptide) được tạo thành từ chuỗi dài của các đơn vị nào sau đây?", "opts": ["Các gốc α-amino acid liên kết với nhau bằng liên kết peptide", "Các phân tử monosaccharide liên kết bằng liên kết glycoside", "Các gốc acid béo liên kết với glycerol", "Các nucleotide liên kết bằng liên kết phosphodiester"], "ans": 0, "exp": "• <b>Định nghĩa protein:</b> Protein là những polypeptide cao phân tử có khối lượng phân tử từ vài chục nghìn đến hàng triệu amu, được cấu tạo từ chuỗi dài gồm hàng chục đến hàng nghìn gốc α-amino acid liên kết bởi liên kết peptide.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"28\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14.5\" font-weight=\"800\">4 BẬC CẤU TRÚC KHÔNG GIAN CỦA PROTEIN</text>\n  <!-- 4 Level Boxes -->\n  <!-- Level 1 -->\n  <g transform=\"translate(20, 50)\">\n    <rect width=\"110\" height=\"110\" rx=\"8\" fill=\"rgba(14,165,233,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n    <text x=\"55\" y=\"22\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"11.5\" font-weight=\"bold\">BẬC 1</text>\n    <line x1=\"15\" y1=\"55\" x2=\"95\" y2=\"55\" stroke=\"#38bdf8\" stroke-width=\"3\"/>\n    <circle cx=\"25\" cy=\"55\" r=\"5\" fill=\"#f43f5e\"/><circle cx=\"45\" cy=\"55\" r=\"5\" fill=\"#fbbf24\"/><circle cx=\"65\" cy=\"55\" r=\"5\" fill=\"#34d399\"/><circle cx=\"85\" cy=\"55\" r=\"5\" fill=\"#818cf8\"/>\n    <text x=\"55\" y=\"85\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"9.5\">Trình tự chuỗi</text>\n    <text x=\"55\" y=\"98\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"9.5\">Polypeptide</text>\n  </g>\n  <!-- Level 2 -->\n  <g transform=\"translate(145, 50)\">\n    <rect width=\"110\" height=\"110\" rx=\"8\" fill=\"rgba(52,211,153,0.12)\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"55\" y=\"22\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"11.5\" font-weight=\"bold\">BẬC 2</text>\n    <path d=\"M 25 65 Q 40 40 55 65 T 85 65\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2.5\"/>\n    <text x=\"55\" y=\"85\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"9.5\">Xoắn α hoặc</text>\n    <text x=\"55\" y=\"98\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"9.5\">Phiến gấp nếp β</text>\n  </g>\n  <!-- Level 3 -->\n  <g transform=\"translate(270, 50)\">\n    <rect width=\"110\" height=\"110\" rx=\"8\" fill=\"rgba(251,191,36,0.12)\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n    <text x=\"55\" y=\"22\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11.5\" font-weight=\"bold\">BẬC 3</text>\n    <path d=\"M 25 70 C 25 35, 85 35, 85 65 C 85 85, 40 85, 55 50\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n    <text x=\"55\" y=\"85\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"9.5\">Cuộn nếp 3D</text>\n    <text x=\"55\" y=\"98\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"9.5\">Cầu disulfide -S-S-</text>\n  </g>\n  <!-- Level 4 -->\n  <g transform=\"translate(395, 50)\">\n    <rect width=\"105\" height=\"110\" rx=\"8\" fill=\"rgba(244,63,94,0.12)\" stroke=\"#f43f5e\" stroke-width=\"1.5\"/>\n    <text x=\"52\" y=\"22\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"11.5\" font-weight=\"bold\">BẬC 4</text>\n    <circle cx=\"40\" cy=\"55\" r=\"14\" fill=\"#0284c7\" opacity=\"0.6\"/>\n    <circle cx=\"65\" cy=\"55\" r=\"14\" fill=\"#f43f5e\" opacity=\"0.6\"/>\n    <text x=\"52\" y=\"85\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"9.5\">Phức hợp nhiều</text>\n    <text x=\"52\" y=\"98\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"9.5\">Chuỗi tiểu đơn vị</text>\n  </g>\n  <!-- Summary Box -->\n  <rect x=\"20\" y=\"170\" width=\"480\" height=\"48\" rx=\"6\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.1)\"/>\n  <text x=\"260\" y=\"190\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11\">Phản ứng màu đặc trưng: <tspan fill=\"#a855f7\" font-weight=\"bold\">Biuret</tspan> (màu tím với Cu(OH)₂) • <tspan fill=\"#fbbf24\" font-weight=\"bold\">Xanthoproteic</tspan> (vàng với HNO₃ đ)</text>\n  <text x=\"260\" y=\"206\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"10.5\">Sự đông tụ do nhiệt, acid, base hoặc ion kim loại nặng làm mất cấu trúc không gian</text>\n</svg>"}, {"q": "Hiện tượng lòng trắng trứng (albumin) bị đông cứng lại khi luộc trong nước sôi là do hiện tượng hoá sinh nào sau đây?", "opts": ["Sự đông tụ protein dưới tác dụng của nhiệt độ cao làm phá vỡ các cấu trúc không gian bậc cao.", "Protein bị thuỷ phân hoàn toàn thành các amino acid đơn lẻ.", "Lòng trắng trứng phản ứng với oxygen trong không khí tạo thành chất dẻo.", "Sự kết tinh của đường glucose có trong trứng."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Dưới tác dụng của nhiệt độ, acid, kiềm hoặc muối của kim loại nặng, các liên kết hydrogen và cầu nối yếu duy trì cấu trúc bậc 2, 3, 4 của protein bị phá vỡ.<br>• Chuỗi polypeptide duỗi thẳng ra và liên kết chéo lộn xộn với nhau tạo thành mạng lưới không tan gọi là sự đông tụ protein.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nhỏ dung dịch HNO<sub>3</sub> đặc vào dung dịch lòng trắng trứng, xuất hiện kết tủa màu vàng. Hiện tượng này được gọi là phản ứng gì?", "opts": ["Phản ứng xanthoproteic (nitro hoá các vòng thơm của amino acid)", "Phản ứng màu biuret", "Phản ứng tráng gương của protein", "Phản ứng thuỷ phân kiềm"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Protein chứa các amino acid có nhân thơm benzene (như tyrosine, phenylalanine).<br>• Khi gặp HNO<sub>3</sub> đặc, nhân thơm bị nitro hoá tạo thành dẫn xuất nitro có màu vàng tươi đặc trưng (phản ứng xanthoproteic).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về bản chất và tính chất xúc tác của enzyme trong hệ thống sống:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Enzyme hầu hết có bản chất là protein có hoạt tính xúc tác sinh học.", "Tốc độ phản ứng do enzyme xúc tác thường lớn hơn hàng triệu lần so với xúc tác hoá học vô cơ ở cùng điều kiện thân nhiệt.", "Enzyme có tính chọn lọc cực kì cao, mỗi enzyme thường chỉ xúc tác cho một phản ứng hoặc một loại cơ chất xác định.", "Enzyme có thể hoạt động bền vững ở nhiệt độ rất cao trên 150°C mà không hề bị mất hoạt tính xúc tác."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Bản chất hầu hết các enzyme là protein cấu trúc bậc 3 hoàn chỉnh.<br>• <b>Ý b [Đúng]:</b> Hiệu quả xúc tác sinh học cực kì mạnh mẽ.<br>• <b>Ý c [Đúng]:</b> Thuyết 'ổ khoá và chìa khoá' thể hiện tính đặc hiệu cao của enzyme.<br>• <b>Ý d [Sai]:</b> Bản chất là protein nên ở nhiệt độ cao (> 60 - 70°C), enzyme bị biến tính và mất hoàn toàn hoạt tính xúc tác.", "svgGraph": null}, {"q": "Ghép từng loại protein (Cột A) với vị trí và chức năng sinh học chủ yếu trong cơ thể (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Hemoglobin ➔ Vận chuyển oxygen trong máu từ phổi đến các mô tế bào", "Hemoglobin ➔ Hormone tuyến tuỵ điều hoà chuyển hoá glucose máu", "Hemoglobin ➔ Cấu tạo nên tóc, móng tay, sừng, lông vũ", "Hemoglobin ➔ Protein sợi chính trong da, gân, sụn và xương"], "ans": 0, "exp": "• <b>1 - A:</b> Hemoglobin chứa ion Fe<sup>2+</sup> vận chuyển O<sub>2</sub>.<br>• <b>2 - B:</b> Insulin điều hòa đường huyết.<br>• <b>3 - C:</b> Keratin là protein dạng sợi ở tóc, móng.<br>• <b>4 - D:</b> Collagen tạo độ đàn hồi, liên kết mô da và xương.", "svgGraph": null}, {"q": "Hoàn thành các đặc tính của cấu trúc không gian protein:<br><i>\"Cấu trúc  [ ... ]  của protein là trình tự sắp xếp các gốc α-amino acid trong chuỗi polypeptide. Cấu trúc  [ ... ]  là dạng cuộn nếp không gian ba chiều đặc thù. Khi cấu trúc không gian bị phá vỡ, protein bị  [ ... ]  và  [ ... ]  hoạt tính sinh học ban đầu.\"</i>", "opts": ["bậc 1 — bậc 3 — biến tính — mất", "mất — biến tính — bậc 3 — bậc 1", "bậc 3 — bậc 2 — biến tính — mất", "bậc 2 — biến tính — mất — tăng"], "ans": 0, "exp": "• Cấu trúc bậc 1 quyết định toàn bộ các bậc cấu trúc cao hơn.<br>• Cấu trúc bậc 3 tạo trung tâm hoạt động của phân tử.<br>• Biến tính làm thay đổi hình thể 3D dẫn đến mất chức năng sinh học.", "svgGraph": null}, {"q": "Khi nấu canh cua đồng, hiện tượng gạch cua nổi lên thành từng mảng đóng váng trên mặt nước canh sôi là do:", "opts": ["Protein trong thịt cua bị đông tụ do nhiệt độ cao nổi lên trên.", "Chất béo trong cua bị xà phòng hoá tạo bọt.", "Vỏ cua bị hoà tan trong nước sôi giải phóng canxi.", "Muối ăn NaCl phản ứng với gạch cua sinh kết tủa."], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Thịt cua chứa lượng lớn protein hoà tan dạng keo trong nước lạnh.<br>• Khi đun nóng đến sôi, nhiệt độ làm các phân tử protein bị đông tụ và kết dính lại với nhau thành mảng váng đặc, nhẹ hơn nước nên nổi lên mặt nồi canh.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho dung dịch lòng trắng trứng tác dụng với Cu(OH)<sub>2</sub> trong môi trường kiềm (dung dịch NaOH), xuất hiện dung dịch có màu gì?", "opts": ["Màu tím đặc trưng (phản ứng màu biuret)", "Màu xanh lam nhạt", "Màu đỏ gạch", "Màu vàng tươi"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Lòng trắng trứng chứa phân tử protein (albumin) có hàng trăm liên kết peptide kề nhau.<br>• Trong môi trường kiềm, các nguyên tử N của liên kết peptide tạo phức chelate phối trí với ion Cu<sup>2+</sup> cho màu tím thẫm đặc trưng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về vai trò dinh dưỡng và ứng dụng công nghệ của protein và enzyme:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Protein là nguồn cung cấp các amino acid thiết yếu mà cơ thể người không thể tự tổng hợp được (như valine, leucine, lysine).", "Enzyme papain chiết xuất từ quả đu đủ xanh có khả năng thuỷ phân protein, được dùng làm chất làm mềm thịt trong nấu ăn.", "Các loại bột giặt sinh học hiện đại thường bổ sung enzyme protease và amylase để tăng hiệu quả giặt tẩy vết bẩn thức ăn.", "Có thể đun sôi nước có pha sữa tươi ở nhiệt độ trên 100°C liên tục hàng giờ mà hàm lượng kháng thể và protein không hề bị biến tính."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Cơ thể cần 8 - 9 amino acid thiết yếu từ thức ăn.<br>• <b>Ý b [Đúng]:</b> Papain cắt liên kết peptide làm mềm sợi cơ thịt.<br>• <b>Ý c [Đúng]:</b> Bột giặt sinh học dùng enzyme để tẩy protein và tinh bột ở nhiệt độ thường.<br>• <b>Ý d [Sai]:</b> Đun sôi kéo dài phá huỷ hoàn toàn cấu trúc protein và kháng thể sinh học trong sữa.", "svgGraph": null}, {"q": "Phát biểu nào sau đây là SAI khi nói về cấu trúc và tính chất của protein?", "opts": ["Tất cả các protein đều tan tốt trong nước tạo thành dung dịch trong suốt không bao giờ bị đông tụ.", "Protein dạng sợi như keratin (ở tóc, móng), fibroin (ở tơ tằm) hoàn toàn không tan trong nước.", "Protein dạng hình cầu như hemoglobin, albumin tan được trong nước tạo thành dung dịch keo.", "Thuỷ phân hoàn toàn protein đơn giản thu được hỗn hợp các α-amino acid."], "ans": 0, "exp": "• <b>Phân tích:</b><br>- Protein dạng sợi (như tóc, móng, tơ tằm) không tan trong nước.<br>- Protein dạng cầu tan tạo dung dịch keo và rất dễ bị đông tụ bởi nhiệt, acid, base.<br>- Nhận định 'Tất cả các protein đều tan tốt... không bao giờ bị đông tụ' là SAI.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "11": [{"q": "Cho các chất sau: (1) C<sub>2</sub>H<sub>5</sub>NH<sub>2</sub>, (2) NH<sub>3</sub>, (3) C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub>, (4) (CH<sub>3</sub>)<sub>2</sub>NH. Thứ tự tăng dần tính base của các chất là:", "opts": ["(3) < (2) < (1) < (4)", "(3) < (1) < (2) < (4)", "(2) < (3) < (1) < (4)", "(4) < (1) < (2) < (3)"], "ans": 0, "exp": "• <b>Thứ tự lực base tăng dần:</b><br>Aniline (3) < Amoniac (2) < Ethylamine (1) < Dimethylamine (4).<br>• Gốc thơm hút e làm giảm tính base; gốc ankyl đẩy e làm tăng tính base; amine bậc 2 béo có tính base mạnh nhất.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho 0,1 mol glycine tác dụng với 150 mL dung dịch HCl 1M. Sau khi phản ứng hoàn toàn, số mol NaOH cần dùng để phản ứng hết với các chất trong dung dịch thu được là:", "opts": ["0,25 mol", "0,15 mol", "0,20 mol", "0,10 mol"], "ans": 0, "exp": "• <b>Phương pháp quy đổi tương đương:</b><br>Dung dịch sau phản ứng gồm muối ClH<sub>3</sub>N–CH<sub>2</sub>–COOH và HCl dư.<br>Khi tác dụng với NaOH, NaOH phản ứng với:<br>- Nhóm –COOH của glycine: n = 0,1 mol.<br>- Toàn bộ lượng HCl ban đầu: n(HCl) = 0,15 · 1 = 0,15 mol.<br>Tổng số mol NaOH cần dùng = 0,1 + 0,15 = 0,25 mol.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Peptide nào sau đây KHÔNG tham gia phản ứng màu biuret?", "opts": ["Gly–Ala", "Gly–Ala–Val", "Ala–Gly–Ala", "Ala–Gly–Val–Phe"], "ans": 0, "exp": "• <b>Quy tắc biuret:</b> Chỉ các peptide có từ <b>2 liên kết peptide trở lên</b> (tức từ tripeptide trở lên) mới tạo phức tím biuret với Cu(OH)<sub>2</sub>.<br>• Gly–Ala là dipeptide chỉ có 1 liên kết peptide nên không phản ứng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính Đúng/Sai của các phát biểu về hợp chất chứa nitrogen:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Aniline phản ứng với dung dịch HCl sinh ra muối phenylammonium chloride tan trong nước.", "Dung dịch lysine làm phenolphthalein chuyển sang màu hồng vì phân tử có 2 nhóm amino và 1 nhóm carboxyl.", "Protein đơn giản khi bị thuỷ phân hoàn toàn chỉ sinh ra hỗn hợp các α-amino acid.", "Tất cả các amine đều có tính base mạnh hơn amoniac."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub> + HCl → C<sub>6</sub>H<sub>5</sub>NH<sub>3</sub>Cl.<br>• <b>Ý b [Đúng]:</b> Lysine có tính base trội hơn acid nên làm hồng phenolphthalein.<br>• <b>Ý c [Đúng]:</b> Định nghĩa protein đơn giản chuẩn SGK.<br>• <b>Ý d [Sai]:</b> Các amine thơm như aniline có tính base yếu hơn nhiều so với NH<sub>3</sub>.", "svgGraph": null}, {"q": "Ghép từng thuốc thử (Cột A) với hiện tượng hoá học tương ứng khi phân biệt các chất chứa nitrogen (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Aniline + Nước bromine ➔ Xuất hiện kết tủa trắng 2,4,6-tribromoaniline", "Aniline + Nước bromine ➔ Dung dịch chuyển sang màu tím đặc trưng (phản ứng biuret)", "Aniline + Nước bromine ➔ Xuất hiện kết tủa màu vàng (phản ứng xanthoproteic)", "Aniline + Nước bromine ➔ Quỳ tím giữ nguyên màu tím, không chuyển màu"], "ans": 0, "exp": "• <b>1 - A:</b> Aniline tạo kết tủa trắng với Br<sub>2</sub>.<br>• <b>2 - B:</b> Protein phản ứng biuret cho màu tím.<br>• <b>3 - C:</b> Phản ứng xanthoproteic tạo màu vàng.<br>• <b>4 - D:</b> Glycine có pH gần trung tính không đổi màu quỳ.", "svgGraph": null}, {"q": "Hoàn thiện các nội dung cốt lõi của Chương 3:<br><i>\"Amine là dẫn xuất khi thay thế nguyên tử H trong NH₃ bằng gốc  [ ... ] . Amino acid là hợp chất  [ ... ]  vừa có tính acid vừa có tính base. Peptide và protein bị  [ ... ]  trong môi trường acid hoặc base dưới tác dụng của nhiệt độ hoặc  [ ... ] .\"</i>", "opts": ["hydrocarbon — lưỡng tính — thuỷ phân — enzyme", "enzyme — thuỷ phân — lưỡng tính — hydrocarbon", "lưỡng tính — thuỷ phân — enzyme — ester", "thuỷ phân — enzyme — ester — trùng hợp"], "ans": 0, "exp": "• Định nghĩa amine: thay H trong NH<sub>3</sub> bằng gốc hydrocarbon.<br>• Amino acid mang tính lưỡng tính.<br>• Peptide bị thuỷ phân cắt liên kết –CO–NH– nhờ enzyme hoặc acid/kiềm.", "svgGraph": null}, {"q": "Đốt cháy hoàn toàn một lượng peptide X mạch hở tạo bởi amino acid no đơn chức (chứa 1 nhóm –NH<sub>2</sub> và 1 nhóm –COOH). Tỉ lệ mol giữa CO<sub>2</sub> và H<sub>2</sub>O sinh ra luôn có đặc điểm gì?", "opts": ["Số mol CO<sub>2</sub> nhỏ hơn số mol H<sub>2</sub>O", "Số mol CO<sub>2</sub> bằng số mol H<sub>2</sub>O", "Số mol CO<sub>2</sub> lớn hơn số mol H<sub>2</sub>O", "Không xác định được tỉ lệ"], "ans": 0, "exp": "• <b>Bản chất hóa học:</b> Phân tử peptide tạo từ n amino acid no đơn chức hở có CTPT C<sub>x</sub>H<sub>y</sub>O<sub>z</sub>N<sub>n</sub> với y = 2x + 2 - n (nếu n amino acid nối lại thì bớt đi (n-1) phân tử H<sub>2</sub>O).<br>• Do đó y > 2x đối với chuỗi peptide nhỏ, hay khi đốt cháy n(H<sub>2</sub>O) > n(CO<sub>2</sub>).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Một tetrapeptide mạch hở có cấu tạo Gly–Ala–Val–Gly. Khi thuỷ phân không hoàn toàn peptide này có thể thu được tối đa bao nhiêu loại dipeptide khác nhau?", "opts": ["3 dipeptide (Gly–Ala, Ala–Val, Val–Gly)", "2 dipeptide", "4 dipeptide", "1 dipeptide"], "ans": 0, "exp": "• <b>Phân tích mạch:</b> Chuỗi gồm: Gly(1) – Ala(2) – Val(3) – Gly(4).<br>Các dipeptide cắt ra gồm:<br>1. Gly–Ala (vị trí 1-2)<br>2. Ala–Val (vị trí 2-3)<br>3. Val–Gly (vị trí 3-4)<br>Cả 3 dipeptide này đều phân biệt và khác nhau.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về độ bền và bảo quản các hợp chất sinh học chứa nitrogen:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Thịt cá tươi được ướp muối ăn để hút nước và làm ức chế sự phát triển của vi khuẩn phân huỷ protein.", "Enzyme trong cơ thể người hoạt động tối ưu ở khoảng nhiệt độ 36,5°C - 37,5°C và pH sinh lí thích hợp.", "Để phân biệt bột ngọt thật (monosodium glutamate) và hàn the độc hại có thể dùng quỳ tím thử dung dịch.", "Phơi nắng quần áo lụa tơ tằm nguyên chất dưới ánh nắng gay gắt mùa hè giúp tơ bền hơn và tăng tuổi thọ."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Muối tạo áp suất thẩm thấu cao tiêu diệt vi khuẩn.<br>• <b>Ý b [Đúng]:</b> Thân nhiệt bình thường là khoảng tối ưu của enzyme người.<br>• <b>Ý c [Đúng]:</b> Dung dịch hàn the (borax) có tính kiềm mạnh làm xanh quỳ tím.<br>• <b>Ý d [Sai]:</b> Tơ tằm là protein (fibroin) rất nhạy cảm với nhiệt và tia UV, phơi nắng gắt làm đứt gãy liên kết peptide khiến lụa nhanh giòn, ố vàng và mục nát.", "svgGraph": null}, {"q": "Khối lượng mol phân tử của tripeptide Gly–Ala–Gly là bao nhiêu (biết Gly = 75, Ala = 89, H<sub>2</sub>O = 18)?", "opts": ["203 g/mol", "239 g/mol", "221 g/mol", "185 g/mol"], "ans": 0, "exp": "• <b>Công thức tính:</b><br>Tripeptide được tạo bởi 2 phân tử Gly và 1 phân tử Ala, tách ra 2 phân tử H<sub>2</sub>O.<br>M = 2 · M(Gly) + M(Ala) - 2 · M(H<sub>2</sub>O)<br>M = 2 · 75 + 89 - 2 · 18 = 150 + 89 - 36 = 203 g/mol.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "12": [{"q": "Polymer nào sau đây được điều chế bằng phản ứng trùng hợp (addition polymerization)?", "opts": ["Polyethylene (PE, từ ethylene CH<sub>2</sub>=CH<sub>2</sub>)", "Nylon-6,6 (từ hexamethylenediamine và adipic acid)", "Poly(ethylene terephthalate) (tơ lapsan)", "Tơ tằm tự nhiên"], "ans": 0, "exp": "• <b>Bản chất hoá học:</b> Phản ứng trùng hợp là quá trình kết hợp nhiều phân tử nhỏ giống nhau hoặc tương tự nhau (monomer chứa liên kết bội C=C hoặc vòng kém bền) tạo thành polymer mà không giải phóng phân tử nhỏ khác.<br>• Ethylene n CH<sub>2</sub>=CH<sub>2</sub> ⎯(xt, p, t°)→ –(CH<sub>2</sub>–CH<sub>2</sub>)<sub>n</sub>–.<br>• Các polymer còn lại được điều chế bằng phản ứng trùng ngưng (tách giải phóng H<sub>2</sub>O).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"28\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">PHÂN BIỆT PHẢN ỨNG TRÙNG HỢP VÀ TRÙNG NGƯNG</text>\n  <!-- Addition Box -->\n  <g transform=\"translate(25, 48)\">\n    <rect width=\"225\" height=\"115\" rx=\"8\" fill=\"rgba(14,165,233,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n    <text x=\"112\" y=\"22\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">PHẢN ỨNG TRÙNG HỢP</text>\n    <text x=\"112\" y=\"50\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"12.5\" font-weight=\"bold\">n CH₂=CH–Cl</text>\n    <text x=\"112\" y=\"68\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Monomer có nối đôi C=C</text>\n    <path d=\"M 60 78 L 165 78 M 155 74 L 165 78\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <text x=\"112\" y=\"98\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"12.5\" font-weight=\"bold\">–(CH₂–CHCl)ₙ–</text>\n    <text x=\"112\" y=\"110\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"9.5\">Không giải phóng phân tử nhỏ</text>\n  </g>\n  <!-- Condensation Box -->\n  <g transform=\"translate(270, 48)\">\n    <rect width=\"225\" height=\"115\" rx=\"8\" fill=\"rgba(52,211,153,0.12)\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"112\" y=\"22\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">PHẢN ỨNG TRÙNG NGƯNG</text>\n    <text x=\"112\" y=\"48\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">n H₂N–(CH₂)₅–COOH</text>\n    <text x=\"112\" y=\"64\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">Có từ 2 nhóm chức phản ứng</text>\n    <path d=\"M 60 76 L 165 76 M 155 72 L 165 76\" stroke=\"#34d399\" stroke-width=\"2\"/>\n    <text x=\"112\" y=\"94\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"11.5\" font-weight=\"bold\">–(NH–(CH₂)₅–CO)ₙ–</text>\n    <text x=\"112\" y=\"108\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"10\" font-weight=\"bold\">+ n H₂O (tách phân tử nhỏ)</text>\n  </g>\n  <!-- Footnote -->\n  <rect x=\"25\" y=\"170\" width=\"470\" height=\"48\" rx=\"6\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.1)\"/>\n  <text x=\"260\" y=\"188\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11\">Cấu trúc mạch: Mạch không nhánh (PE, PVC) • Mạch phân nhánh (Amylopectin)</text>\n  <text x=\"260\" y=\"204\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"10.5\">Mạng không gian mạng lưới 3D: <tspan fill=\"#fbbf24\" font-weight=\"bold\">Cao su lưu hoá</tspan> (cầu -S-S-) và <tspan fill=\"#a7f3d0\" font-weight=\"bold\">Nhựa Bakelite</tspan></text>\n</svg>"}, {"q": "Polymer nào sau đây có cấu trúc mạng không gian (mạng lưới ba chiều)?", "opts": ["Cao su lưu hoá (và nhựa rezit / bakelite)", "Polyethylene (PE)", "Poly(vinyl chloride) (PVC)", "Amylose trong tinh bột"], "ans": 0, "exp": "• <b>Phân loại cấu trúc mạch polymer:</b><br>- Mạch không phân nhánh: PE, PVC, cellulose, tơ nylon, amylose.<br>- Mạch phân nhánh: Amylopectin, glycogen.<br>- Mạng lưới không gian 3 chiều: Cao su lưu hoá (các mạch cao su nối nhau bằng cầu disulfide –S–S–) và nhựa rezit (nhựa bakelite).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Tên gọi theo danh pháp IUPAC của polymer có công thức cấu tạo –(CH<sub>2</sub>–CH(CH<sub>3</sub>))<sub>n</sub>– là gì?", "opts": ["Polypropylene (PP)", "Polyethylene (PE)", "Polystyrene (PS)", "Poly(vinyl alcohol) (PVA)"], "ans": 0, "exp": "• <b>Danh pháp:</b> Ghép tiền tố 'poly' với tên của monomer tạo nên nó.<br>• Monomer là propylene (propene, CH<sub>2</sub>=CH–CH<sub>3</sub>) → tên polymer là polypropylene (kí hiệu là PP).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về tính chất vật lí và hoá học chung của các polymer, xác định tính Đúng/Sai:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Hầu hết các polymer là những chất rắn, không bay hơi, không có nhiệt độ nóng chảy xác định mà nóng chảy trong một khoảng nhiệt độ khá rộng.", "Đa số polymer không tan trong nước và các dung môi thông thường, một số tan được trong dung môi hữu cơ thích hợp.", "Nhiều polymer có tính cách điện, cách nhiệt tốt, bền cơ học và có tính đàn hồi cao.", "Mọi polymer đều có thể bị đun nóng chảy rồi đúc thành các hình dạng khác nhau nhiều lần (đều là chất nhiệt dẻo)."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Do phân tử khối lớn và chuỗi polymer có độ dài ngắn khác nhau.<br>• <b>Ý b [Đúng]:</b> Tính chất hoà tan đặc thù của polymer.<br>• <b>Ý c [Đúng]:</b> Ứng dụng làm vỏ bọc dây điện, tay cầm xoong chảo.<br>• <b>Ý d [Sai]:</b> Chỉ có chất <b>nhiệt dẻo</b> (như PE, PP) mới nóng chảy khi đun; các chất <b>nhiệt rắn</b> (như rezit, cao su lưu hoá) khi đun nóng bị phân huỷ cháy khét chứ không nóng chảy.", "svgGraph": null}, {"q": "Ghép từng polymer thông dụng (Cột A) với loại phản ứng điều chế tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Poly(vinyl chloride) (PVC) ➔ Trùng hợp vinyl chloride (CH₂=CH–Cl)", "Poly(vinyl chloride) (PVC) ➔ Trùng ngưng hexamethylenediamine với adipic acid", "Poly(vinyl chloride) (PVC) ➔ Trùng hợp methyl methacrylate", "Poly(vinyl chloride) (PVC) ➔ Trùng ngưng terephthalic acid với ethylene glycol"], "ans": 0, "exp": "• <b>1 - A:</b> PVC trùng hợp từ vinyl chloride.<br>• <b>2 - B:</b> Nylon-6,6 trùng ngưng từ 2 monomer 6 carbon.<br>• <b>3 - C:</b> Thuỷ tinh hữu cơ trùng hợp từ methyl methacrylate.<br>• <b>4 - D:</b> Tơ lapsan trùng ngưng từ terephthalic acid và glycol.", "svgGraph": null}, {"q": "Hoàn thiện định nghĩa về phản ứng trùng ngưng:<br><i>\"Trùng ngưng là quá trình kết hợp nhiều phân tử nhỏ ( [ ... ] ) có ít nhất  [ ... ]  nhóm chức có khả năng phản ứng, tạo thành phân tử lớn ( [ ... ] ) đồng thời giải phóng các phân tử nhỏ khác như  [ ... ] .\"</i>", "opts": ["monomer — hai — polymer — H₂O", "H₂O — polymer — hai — monomer", "hai — polymer — H₂O — CO₂", "polymer — H₂O — CO₂ — một"], "ans": 0, "exp": "• Khác biệt bản chất giữa trùng hợp và trùng ngưng là sự giải phóng các phân tử nhỏ (thường là nước) trong phản ứng trùng ngưng.", "svgGraph": null}, {"q": "Một đoạn mạch polymer của poly(vinyl chloride) có khối lượng phân tử trung bình là 250 000 amu. Hệ số polymer hoá (độ trùng hợp n) trung bình của đoạn mạch này là bao nhiêu (cho C=12, H=1, Cl=35,5)?", "opts": ["4 000", "3 500", "2 500", "5 000"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Mắt xích của PVC là –CH<sub>2</sub>–CHCl– có khối lượng mol: M = 14 + 13 + 35,5 = 62,5 amu.<br>Hệ số polymer hoá n = M<sub>polymer</sub> / M<sub>mắt xích</sub> = 250 000 / 62,5 = 4 000.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Polymer nào sau đây là polymer bán tổng hợp (polymer nhân tạo)?", "opts": ["Tơ visco (chế biến từ cellulose với CS<sub>2</sub> và NaOH)", "Cellulose tự nhiên trong cây xanh", "Polyethylene (PE)", "Nylon-6 (tơ capron)"], "ans": 0, "exp": "• <b>Phân loại nguồn gốc polymer:</b><br>- Thiên nhiên: tinh bột, cellulose, tơ tằm, cao su thiên nhiên.<br>- Tổng hợp: PE, PP, PVC, cao su buna, nylon-6,6.<br>- Bán tổng hợp (nhân tạo): Lấy polymer thiên nhiên biến đổi hoá học một phần (tơ visco, tơ acetate).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về sự phân huỷ và tác động môi trường của vật liệu polymer (rác thải nhựa):<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Nhựa thông thường như PE, PP rất khó bị phân huỷ sinh học trong môi trường tự nhiên, có thể tồn tại hàng trăm năm gây ô nhiễm 'rác thải trắng'.", "Hiện nay các nhà khoa học phát triển các loại nhựa sinh học tự huỷ (như PLA làm từ tinh bột ngô) có thể phân huỷ hoàn toàn thành CO₂ và H₂O nhờ vi sinh vật.", "Đốt rác thải nhựa PVC tự do ngoài trời giải phóng khí dioxin và HCl cực kì độc hại cho đường hô hấp của con người.", "Tái chế nhựa là giải pháp không mang lại lợi ích kinh tế nào và luôn làm ô nhiễm không khí nhiều hơn sản xuất nhựa mới."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Vấn đề ô nhiễm rác thải nhựa toàn cầu.<br>• <b>Ý b [Đúng]:</b> Nhựa sinh học PLA thân thiện môi trường.<br>• <b>Ý c [Đúng]:</b> Nhựa chứa clo (PVC) khi cháy tạo dioxin cực độc.<br>• <b>Ý d [Sai]:</b> Tái chế nhựa tiết kiệm tài nguyên dầu mỏ và giảm phát thải khí nhà kính đáng kể.", "svgGraph": null}, {"q": "Khi thuỷ phân hoàn toàn poly(vinyl acetate) (PVA) trong dung dịch kiềm đun nóng, thu được polymer nào sau đây?", "opts": ["Poly(vinyl alcohol)", "Polyethylene", "Polypropylene", "Poly(acrylic acid)"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>–(CH<sub>2</sub>–CH(OCOCH<sub>3</sub>))<sub>n</sub>– + n NaOH → –(CH<sub>2</sub>–CH(OH))<sub>n</sub>– (poly(vinyl alcohol)) + n CH<sub>3</sub>COONa.<br>• Do vinyl alcohol CH<sub>2</sub>=CH–OH không bền nên không thể trùng hợp trực tiếp, người ta phải thuỷ phân poly(vinyl acetate) để sản xuất poly(vinyl alcohol).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "13": [{"q": "Poly(methyl methacrylate) (PMM) là chất dẻo trong suốt, cho khoảng 90% ánh sáng truyền qua, có độ bền cơ học cao, được ứng dụng làm vật liệu gì?", "opts": ["Kính máy bay, kính bảo hộ, thuỷ tinh hữu cơ (plexiglas)", "Ống dẫn nước gia dụng thay thế ống sắt", "Lốp xe ô tô có độ đàn hồi cao", "Vải may áo ấm mùa đông thay thế len tự nhiên"], "ans": 0, "exp": "• <b>Ứng dụng của PMM:</b> Trùng hợp methyl methacrylate CH<sub>2</sub>=C(CH<sub>3</sub>)COOCH<sub>3</sub> thu được poly(methyl methacrylate) gọi là thuỷ tinh hữu cơ plexiglas.<br>• Chất dẻo này rất bền, không vỡ vụn nguy hiểm như thuỷ tinh vô cơ silicat, dùng làm kính chắn gió máy bay, đèn xe hơi, răng giả.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Tơ nào sau đây thuộc loại tơ tổng hợp (synthetic fiber)?", "opts": ["Tơ nylon-6,6", "Tơ tằm", "Tơ visco", "Tơ acetate"], "ans": 0, "exp": "• <b>Phân loại tơ:</b><br>- Tơ thiên nhiên: bông, len cừu, tơ tằm.<br>- Tơ bán tổng hợp (nhân tạo): tơ visco, tơ acetate.<br>- Tơ tổng hợp: tơ polyamide (nylon-6, nylon-6,6), tơ vinylic (nitron/olon), tơ polyester (lapsan).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Vật liệu nào sau đây được mệnh danh là 'vua chất dẻo', có hệ số ma sát rất nhỏ, chịu nhiệt độ cao và trơ với hầu hết các hoá chất acid, kiềm, thường dùng tráng chảo chống dính?", "opts": ["Teflon (poly(tetrafluoroethylene), –(CF<sub>2</sub>–CF<sub>2</sub>)<sub>n</sub>–)", "Polyethylene (PE)", "Poly(vinyl chloride) (PVC)", "Polystyrene (PS)"], "ans": 0, "exp": "• <b>Đặc tính của Teflon:</b> Poly(tetrafluoroethylene) chứa liên kết C–F cực kì bền vững, không cháy, chịu nhiệt lên tới 300°C, không bám dính dầu mỡ, trơ với cả nước cường toan.<br>• Dùng phủ chảo chống dính, ổ bi tự bôi trơn, thiết bị van dẫn hoá chất ăn mòn mạnh.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về quá trình lưu hoá cao su và tính chất của cao su lưu hoá:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Quá trình lưu hoá cao su là cho cao su thô tác dụng với lưu huỳnh (S) ở nhiệt độ thích hợp tạo thành các cầu nối disulfide –S–S– giữa các mạch polymer.", "Cao su lưu hoá có cấu trúc mạng lưới không gian 3 chiều nên có độ đàn hồi cao hơn, chịu mài mòn và lâu hỏng hơn cao su thô.", "Cao su buna-S được điều chế bằng phản ứng đồng trùng hợp giữa buta-1,3-diene và lưu huỳnh nguyên tố.", "Cao su thiên nhiên được lấy từ mủ cây cao su, có thành phần chính là polyisoprene dạng đồng phân cis."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Bản chất quá trình lưu hoá.<br>• <b>Ý b [Đúng]:</b> Cấu trúc mạng 3D giúp cao su phục hồi hình dạng nhanh chóng khi kéo giãn.<br>• <b>Ý c [Sai]:</b> Cao su buna-S là sản phẩm đồng trùng hợp giữa buta-1,3-diene và <b>styrene</b> C<sub>6</sub>H<sub>5</sub>CH=CH<sub>2</sub> (chữ S là viết tắt của Styrene, không phải lưu huỳnh).<br>• <b>Ý d [Đúng]:</b> Cao su thiên nhiên là cis-1,4-polyisoprene.", "svgGraph": null}, {"q": "Ghép từng loại tơ tổng hợp (Cột A) với đặc tính và ứng dụng chính (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Nylon-6,6 ➔ Sợi tơ bóng mịn, bền xé, dùng dệt vải may mặc, bít tất, dây dù, lưới đánh cá", "Nylon-6,6 ➔ Dai, bền, giữ nhiệt rất tốt, thường dùng dệt len đan áo ấm mùa đông", "Nylon-6,6 ➔ Rất bền cơ học và hoá học, dùng may quần áo chống nhăn, sợi lốp xe", "Nylon-6,6 ➔ Điều chế từ caprolactam, dùng dệt vải lót, chỉ may phẫu thuật y tế"], "ans": 0, "exp": "• <b>1 - B:</b> Nylon-6,6 bền dai, bóng mịn.<br>• <b>2 - A:</b> Tơ nitron từ acrylonitrile giữ nhiệt tốt may áo ấm.<br>• <b>3 - C:</b> Tơ lapsan chống nhăn may âu phục.<br>• <b>4 - D:</b> Tơ capron từ caprolactam.", "svgGraph": null}, {"q": "Hoàn thành phân loại vật liệu composite:<br><i>\"Vật liệu composite gồm hai thành phần cốt lõi: chất  [ ... ]  (như polymer tạo độ liên kết, dẻo dai) và chất  [ ... ]  (như sợi thuỷ tinh, sợi carbon tăng độ bền cơ học). Nhờ sự kết hợp này, composite có độ bền kéo và độ cứng  [ ... ]  hơn rất nhiều so với từng thành phần riêng rẽ, được ứng dụng làm vỏ tàu thuyền và  [ ... ] .\"</i>", "opts": ["nền — gia cường — cao — vỏ máy bay", "vỏ máy bay — cao — gia cường — nền", "gia cường — cao — vỏ máy bay — thấp", "cao — vỏ máy bay — thấp — dung môi"], "ans": 0, "exp": "• Composite là vật liệu tổ hợp giữa pha nền (matrix) và pha gia cường (reinforcement) tạo cơ tính vượt trội.", "svgGraph": null}, {"q": "Quần áo may bằng vải làm từ sợi tơ polyamide (như nylon-6, nylon-6,6) không nên giặt bằng xà phòng có độ kiềm cao hoặc trong nước quá nóng vì nguyên nhân nào sau đây?", "opts": ["Liên kết peptide –CO–NH– trong tơ dễ bị thuỷ phân trong môi trường kiềm và nhiệt độ cao làm sờn mục sợi vải.", "Tơ nylon phản ứng với kiềm tạo thành muối hoà tan trong nước.", "Nước nóng làm các nguyên tử carbon trong tơ biến thành kim cương cứng.", "Xà phòng làm tăng tính đàn hồi của sợi tơ khiến quần áo bị co rút quá mức."], "ans": 0, "exp": "• <b>Bản chất hoá học:</b> Các loại tơ polyamide chứa liên kết amide –CO–NH– kém bền với nhiệt và rất dễ bị thuỷ phân trong môi trường acid hoặc base.<br>• Vì vậy giặt bằng bột giặt tính kiềm mạnh hoặc dùng nước sôi sẽ làm đứt chuỗi polymer, sợi vải nhanh bị mủn và rách.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Keo dán epoxy là loại keo dán tổng hợp đóng rắn hai thành phần (nhựa epoxy và chất đóng rắn amine), có ưu điểm nổi bật là:", "opts": ["Kết dính cực kì chắc chắn trên kim loại, thuỷ tinh, gốm sứ và chịu nước, chịu nhiệt tốt.", "Dễ dàng hoà tan trong nước để bóc gỡ tái sử dụng.", "Làm mềm dẻo các thanh sắt để uốn hoa văn.", "Chỉ dính được các loại giấy viết mỏng."], "ans": 0, "exp": "• <b>Bản chất hoá học:</b> Khi trộn 2 thành phần, phản ứng giữa nhóm epoxide và nhóm amine tạo mạng lưới không gian bền chắc, liên kết chặt với bề mặt các vật liệu vô cơ và kim loại, chống chịu thời tiết khắc nghiệt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về cao su buna và các loại cao su tổng hợp thông dụng:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Cao su buna được điều chế bằng phản ứng trùng hợp buta-1,3-diene với xúc tác sodium (Na).", "Cao su buna-N có tính chống dầu mỡ cao nhờ chứa nhóm chức nitrile (–C≡N) phân cực.", "Cao su thiên nhiên không có khả năng tham gia phản ứng cộng với HCl hay bromine.", "Tất cả các loại cao su đều có tính đàn hồi: biến dạng khi chịu ngoại lực và tự trở lại hình dạng ban đầu khi thôi tác dụng lực."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Tên gọi Buna bắt nguồn từ <b>Bu</b>tadiene và <b>Na</b>trium.<br>• <b>Ý b [Đúng]:</b> Buna-N đồng trùng hợp từ butadiene và acrylonitrile chứa –C≡N chống dầu tốt dùng làm ống dẫn nhiên liệu.<br>• <b>Ý c [Sai]:</b> Cao su thiên nhiên còn nối đôi C=C nên tham gia phản ứng cộng bình thường.<br>• <b>Ý d [Đúng]:</b> Định nghĩa tính đàn hồi của cao su.", "svgGraph": null}, {"q": "Đồng trùng hợp 0,1 mol buta-1,3-diene và 0,1 mol styrene với hiệu suất 80% thu được m gam cao su buna-S. Giá trị của m là bao nhiêu (cho C=12, H=1)?", "opts": ["12,64 gam", "15,80 gam", "10,50 gam", "18,96 gam"], "ans": 0, "exp": "• <b>Tính toán đại số:</b><br>Khối lượng monomer ban đầu:<br>m(butadiene) = 0,1 · 54 = 5,4 gam.<br>m(styrene) = 0,1 · 104 = 10,4 gam.<br>Tổng khối lượng monomer = 5,4 + 10,4 = 15,8 gam.<br>Do hiệu suất phản ứng H = 80%, khối lượng cao su thu được = 15,8 · 0,8 = 12,64 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "14": [{"q": "Polymer nào sau đây chứa nguyên tố nitrogen trong phân tử?", "opts": ["Tơ nylon-6,6", "Polyethylene (PE)", "Poly(vinyl chloride) (PVC)", "Poly(methyl methacrylate)"], "ans": 0, "exp": "• <b>Bản chất hoá học:</b> Nylon-6,6 là polyamide –(NH–(CH<sub>2</sub>)<sub>6</sub>–NH–CO–(CH<sub>2</sub>)<sub>4</sub>–CO)<sub>n</sub>– chứa các nguyên tố C, H, O, N.<br>• PE chỉ chứa C, H; PVC chứa C, H, Cl; PMM chứa C, H, O.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho các polymer sau: (1) tơ tằm, (2) tơ visco, (3) tơ nitron, (4) tơ lapsan, (5) tơ acetate. Dãy gồm các polymer có nguồn gốc thiên nhiên và bán tổng hợp là:", "opts": ["(1), (2), (5)", "(2), (3), (4)", "(1), (3), (4)", "(3), (4)"], "ans": 0, "exp": "• <b>Phân loại:</b><br>- Thiên nhiên: (1) tơ tằm.<br>- Bán tổng hợp (nhân tạo chế từ cellulose): (2) tơ visco, (5) tơ acetate.<br>- Tổng hợp hoàn toàn: (3) tơ nitron, (4) tơ lapsan.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Mắt xích cấu tạo của poly(vinyl chloride) (PVC) là:", "opts": ["–CH<sub>2</sub>–CHCl–", "–CH<sub>2</sub>–CH<sub>2</sub>–", "–CF<sub>2</sub>–CF<sub>2</sub>–", "–CH<sub>2</sub>–CH(CH<sub>3</sub>)–"], "ans": 0, "exp": "• Trùng hợp vinyl chloride CH<sub>2</sub>=CH–Cl thu được PVC có mắt xích lặp lại là –CH<sub>2</sub>–CHCl–.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các mệnh đề về phương pháp điều chế và cấu trúc polymer:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Phản ứng điều chế cao su buna-S và cao su buna-N thuộc loại phản ứng đồng trùng hợp.", "Các polymer tổng hợp bằng phản ứng trùng ngưng luôn chứa các dị nguyên tử (như N hoặc O) trong mạch chính của polymer.", "Cao su tự nhiên khi chưa lưu hoá có độ dẻo cao và dễ bị dính nhơm nhếch khi trời nóng bức.", "Tất cả các loại tơ sợi thiên nhiên đều không bị thuỷ phân trong môi trường acid đun nóng."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Đồng trùng hợp từ 2 monomer khác nhau.<br>• <b>Ý b [Đúng]:</b> Trùng ngưng tạo liên kết ester hoặc amide chứa O hoặc N trong chuỗi mạch.<br>• <b>Ý c [Đúng]:</b> Cao su thô biến tính mạnh theo nhiệt độ nên cần lưu hoá.<br>• <b>Ý d [Sai]:</b> Cả bông (cellulose) và tơ tằm (protein) đều bị thuỷ phân mạnh trong acid nóng.", "svgGraph": null}, {"q": "Ghép từng polymer (Cột A) với ứng dụng thực tế tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Poly(vinyl chloride) (PVC) ➔ Làm ống dẫn nước, áo mưa, màng bọc cách điện dây cáp", "Poly(vinyl chloride) (PVC) ➔ Tráng chảo chống dính, băng tan quấn ống nước chịu nhiệt", "Poly(vinyl chloride) (PVC) ➔ Dệt sợi len nhân tạo may áo ấm, chăn bông mùa đông", "Poly(vinyl chloride) (PVC) ➔ Chế tạo gioăng đệm máy, ống dẫn dầu mỡ nhiên liệu"], "ans": 0, "exp": "• <b>1 - A:</b> PVC làm ống nhựa dân dụng.<br>• <b>2 - B:</b> Teflon chống dính chịu nhiệt.<br>• <b>3 - C:</b> Tơ nitron giữ ấm dệt len.<br>• <b>4 - D:</b> Buna-N chống dầu làm đệm gioăng.", "svgGraph": null}, {"q": "Hoàn thiện nội dung kiến thức tổng kết Chương 4:<br><i>\"Polymer là hợp chất có  [ ... ]  phân tử rất lớn do nhiều mắt xích liên kết với nhau. Vật liệu polymer gồm chất dẻo, tơ sợi,  [ ... ]  và keo dán. Sự lưu hoá biến cao su từ mạch thẳng thành cấu trúc  [ ... ]  đàn hồi cao. Nylon-6,6 là sản phẩm của phản ứng  [ ... ] .\"</i>", "opts": ["khối lượng — cao su — mạng không gian — trùng ngưng", "trùng ngưng — mạng không gian — cao su — khối lượng", "cao su — mạng không gian — trùng ngưng — trùng hợp", "mạng không gian — trùng ngưng — trùng hợp — phân nhánh"], "ans": 0, "exp": "• Khái niệm polymer, phân loại vật liệu, cấu trúc mạng lưu hoá và phản ứng trùng ngưng nylon-6,6.", "svgGraph": null}, {"q": "Đun nóng hỗn hợp gồm adipic acid (HOOC–(CH<sub>2</sub>)<sub>4</sub>–COOH) và hexamethylenediamine (H<sub>2</sub>N–(CH<sub>2</sub>)<sub>6</sub>–NH<sub>2</sub>) thu được tơ nylon-6,6. Đây là loại phản ứng hoá học nào?", "opts": ["Trùng ngưng", "Trùng hợp", "Xà phòng hoá", "Thuỷ phân"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>n HOOC–(CH<sub>2</sub>)<sub>4</sub>–COOH + n H<sub>2</sub>N–(CH<sub>2</sub>)<sub>6</sub>–NH<sub>2</sub> ⎯(t°)→ –(CO–(CH<sub>2</sub>)<sub>4</sub>–CO–NH–(CH<sub>2</sub>)<sub>6</sub>–NH)<sub>n</sub>– + 2n H<sub>2</sub>O.<br>• Phản ứng giải phóng các phân tử nước nên thuộc loại phản ứng trùng ngưng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Polymer nào sau đây khi đốt cháy hoàn toàn KHÔNG sinh ra khí độc hại đối với hệ hô hấp mà chỉ sinh ra CO<sub>2</sub> và H<sub>2</sub>O?", "opts": ["Polyethylene (PE)", "Poly(vinyl chloride) (PVC)", "Tơ nitron", "Tơ tằm"], "ans": 0, "exp": "• <b>Bản chất hoá học:</b> PE chỉ cấu tạo từ carbon và hydrogen (–CH<sub>2</sub>–CH<sub>2</sub>–)<sub>n</sub>, khi đốt cháy hoàn toàn chỉ tạo khí CO<sub>2</sub> và hơi nước.<br>• PVC sinh khí độc HCl; tơ nitron sinh khí độc HCN; tơ tằm sinh các khí độc chứa lưu huỳnh và nitrogen.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về quy trình thu gom, phân loại và tái chế chất dẻo:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Kí hiệu số 1 (PETE) trên đáy chai nước ngọt chỉ ra chai được làm từ poly(ethylene terephthalate) có thể tái chế thành sợi dệt may.", "Nhựa nhiệt rắn sau khi bị nung hỏng có thể dễ dàng đun nấu lại để đúc thành sản phẩm mới nguyên vẹn.", "Tái chế hoá học là phương pháp nhiệt phân hoặc bẻ gãy mạch polymer để thu hồi lại các monomer tinh khiết.", "Hạn chế sử dụng đồ nhựa dùng một lần và thay bằng vật liệu thân thiện môi trường là giải pháp bền vững bảo vệ Trái Đất."], "ans": 1, "exp": "• <b>Ý a [Đúng]:</b> Nhãn tái chế số 1 chuẩn quốc tế cho nhựa PET.<br>• <b>Ý b [Sai]:</b> Nhựa nhiệt rắn có mạng 3D không thể nóng chảy tái sinh hình dạng.<br>• <b>Ý c [Đúng]:</b> Tái chế hoá học thu hồi monomer ban đầu.<br>• <b>Ý d [Đúng]:</b> Xu thế phát triển xanh toàn cầu.", "svgGraph": null}, {"q": "Khối lượng của một đoạn mạch tơ nylon-6 (polycaproamide) là 33 900 amu. Số mắt xích (hệ số polymer hoá n) trong đoạn mạch tơ đó là bao nhiêu (cho C=12, H=1, O=16, N=14)?", "opts": ["300", "250", "350", "400"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Mắt xích tơ capron là –NH–(CH<sub>2</sub>)<sub>5</sub>–CO– có khối lượng mol:<br>M = 14 + 1 + 5 · 14 + 12 + 16 = 113 amu.<br>Hệ số trùng hợp n = 33 900 / 113 = 300.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "15": [{"q": "Trong pin điện hoá Galvani Zn – Cu (pin Daniell), phản ứng xảy ra tại cực âm (anode) là:", "opts": ["Zn → Zn<sup>2+</sup> + 2e (quá trình oxi hoá kẽm)", "Cu<sup>2+</sup> + 2e → Cu (quá trình khử ion đồng)", "Zn<sup>2+</sup> + 2e → Zn (quá trình khử ion kẽm)", "Cu → Cu<sup>2+</sup> + 2e (quá trình oxi hoá đồng)"], "ans": 0, "exp": "• <b>Nguyên tắc hoạt động của pin Galvani:</b><br>- Kim loại có thế điện cực âm hơn (tính khử mạnh hơn) đóng vai trò là <b>cực âm (Anode)</b>, tại đây xảy ra <b>quá trình oxi hoá</b>: Zn → Zn<sup>2+</sup> + 2e.<br>- Kim loại có thế điện cực dương hơn đóng vai trò là <b>cực dương (Cathode)</b>, tại đây xảy ra <b>quá trình khử</b>: Cu<sup>2+</sup> + 2e → Cu.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 240\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">SƠ ĐỒ NGUYÊN LÍ PIN ĐIỆN HOÁ DANIELL (Zn – Cu)</text>\n  <!-- Beaker 1: Zn in ZnSO4 -->\n  <rect x=\"50\" y=\"70\" width=\"120\" height=\"120\" rx=\"6\" fill=\"rgba(14,165,233,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n  <rect x=\"52\" y=\"110\" width=\"116\" height=\"78\" fill=\"rgba(56,189,248,0.25)\"/>\n  <!-- Zn electrode -->\n  <rect x=\"95\" y=\"45\" width=\"25\" height=\"110\" fill=\"#94a3b8\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n  <text x=\"107\" y=\"40\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"11.5\" font-weight=\"bold\">Anode (-) Zn</text>\n  <text x=\"110\" y=\"170\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"10\">dd ZnSO₄ 1M</text>\n  <!-- Beaker 2: Cu in CuSO4 -->\n  <rect x=\"350\" y=\"70\" width=\"120\" height=\"120\" rx=\"6\" fill=\"rgba(244,63,94,0.12)\" stroke=\"#f43f5e\" stroke-width=\"1.8\"/>\n  <rect x=\"352\" y=\"110\" width=\"116\" height=\"78\" fill=\"rgba(244,63,94,0.25)\"/>\n  <!-- Cu electrode -->\n  <rect x=\"395\" y=\"45\" width=\"25\" height=\"110\" fill=\"#ea580c\" stroke=\"#fb923c\" stroke-width=\"1.5\"/>\n  <text x=\"407\" y=\"40\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"11.5\" font-weight=\"bold\">Cathode (+) Cu</text>\n  <text x=\"410\" y=\"170\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"10\">dd CuSO₄ 1M</text>\n  <!-- Salt Bridge U-tube -->\n  <path d=\"M 140 130 L 140 85 Q 140 70 160 70 L 360 70 Q 380 70 380 85 L 380 130\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"10\" stroke-linecap=\"round\" opacity=\"0.85\"/>\n  <text x=\"260\" y=\"65\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">Cầu muối (KNO₃)</text>\n  <!-- Voltmeter & Wire -->\n  <path d=\"M 107 45 L 107 35 L 230 35 M 290 35 L 407 35 L 407 45\" fill=\"none\" stroke=\"#34d399\" stroke-width=\"2\"/>\n  <circle cx=\"260\" cy=\"35\" r=\"16\" fill=\"#0f172a\" stroke=\"#34d399\" stroke-width=\"2\"/>\n  <text x=\"260\" y=\"39\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"10.5\" font-weight=\"bold\">1.10V</text>\n  <!-- Electron flow arrow -->\n  <path d=\"M 150 25 L 200 25\" fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"2\" marker-end=\"url(#arrow)\"/>\n  <text x=\"175\" y=\"20\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"10\">Dòng e⁻ ➔</text>\n  <!-- Bottom note -->\n  <rect x=\"50\" y=\"202\" width=\"420\" height=\"28\" rx=\"4\" fill=\"rgba(30,41,59,0.8)\"/>\n  <text x=\"260\" y=\"221\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11\">E°pin = E°(cathode) - E°(anode) = 0,34 - (-0,76) = <tspan fill=\"#34d399\" font-weight=\"bold\">1,10 V</tspan></text>\n</svg>"}, {"q": "Cho thế điện cực chuẩn của hai cặp oxi hoá - khử: E°(Zn<sup>2+</sup>/Zn) = -0,76 V và E°(Cu<sup>2+</sup>/Cu) = +0,34 V. Sức điện động chuẩn của pin Galvani Zn – Cu là bao nhiêu?", "opts": ["+1,10 V", "+0,42 V", "-1,10 V", "+0,76 V"], "ans": 0, "exp": "• <b>Công thức tính sức điện động chuẩn của pin:</b><br>E°<sub>pin</sub> = E°<sub>cathode (+)</sub> - E°<sub>anode (-)</sub><br>E°<sub>pin</sub> = E°(Cu<sup>2+</sup>/Cu) - E°(Zn<sup>2+</sup>/Zn)<br>E°<sub>pin</sub> = 0,34 - (-0,76) = +1,10 V.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Trong pin điện hoá, cầu muối (chứa dung dịch chất điện li trơ như KNO<sub>3</sub> hoặc KCl trong thạch agar) có vai trò chủ yếu nào sau đây?", "opts": ["Khép kín mạch điện và trung hoà điện tích ở hai nửa pin (dung dịch hai cốc điện cực).", "Cung cấp electron trực tiếp cho cực dương cathode.", "Làm tăng điện trở để pin không bị ngắn mạch chập cháy.", "Hút toàn bộ nước ở hai bên điện cực để pin khô ráo."], "ans": 0, "exp": "• <b>Vai trò của cầu muối:</b><br>1. Cho các ion di chuyển qua lại để khép kín mạch điện bên trong dung dịch.<br>2. Cation (K<sup>+</sup>) di chuyển về cathode để bù điện tích dương bị mất khi Cu<sup>2+</sup> bị khử; Anion (NO<sub>3</sub><sup>-</sup>) di chuyển về anode để trung hoà lượng cation Zn<sup>2+</sup> mới sinh ra, giữ cho hai dung dịch luôn trung hoà điện tích.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về thế điện cực chuẩn và dãy thế điện cực chuẩn của kim loại:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Thế điện cực chuẩn của điện cực hydro chuẩn 2H⁺/H₂ được quy ước bằng 0,00 V ở điều kiện chuẩn.", "Thế điện cực chuẩn E°(Mⁿ⁺/M) càng âm thì kim loại M có tính khử càng mạnh và cation Mⁿ⁺ có tính oxi hoá càng yếu.", "Kim loại đứng trước trong dãy thế điện cực chuẩn có thể khử được cation của kim loại đứng sau trong dung dịch nước (quy tắc α).", "Giá trị E°(Au³⁺/Au) có giá trị âm hơn rất nhiều so với E°(Na⁺/Na)."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Quy ước quốc tế IUPAC: E°(2H<sup>+</sup>/H<sub>2</sub>) = 0,00 V.<br>• <b>Ý b [Đúng]:</b> Ý nghĩa dãy thế điện cực: E° càng âm, dạng khử càng mạnh.<br>• <b>Ý c [Đúng]:</b> Chất khử mạnh hơn tác dụng với chất oxi hoá mạnh hơn sinh chất khử yếu hơn và chất oxi hoá yếu hơn (quy tắc α).<br>• <b>Ý d [Sai]:</b> Na là kim loại hoạt động mạnh có E° = -2,71 V (rất âm); Au là kim loại quý trơ có E° = +1,50 V (rất dương).", "svgGraph": null}, {"q": "Ghép từng loại nguồn điện hoá học (Cột A) với bản chất và đặc điểm hoạt động (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Pin Leclanché (pin con thỏ kẽm - carbon) ➔ Pin sơ cấp dùng một lần rồi bỏ, cực âm là vỏ kẽm, chất điện li paste NH₄Cl", "Pin Leclanché (pin con thỏ kẽm - carbon) ➔ Nguồn điện thứ cấp có thể nạp điện (sạc lại) nhiều lần để tái sử dụng", "Pin Leclanché (pin con thỏ kẽm - carbon) ➔ Mật độ năng lượng rất cao, trọng lượng nhẹ, dùng phổ biến trong smartphone, laptop và xe điện", "Pin Leclanché (pin con thỏ kẽm - carbon) ➔ Chuyển hoá trực tiếp năng lượng phản ứng giữa H₂ và O₂ thành điện năng, khí thải là nước sạch"], "ans": 0, "exp": "• <b>1 - A:</b> Pin Leclanché là pin khô sơ cấp 1 lần.<br>• <b>2 - B:</b> Acquy chì là nguồn thứ cấp sạc lại được.<br>• <b>3 - C:</b> Pin Li-ion công nghệ pin hiện đại nhất trên thiết bị di động.<br>• <b>4 - D:</b> Pin nhiên liệu sinh thái sạch.", "svgGraph": null}, {"q": "Hoàn thành quy tắc tính sức điện động chuẩn của pin điện hoá:<br><i>\"Sức điện động chuẩn của pin điện hoá kí hiệu là  [ ... ] , luôn có giá trị  [ ... ] . Công thức tính là: E°pin =  [ ... ]  -  [ ... ] , trong đó cathode là cực dương có thế điện cực lớn hơn và anode là cực âm có thế điện cực nhỏ hơn.\"</i>", "opts": ["E°pin — dương — E°(cathode) — E°(anode)", "E°(anode) — E°(cathode) — dương — E°pin", "dương — E°(cathode) — E°(anode) — âm", "E°(cathode) — E°(anode) — âm — E°(ox)"], "ans": 0, "exp": "• Sức điện động chuẩn luôn dương trong phản ứng tự diễn biến: E°pin = E°(cathode) - E°(anode) > 0.", "svgGraph": null}, {"q": "Cho biết E°(Ag<sup>+</sup>/Ag) = +0,80 V và E°(Fe<sup>2+</sup>/Fe) = -0,44 V. Phản ứng nào sau đây tự xảy ra trong điều kiện chuẩn?", "opts": ["Fe + 2Ag<sup>+</sup> → Fe<sup>2+</sup> + 2Ag", "Fe<sup>2+</sup> + 2Ag → Fe + 2Ag<sup>+</sup>", "Fe + Ag → Fe<sup>2+</sup> + Ag<sup>+</sup>", "Fe<sup>2+</sup> + Ag<sup>+</sup> → Fe + Ag"], "ans": 0, "exp": "• <b>Áp dụng quy tắc α:</b><br>Chất khử mạnh hơn (Fe) tác dụng với chất oxi hoá mạnh hơn (Ag<sup>+</sup>) sinh ra chất khử yếu hơn (Ag) và chất oxi hoá yếu hơn (Fe<sup>2+</sup>).<br>Sức điện động phản ứng: E° = E°(Ag<sup>+</sup>/Ag) - E°(Fe<sup>2+</sup>/Fe) = 0,80 - (-0,44) = +1,24 V > 0 → phản ứng tự xảy ra theo chiều thuận.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Ưu điểm vượt trội nhất của pin Lithium-ion so với các loại acquy chì truyền thống là gì?", "opts": ["Mật độ năng lượng cao hơn nhiều, khối lượng nhẹ hơn và chu kì nạp xả dài hơn.", "Rẻ tiền hơn acquy chì gấp nhiều lần.", "Không cần sạc điện mà tự phát điện vĩnh viễn.", "Sử dụng chất điện li là nước cất tinh khiết."], "ans": 0, "exp": "• <b>Đặc điểm công nghệ:</b> Lithium là kim loại nhẹ nhất (M=7) và có thế điện cực âm nhất (-3,04 V), giúp pin Li-ion có hiệu điện thế cao (3,7 - 4,2 V), kích thước nhỏ gọn nhưng lưu trữ năng lượng cực lớn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về quá trình sạc và xả điện của acquy chì:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Khi xả điện (phát điện), acquy đóng vai trò như một pin điện hoá biến đổi hoá năng thành điện năng.", "Khi sạc điện (nạp điện), acquy đóng vai trò như một bình điện phân biến đổi điện năng từ nguồn ngoài thành hoá năng.", "Trong quá trình xả điện, nồng độ acid H₂SO₄ trong dung dịch acquy giảm dần vì phản ứng tiêu hao H₂SO₄ và tạo ra kết tủa PbSO₄ trên hai bản cực.", "Sau khi xả kiệt điện, cả 2 bản cực của acquy đều được biến đổi thành chì kim loại nguyên chất."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Quá trình xả là quá trình pin Galvani tự phát.<br>• <b>Ý b [Đúng]:</b> Quá trình nạp là quá trình điện phân cưỡng bức.<br>• <b>Ý c [Đúng]:</b> Pb + PbO<sub>2</sub> + 2H<sub>2</sub>SO<sub>4</sub> ⇌ 2PbSO<sub>4</sub> + 2H<sub>2</sub>O; nồng độ acid giảm nên đo tỉ trọng acid biết được mức pin.<br>• <b>Ý d [Sai]:</b> Khi xả điện, cả 2 bản cực đều bị phủ kín bởi chì sulfate PbSO<sub>4</sub> màu trắng chứ không phải Pb nguyên chất.", "svgGraph": null}, {"q": "Cho pin điện hoá tạo bởi hai cặp oxi hoá khử Ni<sup>2+</sup>/Ni (E° = -0,26 V) và Ag<sup>+</sup>/Ag (E° = +0,80 V). Sức điện động chuẩn của pin là:", "opts": ["+1,06 V", "+0,54 V", "+0,26 V", "+0,80 V"], "ans": 0, "exp": "• <b>Tính toán:</b><br>E°(Ag<sup>+</sup>/Ag) = +0,80 V lớn hơn nên Ag là Cathode (+).<br>E°(Ni<sup>2+</sup>/Ni) = -0,26 V nhỏ hơn nên Ni là Anode (-).<br>E°<sub>pin</sub> = E°(cathode) - E°(anode) = 0,80 - (-0,26) = +1,06 V.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "16": [{"q": "Điện phân là quá trình oxi hoá – khử xảy ra ở các điện cực khi có dòng điện một chiều đi qua chất điện li nóng chảy hoặc dung dịch. Tại cực âm (cathode) của bình điện phân luôn xảy ra quá trình gì?", "opts": ["Quá trình khử (nhận electron)", "Quá trình oxi hoá (nhường electron)", "Quá trình hoà tan điện cực", "Quá trình tạo muối không tan"], "ans": 0, "exp": "• <b>Quy tắc điện phân bất biến:</b><br>- <b>Cathode (Cực âm trong điện phân):</b> Hút các cation dương về, tại đây luôn xảy ra <b>quá trình khử</b> (chất nhận electron: M<sup>n+</sup> + ne → M hoặc 2H<sub>2</sub>O + 2e → H<sub>2</sub> + 2OH<sup>-</sup>).<br>- <b>Anode (Cực dương trong điện phân):</b> Hút các anion âm về, tại đây luôn xảy ra <b>quá trình oxi hoá</b> (chất nhường electron: 2Cl<sup>-</sup> → Cl<sub>2</sub> + 2e hoặc 2H<sub>2</sub>O → O<sub>2</sub> + 4H<sup>+</sup> + 4e).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">SƠ ĐỒ BÌNH ĐIỆN PHÂN DUNG DỊCH CuSO₄ (ĐIỆN CỰC TRƠ)</text>\n  <!-- DC Power Source -->\n  <g transform=\"translate(230, 28)\">\n    <circle cx=\"30\" cy=\"18\" r=\"14\" fill=\"#0f172a\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n    <text x=\"30\" y=\"22\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">DC</text>\n    <text x=\"5\" y=\"14\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">+</text>\n    <text x=\"55\" y=\"14\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"bold\">-</text>\n    <line x1=\"16\" y1=\"18\" x2=\"-80\" y2=\"18\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n    <line x1=\"44\" y1=\"18\" x2=\"140\" y2=\"18\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n  </g>\n  <!-- Electrolysis Tank -->\n  <rect x=\"100\" y=\"75\" width=\"320\" height=\"115\" rx=\"8\" fill=\"rgba(14,165,233,0.1)\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n  <rect x=\"102\" y=\"105\" width=\"316\" height=\"83\" fill=\"rgba(14,165,233,0.22)\"/>\n  <!-- Anode (+) Left -->\n  <rect x=\"140\" y=\"55\" width=\"22\" height=\"115\" fill=\"#475569\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n  <text x=\"151\" y=\"48\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">Anode (+)</text>\n  <!-- Oxygen gas bubbles -->\n  <circle cx=\"145\" cy=\"120\" r=\"4\" fill=\"#f8fafc\" opacity=\"0.8\"/>\n  <circle cx=\"157\" cy=\"100\" r=\"5\" fill=\"#f8fafc\" opacity=\"0.8\"/>\n  <text x=\"90\" y=\"140\" fill=\"#cbd5e1\" font-size=\"10\">2H₂O ➔ O₂↑ + 4H⁺ + 4e</text>\n  <!-- Cathode (-) Right -->\n  <rect x=\"358\" y=\"55\" width=\"22\" height=\"115\" fill=\"#ea580c\" stroke=\"#fb923c\" stroke-width=\"1.5\"/>\n  <text x=\"369\" y=\"48\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"11\" font-weight=\"bold\">Cathode (-)</text>\n  <!-- Cu deposited -->\n  <text x=\"369\" y=\"180\" text-anchor=\"middle\" fill=\"#ea580c\" font-size=\"10.5\" font-weight=\"bold\">Cu bám đỏ</text>\n  <text x=\"275\" y=\"140\" fill=\"#cbd5e1\" font-size=\"10\">Cu²⁺ + 2e ➔ Cu↓</text>\n  <!-- Tank Label -->\n  <text x=\"260\" y=\"165\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"11\">Dung dịch CuSO₄ ➔ màu xanh nhạt dần, tạo H₂SO₄ (pH giảm)</text>\n  <!-- Footnote -->\n  <rect x=\"100\" y=\"198\" width=\"320\" height=\"24\" rx=\"4\" fill=\"rgba(30,41,59,0.9)\"/>\n  <text x=\"260\" y=\"214\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"10.5\">2CuSO₄ + 2H₂O ⎯(đpdd)➔ 2Cu↓ + O₂↑ + 2H₂SO₄</text>\n</svg>"}, {"q": "Điện phân dung dịch NaCl có màng ngăn xốp với điện cực trơ (quá trình sản xuất xút – clo trong công nghiệp), sản phẩm thu được ở cực âm (cathode) là gì?", "opts": ["Khí H<sub>2</sub> và dung dịch NaOH", "Khí Cl<sub>2</sub>", "Kim loại Na kết tủa", "Khí O<sub>2</sub> và dung dịch HCl"], "ans": 0, "exp": "• <b>Quá trình tại các điện cực:</b><br>- Tại Cathode (-): Ion Na<sup>+</sup> không bị khử trong dung dịch nước, nước bị khử:<br>2H<sub>2</sub>O + 2e → H<sub>2</sub> ↑ + 2OH<sup>-</sup> (sinh ra khí H<sub>2</sub> và dung dịch NaOH).<br>- Tại Anode (+): Ion Cl<sup>-</sup> bị oxi hoá:<br>2Cl<sup>-</sup> → Cl<sub>2</sub> ↑ + 2e.<br>• Phương trình điện phân có màng ngăn:<br>2NaCl + 2H<sub>2</sub>O ⎯(đpdd, màng ngăn)→ 2NaOH + H<sub>2</sub> ↑ + Cl<sub>2</sub> ↑.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nếu trong quá trình điện phân dung dịch NaCl KHÔNG có màng ngăn xốp giữa hai cực, khí Cl<sub>2</sub> sinh ra ở anode sẽ phản ứng ngay với dung dịch NaOH ở cathode để tạo thành sản phẩm gì?", "opts": ["Nước Javel (hỗn hợp NaCl và NaClO có tính tẩy màu, sát trùng)", "Muối ăn NaCl kết tinh lại nguyên vẹn", "Khí hydro chloride HCl bay lên", "Dung dịch sodium chlorate NaClO<sub>3</sub> đậm đặc"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>Cl<sub>2</sub> + 2NaOH → NaCl + NaClO + H<sub>2</sub>O.<br>• Hỗn hợp hai muối NaCl và sodium hypochlorite NaClO gọi là nước Javel, có tính oxi hoá mạnh dùng tẩy trắng quần áo và khử trùng nước sinh hoạt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về phương pháp điện phân nóng chảy trong công nghiệp luyện kim:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Điện phân nóng chảy là phương pháp duy nhất để điều chế các kim loại hoạt động hoá học mạnh như K, Na, Ca, Mg, Al.", "Trong quá trình sản xuất nhôm bằng điện phân Al₂O₃ nóng chảy, người ta hoà tan Al₂O₃ vào cryolite (Na₃AlF₆) để hạ nhiệt độ nóng chảy từ 2050°C xuống khoảng 900°C.", "Tại cathode của thùng điện phân Al₂O₃ nóng chảy, khí O₂ thoát ra làm cháy mòn dần các điện cực carbon.", "Khối lượng kim loại giải phóng ở điện cực tỉ lệ thuận với cường độ dòng điện và thời gian điện phân theo định luật Faraday."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Các kim loại có tính khử mạnh không thể điều chế bằng phương pháp khử trong dung dịch nước.<br>• <b>Ý b [Đúng]:</b> Cryolite giúp tiết kiệm năng lượng, tăng độ dẫn điện và tạo lớp màng nổi bảo vệ Al nóng chảy không bị oxi hoá trở lại.<br>• <b>Ý c [Sai]:</b> Khí O<sub>2</sub> thoát ra ở <b>Anode (+)</b> mới phản ứng với than chì anode làm mòn cực carbon: C + O<sub>2</sub> → CO<sub>2</sub>.<br>• <b>Ý d [Đúng]:</b> Định luật Faraday m = (A·I·t) / (n·F).", "svgGraph": null}, {"q": "Ghép từng ứng dụng kĩ thuật của điện phân (Cột A) với bản chất bố trí điện cực tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Mạ điện (mạ bạc cho thìa kim loại) ➔ Vật cần mạ gắn ở Cathode (-), thanh kim loại bạc Ag nguyên chất làm Anode (+)", "Mạ điện (mạ bạc cho thìa kim loại) ➔ Đồng thô nhiều tạp chất làm Anode (+), lá đồng tinh khiết mỏng làm Cathode (-)", "Mạ điện (mạ bạc cho thìa kim loại) ➔ Điện phân dung dịch NaCl có màng ngăn xốp ngăn Cl₂ phản ứng với NaOH", "Mạ điện (mạ bạc cho thìa kim loại) ➔ Điện phân hỗn hợp Al₂O₃ nóng chảy trong cryolite Na₃AlF₆"], "ans": 0, "exp": "• <b>1 - A:</b> Mạ bạc: vật làm cathode để Ag<sup>+</sup> khử bám lên bề mặt.<br>• <b>2 - B:</b> Tinh chế Cu: Cu thô tan ở anode, Cu tinh khiết bám cathode.<br>• <b>3 - C:</b> Sản xuất xút - clo có màng ngăn.<br>• <b>4 - D:</b> Luyện nhôm nóng chảy.", "svgGraph": null}, {"q": "Hoàn thành định luật Faraday về điện phân định lượng:<br><i>\"Khối lượng m của chất giải phóng ở điện cực tính theo công thức m =  [ ... ]  /  [ ... ] . Trong đó A là khối lượng mol nguyên tử, I là  [ ... ]  dòng điện (Ampe), t là  [ ... ]  điện phân (giây), n là số electron trao đổi và F là hằng số Faraday (96500 C/mol).\"</i>", "opts": ["A·I·t — n·F — cường độ — thời gian", "thời gian — cường độ — n·F — A·I·t", "n·F — cường độ — thời gian — hiệu điện thế", "cường độ — thời gian — hiệu điện thế — khối lượng"], "ans": 0, "exp": "• Công thức Faraday: m = (A·I·t) / (n·F). Số mol electron trao đổi n<sub>e</sub> = (I·t) / F.", "svgGraph": null}, {"q": "Điện phân 200 mL dung dịch CuSO<sub>4</sub> 0,5M với điện cực trơ, cường độ dòng điện I = 1,93 A trong thời gian 2000 giây. Khối lượng đồng kim loại bám trên cathode là bao nhiêu (cho Cu=64, F=96500 C/mol)?", "opts": ["1,28 gam", "2,56 gam", "0,64 gam", "6,40 gam"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Số mol electron trao đổi: n<sub>e</sub> = (I · t) / F = (1,93 · 2000) / 96500 = 0,04 mol.<br>Ban đầu n(CuSO<sub>4</sub>) = 0,2 · 0,5 = 0,1 mol.<br>Quá trình tại cathode: Cu<sup>2+</sup> + 2e → Cu<br>Số mol Cu sinh ra = n<sub>e</sub> / 2 = 0,04 / 2 = 0,02 mol (nhỏ hơn 0,1 mol nên Cu<sup>2+</sup> chưa bị điện phân hết).<br>Khối lượng Cu bám trên cathode = 0,02 · 64 = 1,28 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi điện phân dung dịch chứa hỗn hợp gồm FeSO<sub>4</sub>, CuSO<sub>4</sub> và AgNO<sub>3</sub> với điện cực trơ, thứ tự các cation kim loại bị khử tại cathode từ trước đến sau lần lượt là:", "opts": ["Ag<sup>+</sup>, sau đó đến Cu<sup>2+</sup>, rồi đến Fe<sup>2+</sup>", "Fe<sup>2+</sup>, sau đó đến Cu<sup>2+</sup>, rồi đến Ag<sup>+</sup>", "Cu<sup>2+</sup>, sau đó đến Ag<sup>+</sup>, rồi đến Fe<sup>2+</sup>", "Cả 3 cation kim loại bị khử đồng thời cùng lúc"], "ans": 0, "exp": "• <b>Quy tắc thứ tự khử ở cathode:</b><br>Cation nào có tính oxi hoá mạnh hơn (thế điện cực chuẩn E° lớn hơn) sẽ bị khử trước:<br>E°(Ag<sup>+</sup>/Ag) = +0,80 V > E°(Cu<sup>2+</sup>/Cu) = +0,34 V > E°(Fe<sup>2+</sup>/Fe) = -0,44 V.<br>Do đó: Ag<sup>+</sup> bị khử đầu tiên, khi hết Ag<sup>+</sup> thì đến Cu<sup>2+</sup>, cuối cùng mới đến Fe<sup>2+</sup>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về sự biến đổi môi trường pH của dung dịch trong quá trình điện phân (điện cực trơ):<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Khi điện phân dung dịch CuSO₄, môi trường dung dịch dần chuyển sang có tính acid (pH < 7) do nước bị oxi hoá ở anode giải phóng H⁺.", "Khi điện phân dung dịch NaCl có màng ngăn, môi trường dung dịch dần chuyển sang kiềm mạnh (pH > 7) do tạo thành NaOH.", "Khi điện phân dung dịch Na₂SO₄, thực chất chỉ có H₂O bị điện phân ở cả 2 điện cực sinh ra H₂ và O₂, nồng độ Na₂SO₄ tăng dần nhưng pH vẫn xấp xỉ bằng 7.", "Trong quá trình mạ kẽm (anode tan bằng kẽm Zn trong dung dịch ZnSO₄), nồng độ ion Zn²⁺ trong dung dịch giảm liên tục về 0."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Tạo acid H<sub>2</sub>SO<sub>4</sub> nên pH giảm.<br>• <b>Ý b [Đúng]:</b> Tạo NaOH nên pH tăng.<br>• <b>Ý c [Đúng]:</b> Cả Na<sup>+</sup> và SO<sub>4</sub><sup>2-</sup> không bị điện phân, chỉ có nước phân huỷ: 2H<sub>2</sub>O → 2H<sub>2</sub> + O<sub>2</sub>.<br>• <b>Ý d [Sai]:</b> Trong điện phân anode tan, lượng Zn tan ra ở anode đúng bằng lượng Zn kết tủa ở cathode nên nồng độ Zn<sup>2+</sup> hầu như không đổi.", "svgGraph": null}, {"q": "Điện phân dung dịch NaCl không màng ngăn xốp dùng để sản xuất hoá chất gia dụng nào?", "opts": ["Nước Javel sát khuẩn, tẩy màu vải sợi", "Xút ăn da rắn NaOH tinh khiết", "Kim loại natri nguyên chất", "Khí chlorine nén lỏng"], "ans": 0, "exp": "• <b>Bản chất hoá học:</b> Khi không có màng ngăn, NaOH sinh ra ở cathode gặp Cl<sub>2</sub> ở anode tạo nước Javel: 2NaCl + 2H<sub>2</sub>O ⎯(đpdd)→ NaCl + NaClO + H<sub>2</sub> ↑.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "17": [{"q": "Điểm khác biệt căn bản nhất giữa pin điện hoá và bình điện phân là gì?", "opts": ["Pin điện hoá biến hoá năng thành điện năng (phản ứng tự phát); bình điện phân dùng điện năng cưỡng bức phản ứng hoá học xảy ra.", "Pin điện hoá cần nối với nguồn điện bên ngoài; bình điện phân tự phát ra dòng điện.", "Cực âm của pin điện là cathode; cực âm của bình điện phân là anode.", "Pin điện chỉ hoạt động ở nhiệt độ cao; bình điện phân chỉ hoạt động ở nhiệt độ phòng."], "ans": 0, "exp": "• <b>So sánh bản chất nhiệt động học:</b><br>- Pin Galvani: Phản ứng oxi hoá khử tự diễn biến giải phóng năng lượng dưới dạng dòng điện (hoá năng → điện năng).<br>- Bình điện phân: Dùng dòng điện từ nguồn ngoài để cưỡng bức một phản ứng oxi hoá khử không tự phát xảy ra (điện năng → hoá năng).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Trong cả pin điện hoá và bình điện phân, quá trình hoá học luôn diễn ra tại cực ANODE là:", "opts": ["Quá trình oxi hoá (sự nhường electron)", "Quá trình khử (sự nhận electron)", "Sự tạo kết tủa kim loại", "Sự giải phóng khí hydrogen"], "ans": 0, "exp": "• <b>Quy tắc ghi nhớ quốc tế (Anode - Oxi hoá):</b><br>- <b>Anode:</b> Luôn luôn là nơi xảy ra quá trình OXI HOÁ (mất electron).<br>- <b>Cathode:</b> Luôn luôn là nơi xảy ra quá trình KHỬ (nhận electron).<br>(Lưu ý dấu cực: Trong pin điện Anode là cực âm; trong bình điện phân Anode là cực dương).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho hai pin điện hoá: Pin (1) Zn – Cu có E°<sub>pin</sub> = 1,10 V; Pin (2) Mg – Cu có E°<sub>pin</sub> = 2,71 V. Sức điện động chuẩn của pin Mg – Zn là bao nhiêu?", "opts": ["1,61 V", "3,81 V", "0,85 V", "2,10 V"], "ans": 0, "exp": "• <b>Tính toán đại số:</b><br>E°<sub>pin (Mg-Cu)</sub> = E°(Cu<sup>2+</sup>/Cu) - E°(Mg<sup>2+</sup>/Mg) = 2,71 V.<br>E°<sub>pin (Zn-Cu)</sub> = E°(Cu<sup>2+</sup>/Cu) - E°(Zn<sup>2+</sup>/Zn) = 1,10 V.<br>Lấy hiệu hai phương trình:<br>E°(Zn<sup>2+</sup>/Zn) - E°(Mg<sup>2+</sup>/Mg) = 2,71 - 1,10 = 1,61 V.<br>Đây chính là sức điện động chuẩn của pin Mg – Zn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các mệnh đề về so sánh quy tắc dấu cực và bản chất phản ứng giữa pin Galvani và bình điện phân:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Trong pin điện hoá, cực âm là Anode; trong bình điện phân, cực dương là Anode.", "Tại Cathode của cả pin điện hoá và bình điện phân đều luôn luôn diễn ra quá trình khử.", "Dòng electron ở mạch ngoài luôn di chuyển từ cực âm sang cực dương.", "Có thể điều chế kim loại nhôm bằng cách điện phân dung dịch AlCl₃ với điện cực trơ."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Quy ước dấu cực chuẩn của hoá điện.<br>• <b>Ý b [Đúng]:</b> Cathode luôn nhận e (quá trình khử).<br>• <b>Ý c [Đúng]:</b> Cực âm dư e nên đẩy dòng e qua dây dẫn sang cực dương.<br>• <b>Ý d [Sai]:</b> Trong dung dịch nước, H<sub>2</sub>O có thế khử lớn hơn Al<sup>3+</sup> nên nước bị khử trước sinh ra H<sub>2</sub> và Al(OH)<sub>3</sub> kết tủa; không thể điều chế Al bằng điện phân dung dịch.", "svgGraph": null}, {"q": "Ghép từng phản ứng điện cực (Cột A) với tên quá trình và vị trí điện cực tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Cu²⁺ + 2e → Cu (trong pin Daniell) ➔ Quá trình khử tại Cathode (+) của pin điện hoá", "Cu²⁺ + 2e → Cu (trong pin Daniell) ➔ Quá trình oxi hoá tại Anode (-) của pin điện hoá", "Cu²⁺ + 2e → Cu (trong pin Daniell) ➔ Quá trình khử tại Cathode (-) của bình điện phân", "Cu²⁺ + 2e → Cu (trong pin Daniell) ➔ Quá trình oxi hoá tại Anode (+) của bình điện phân"], "ans": 0, "exp": "• <b>1 - A:</b> Khử Cu<sup>2+</sup> ở Cathode pin.<br>• <b>2 - B:</b> Oxi hoá Zn ở Anode pin.<br>• <b>3 - C:</b> Khử H<sub>2</sub>O ở Cathode bình điện phân.<br>• <b>4 - D:</b> Oxi hoá Cl<sup>-</sup> ở Anode bình điện phân.", "svgGraph": null}, {"q": "Hoàn thiện tổng kết kiến thức cốt lõi Chương 5:<br><i>\"Trong pin điện hoá, kim loại có thế điện cực chuẩn  [ ... ]  hơn đóng vai trò anode. Dòng điện tự sinh ra chạy từ cathode sang anode ở mạch ngoài, ngược chiều dòng  [ ... ] . Trong bình điện phân, dòng điện một chiều cưỡng bức cation di chuyển về  [ ... ]  và anion di chuyển về  [ ... ] .\"</i>", "opts": ["âm — electron — cathode — anode", "anode — cathode — electron — âm", "dương — electron — cathode — anode", "electron — cathode — anode — neutron"], "ans": 0, "exp": "• Thế điện cực âm hơn làm anode.<br>• Chiều dòng điện ngược chiều dòng e.<br>• Cation về cathode (cực âm bình điện phân), anion về anode.", "svgGraph": null}, {"q": "Một dòng điện không đổi I = 5 A chạy qua bình điện phân nóng chảy Al<sub>2</sub>O<sub>3</sub> trong thời gian 9650 giây. Khối lượng nhôm kim loại thu được ở cathode là bao nhiêu (cho Al=27, F=96500 C/mol)?", "opts": ["4,50 gam", "13,50 gam", "1,50 gam", "9,00 gam"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Số mol electron trao đổi: n<sub>e</sub> = (I · t) / F = (5 · 9650) / 96500 = 0,5 mol.<br>Quá trình khử tại cathode: Al<sup>3+</sup> + 3e → Al<br>Số mol Al = n<sub>e</sub> / 3 = 0,5 / 3 = 1/6 mol.<br>Khối lượng Al = (1/6) · 27 = 4,50 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Để bảo vệ vỏ tàu biển bằng thép (chứa Fe) khỏi bị ăn mòn điện hoá khi ngâm trong nước biển, người ta thường gắn những khối kim loại nào sau đây vào vỏ tàu dưới mực nước biển?", "opts": ["Khối kim loại kẽm (Zn) làm vật hi sinh", "Khối kim loại đồng (Cu)", "Khối kim loại bạc (Ag)", "Khối chì (Pb)"], "ans": 0, "exp": "• <b>Nguyên tắc phương pháp điện hoá bảo vệ:</b><br>Kẽm (Zn) có tính khử mạnh hơn sắt (Fe) vì E°(Zn<sup>2+</sup>/Zn) = -0,76 V âm hơn E°(Fe<sup>2+</sup>/Fe) = -0,44 V.<br>Khi tạo thành cặp pin điện hoá trong nước biển, kẽm là Anode (-) bị ăn mòn hi sinh, còn vỏ thép đóng vai trò là Cathode (+) được bảo vệ an toàn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về ứng dụng thực tế của công nghệ hoá điện hiện đại:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Mạ điện giúp tạo một lớp kim loại quý, bền đẹp (như niken, crom, vàng) bảo vệ kim loại nền chống gỉ sét và tăng tính thẩm mĩ.", "Công nghệ pin xe điện (EV) chủ yếu sử dụng pin lithium-ion nhờ khả năng sạc nhanh, mật độ năng lượng cao và xả điện công suất lớn.", "Pin nhiên liệu sử dụng khí hydro và oxy chỉ thải ra hơi nước tinh khiết, được coi là nguồn năng lượng tương lai thân thiện môi trường.", "Pin cúc áo đã dùng hết có thể vứt bừa bãi vào thùng rác sinh hoạt thông thường mà không cần thu gom xử lý pin độc hại."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Ứng dụng phổ biến của mạ điện công nghiệp.<br>• <b>Ý b [Đúng]:</b> Trọng tâm ngành công nghiệp xe điện toàn cầu.<br>• <b>Ý c [Đúng]:</b> Nền kinh tế hydro sạch không phát thải carbon.<br>• <b>Ý d [Sai]:</b> Pin chứa kim loại nặng độc hại (chì, thuỷ ngân, cadmi, liti) ngấm vào đất và nguồn nước gây ngộ độc nặng, bắt buộc phải thu gom riêng.", "svgGraph": null}, {"q": "Điện phân 500 mL dung dịch AgNO<sub>3</sub> với điện cực trơ đến khi ở cathode bắt đầu có khí thoát ra thì dừng lại. Biết thời gian điện phân là 1000 giây với dòng điện 1,93 A. Nồng độ mol của dung dịch AgNO<sub>3</sub> ban đầu là bao nhiêu (cho F=96500 C/mol)?", "opts": ["0,04 M", "0,02 M", "0,08 M", "0,05 M"], "ans": 0, "exp": "• <b>Phân tích quá trình:</b><br>Ở cathode, ion Ag<sup>+</sup> bị khử trước: Ag<sup>+</sup> + 1e → Ag.<br>Khi bắt đầu có bọt khí thoát ra nghĩa là Ag<sup>+</sup> đã bị khử hết hoàn toàn và nước bắt đầu bị khử.<br>Số mol electron trao đổi = (I · t) / F = (1,93 · 1000) / 96500 = 0,02 mol.<br>n(Ag<sup>+</sup>) = n<sub>e</sub> = 0,02 mol.<br>Nồng độ mol = n / V = 0,02 / 0,5 = 0,04 M.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "18": [{"q": "Liên kết kim loại được hình thành do lực hút tĩnh điện giữa:", "opts": ["Các cation kim loại ở nút mạng tinh thể với các electron hoá trị tự do chuyển động trong toàn khối tinh thể.", "Các cation kim loại với các anion phi kim tích điện âm.", "Các nguyên tử kim loại dùng chung cặp electron liên kết cộng hoá trị phân cực.", "Các ion kim loại mang điện tích cùng dấu đẩy nhau."], "ans": 0, "exp": "• <b>Định nghĩa liên kết kim loại:</b> Liên kết kim loại là liên kết được hình thành do lực hút tĩnh điện giữa các ion dương (cation) kim loại tại các nút mạng tinh thể với các electron tự do (biển electron) chuyển động hỗn loạn không ngừng trong toàn bộ tinh thể.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">MÔ HÌNH TINH THỂ VÀ BIỂN ELECTRON TỰ DO CỦA KIM LOẠI</text>\n  <!-- Lattice box -->\n  <rect x=\"40\" y=\"45\" width=\"260\" height=\"135\" rx=\"8\" fill=\"rgba(14,165,233,0.08)\" stroke=\"#0284c7\" stroke-width=\"1.5\"/>\n  <!-- Cations grid -->\n  <g fill=\"#0284c7\" stroke=\"#38bdf8\" stroke-width=\"2\">\n    <!-- Row 1 -->\n    <circle cx=\"80\" cy=\"75\" r=\"16\"/><circle cx=\"145\" cy=\"75\" r=\"16\"/><circle cx=\"210\" cy=\"75\" r=\"16\"/><circle cx=\"270\" cy=\"75\" r=\"16\"/>\n    <!-- Row 2 -->\n    <circle cx=\"80\" cy=\"115\" r=\"16\"/><circle cx=\"145\" cy=\"115\" r=\"16\"/><circle cx=\"210\" cy=\"115\" r=\"16\"/><circle cx=\"270\" cy=\"115\" r=\"16\"/>\n    <!-- Row 3 -->\n    <circle cx=\"80\" cy=\"155\" r=\"16\"/><circle cx=\"145\" cy=\"155\" r=\"16\"/><circle cx=\"210\" cy=\"155\" r=\"16\"/><circle cx=\"270\" cy=\"155\" r=\"16\"/>\n  </g>\n  <!-- Plus signs on cations -->\n  <g fill=\"#ffffff\" font-size=\"13\" font-weight=\"bold\" text-anchor=\"middle\">\n    <text x=\"80\" y=\"80\">+</text><text x=\"145\" y=\"80\">+</text><text x=\"210\" y=\"80\">+</text><text x=\"270\" y=\"80\">+</text>\n    <text x=\"80\" y=\"120\">+</text><text x=\"145\" y=\"120\">+</text><text x=\"210\" y=\"120\">+</text><text x=\"270\" y=\"120\">+</text>\n    <text x=\"80\" y=\"160\">+</text><text x=\"145\" y=\"160\">+</text><text x=\"210\" y=\"160\">+</text><text x=\"270\" y=\"160\">+</text>\n  </g>\n  <!-- Delocalized electrons -->\n  <g fill=\"#fbbf24\">\n    <circle cx=\"112\" cy=\"70\" r=\"3.5\"/><circle cx=\"177\" cy=\"85\" r=\"3.5\"/><circle cx=\"240\" cy=\"65\" r=\"3.5\"/>\n    <circle cx=\"115\" cy=\"130\" r=\"3.5\"/><circle cx=\"180\" cy=\"120\" r=\"3.5\"/><circle cx=\"238\" cy=\"135\" r=\"3.5\"/>\n    <circle cx=\"110\" cy=\"165\" r=\"3.5\"/><circle cx=\"175\" cy=\"155\" r=\"3.5\"/><circle cx=\"245\" cy=\"160\" r=\"3.5\"/>\n  </g>\n  <!-- Side Info Box -->\n  <g transform=\"translate(320, 45)\">\n    <rect width=\"165\" height=\"135\" rx=\"8\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.12)\"/>\n    <text x=\"82\" y=\"24\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">KIỂU MẠNG CHÍNH</text>\n    <text x=\"15\" y=\"50\" fill=\"#f8fafc\" font-size=\"10.5\">• <tspan fill=\"#38bdf8\" font-weight=\"bold\">Lập phương tâm khối</tspan></text>\n    <text x=\"25\" y=\"65\" fill=\"#94a3b8\" font-size=\"9.5\">(bcc: Na, K, Ba, Cr, Fe-α)</text>\n    <text x=\"15\" y=\"85\" fill=\"#f8fafc\" font-size=\"10.5\">• <tspan fill=\"#34d399\" font-weight=\"bold\">Lập phương tâm diện</tspan></text>\n    <text x=\"25\" y=\"100\" fill=\"#94a3b8\" font-size=\"9.5\">(fcc: Cu, Ag, Au, Al, Fe-γ)</text>\n    <text x=\"15\" y=\"120\" fill=\"#f8fafc\" font-size=\"10.5\">• <tspan fill=\"#f43f5e\" font-weight=\"bold\">Lục phương</tspan> (hcp: Mg, Zn)</text>\n  </g>\n  <!-- Summary note -->\n  <rect x=\"40\" y=\"190\" width=\"445\" height=\"30\" rx=\"4\" fill=\"rgba(30,41,59,0.9)\"/>\n  <text x=\"262\" y=\"210\" text-anchor=\"middle\" fill=\"#a7f3d0\" font-size=\"11\">Các electron tự do quyết định: <tspan fill=\"#fbbf24\" font-weight=\"bold\">Tính dẫn điện, dẫn nhiệt, ánh kim và tính dẻo</tspan></text>\n</svg>"}, {"q": "Kim loại nào sau đây kết tinh theo kiểu mạng tinh thể lập phương tâm khối (BCC)?", "opts": ["Sodium (Na) và Kẽm (Cr, Ba, Fe-α)", "Đồng (Cu) và Bạc (Ag)", "Nhôm (Al) và Vàng (Au)", "Magnesium (Mg) và Zinc (Zn)"], "ans": 0, "exp": "• <b>Phân loại kiểu mạng:</b><br>- Lập phương tâm khối (BCC - độ đặc khít 68%): Kim loại kiềm (Li, Na, K, Rb, Cs), Ba, Cr, Fe ở nhiệt độ thường.<br>- Lập phương tâm diện (FCC - độ đặc khít 74%): Cu, Ag, Au, Al, Ni, Pt.<br>- Lục phương chặt khít (HCP - độ đặc khít 74%): Be, Mg, Zn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Số phối trí (số nguyên tử lân cận cách đều gần nhất một nguyên tử) trong mạng tinh thể lập phương tâm diện (FCC) là bao nhiêu?", "opts": ["12", "8", "6", "4"], "ans": 0, "exp": "• <b>Cấu trúc mạng FCC:</b> Trong kiểu mạng lập phương tâm diện, mỗi nguyên tử tiếp xúc với 12 nguyên tử lân cận gần nhất (4 nguyên tử cùng mặt phẳng, 4 nguyên tử ở mặt phẳng phía trên và 4 nguyên tử ở mặt phẳng phía dưới).<br>• Độ đặc khít đạt giá trị tối đa là 74%.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về cấu tạo nguyên tử và mạng tinh thể kim loại:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Nguyên tử kim loại thường có ít electron ở lớp ngoài cùng (thường là 1, 2 hoặc 3 electron) và có bán kính nguyên tử tương đối lớn hơn so với phi kim cùng chu kì.", "Năng lượng ion hoá của các nguyên tử kim loại tương đối nhỏ nên chúng dễ nhường electron hoá trị để trở thành các cation dương.", "Độ đặc khít của mạng tinh thể lục phương và lập phương tâm diện đều đạt giá trị xấp xỉ 74%.", "Ở mọi nhiệt độ, sắt kim loại (Fe) chỉ tồn tại duy nhất một kiểu mạng tinh thể lập phương tâm khối không bao giờ biến đổi."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Đặc điểm cấu hình electron nguyên tử kim loại.<br>• <b>Ý b [Đúng]:</b> Năng lượng ion hoá thấp tạo tính khử đặc trưng.<br>• <b>Ý c [Đúng]:</b> Hai kiểu mạng xếp chặt khít nhất đạt 74%.<br>• <b>Ý d [Sai]:</b> Sắt có hiện tượng đa hình: ở nhiệt độ phòng là Fe-α (tâm khối, bcc), khi nung nóng trên 912°C chuyển sang Fe-γ (tâm diện, fcc).", "svgGraph": null}, {"q": "Ghép từng kim loại (Cột A) với kiểu mạng tinh thể tương ứng ở điều kiện chuẩn (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Potassium (K) ➔ Lập phương tâm khối (bcc, độ đặc khít 68%)", "Potassium (K) ➔ Lập phương tâm diện (fcc, độ đặc khít 74%)", "Potassium (K) ➔ Lục phương chặt khít (hcp, độ đặc khít 74%)", "Potassium (K) ➔ Lập phương tâm khối (kim loại cứng nhất thế giới)"], "ans": 0, "exp": "• <b>1 - A:</b> Kim loại kiềm K là mạng tâm khối.<br>• <b>2 - B:</b> Al là mạng tâm diện.<br>• <b>3 - C:</b> Mg là mạng lục phương.<br>• <b>4 - D:</b> Cr mạng tâm khối liên kết cộng hoá trị phụ rất cứng.", "svgGraph": null}, {"q": "Hoàn thành các khái niệm về mạng tinh thể kim loại:<br><i>\"Đa số các kim loại ở trạng thái rắn kết tinh dưới dạng  [ ... ]  kim loại. Các cation kim loại nằm ở  [ ... ]  mạng, còn các electron tự do di chuyển tự do trong toàn bộ khối kim loại tạo thành  [ ... ]  electron. Mật độ sắp xếp nguyên tử trong mạng gọi là  [ ... ]  của tinh thể.\"</i>", "opts": ["tinh thể — nút — biển — độ đặc khít", "độ đặc khít — biển — nút — tinh thể", "nút — biển — độ đặc khít — chất lỏng", "biển — độ đặc khít — chất lỏng — phân tử"], "ans": 0, "exp": "• Cấu tạo tinh thể kim loại gồm cation ở nút mạng, electron tự do chuyển động tạo thành 'biển electron'.", "svgGraph": null}, {"q": "Cấu hình electron nguyên tử của kim loại nhôm (Al, Z = 13) ở trạng thái cơ bản là:", "opts": ["[Ne] 3s<sup>2</sup> 3p<sup>1</sup>", "[Ne] 3s<sup>2</sup>", "[Ar] 4s<sup>2</sup>", "1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup>"], "ans": 0, "exp": "• Al có Z = 13: 1s<sup>2</sup> 2s<sup>2</sup> 2p<sup>6</sup> 3s<sup>2</sup> 3p<sup>1</sup> viết gọn là [Ne] 3s<sup>2</sup> 3p<sup>1</sup>.<br>• Có 3 electron ở lớp ngoài cùng nên dễ nhường 3e tạo cation Al<sup>3+</sup>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hiện tượng các kim loại khi bị tác dụng lực cơ học mạnh (rèn, dát mỏng, kéo sợi) không bị vỡ vụn mà biến dạng dẻo là nhờ yếu tố nào?", "opts": ["Các lớp tinh thể trượt lên nhau nhưng vẫn được gắn kết nhờ biển electron tự do liên tục liên kết các cation.", "Các cation kim loại tạo liên kết ion với không khí.", "Nguyên tử kim loại có kích thước đàn hồi như cao su.", "Kim loại bị nóng chảy cục bộ tại điểm va chạm."], "ans": 0, "exp": "• <b>Giải thích tính dẻo:</b> Khi có lực tác dụng, các lớp ion dương kim loại trượt trượt lên nhau mà không bị tách rời vì các electron tự do linh động di chuyển tức thời đến bao quanh và duy trì lực hút tĩnh điện liên kết.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về độ đặc khít và khối lượng riêng của kim loại:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Độ đặc khít của mạng tinh thể là tỉ lệ phần trăm thể tích do các quả cầu nguyên tử chiếm chỗ so với thể tích toàn bộ ô mạng cơ sở.", "Mạng lập phương tâm diện (fcc) có độ đặc khít lớn hơn mạng lập phương tâm khối (bcc).", "Khối lượng riêng của kim loại chỉ phụ thuộc duy nhất vào số khối A của nguyên tử kim loại mà không phụ thuộc vào bán kính nguyên tử hay kiểu mạng.", "Lithium (Li) là kim loại có khối lượng riêng nhỏ nhất (d ≈ 0,53 g/cm³), có thể nổi trên mặt dầu hoả."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Định nghĩa độ đặc khít.<br>• <b>Ý b [Đúng]:</b> FCC đạt 74%, BCC đạt 68%.<br>• <b>Ý c [Sai]:</b> Khối lượng riêng d phụ thuộc vào khối lượng mol M, bán kính nguyên tử r và kiểu xếp mạng tinh thể.<br>• <b>Ý d [Đúng]:</b> Li nhẹ nhất trong tất cả kim loại.", "svgGraph": null}, {"q": "Trong tinh thể kim loại sắt ở thể α (mạng lập phương tâm khối), số nguyên tử sắt hiệu dụng nằm trong một ô mạng cơ sở là:", "opts": ["2 nguyên tử", "4 nguyên tử", "1 nguyên tử", "8 nguyên tử"], "ans": 0, "exp": "• <b>Tính toán:</b><br>- 8 đỉnh, mỗi đỉnh thuộc về 8 ô mạng xung quanh → đóng góp = 8 · (1/8) = 1 nguyên tử.<br>- 1 nguyên tử nằm trọn vẹn ở tâm ô mạng → đóng góp = 1 nguyên tử.<br>Tổng số nguyên tử trong 1 ô mạng cơ sở BCC = 1 + 1 = 2 nguyên tử.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "19": [{"q": "Bốn tính chất vật lí chung của kim loại (tính dẻo, tính dẫn điện, tính dẫn nhiệt và ánh kim) đều do yếu tố nào sau đây chủ yếu gây ra?", "opts": ["Sự có mặt của các electron tự do chuyển động trong mạng tinh thể", "Khối lượng riêng rất lớn của các cation kim loại", "Cấu trúc mạng lập phương chặt khít", "Năng lượng liên kết ion giữa các lớp nguyên tử"], "ans": 0, "exp": "• <b>Bản chất vật lí:</b> Tất cả các tính chất vật lí chung của kim loại (dẻo, dẫn điện, dẫn nhiệt, ánh kim) đều do các electron tự do trong tinh thể kim loại gây nên.<br>• Các tính chất riêng (nhiệt độ nóng chảy, khối lượng riêng, độ cứng) phụ thuộc vào bán kính, cấu hình electron và độ bền liên kết.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Kim loại nào sau đây có tính dẫn điện và dẫn nhiệt tốt nhất trong tất cả các kim loại?", "opts": ["Bạc (Ag)", "Đồng (Cu)", "Vàng (Au)", "Nhôm (Al)"], "ans": 0, "exp": "• <b>Dãy dẫn điện giảm dần chuẩn SGK:</b><br>Ag (Bạc) > Cu (Đồng) > Au (Vàng) > Al (Nhôm) > Fe (Sắt).<br>• Mặc dù bạc dẫn điện tốt nhất nhưng do đắt tiền nên dây dẫn điện truyền tải thông dụng dùng đồng và nhôm.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Kim loại có độ cứng cao nhất (đạt độ 10 trên thang Mohs, có thể cắt được thuỷ tinh) và kim loại có nhiệt độ nóng chảy cao nhất (dùng làm dây tóc bóng đèn sợi đốt) lần lượt là:", "opts": ["Chromium (Cr) và Tungsten (Vonfram, W)", "Kim cương và Sắt (Fe)", "Titanium (Ti) và Platin (Pt)", "Đồng (Cu) và Thuỷ ngân (Hg)"], "ans": 0, "exp": "• <b>Kỉ lục vật lí của kim loại:</b><br>- Kim loại cứng nhất: Chromium (Cr, độ cứng 9 - 10).<br>- Kim loại mềm nhất: Cs, Rb, K, Na (cắt được bằng dao).<br>- Nhiệt độ nóng chảy cao nhất: Tungsten (W, t°<sub>nc</sub> = 3422°C).<br>- Nhiệt độ nóng chảy thấp nhất: Thuỷ ngân (Hg, t°<sub>nc</sub> = -38,83°C, ở thể lỏng ở nhiệt độ phòng).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về tính chất hoá học chung của kim loại:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Tính chất hoá học chung đặc trưng của kim loại là tính khử (nguyên tử kim loại dễ bị oxi hoá: M → Mⁿ⁺ + ne).", "Tất cả các kim loại đều tác dụng được với dung dịch HCl và H₂SO₄ loãng giải phóng khí hydrogen H₂.", "Các kim loại Al, Fe, Cr bị thụ động hoá trong dung dịch HNO₃ đặc nguội và H₂SO₄ đặc nguội.", "Kim loại đồng (Cu) tan được trong dung dịch muối sắt(III) chloride FeCl₃ ở nhiệt độ thường."], "ans": 1, "exp": "• <b>Ý a [Đúng]:</b> Kim loại chỉ có số oxi hoá 0 và các số oxi hoá dương trong hợp chất nên chỉ thể hiện tính khử.<br>• <b>Ý b [Sai]:</b> Chỉ các kim loại đứng trước H trong dãy thế điện cực chuẩn mới giải phóng H<sub>2</sub> từ acid loãng; kim loại sau H (Cu, Ag, Au, Pt) không phản ứng.<br>• <b>Ý c [Đúng]:</b> Tạo màng oxide bảo vệ đặc khít ngăn phản ứng.<br>• <b>Ý d [Đúng]:</b> Cu + 2FeCl<sub>3</sub> → CuCl<sub>2</sub> + 2FeCl<sub>2</sub> (quy tắc α).", "svgGraph": null}, {"q": "Ghép từng kim loại (Cột A) với kỉ lục vật lí tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Osmium (Os) ➔ Kim loại nặng nhất (khối lượng riêng lớn nhất d ≈ 22,6 g/cm³)", "Osmium (Os) ➔ Kim loại nhẹ nhất (khối lượng riêng nhỏ nhất d ≈ 0,53 g/cm³)", "Osmium (Os) ➔ Kim loại duy nhất ở thể lỏng ở nhiệt độ phòng", "Osmium (Os) ➔ Kim loại dẻo nhất (1 gam có thể dát mỏng thành lá diện tích 1 m²)"], "ans": 0, "exp": "• <b>1 - A:</b> Os nặng nhất.<br>• <b>2 - B:</b> Li nhẹ nhất.<br>• <b>3 - C:</b> Hg thể lỏng duy nhất.<br>• <b>4 - D:</b> Vàng dẻo nhất.", "svgGraph": null}, {"q": "Hoàn thiện nhận định về tính chất hoá học của kim loại tác dụng với acid:<br><i>\"Kim loại đứng trước  [ ... ]  trong dãy điện hoá tác dụng với dung dịch acid HCl giải phóng khí  [ ... ] . Khi tác dụng với acid có tính oxi hoá mạnh như HNO₃ đặc nóng, kim loại bị oxi hoá lên số oxi hoá  [ ... ]  và giải phóng các sản phẩm khử của nitrogen như khí  [ ... ]  màu nâu đỏ.\"</i>", "opts": ["hydrogen — H₂ — cao nhất — NO₂", "NO₂ — cao nhất — H₂ — hydrogen", "H₂ — cao nhất — NO₂ — thấp nhất", "cao nhất — NO₂ — thấp nhất — oxygen"], "ans": 0, "exp": "• Kim loại khử H<sup>+</sup> thành H<sub>2</sub>.<br>• Với HNO<sub>3</sub>/H<sub>2</sub>SO<sub>4</sub> đặc, gốc acid là chất oxi hoá đưa kim loại lên số oxi hoá cao nhất và giải phóng NO<sub>2</sub>/SO<sub>2</sub>.", "svgGraph": null}, {"q": "Hoà tan hoàn toàn 5,4 gam bột nhôm (Al) vào dung dịch HCl dư. Thể tích khí H<sub>2</sub> thu được ở điều kiện chuẩn (25°C, 1 bar ứng với 24,79 L/mol) là bao nhiêu (cho Al=27)?", "opts": ["7,437 lít", "4,958 lít", "2,479 lít", "9,916 lít"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>2Al + 6HCl → 2AlCl<sub>3</sub> + 3H<sub>2</sub> ↑<br>• <b>Tính toán:</b><br>n(Al) = 5,4 / 27 = 0,2 mol.<br>n(H<sub>2</sub>) = 1,5 · n(Al) = 1,5 · 0,2 = 0,3 mol.<br>Thể tích H<sub>2</sub> ở đkc = 0,3 · 24,79 = 7,437 lít.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cho một đinh sắt sạch vào dung dịch đồng(II) sulfate (CuSO<sub>4</sub>). Sau một thời gian quan sát thấy hiện tượng gì?", "opts": ["Dung dịch xanh lam nhạt dần, có lớp kim loại màu đỏ gạch bám trên đinh sắt.", "Có khí màu nâu đỏ thoát ra mãnh liệt.", "Đinh sắt tan hết không để lại chất gì.", "Xuất hiện kết tủa màu trắng đục lắng xuống đáy cốc."], "ans": 0, "exp": "• <b>Phương trình hoá học:</b><br>Fe + CuSO<sub>4</sub> → FeSO<sub>4</sub> + Cu ↓<br>• Fe đẩy Cu ra khỏi muối: ion Cu<sup>2+</sup> màu xanh lam giảm dần làm dung dịch nhạt màu, Cu kim loại giải phóng bám ngoài đinh sắt có màu đỏ.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng của kim loại với các phi kim thông dụng:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Sắt (Fe) cháy trong khí chlorine (Cl₂) khô sinh ra muối iron(III) chloride FeCl₃ màu nâu đỏ.", "Thuỷ ngân (Hg) phản ứng với bột lưu huỳnh (S) ngay ở nhiệt độ thường tạo HgS không độc, dùng để xử lý thuỷ ngân vỡ từ nhiệt kế.", "Đồng (Cu) cháy trong oxygen không khí tạo thành đồng(I) oxide Cu₂O màu xanh lam.", "Nhôm (Al) tự bốc cháy mãnh liệt khi tiếp xúc với bột lưu huỳnh ở nhiệt độ phòng."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> 2Fe + 3Cl<sub>2</sub> ⎯(t°)→ 2FeCl<sub>3</sub>.<br>• <b>Ý b [Đúng]:</b> Hg + S → HgS (phương pháp xử lý nhiệt kế thuỷ ngân vỡ chuẩn an toàn phòng thí nghiệm).<br>• <b>Ý c [Sai]:</b> 2Cu + O<sub>2</sub> ⎯(t°)→ 2CuO (màu đen).<br>• <b>Ý d [Sai]:</b> Hỗn hợp Al và S phải khơi mào bằng ngọn lửa nhiệt độ cao mới phản ứng nổ sáng.", "svgGraph": null}, {"q": "Ngâm một lá kẽm (Zn) có khối lượng 50 gam vào 200 mL dung dịch AgNO<sub>3</sub> 1M. Sau khi phản ứng xảy ra hoàn toàn, lấy lá kẽm ra rửa sạch sấy khô cân lại. Khối lượng lá kim loại sau phản ứng là bao nhiêu (cho Zn=65, Ag=108)?", "opts": ["65,1 gam", "50,0 gam", "58,2 gam", "71,6 gam"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>Zn + 2AgNO<sub>3</sub> → Zn(NO<sub>3</sub>)<sub>2</sub> + 2Ag ↓<br>• <b>Tính toán:</b><br>n(AgNO<sub>3</sub>) = 0,2 · 1 = 0,2 mol.<br>n(Zn phản ứng) = 0,2 / 2 = 0,1 mol.<br>Khối lượng Zn tan ra = 0,1 · 65 = 6,5 gam.<br>Khối lượng Ag sinh ra bám vào = 0,2 · 108 = 21,6 gam.<br>Độ tăng khối lượng: Δm = 21,6 - 6,5 = 15,1 gam.<br>Khối lượng lá kim loại sau cùng = 50 + 15,1 = 65,1 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "20": [{"q": "Nguyên tắc chung của mọi phương pháp điều chế kim loại là gì?", "opts": ["Khử các cation kim loại trong hợp chất thành nguyên tử kim loại tự do (M<sup>n+</sup> + ne → M)", "Oxi hoá kim loại thành ion kim loại", "Nung chảy kim loại ở nhiệt độ cao", "Hoà tan kim loại vào acid mạnh"], "ans": 0, "exp": "• <b>Nguyên tắc điều chế kim loại:</b> Trong tự nhiên, hầu hết kim loại tồn tại ở dạng hợp chất (số oxi hoá dương M<sup>n+</sup>). Để điều chế kim loại tự do (số oxi hoá 0), ta phải khử cation kim loại bằng cách cung cấp electron: M<sup>n+</sup> + ne → M.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phương pháp nhiệt luyện (dùng các chất khử như CO, H<sub>2</sub>, C, Al ở nhiệt độ cao) thường được áp dụng trong công nghiệp để tách các kim loại nào sau đây?", "opts": ["Các kim loại có độ hoạt động hoá học trung bình và yếu (đứng sau nhôm Al như Fe, Cu, Zn, Pb)", "Các kim loại hoạt động mạnh (K, Na, Ca, Mg, Al)", "Chỉ dùng cho kim loại quý như vàng Au và platin Pt", "Tất cả các kim loại trong bảng tuần hoàn"], "ans": 0, "exp": "• <b>Phạm vi phương pháp nhiệt luyện:</b> Các oxide của kim loại đứng trước Al liên kết ion rất bền vững, các chất khử thông thường (CO, H<sub>2</sub>, C) không thể khử được ở nhiệt độ lò cao thông thường.<br>• Nhiệt luyện áp dụng cho oxide kim loại từ Zn trở về sau trong dãy hoạt động: Fe<sub>2</sub>O<sub>3</sub> + 3CO ⎯(t°)→ 2Fe + 3CO<sub>2</sub>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khoáng vật bauxite (chứa Al<sub>2</sub>O<sub>3</sub>·2H<sub>2</sub>O) là nguồn quặng tự nhiên quan trọng nhất để sản xuất kim loại nào?", "opts": ["Aluminium (Nhôm)", "Iron (Sắt)", "Copper (Đồng)", "Titanium (Titan)"], "ans": 0, "exp": "• Bauxite là quặng nhôm tự nhiên dồi dào ở Tây Nguyên nước ta. Quặng được tinh chế bằng phương pháp Bayer thành Al<sub>2</sub>O<sub>3</sub> tinh khiết, sau đó điện phân nóng chảy trong cryolite để thu nhôm kim loại.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về ba phương pháp tách và điều chế kim loại cơ bản:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Phương pháp thuỷ luyện dùng dung dịch thích hợp hoà tan quặng, sau đó dùng kim loại có tính khử mạnh hơn để đẩy kim loại yếu ra khỏi dung dịch.", "Phương pháp điện phân nóng chảy là con đường công nghiệp duy nhất để tách kim loại nhôm (Al) và kim loại kiềm (Na).", "Khí CO có thể khử được oxide MgO ở nhiệt độ cao tạo kim loại magnesium.", "Phương pháp nhiệt nhôm (dùng bột Al khử oxide kim loại) toả nhiệt lượng rất lớn và được ứng dụng để hàn đường ray xe lửa."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Định nghĩa thuỷ luyện (ví dụ Fe + CuSO<sub>4</sub> → FeSO<sub>4</sub> + Cu).<br>• <b>Ý b [Đúng]:</b> Kim loại mạnh chỉ điều chế bằng điện phân nóng chảy.<br>• <b>Ý c [Sai]:</b> Mg đứng trước Al nên CO không khử được MgO.<br>• <b>Ý d [Đúng]:</b> Phản ứng nhiệt nhôm 2Al + Fe<sub>2</sub>O<sub>3</sub> → Al<sub>2</sub>O<sub>3</sub> + 2Fe toả nhiệt trên 2500°C làm sắt nóng chảy lấp đầy khe nứt đường ray.", "svgGraph": null}, {"q": "Ghép từng loại quặng tự nhiên (Cột A) với thành phần hoá học chính tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Hematite đỏ ➔ Fe₂O₃ (không ngậm nước)", "Hematite đỏ ➔ Fe₃O₄ (quặng sắt giàu nhất nhưng hiếm hơn)", "Hematite đỏ ➔ CuFeS₂ (quặng đồng phổ biến)", "Hematite đỏ ➔ Al₂O₃·2H₂O (quặng nhôm chính)"], "ans": 0, "exp": "• <b>1 - A:</b> Hematite là Fe<sub>2</sub>O<sub>3</sub>.<br>• <b>2 - B:</b> Magnetite là Fe<sub>3</sub>O<sub>4</sub> có từ tính.<br>• <b>3 - C:</b> Chalcopyrite là CuFeS<sub>2</sub>.<br>• <b>4 - D:</b> Bauxite là Al<sub>2</sub>O<sub>3</sub>·2H<sub>2</sub>O.", "svgGraph": null}, {"q": "Hoàn thiện ba phương pháp tách kim loại trong công nghiệp:<br><i>\"Phương pháp  [ ... ]  dùng chất khử như CO khử ion kim loại trong oxide ở nhiệt độ cao. Phương pháp  [ ... ]  dùng kim loại mạnh đẩy kim loại yếu ra khỏi dung dịch muối. Phương pháp  [ ... ]  dùng dòng điện một chiều là phương pháp vạn năng nhất, dùng để điều chế các kim loại hoạt động mạnh.\"</i>", "opts": ["nhiệt luyện — thuỷ luyện — điện phân", "điện phân — thuỷ luyện — nhiệt luyện", "thuỷ luyện — điện phân — nóng chảy — chiết tách", "điện phân — nóng chảy — chiết tách — chưng cất"], "ans": 0, "exp": "• 3 phương pháp điều chế kim loại cơ bản trong hoá học: Nhiệt luyện, Thuỷ luyện, và Điện phân.", "svgGraph": null}, {"q": "Dẫn khí CO dư qua ống sứ nung nóng chứa 16 gam Fe<sub>2</sub>O<sub>3</sub>. Sau khi phản ứng hoàn toàn, khối lượng sắt kim loại thu được là bao nhiêu (cho Fe=56, O=16)?", "opts": ["11,2 gam", "5,6 gam", "8,4 gam", "14,0 gam"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>Fe<sub>2</sub>O<sub>3</sub> + 3CO ⎯(t°)→ 2Fe + 3CO<sub>2</sub><br>• <b>Tính toán:</b><br>n(Fe<sub>2</sub>O<sub>3</sub>) = 16 / 160 = 0,1 mol.<br>n(Fe) = 2 · n(Fe<sub>2</sub>O<sub>3</sub>) = 2 · 0,1 = 0,2 mol.<br>Khối lượng Fe = 0,2 · 56 = 11,2 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Kim loại nào sau đây thường được tìm thấy trong tự nhiên ở dạng đơn chất tự do (vàng cốm, sa khoáng) do có tính trơ hoá học rất cao?", "opts": ["Gold (Vàng, Au)", "Iron (Sắt, Fe)", "Sodium (Natri, Na)", "Aluminium (Nhôm, Al)"], "ans": 0, "exp": "• Vàng (Au) và platin (Pt) có thế điện cực chuẩn rất dương (+1,50 V) và độ hoạt động hoá học cực kì yếu, không bị oxi hoá bởi oxy hay nước trong khí quyển qua hàng triệu năm nên tồn tại dạng kim loại tự do.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các vấn đề môi trường và tái chế kim loại trong thời đại công nghệ số:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Rác thải điện tử (bo mạch máy tính, điện thoại hỏng) là 'mỏ quặng đô thị' chứa hàm lượng vàng, đồng, bạc cao hơn nhiều lần quặng tự nhiên.", "Tái chế kim loại (như nhôm, thép) tiêu tốn năng lượng chỉ bằng 5% - 10% so với quá trình luyện kim từ quặng nguyên sinh.", "Xỉ thải bauxite (bùn đỏ) trong quá trình sản xuất nhôm hoàn toàn trung tính và có thể xả thẳng trực tiếp ra biển.", "Khai thác vàng thủ công dùng thuỷ ngân (Hg) tạo hỗn hống gây ô nhiễm thuỷ ngân nghiêm trọng cho nguồn nước và sức khoẻ người dân."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Khái niệm khai thác mỏ đô thị (urban mining).<br>• <b>Ý b [Đúng]:</b> Tái chế nhôm tiết kiệm 95% năng lượng so với điện phân bauxite.<br>• <b>Ý c [Sai]:</b> Bùn đỏ có tính kiềm rất cao (pH > 11 - 12) và chứa kim loại nặng độc hại, là chất thải công nghiệp nguy hại bắt buộc xử lý nghiêm ngặt.<br>• <b>Ý d [Đúng]:</b> Ô nhiễm thuỷ ngân do tuyển quặng thủ công.", "svgGraph": null}, {"q": "Dùng phương pháp thuỷ luyện để tách bạc (Ag) từ quặng chứa AgCl, người ta dùng dung dịch NaCN để hoà tan tạo phức tan, sau đó dùng kim loại nào để khử lấy kim loại Ag?", "opts": ["Bột kẽm (Zn)", "Bột đồng (Cu)", "Kim loại chì (Pb)", "Khí hydrogen (H<sub>2</sub>)"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>2[Ag(CN)<sub>2</sub>]<sup>-</sup> + Zn → [Zn(CN)<sub>4</sub>]<sup>2-</sup> + 2Ag ↓<br>• Kẽm có tính khử mạnh đẩy bạc ra khỏi phức chất cyanide một cách triệt để.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "21": [{"q": "Gang và thép đều là hợp kim của sắt (Fe) với carbon (C), trong đó điểm khác biệt chủ yếu về hàm lượng carbon là:", "opts": ["Gang chứa từ 2% đến 5% C; Thép chứa từ 0,01% đến 2% C theo khối lượng.", "Gang chứa dưới 0,01% C; Thép chứa trên 10% C.", "Gang không chứa carbon; Thép chứa carbon nguyên chất.", "Gang và thép có hàm lượng carbon hoàn toàn bằng nhau."], "ans": 0, "exp": "• <b>Định nghĩa gang và thép:</b><br>- <b>Gang:</b> Hợp kim Fe – C chứa 2 - 5% carbon cùng lượng nhỏ Si, Mn, S, P (cứng và giòn, không rèn được).<br>- <b>Thép:</b> Hợp kim Fe – C chứa 0,01 - 2% carbon (đàn hồi, dẻo, bền cơ học, rèn cán dễ dàng).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hợp kim Duralumin (Đuy-ra) gồm nhôm (chính) với đồng, mangan, magie có đặc tính nổi bật là:", "opts": ["Nhẹ tương đương nhôm nhưng bền cứng ngang thép đặc biệt, dùng chế tạo thân vỏ máy bay.", "Nhiệt độ nóng chảy cao hơn vonfram.", "Dẫn điện tốt hơn bạc nguyên chất.", "Mềm xốp và dễ hoà tan trong nước."], "ans": 0, "exp": "• <b>Đặc tính của Duralumin:</b> Khối lượng riêng nhỏ (nhẹ) nhưng độ bền cơ học cực cao, chống ăn mòn tốt, là vật liệu xương sống trong ngành công nghiệp hàng không vũ trụ chế tạo khung thân máy bay, tên lửa.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Thép không gỉ (Inox) thường được chế tạo bằng cách thêm vào thép những nguyên tố hợp kim nào để tạo lớp màng bảo vệ thụ động chống ăn mòn?", "opts": ["Chromium (Cr khoảng 12 - 18%) và Nickel (Ni)", "Chì (Pb) và Thuỷ ngân (Hg)", "Đồng (Cu) và Kẽm (Zn)", "Carbon (C trên 10%)"], "ans": 0, "exp": "• <b>Bản chất chống gỉ của Inox:</b> Chromium trong thép phản ứng với oxy trong không khí tạo một lớp màng oxide Cr<sub>2</sub>O<sub>3</sub> siêu mỏng nhưng cực kì đặc khít bảo vệ sắt bên trong khỏi bị ăn mòn rỉ sét trong nước và môi trường gia dụng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định so sánh tính chất giữa hợp kim và các kim loại thành phần nguyên chất:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Hợp kim thường có độ cứng và độ bền cơ học cao hơn so với các kim loại thành phần tinh khiết.", "Nhiệt độ nóng chảy của hợp kim thường thấp hơn nhiệt độ nóng chảy của kim loại thành phần chính.", "Khả năng dẫn điện và dẫn nhiệt của hợp kim luôn luôn tốt hơn kim loại tinh khiết.", "Vàng tây (hợp kim của Au với Cu, Ag) cứng hơn nhiều so với vàng ta 24K (vàng 99,99%) nên dễ chế tác đồ trang sức tinh xảo."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Các nguyên tử khác kích thước cản trở sự trượt của các mặt phẳng tinh thể làm tăng độ cứng.<br>• <b>Ý b [Đúng]:</b> Mạng tinh thể pha tạp làm giảm nhiệt độ nóng chảy.<br>• <b>Ý c [Sai]:</b> Sự sắp xếp lộn xộn cản trở chuyển động của electron tự do nên hợp kim dẫn điện và nhiệt kém hơn kim loại sạch.<br>• <b>Ý d [Đúng]:</b> Vàng 24K quá mềm, vàng 18K/14K cứng bền chế tạo trang sức đính đá.", "svgGraph": null}, {"q": "Ghép từng loại hợp kim quen thuộc (Cột A) với thành phần kim loại chủ yếu (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Đồng thau (Brass) ➔ Hợp kim của Cu và Zn (màu vàng kim sáng)", "Đồng thau (Brass) ➔ Hợp kim của Cu và Sn (thiếc)", "Đồng thau (Brass) ➔ Hợp kim của Al với Cu, Mg, Mn", "Đồng thau (Brass) ➔ Hợp kim của Fe với C, Cr, Ni"], "ans": 0, "exp": "• <b>1 - A:</b> Đồng thau: Cu - Zn.<br>• <b>2 - B:</b> Đồng thanh: Cu - Sn (đúc chuông, tượng đồng).<br>• <b>3 - C:</b> Duralumin: Al hợp kim máy bay.<br>• <b>4 - D:</b> Inox: Fe - Cr - Ni.", "svgGraph": null}, {"q": "Hoàn thành định nghĩa và phân loại hợp kim:<br><i>\"Hợp kim là vật liệu kim loại chứa một kim loại  [ ... ]  và một số kim loại hoặc  [ ... ]  khác. Gang được sản xuất trong lò  [ ... ]  từ quặng sắt, sau đó gang trắng được luyện thành  [ ... ]  trong lò thổi oxy.\"</i>", "opts": ["cơ bản — phi kim — cao — thép", "thép — cao — phi kim — cơ bản", "phi kim — cao — thép — điện phân", "cao — thép — điện phân — đồng"], "ans": 0, "exp": "• Định nghĩa hợp kim, lò cao luyện gang và lò thổi oxy luyện thép.", "svgGraph": null}, {"q": "Hợp kim nha khoa amalgam dùng để hàn trám răng sâu là hợp kim của thuỷ ngân (Hg) với kim loại nào sau đây?", "opts": ["Bạc (Ag) và thiếc (Sn)", "Chì (Pb)", "Sắt (Fe)", "Natri (Na)"], "ans": 0, "exp": "• Amalgam nha khoa là hỗn hống của thuỷ ngân với hợp kim bạc - thiếc - đồng. Khi mới trộn ở thể dẻo dễ ép trám vào lỗ răng, sau vài phút đông cứng lại cực kì bền chắc chịu lực nhai lớn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Để luyện 10 tấn gang chứa 4% carbon từ quặng hematite đỏ chứa 80% Fe<sub>2</sub>O<sub>3</sub> (hiệu suất cả quá trình đạt 90%), khối lượng quặng cần dùng tối thiểu là bao nhiêu (cho Fe=56, O=16)?", "opts": ["19,05 tấn", "15,24 tấn", "21,16 tấn", "13,71 tấn"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Khối lượng Fe trong 10 tấn gang = 10 · (100% - 4%) = 9,6 tấn.<br>Fe<sub>2</sub>O<sub>3</sub> ➔ 2Fe (160 tấn Fe<sub>2</sub>O<sub>3</sub> tạo 112 tấn Fe).<br>Khối lượng Fe<sub>2</sub>O<sub>3</sub> lý thuyết cần = 9,6 · (160 / 112) = 13,714 tấn.<br>Khối lượng Fe<sub>2</sub>O<sub>3</sub> thực tế cần (H=90%) = 13,714 / 0,9 = 15,238 tấn.<br>Khối lượng quặng hematite (chứa 80% Fe<sub>2</sub>O<sub>3</sub>) = 15,238 / 0,8 = 19,05 tấn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về ứng dụng của hợp kim nhớ hình (shape memory alloy) và hợp kim siêu nhẹ:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Nitinol (hợp kim Ni - Ti) có khả năng 'nhớ hình': tự động trở lại hình dạng ban đầu khi được gia nhiệt, ứng dụng làm stent nong mạch vành tim và gọng kính mắt.", "Hợp kim magie - lithium là một trong những hợp kim kết cấu nhẹ nhất thế giới hiện nay, được dùng trong công nghiệp hàng không vũ trụ.", "Gang xám chứa carbon ở dạng than chì (graphite) nên có khả năng hấp thụ rung động tốt, dùng đúc bệ máy công cụ.", "Hợp kim hàn (thiếc hàn) có nhiệt độ nóng chảy cao hơn nhiều so với nhiệt độ nóng chảy của đồng và sắt."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Ứng dụng y học hiện đại của hợp kim nhớ hình Nitinol.<br>• <b>Ý b [Đúng]:</b> Hợp kim siêu nhẹ Mg-Li công nghệ vũ trụ.<br>• <b>Ý c [Đúng]:</b> Than chì trong gang xám dập tắt dao động rung bệ máy tiện, phay.<br>• <b>Ý d [Sai]:</b> Thiếc hàn (hợp kim Sn - Pb) có nhiệt độ nóng chảy thấp (khoảng 180 - 200°C) để mỏ hàn nhiệt dễ dàng làm chảy dính các mối điện tử mà không làm hỏng vi mạch.", "svgGraph": null}, {"q": "Vàng 18K là loại hợp kim vàng chứa bao nhiêu phần trăm khối lượng là vàng nguyên chất?", "opts": ["75%", "50%", "99,99%", "18%"], "ans": 0, "exp": "• <b>Quy ước Karat (K):</b> Vàng nguyên chất 100% được quy định là vàng 24K.<br>Hàm lượng vàng nguyên chất trong vàng 18K = (18 / 24) · 100% = 75% khối lượng (25% còn lại là đồng, bạc, niken để tăng độ cứng và tạo màu sắc).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "22": [{"q": "Ăn mòn điện hoá học là quá trình phá huỷ kim loại do tác dụng của môi trường, trong đó phát sinh dòng điện. Điều kiện nào sau đây KHÔNG PHẢI là điều kiện cần để xảy ra ăn mòn điện hoá?", "opts": ["Các điện cực bắt buộc phải đặt trong chân không hoàn toàn.", "Các điện cực phải khác chất nhau (hai kim loại khác nhau hoặc kim loại với phi kim).", "Các điện cực phải tiếp xúc trực tiếp hoặc gián tiếp với nhau qua dây dẫn.", "Các điện cực phải cùng tiếp xúc với một dung dịch chất điện li."], "ans": 0, "exp": "• <b>3 điều kiện ăn mòn điện hoá:</b><br>1. Có 2 điện cực khác chất.<br>2. Tiếp xúc trực tiếp hoặc qua dây dẫn.<br>3. Cùng nhúng trong dung dịch chất điện li (như không khí ẩm, nước mưa, nước biển).<br>Trong chân không không có chất điện li nên không thể xảy ra ăn mòn điện hoá.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">CƠ CHẾ ĂN MÒN ĐIỆN HOÁ CỦA GANG THÉP TRONG KHÔNG KHÍ ẨM</text>\n  <!-- Water droplet on steel -->\n  <g transform=\"translate(60, 45)\">\n    <!-- Steel Base -->\n    <rect x=\"0\" y=\"90\" width=\"400\" height=\"50\" fill=\"#334155\" stroke=\"#64748b\" stroke-width=\"2\"/>\n    <text x=\"200\" y=\"122\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"13\" font-weight=\"bold\">THÉP NỀN (Fe)</text>\n    <!-- Carbon / Cementite particle -->\n    <rect x=\"230\" y=\"70\" width=\"30\" height=\"20\" fill=\"#0f172a\" stroke=\"#fbbf24\" stroke-width=\"1.8\"/>\n    <text x=\"245\" y=\"84\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10\" font-weight=\"bold\">C</text>\n    <!-- Water Drop (Electrolyte) -->\n    <path d=\"M 50 90 Q 200 10 350 90 Z\" fill=\"rgba(56,189,248,0.2)\" stroke=\"#38bdf8\" stroke-width=\"1.8\"/>\n    <text x=\"120\" y=\"55\" fill=\"#38bdf8\" font-size=\"11\">Dung dịch điện li (H₂O + CO₂ + O₂)</text>\n    <!-- Anode Fe reaction -->\n    <circle cx=\"120\" cy=\"90\" r=\"4\" fill=\"#f43f5e\"/>\n    <text x=\"120\" y=\"105\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"10\" font-weight=\"bold\">Anode: Fe ➔ Fe²⁺ + 2e</text>\n    <text x=\"120\" y=\"145\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"9.5\">Sắt bị ăn mòn rỉ sét</text>\n    <!-- Electron flow arrow -->\n    <path d=\"M 145 80 L 215 80\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n    <text x=\"180\" y=\"74\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"9.5\">e⁻ ➔</text>\n    <!-- Cathode C reaction -->\n    <circle cx=\"245\" cy=\"70\" r=\"4\" fill=\"#34d399\"/>\n    <text x=\"285\" y=\"45\" fill=\"#34d399\" font-size=\"10\" font-weight=\"bold\">Cathode: O₂ + 2H₂O + 4e ➔ 4OH⁻</text>\n  </g>\n  <!-- Rust footnote -->\n  <rect x=\"60\" y=\"195\" width=\"400\" height=\"26\" rx=\"4\" fill=\"rgba(30,41,59,0.9)\"/>\n  <text x=\"260\" y=\"213\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"10.5\">Fe²⁺ + OH⁻ kết hợp tiếp với O₂ tạo gỉ sắt: <tspan fill=\"#ea580c\" font-weight=\"bold\">Fe₂O₃·nH₂O (màu nâu đỏ xốp)</tspan></text>\n</svg>"}, {"q": "Trong quá trình ăn mòn điện hoá gang, thép trong không khí ẩm, kim loại sắt đóng vai trò là điện cực nào và xảy ra quá trình gì?", "opts": ["Cực âm (Anode) và xảy ra quá trình oxi hoá: Fe → Fe<sup>2+</sup> + 2e (bị ăn mòn)", "Cực dương (Cathode) và xảy ra quá trình khử", "Cực âm (Anode) và được bảo vệ không bị ăn mòn", "Cực trung hoà không tham gia phản ứng"], "ans": 0, "exp": "• <b>Cơ chế vi pin Fe – C:</b> Sắt (Fe) có tính khử mạnh hơn carbon (C) nên đóng vai trò là <b>Anode (-)</b>.<br>• Tại Anode, sắt nhường electron bị oxi hoá thành ion Fe<sup>2+</sup> đi vào dung dịch màng ẩm: Fe → Fe<sup>2+</sup> + 2e (sắt bị phá huỷ).<br>• Carbon là Cathode (+) thu hút O<sub>2</sub> hoà tan để nhận e: O<sub>2</sub> + 2H<sub>2</sub>O + 4e → 4OH<sup>-</sup>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Một sợi dây phơi quần áo bằng đồng (Cu) được buộc chặt nối tiếp vào một sợi dây thép (chứa Fe) và để ngoài trời mưa. Sau một thời gian, vị trí chỗ nối hai dây bị đứt là do:", "opts": ["Sắt bị ăn mòn điện hoá nhanh hơn bình thường vì đóng vai trò là cực âm (anode).", "Đồng bị ăn mòn điện hoá nhanh chóng biến mất.", "Dây thép bị hoà tan bởi nước mưa tinh khiết.", "Đồng và sắt phản ứng trực tiếp với nhau tạo thành khí."], "ans": 0, "exp": "• <b>Giải thích:</b> Tại chỗ tiếp xúc giữa Cu và Fe hình thành vi pin điện hoá Fe – Cu có nước mưa làm chất điện li.<br>• Fe có tính khử mạnh hơn Cu nên Fe đóng vai trò Anode (-) bị ăn mòn mãnh liệt, khiến phần dây thép ở chỗ nối nhanh chóng bị gỉ sét và đứt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các biện pháp bảo vệ kim loại chống ăn mòn trong thực tiễn:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Sơn, mạ, bôi dầu mỡ lên bề mặt kim loại thuộc phương pháp bảo vệ bề mặt nhằm cách ly kim loại với môi trường không khí ẩm.", "Gắn các tấm kẽm (Zn) vào vỏ tàu biển bằng thép là phương pháp điện hoá (dùng vật hi sinh để bảo vệ sắt).", "Để đồ dùng bằng sắt ở nơi khô ráo, thoáng mát giúp giảm đáng kể tốc độ ăn mòn kim loại.", "Tráng thiếc (Sn) lên tấm sắt (sắt tây làm hộp sữa) bảo vệ sắt vĩnh viễn, kể cả khi lớp thiếc bên ngoài bị trầy xước sâu tới lõi sắt."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Phương pháp cách ly bề mặt.<br>• <b>Ý b [Đúng]:</b> Zn có thế điện cực âm hơn Fe nên bị ăn mòn hi sinh thay cho vỏ thép.<br>• <b>Ý c [Đúng]:</b> Không có màng ẩm chất điện li thì không có ăn mòn điện hoá.<br>• <b>Ý d [Sai]:</b> Thiếc có tính khử yếu hơn sắt. Khi bị trầy xước tới lõi, sắt trở thành Anode (-) sẽ bị ăn mòn điện hoá nhanh hơn gấp nhiều lần so với sắt để trần.", "svgGraph": null}, {"q": "Ghép từng trường hợp thực tế (Cột A) với loại ăn mòn tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Đốt cháy sợi dây sắt trong bình khí chlorine khô ở nhiệt độ cao ➔ Ăn mòn hoá học (không phát sinh dòng điện)", "Đốt cháy sợi dây sắt trong bình khí chlorine khô ở nhiệt độ cao ➔ Ăn mòn điện hoá học (nước biển làm chất điện li dẫn điện tốt)", "Đốt cháy sợi dây sắt trong bình khí chlorine khô ở nhiệt độ cao ➔ Ăn mòn điện hoá học (Fe bị ăn mòn bảo vệ Ag)", "Đốt cháy sợi dây sắt trong bình khí chlorine khô ở nhiệt độ cao ➔ Ăn mòn hoá học ở nhiệt độ cao do khí cháy"], "ans": 0, "exp": "• <b>1 - A:</b> Ăn mòn hoá học trực tiếp với Cl<sub>2</sub>.<br>• <b>2 - B:</b> Ăn mòn điện hoá vỏ tàu.<br>• <b>3 - C:</b> Ăn mòn điện hoá cặp Fe - Ag.<br>• <b>4 - D:</b> Ăn mòn hoá học buồng đốt.", "svgGraph": null}, {"q": "Hoàn thành hai phương pháp chống ăn mòn kim loại chính:<br><i>\"Phương pháp bảo vệ  [ ... ]  ngăn không cho kim loại tiếp xúc với môi trường bằng cách phủ lớp sơn, men, dầu mỡ hoặc mạ kim loại bền. Phương pháp  [ ... ]  bảo vệ kim loại bằng cách nối nó với một kim loại có tính khử  [ ... ]  hơn đóng vai trò là vật  [ ... ] .\"</i>", "opts": ["bề mặt — điện hoá — mạnh — hi sinh", "hi sinh — mạnh — điện hoá — bề mặt", "điện hoá — mạnh — hi sinh — yếu", "mạnh — hi sinh — yếu — nhiệt luyện"], "ans": 0, "exp": "• 2 nhóm phương pháp bảo vệ kim loại: Bảo vệ bề mặt và Bảo vệ điện hoá (vật hi sinh).", "svgGraph": null}, {"q": "Tiến hành 4 thí nghiệm: Nhúng một đinh sắt sạch vào 4 ống nghiệm chứa: (1) Khí oxy khô, (2) Nước cất có lớp dầu nổi trên mặt, (3) Dung dịch nước muối NaCl, (4) Không khí khô có hạt hút ẩm CaCl<sub>2</sub>. Ống nghiệm xảy ra ăn mòn nhanh nhất là:", "opts": ["Ống nghiệm (3)", "Ống nghiệm (1)", "Ống nghiệm (2)", "Ống nghiệm (4)"], "ans": 0, "exp": "• <b>Phân tích:</b><br>- Ống (1) và (4): Khí khô, không có nước nên không có ăn mòn.<br>- Ống (2): Nước cất không có oxy hoà tan (bị chặn bởi lớp dầu) nên ăn mòn cực kì chậm.<br>- Ống (3): Có cả nước, oxy hoà tan và ion Na<sup>+</sup>, Cl<sup>-</sup> làm dung dịch dẫn điện rất tốt, thúc đẩy vi pin điện hoá hoạt động mạnh nhất → sắt bị gỉ nhanh nhất.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Tôn lợp nhà là sản phẩm sắt được bảo vệ bằng cách nào?", "opts": ["Mạ kẽm (tráng một lớp kẽm Zn mỏng lên bề mặt thép)", "Tráng thiếc (Sn)", "Phủ một lớp sơn tĩnh điện không màu", "Mạ vàng 24K"], "ans": 0, "exp": "• Tôn hoa (thép lá tráng kẽm): Kẽm tạo màng oxide ZnO bền bảo vệ bề mặt. Khi bị trầy xước, kẽm có tính khử mạnh hơn sắt nên kẽm bị ăn mòn hi sinh, bảo vệ sắt không bị thủng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về thiệt hại kinh tế do sự ăn mòn kim loại gây ra trên thế giới:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Ước tính thiệt hại do ăn mòn kim loại gây ra hàng năm chiếm từ 3% đến 4% tổng sản phẩm quốc nội (GDP) của các nước công nghiệp phát triển.", "Sự ăn mòn kim loại có thể gây ra những thảm hoạ nghiêm trọng như sập cầu thép, vỡ đường ống dẫn dầu khí và rò rỉ hoá chất độc hại.", "Các kết cấu bê tông cốt thép ở vùng ven biển không bao giờ bị ăn mòn vì được bao bọc bởi lớp xi măng dày.", "Phát triển các vật liệu mới chống ăn mòn và sơn thông minh là hướng nghiên cứu quan trọng của khoa học vật liệu hiện đại."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Thiệt hại kinh tế khổng lồ hàng nghìn tỉ USD mỗi năm.<br>• <b>Ý b [Đúng]:</b> Nguy cơ thảm hoạ gãy sập công trình.<br>• <b>Ý c [Sai]:</b> Ion Cl<sup>-</sup> trong hơi muối biển thẩm thấu qua các khe nứt li ti của bê tông phá huỷ cốt thép bên trong làm phồng nứt bê tông.<br>• <b>Ý d [Đúng]:</b> Ứng dụng công nghệ nano và sơn thông minh.", "svgGraph": null}, {"q": "Trường hợp nào sau đây xảy ra hiện tượng ăn mòn hoá học thuần tuý mà không có ăn mòn điện hoá?", "opts": ["Thanh sắt bị nung nóng đỏ trong lò rèn tiếp xúc với không khí.", "Tấm tôn mạ kẽm bị xước để ngoài trời mưa.", "Thìa sắt tiếp xúc với thìa đồng trong bát canh mặn.", "Mẩu gang ngâm trong dung dịch acid HCl."], "ans": 0, "exp": "• <b>Bản chất:</b> Thanh sắt nung nóng phản ứng trực tiếp với O<sub>2</sub>: 3Fe + 2O<sub>2</sub> ⎯(t°)→ Fe<sub>3</sub>O<sub>4</sub>. Electron truyền trực tiếp từ Fe sang O<sub>2</sub> tại chỗ va chạm, không phát sinh dòng điện → ăn mòn hoá học thuần tuý.<br>• Các trường hợp còn lại đều có 2 điện cực tiếp xúc dung dịch điện li nên là ăn mòn điện hoá.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "23": [{"q": "Cho các kim loại: Na, Mg, Fe, Cu, Ag, Al. Số kim loại có thể điều chế được bằng phương pháp nhiệt luyện (dùng CO khử oxide ở nhiệt độ cao) là:", "opts": ["3 kim loại (Fe, Cu, Ag)", "2 kim loại (Fe, Cu)", "4 kim loại", "1 kim loại"], "ans": 0, "exp": "• <b>Quy tắc nhiệt luyện:</b> Áp dụng cho các kim loại đứng sau Al trong dãy hoạt động (Fe, Cu, Ag).<br>• Na, Mg, Al là kim loại mạnh, oxide của chúng không bị khử bởi CO.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Dãy kim loại được xếp theo thứ tự tính dẫn điện giảm dần từ trái sang phải là:", "opts": ["Ag > Cu > Au > Al > Fe", "Cu > Ag > Al > Au > Fe", "Au > Ag > Cu > Fe > Al", "Al > Cu > Ag > Au > Fe"], "ans": 0, "exp": "• Dãy chuẩn độ dẫn điện: Bạc dẫn điện tốt nhất, tiếp đến Đồng, Vàng, Nhôm và Sắt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Kim loại sắt (Fe) phản ứng được với dung dịch muối nào sau đây?", "opts": ["CuSO<sub>4</sub>", "ZnSO<sub>4</sub>", "MgSO<sub>4</sub>", "AlCl<sub>3</sub>"], "ans": 0, "exp": "• Fe có tính khử mạnh hơn Cu (E°(Fe<sup>2+</sup>/Fe) = -0,44 V < E°(Cu<sup>2+</sup>/Cu) = +0,34 V) nên đẩy được Cu ra khỏi CuSO<sub>4</sub>: Fe + CuSO<sub>4</sub> → FeSO<sub>4</sub> + Cu.<br>• Fe đứng sau Zn, Mg, Al nên không khử được cation của các kim loại này.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính Đúng/Sai của các nhận định tổng kết Chương 6:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Kim loại kiềm mềm đến mức có thể cắt dễ dàng bằng dao thí nghiệm do liên kết kim loại yếu và mạng lập phương tâm khối có độ đặc khít nhỏ.", "Để bảo vệ ruột bình nóng lạnh tráng men khỏi bị ăn mòn, nhà sản xuất thường lắp một thanh magie (Mg) làm vật hi sinh.", "Hợp kim luôn có độ bền cơ học và khả năng dẫn điện cao hơn kim loại nguyên chất.", "Hiện tượng sắt bị thụ động hoá trong HNO₃ đặc nguội được ứng dụng để dùng các bồn chứa bằng sắt vận chuyển acid HNO₃ đặc."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Đặc điểm kim loại kiềm.<br>• <b>Ý b [Đúng]:</b> Thanh anode magie trong bình nóng lạnh bảo vệ ruột thép.<br>• <b>Ý c [Sai]:</b> Hợp kim dẫn điện kém hơn kim loại sạch.<br>• <b>Ý d [Đúng]:</b> Màng thụ động trơ cho phép dùng thùng sắt chở HNO<sub>3</sub> đặc nguội an toàn.", "svgGraph": null}, {"q": "Ghép từng hiện tượng (Cột A) với bản chất hoá học tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Đinh sắt quấn dây đồng nhúng vào dung dịch H₂SO₄ loãng thì khí H₂ thoát ra mạnh ở dây đồng ➔ Ăn mòn điện hoá học (H⁺ nhận electron tại cathode Cu)", "Đinh sắt quấn dây đồng nhúng vào dung dịch H₂SO₄ loãng thì khí H₂ thoát ra mạnh ở dây đồng ➔ Hiện tượng thụ động hoá kim loại tạo màng oxide trơ bền", "Đinh sắt quấn dây đồng nhúng vào dung dịch H₂SO₄ loãng thì khí H₂ thoát ra mạnh ở dây đồng ➔ Phản ứng thuỷ luyện kim loại", "Đinh sắt quấn dây đồng nhúng vào dung dịch H₂SO₄ loãng thì khí H₂ thoát ra mạnh ở dây đồng ➔ Phản ứng nhiệt nhôm toả nhiệt cực lớn"], "ans": 0, "exp": "• <b>1 - A:</b> Vi pin Fe - Cu giải phóng H<sub>2</sub> ở Cu.<br>• <b>2 - B:</b> Thụ động hoá ngăn cản phản ứng.<br>• <b>3 - C:</b> Thuỷ luyện Zn + Cu<sup>2+</sup> → Zn<sup>2+</sup> + Cu.<br>• <b>4 - D:</b> Phản ứng nhiệt nhôm hàn đường ray.", "svgGraph": null}, {"q": "Hoàn thiện nội dung kiến thức cốt lõi Chương 6:<br><i>\"Liên kết kim loại được hình thành giữa cation kim loại và  [ ... ]  tự do. Tính chất hoá học đặc trưng của kim loại là tính  [ ... ] . Ba phương pháp điều chế kim loại gồm nhiệt luyện, thuỷ luyện và  [ ... ] . Ăn mòn điện hoá xảy ra khi có hai điện cực khác chất cùng nhúng trong  [ ... ] .\"</i>", "opts": ["electron — khử — điện phân — chất điện li", "chất điện li — điện phân — khử — electron", "khử — điện phân — chất điện li — chất dẻo", "điện phân — chất điện li — chất dẻo — oxi hoá"], "ans": 0, "exp": "• Tổng kết liên kết, tính khử, phương pháp điều chế và điều kiện ăn mòn điện hoá.", "svgGraph": null}, {"q": "Cho m gam hỗn hợp bột gồm Fe và Cu vào dung dịch AgNO<sub>3</sub> dư. Sau khi phản ứng hoàn toàn thu được 43,2 gam chất rắn Ag kết tủa. Biết số mol Fe bằng số mol Cu trong hỗn hợp ban đầu. Giá trị của m là bao nhiêu (cho Fe=56, Cu=64, Ag=108)?", "opts": ["9,6 gam", "12,0 gam", "7,2 gam", "14,4 gam"], "ans": 0, "exp": "• <b>Tính toán:</b><br>Số mol Ag = 43,2 / 108 = 0,4 mol.<br>Vì AgNO<sub>3</sub> dư nên Fe bị oxi hoá lên Fe<sup>3+</sup> (nhường 3e), Cu nhường 2e.<br>Gọi số mol Fe là x, số mol Cu là x.<br>Bảo toàn electron: 3x + 2x = n(Ag) = 0,4 → 5x = 0,4 → x = 0,08 mol.<br>Khối lượng hỗn hợp ban đầu: m = 0,08 · 56 + 0,08 · 64 = 0,08 · 120 = 9,6 gam.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cặp kim loại nào sau đây khi tiếp xúc với nhau và nhúng vào dung dịch chất điện li thì SẮT (Fe) bị ăn mòn trước?", "opts": ["Fe – Cu (hoặc Fe – Sn, Fe – Ag)", "Fe – Zn", "Fe – Mg", "Fe – Al"], "ans": 0, "exp": "• <b>Nguyên tắc:</b> Kim loại có tính khử mạnh hơn sẽ đóng vai trò là Anode (-) và bị ăn mòn trước.<br>- Trong cặp Fe – Cu: Fe mạnh hơn Cu nên Fe bị ăn mòn trước.<br>- Trong các cặp Fe – Zn, Fe – Mg, Fe – Al: Zn, Mg, Al đều có tính khử mạnh hơn Fe nên chúng bị ăn mòn trước để bảo vệ Fe.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về ứng dụng thực tế của kim loại và hợp kim trong đời sống:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Dây cáp điện cao thế thường làm bằng nhôm có lõi thép trợ lực để vừa nhẹ vừa chịu được lực kéo căng lớn trên các cột điện cao.", "Thuỷ ngân được sử dụng trong áp kế và nhiệt kế y tế đo nhiệt độ cơ thể nhờ tính giãn nở nhiệt đều đặn ở thể lỏng.", "Vàng nguyên chất 99,99% thường được dùng để chế tạo vỏ điện thoại chống va đập siêu cứng.", "Gang trắng chứa hàm lượng xi măng tit (Fe₃C) cao rất cứng và giòn, được dùng chủ yếu để luyện thép."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Dây ACSR (Aluminium Conductor Steel Reinforced) tiêu chuẩn truyền tải điện.<br>• <b>Ý b [Đúng]:</b> Ứng dụng truyền thống của thuỷ ngân lỏng.<br>• <b>Ý c [Sai]:</b> Vàng nguyên chất rất mềm, không thể dùng chống va đập cơ học.<br>• <b>Ý d [Đúng]:</b> Gang trắng dùng luyện thép trong lò thổi.", "svgGraph": null}, {"q": "Kim loại nào sau đây nhẹ hơn nước (nổi được trên mặt nước)?", "opts": ["Lithium (Li, d = 0,53 g/cm³) và Potassium (K, d = 0,86 g/cm³)", "Nhôm (Al, d = 2,7 g/cm³)", "Magnesium (Mg, d = 1,74 g/cm³)", "Kẽm (Zn, d = 7,14 g/cm³)"], "ans": 0, "exp": "• Khối lượng riêng của nước là d = 1,00 g/cm<sup>3</sup>.<br>• Các kim loại Li (0,53), Na (0,97), K (0,86) đều có khối lượng riêng nhỏ hơn 1 g/cm<sup>3</sup> nên nổi trên mặt nước (đồng thời phản ứng mãnh liệt với nước).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "24": [{"q": "Các kim loại nhóm IA (Li, Na, K, Rb, Cs) đều có cấu hình electron lớp ngoài cùng chung là gì?", "opts": ["ns<sup>1</sup>", "ns<sup>2</sup>", "ns<sup>2</sup> np<sup>1</sup>", "(n-1)d<sup>1</sup> ns<sup>2</sup>"], "ans": 0, "exp": "• <b>Cấu tạo nguyên tử kim loại kiềm:</b> Thuộc phân nhóm chính nhóm I (nhóm IA), lớp vỏ electron ngoài cùng chỉ có 1 electron hoá trị dạng ns<sup>1</sup>.<br>• Bán kính nguyên tử lớn nhất trong chu kì, năng lượng ion hoá thứ nhất I<sub>1</sub> nhỏ nhất nên dễ dàng nhường 1e thể hiện tính khử rất mạnh: M → M<sup>+</sup> + 1e.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">MÀU NGỌN LỬA VÀ TÍNH CHẤT ĐẶC TRƯNG CỦA KIM LOẠI KIỀM</text>\n  <!-- Flame 1: Lithium Crimson -->\n  <g transform=\"translate(60, 45)\">\n    <path d=\"M 30 110 Q 10 70 30 40 Q 50 70 30 110 Z\" fill=\"#e11d48\" opacity=\"0.9\"/>\n    <path d=\"M 30 100 Q 20 75 30 55 Q 40 75 30 100 Z\" fill=\"#f43f5e\"/>\n    <text x=\"30\" y=\"130\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">LITHIUM (Li)</text>\n    <text x=\"30\" y=\"145\" text-anchor=\"middle\" fill=\"#fda4af\" font-size=\"10.5\">Đỏ tía (Crimson)</text>\n  </g>\n  <!-- Flame 2: Sodium Yellow -->\n  <g transform=\"translate(190, 45)\">\n    <path d=\"M 30 110 Q 10 70 30 40 Q 50 70 30 110 Z\" fill=\"#eab308\" opacity=\"0.9\"/>\n    <path d=\"M 30 100 Q 20 75 30 55 Q 40 75 30 100 Z\" fill=\"#fef08a\"/>\n    <text x=\"30\" y=\"130\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">SODIUM (Na)</text>\n    <text x=\"30\" y=\"145\" text-anchor=\"middle\" fill=\"#fef08a\" font-size=\"10.5\">Vàng tươi sáng</text>\n  </g>\n  <!-- Flame 3: Potassium Violet -->\n  <g transform=\"translate(320, 45)\">\n    <path d=\"M 30 110 Q 10 70 30 40 Q 50 70 30 110 Z\" fill=\"#8b5cf6\" opacity=\"0.9\"/>\n    <path d=\"M 30 100 Q 20 75 30 55 Q 40 75 30 100 Z\" fill=\"#ddd6fe\"/>\n    <text x=\"30\" y=\"130\" text-anchor=\"middle\" fill=\"#a78bfa\" font-size=\"12\" font-weight=\"bold\">POTASSIUM (K)</text>\n    <text x=\"30\" y=\"145\" text-anchor=\"middle\" fill=\"#c4b5fd\" font-size=\"10.5\">Tím nhạt (Lilac)</text>\n  </g>\n  <!-- Storage box -->\n  <g transform=\"translate(420, 60)\">\n    <rect width=\"80\" height=\"90\" rx=\"6\" fill=\"rgba(30,41,59,0.9)\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n    <text x=\"40\" y=\"25\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10.5\" font-weight=\"bold\">BẢO QUẢN</text>\n    <text x=\"40\" y=\"50\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"9.5\">Ngâm chìm</text>\n    <text x=\"40\" y=\"65\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"10.5\" font-weight=\"bold\">trong dầu hoả</text>\n    <text x=\"40\" y=\"80\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"9\">(Tránh H₂O, O₂)</text>\n  </g>\n  <!-- Summary text -->\n  <rect x=\"30\" y=\"195\" width=\"460\" height=\"26\" rx=\"4\" fill=\"rgba(30,41,59,0.9)\"/>\n  <text x=\"260\" y=\"213\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11\">Phản ứng mãnh liệt với nước: 2M + 2H₂O ➔ 2MOH + H₂↑ (toả nhiều nhiệt gây nổ)</text>\n</svg>"}, {"q": "Để bảo quản các kim loại kiềm như sodium (Na) và potassium (K) trong phòng thí nghiệm, người ta phải ngâm chúng ngập hoàn toàn trong chất lỏng nào?", "opts": ["Dầu hoả (kerosene)", "Nước cất", "Alcohol ethanol", "Dung dịch giấm ăn"], "ans": 0, "exp": "• <b>Nguyên tắc bảo quản:</b> Kim loại kiềm có tính khử cực kì mạnh, tác dụng tức thời và mãnh liệt với oxygen và hơi ẩm trong không khí.<br>• Dầu hoả không phản ứng với kim loại kiềm và ngăn cách hoàn toàn kim loại với không khí và nước.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi đốt muối hoặc hợp chất của sodium (Na) trên ngọn lửa đèn khí không màu, ngọn lửa cháy phát ra ánh sáng có màu gì đặc trưng?", "opts": ["Màu vàng tươi sáng", "Màu tím nhạt", "Màu đỏ tía", "Màu lục sáng"], "ans": 0, "exp": "• <b>Thử màu ngọn lửa (Flame test):</b><br>- Lithium (Li): màu đỏ tía (đỏ carmine).<br>- Sodium (Na): màu vàng tươi (vàng rực).<br>- Potassium (K): màu tím nhạt.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về tính chất vật lí và hoá học của kim loại nhóm IA:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Kim loại kiềm có nhiệt độ nóng chảy và nhiệt độ sôi thấp do liên kết kim loại yếu và bán kính nguyên tử lớn.", "Tất cả các kim loại kiềm đều tác dụng mãnh liệt với nước ngay ở nhiệt độ thường tạo hydroxide kiềm và giải phóng khí hydrogen.", "Hợp kim natri – kali (Na – K) ở thể lỏng ở nhiệt độ thường, được dùng làm chất trao đổi nhiệt trong một số lò phản ứng hạt nhân.", "Có thể dùng nước cất để dập tắt đám cháy kim loại natri khi xảy ra sự cố trong phòng thí nghiệm."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Liên kết kim loại yếu vì chỉ có 1e hoá trị trên bán kính lớn.<br>• <b>Ý b [Đúng]:</b> 2M + 2H<sub>2</sub>O → 2MOH + H<sub>2</sub> ↑.<br>• <b>Ý c [Đúng]:</b> Hợp kim Na-K (chất lỏng làm mát lò phản ứng).<br>• <b>Ý d [Sai]:</b> Tuyệt đối cấm dùng nước dập đám cháy kim loại kiềm vì Na phản ứng mãnh liệt với nước toả nhiệt cực lớn gây nổ dữ dội; phải dùng cát khô hoặc bình bột chuyên dụng.", "svgGraph": null}, {"q": "Ghép từng hợp chất quan trọng của kim loại kiềm (Cột A) với tên gọi thông dụng và ứng dụng chính (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["NaCl ➔ Muối ăn, nguyên liệu chính sản xuất xút, clo và nước Javel", "NaCl ➔ Baking soda (thuốc muối dạ dày, bột nở làm bánh mềm xốp)", "NaCl ➔ Soda làm mềm nước cứng, sản xuất thuỷ tinh và xà phòng", "NaCl ➔ Xút ăn da, bazơ mạnh dùng trong ngành giấy, dệt nhuộm và hoá chất"], "ans": 0, "exp": "• <b>1 - A:</b> NaCl là muối ăn.<br>• <b>2 - B:</b> NaHCO<sub>3</sub> là baking soda.<br>• <b>3 - C:</b> Na<sub>2</sub>CO<sub>3</sub> là soda công nghiệp.<br>• <b>4 - D:</b> NaOH là xút ăn da.", "svgGraph": null}, {"q": "Hoàn thiện nhận định về tính chất hoá học đặc trưng của kim loại kiềm:<br><i>\"Các kim loại kiềm có tính khử  [ ... ]  nhất trong các kim loại. Trong mọi hợp chất, kim loại kiềm luôn có số oxi hoá là  [ ... ] . Khi tác dụng với oxygen không khí, lithium tạo oxide Li₂O, còn sodium chủ yếu tạo peroxide có công thức là  [ ... ]  và potassium tạo  [ ... ]  KO₂.\"</i>", "opts": ["mạnh — +1 — Na₂O₂ — superoxide", "superoxide — Na₂O₂ — +1 — mạnh", "+1 — Na₂O₂ — superoxide — yếu", "Na₂O₂ — superoxide — yếu — +2"], "ans": 0, "exp": "• Kim loại kiềm có tính khử mạnh nhất, số oxi hoá duy nhất +1.<br>• Tạo peroxide Na<sub>2</sub>O<sub>2</sub> và superoxide KO<sub>2</sub>.", "svgGraph": null}, {"q": "Cho 4,6 gam kim loại sodium (Na) tác dụng hoàn toàn với nước dư. Thể tích khí H<sub>2</sub> thu được ở điều kiện chuẩn (25°C, 1 bar ứng với 24,79 L/mol) là bao nhiêu (cho Na=23)?", "opts": ["2,479 lít", "4,958 lít", "1,2395 lít", "3,7185 lít"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>2Na + 2H<sub>2</sub>O → 2NaOH + H<sub>2</sub> ↑<br>• <b>Tính toán:</b><br>n(Na) = 4,6 / 23 = 0,2 mol.<br>n(H<sub>2</sub>) = 0,2 / 2 = 0,1 mol.<br>Thể tích khí H<sub>2</sub> ở đkc = 0,1 · 24,79 = 2,479 lít.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Kim loại nào trong nhóm IA được ứng dụng làm tế bào quang điện (biến đổi trực tiếp quang năng thành điện năng) nhờ có năng lượng ion hoá rất thấp dễ bứt electron khi bị chiếu sáng?", "opts": ["Caesium (Cs)", "Lithium (Li)", "Sodium (Na)", "Potassium (K)"], "ans": 0, "exp": "• Caesium (Cs) có bán kính nguyên tử rất lớn và năng lượng ion hoá nhỏ nhất trong số các nguyên tố bền, ánh sáng nhìn thấy chiếu vào đủ năng lượng giải phóng electron (hiệu ứng quang điện ngoài).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về muối hydrogencarbonate và carbonate của kim loại kiềm:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Sodium hydrogencarbonate (NaHCO₃) có tính lưỡng tính: vừa tác dụng với dung dịch acid vừa tác dụng với dung dịch kiềm mạnh.", "Khi đun nóng, dung dịch NaHCO₃ bị nhiệt phân giải phóng khí CO₂ và chuyển thành muối trung hoà Na₂CO₃.", "Muối Na₂CO₃ dễ bị nhiệt phân khi đun nóng ở nhiệt độ ngọn lửa đèn cồn tạo Na₂O và CO₂.", "Dung dịch Na₂CO₃ trong nước có môi trường kiềm (pH > 7) do ion CO₃²⁻ bị thuỷ phân tạo ion OH⁻."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> HCO<sub>3</sub><sup>-</sup> nhận H<sup>+</sup> tạo H<sub>2</sub>O + CO<sub>2</sub>, nhường H<sup>+</sup> tạo CO<sub>3</sub><sup>2-</sup>.<br>• <b>Ý b [Đúng]:</b> 2NaHCO<sub>3</sub> ⎯(t°)→ Na<sub>2</sub>CO<sub>3</sub> + CO<sub>2</sub> + H<sub>2</sub>O.<br>• <b>Ý c [Sai]:</b> Carbonate của kim loại kiềm (Na<sub>2</sub>CO<sub>3</sub>, K<sub>2</sub>CO<sub>3</sub>) rất bền nhiệt, nóng chảy ở hơn 850°C mà không bị nhiệt phân.<br>• <b>Ý d [Đúng]:</b> CO<sub>3</sub><sup>2-</sup> + H<sub>2</sub>O ⇌ HCO<sub>3</sub><sup>-</sup> + OH<sup>-</sup>.", "svgGraph": null}, {"q": "Để phân biệt hai bột màu trắng đựng riêng biệt trong hai lọ mất nhãn: Na<sub>2</sub>CO<sub>3</sub> và NaCl, thuốc thử đơn giản nhất chỉ dùng một lần là:", "opts": ["Dung dịch acid HCl (Na<sub>2</sub>CO<sub>3</sub> sủi bọt khí mạnh, NaCl không hiện tượng)", "Dung dịch NaOH", "Quỳ tím ẩm", "Dung dịch phenolphthalein"], "ans": 0, "exp": "• <b>Hiện tượng:</b><br>- Na<sub>2</sub>CO<sub>3</sub> + 2HCl → 2NaCl + CO<sub>2</sub> ↑ + H<sub>2</sub>O (sủi bọt khí không màu không mùi).<br>- NaCl không phản ứng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "25": [{"q": "Các kim loại nhóm IIA (Be, Mg, Ca, Sr, Ba) đều có cấu hình electron lớp ngoài cùng chung là:", "opts": ["ns<sup>2</sup>", "ns<sup>1</sup>", "ns<sup>2</sup> np<sup>2</sup>", "(n-1)d<sup>2</sup> ns<sup>2</sup>"], "ans": 0, "exp": "• <b>Cấu tạo nguyên tử nhóm IIA:</b> Các nguyên tử kim loại kiềm thổ có 2 electron hoá trị ở phân lớp s lớp ngoài cùng (ns<sup>2</sup>).<br>• Trong các phản ứng hoá học, chúng dễ dàng nhường cả 2 electron để đạt cấu hình khí hiếm bền vững, tạo cation M<sup>2+</sup> (số oxi hoá +2 trong mọi hợp chất).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">CÁC HỢP CHẤT CỦA CALCIUM VÀ HIỆN TƯỢNG NƯỚC CỨNG</text>\n  <!-- Cycle of Limestone -->\n  <g transform=\"translate(60, 45)\">\n    <!-- CaCO3 -->\n    <rect x=\"0\" y=\"0\" width=\"100\" height=\"40\" rx=\"6\" fill=\"rgba(14,165,233,0.18)\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n    <text x=\"50\" y=\"25\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">CaCO₃ (Đá vôi)</text>\n    <!-- Arrow right nung vôi -->\n    <path d=\"M 105 20 L 165 20 M 155 15 L 165 20\" stroke=\"#fbbf24\" stroke-width=\"2\"/>\n    <text x=\"135\" y=\"14\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"9.5\">t° (nung)</text>\n    <!-- CaO -->\n    <rect x=\"170\" y=\"0\" width=\"100\" height=\"40\" rx=\"6\" fill=\"rgba(244,63,94,0.18)\" stroke=\"#f43f5e\" stroke-width=\"1.8\"/>\n    <text x=\"220\" y=\"25\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"12\" font-weight=\"bold\">CaO (Vôi sống)</text>\n    <!-- Arrow down tôi vôi -->\n    <path d=\"M 220 45 L 220 95 M 215 85 L 220 95\" stroke=\"#34d399\" stroke-width=\"2\"/>\n    <text x=\"255\" y=\"72\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"9.5\">+ H₂O (tôi vôi)</text>\n    <!-- Ca(OH)2 -->\n    <rect x=\"170\" y=\"100\" width=\"100\" height=\"40\" rx=\"6\" fill=\"rgba(52,211,153,0.18)\" stroke=\"#10b981\" stroke-width=\"1.8\"/>\n    <text x=\"220\" y=\"125\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"11.5\" font-weight=\"bold\">Ca(OH)₂ (Vôi tôi)</text>\n    <!-- Arrow left CO2 -->\n    <path d=\"M 165 120 L 105 120 M 115 125 L 105 120\" stroke=\"#a78bfa\" stroke-width=\"2\"/>\n    <text x=\"135\" y=\"135\" text-anchor=\"middle\" fill=\"#a78bfa\" font-size=\"9.5\">+ CO₂ (vẩn đục)</text>\n  </g>\n  <!-- Hard water Box -->\n  <g transform=\"translate(350, 45)\">\n    <rect width=\"140\" height=\"140\" rx=\"8\" fill=\"rgba(30,41,59,0.7)\" stroke=\"rgba(255,255,255,0.12)\"/>\n    <text x=\"70\" y=\"22\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11.5\" font-weight=\"bold\">NƯỚC CỨNG</text>\n    <text x=\"15\" y=\"45\" fill=\"#f8fafc\" font-size=\"10.5\">• Chứa nhiều <tspan fill=\"#38bdf8\" font-weight=\"bold\">Ca²⁺, Mg²⁺</tspan></text>\n    <text x=\"15\" y=\"65\" fill=\"#f8fafc\" font-size=\"10\">• Tạm thời: HCO₃⁻</text>\n    <text x=\"15\" y=\"82\" fill=\"#f8fafc\" font-size=\"10\">• Vĩnh cửu: Cl⁻, SO₄²⁻</text>\n    <text x=\"15\" y=\"105\" fill=\"#34d399\" font-size=\"10.5\" font-weight=\"bold\">Cách làm mềm:</text>\n    <text x=\"15\" y=\"122\" fill=\"#cbd5e1\" font-size=\"9.5\">Đun sôi, dùng Na₂CO₃/Ca(OH)₂</text>\n  </g>\n  <!-- Karst cave explanation -->\n  <rect x=\"30\" y=\"195\" width=\"460\" height=\"26\" rx=\"4\" fill=\"rgba(30,41,59,0.9)\"/>\n  <text x=\"260\" y=\"213\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"10.5\">Sự xâm thực đá vôi tạo hang động: CaCO₃ + CO₂ + H₂O ⇌ Ca(HCO₃)₂ (thuận nghịch)</text>\n</svg>"}, {"q": "Nước cứng là nước chứa nhiều các cation nào sau đây?", "opts": ["Ca<sup>2+</sup> và Mg<sup>2+</sup>", "Na<sup>+</sup> và K<sup>+</sup>", "Fe<sup>2+</sup> và Cu<sup>2+</sup>", "Al<sup>3+</sup> và Zn<sup>2+</sup>"], "ans": 0, "exp": "• <b>Định nghĩa nước cứng:</b> Nước chứa nhiều ion Ca<sup>2+</sup> và Mg<sup>2+</sup> gọi là nước cứng.<br>• Nước chứa ít hoặc không chứa ion Ca<sup>2+</sup>, Mg<sup>2+</sup> gọi là nước mềm.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Thạch cao nung có công thức hoá học là CaSO<sub>4</sub>·0,5H<sub>2</sub>O (hoặc 2CaSO<sub>4</sub>·H<sub>2</sub>O), khi nhào với nước tạo thành chất dẻo nhanh chóng đông cứng lại, được ứng dụng để:", "opts": ["Đúc tượng, làm khuôn đúc và bó bột cố định xương gãy trong y tế", "Làm mềm nước cứng vĩnh cửu", "Sản xuất vôi sống xây nhà", "Bón ruộng khử chua đất trồng trọt"], "ans": 0, "exp": "• <b>3 dạng thạch cao:</b><br>- Thạch cao sống: CaSO<sub>4</sub>·2H<sub>2</sub>O (trong tự nhiên).<br>- Thạch cao nung: CaSO<sub>4</sub>·0,5H<sub>2</sub>O (nung thạch cao sống ở 160°C), khi nhào nước nở thể tích và đông cứng nhanh nên dùng đúc tượng, làm phấn viết, bó bột.<br>- Thạch cao khan: CaSO<sub>4</sub>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng của kim loại kiềm thổ với nước ở nhiệt độ phòng:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Beryllium (Be) không tác dụng với nước ở bất kì nhiệt độ nào do có màng oxide rất bền bảo vệ.", "Magnesium (Mg) tác dụng chậm với nước ở nhiệt độ thường nhưng phản ứng nhanh hơn với nước nóng tạo dung dịch base yếu Mg(OH)₂.", "Calcium (Ca), Strontium (Sr) và Barium (Ba) phản ứng mãnh liệt với nước ở nhiệt độ thường giải phóng khí H₂.", "Tất cả các kim loại nhóm IIA đều có nhiệt độ nóng chảy thấp hơn kim loại nhóm IA tương ứng cùng chu kì."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Be trơ với nước.<br>• <b>Ý b [Đúng]:</b> Mg tác dụng chậm nước lạnh, nhanh với nước nóng.<br>• <b>Ý c [Đúng]:</b> Ca, Sr, Ba phản ứng mãnh liệt: M + 2H<sub>2</sub>O → M(OH)<sub>2</sub> + H<sub>2</sub> ↑.<br>• <b>Ý d [Sai]:</b> Kim loại kiềm thổ có 2e hoá trị, mật độ điện tích lớn hơn nên liên kết kim loại bền hơn nhóm IA → nhiệt độ nóng chảy cao hơn nhóm IA tương ứng.", "svgGraph": null}, {"q": "Ghép từng loại thạch cao (Cột A) với công thức phân tử và đặc điểm tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Thạch cao sống ➔ CaSO₄·2H₂O (khoáng vật tự nhiên bền vững)", "Thạch cao sống ➔ CaSO₄·0,5H₂O (dùng đúc khuôn, nặn tượng, bó bột y tế)", "Thạch cao sống ➔ CaSO₄ (sản phẩm khi nung thạch cao ở nhiệt độ cao trên 350°C)", "Thạch cao sống ➔ CaCO₃ (thành phần chính của núi đá vôi, vỏ sò, san hô)"], "ans": 0, "exp": "• <b>1 - A:</b> Thạch cao sống: CaSO<sub>4</sub>·2H<sub>2</sub>O.<br>• <b>2 - B:</b> Thạch cao nung: CaSO<sub>4</sub>·0,5H<sub>2</sub>O.<br>• <b>3 - C:</b> Thạch cao khan: CaSO<sub>4</sub>.<br>• <b>4 - D:</b> Đá vôi: CaCO<sub>3</sub>.", "svgGraph": null}, {"q": "Hoàn thiện bản chất sự xâm thực đá vôi tạo hang động thạch nhũ tự nhiên (như động Phong Nha, Vịnh Hạ Long):<br><i>\"Nước mưa hoà tan khí CO₂ trong khí quyển tạo dung dịch acid yếu hoà tan chậm đá vôi theo phản ứng: CaCO₃ + CO₂ + H₂O ➔  [ ... ] . Khi dung dịch này nhỏ giọt và mất dần khí CO₂, phản ứng xảy ra theo chiều ngược lại kết tủa tạo thành các cột  [ ... ]  tuyệt đẹp. Đây là phản ứng  [ ... ] .\"</i>", "opts": ["Ca(HCO₃)₂ — thạch nhũ — thuận nghịch", "thuận nghịch — thạch nhũ — Ca(HCO₃)₂", "thạch nhũ — thuận nghịch — CaO — một chiều", "thuận nghịch — CaO — một chiều — CaSO₄"], "ans": 0, "exp": "• Phương trình hoà tan và tái kết tủa đá vôi: CaCO<sub>3</sub> + CO<sub>2</sub> + H<sub>2</sub>O ⇌ Ca(HCO<sub>3</sub>)<sub>2</sub>.", "svgGraph": null}, {"q": "Chất nào sau đây có thể dùng để làm mềm CẢ HAI LOẠI nước cứng (nước cứng tạm thời và nước cứng vĩnh cửu)?", "opts": ["Sodium carbonate (Na<sub>2</sub>CO<sub>3</sub>) hoặc Sodium phosphate (Na<sub>3</sub>PO<sub>4</sub>)", "Dung dịch acid HCl", "Dung dịch muối ăn NaCl", "Khí carbon dioxide CO<sub>2</sub>"], "ans": 0, "exp": "• <b>Nguyên tắc làm mềm nước cứng:</b> Làm giảm nồng độ ion Ca<sup>2+</sup> và Mg<sup>2+</sup> bằng cách kết tủa chúng.<br>• Ion CO<sub>3</sub><sup>2-</sup> và PO<sub>4</sub><sup>3-</sup> tạo kết tủa trắng với cả Ca<sup>2+</sup> và Mg<sup>2+</sup> (CaCO<sub>3</sub> ↓, MgCO<sub>3</sub> ↓, Ca<sub>3</sub>(PO<sub>4</sub>)<sub>2</sub> ↓) trong mọi loại nước cứng (tạm thời, vĩnh cửu, toàn phần).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Tác hại nào sau đây KHÔNG PHẢI do nước cứng gây ra trong đời sống và sản xuất?", "opts": ["Làm tăng khả năng hoà tan chất giặt rửa giúp quần áo nhanh sạch hơn.", "Gây đóng cặn vôi ở đáy ấm đun nước, nồi hơi công nghiệp gây nguy cơ nổ nồi hơi.", "Làm tắc nghẽn các đường ống dẫn nước nóng do cặn bám.", "Làm giảm bọt xà phòng, gây kết tủa làm ố vàng và mục sợi vải khi giặt."], "ans": 0, "exp": "• <b>Phân tích:</b> Nước cứng phản ứng với xà phòng tạo muối kết tủa không tan làm hao tốn xà phòng và bẩn quần áo, chứ không hề làm tăng khả năng giặt sạch.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về phương pháp làm mềm nước cứng:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Đun sôi nước chỉ có thể làm mềm được nước cứng tạm thời (chứa ion Ca²⁺, Mg²⁺ và HCO₃⁻).", "Có thể dùng một lượng vôi tôi Ca(OH)₂ vừa đủ để làm mềm nước cứng tạm thời.", "Phương pháp trao đổi ion dùng hạt nhựa cationite thay thế các cation Ca²⁺, Mg²⁺ bằng ion Na⁺ hoặc H⁺ để làm mềm nước sinh hoạt hiện đại.", "Nước cứng vĩnh cửu có thể làm mềm hoàn toàn bằng cách chỉ cần đun sôi sùng sục trong 10 phút."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Đun sôi phân huỷ HCO<sub>3</sub><sup>-</sup> tạo kết tủa CaCO<sub>3</sub>.<br>• <b>Ý b [Đúng]:</b> Ca(HCO<sub>3</sub>)<sub>2</sub> + Ca(OH)<sub>2</sub> → 2CaCO<sub>3</sub> ↓ + 2H<sub>2</sub>O.<br>• <b>Ý c [Đúng]:</b> Cột lọc trao đổi ion hiện đại.<br>• <b>Ý d [Sai]:</b> Nước cứng vĩnh cửu chứa Cl<sup>-</sup>, SO<sub>4</sub><sup>2-</sup> đun sôi không tạo kết tủa được, bắt buộc phải dùng hoá chất kết tủa (Na<sub>2</sub>CO<sub>3</sub>) hoặc trao đổi ion.", "svgGraph": null}, {"q": "Nhiệt phân hoàn toàn 20 gam đá vôi chứa 90% CaCO<sub>3</sub> về khối lượng (tạp chất trơ không phản ứng). Thể tích khí CO<sub>2</sub> thu được ở điều kiện chuẩn (25°C, 1 bar ứng với 24,79 L/mol) là bao nhiêu (cho Ca=40, C=12, O=16)?", "opts": ["4,4622 lít", "4,9580 lít", "2,4790 lít", "3,7185 lít"], "ans": 0, "exp": "• <b>Phương trình nhiệt phân đá vôi:</b><br>CaCO<sub>3</sub> ⎯(t°)→ CaO + CO<sub>2</sub> ↑<br>• <b>Tính toán:</b><br>m(CaCO<sub>3</sub> nguyên chất) = 20 · 90% = 18 gam.<br>n(CaCO<sub>3</sub>) = 18 / 100 = 0,18 mol.<br>n(CO<sub>2</sub>) = n(CaCO<sub>3</sub>) = 0,18 mol.<br>V(CO<sub>2</sub>) = 0,18 · 24,79 = 4,4622 lít.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "26": [{"q": "So sánh giữa kim loại kiềm (nhóm IA) và kim loại kiềm thổ (nhóm IIA) trong cùng một chu kì:", "opts": ["Kim loại kiềm có bán kính nguyên tử lớn hơn và tính khử mạnh hơn kim loại kiềm thổ.", "Kim loại kiềm thổ có tính khử mạnh hơn kim loại kiềm.", "Kim loại kiềm có nhiệt độ nóng chảy cao hơn kim loại kiềm thổ.", "Kim loại kiềm có 2 electron hoá trị ngoài cùng."], "ans": 0, "exp": "• <b>Quy luật biến đổi trong chu kì:</b> Từ trái sang phải (IA → IIA): điện tích hạt nhân tăng, lực hút mạnh hơn nên bán kính nguyên tử giảm dần, năng lượng ion hoá tăng dần, tính khử giảm dần.<br>• Do đó kim loại kiềm luôn có bán kính lớn nhất và tính khử mạnh nhất chu kì.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Một mẫu nước cứng có chứa các ion: Ca<sup>2+</sup>, Mg<sup>2+</sup>, Cl<sup>-</sup>, SO<sub>4</sub><sup>2-</sup>. Mẫu nước này thuộc loại nước cứng nào?", "opts": ["Nước cứng vĩnh cửu", "Nước cứng tạm thời", "Nước mềm", "Nước cất tinh khiết"], "ans": 0, "exp": "• <b>Phân loại nước cứng:</b><br>- Tạm thời: Chứa Ca<sup>2+</sup>, Mg<sup>2+</sup> và anion HCO<sub>3</sub><sup>-</sup>.<br>- Vĩnh cửu: Chứa Ca<sup>2+</sup>, Mg<sup>2+</sup> và anion Cl<sup>-</sup>, SO<sub>4</sub><sup>2-</sup> (không chứa HCO<sub>3</sub><sup>-</sup>).<br>- Toàn phần: Chứa cả HCO<sub>3</sub><sup>-</sup> và Cl<sup>-</sup>/SO<sub>4</sub><sup>2-</sup>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Dung dịch chất nào sau đây phản ứng được với dung dịch Ba(HCO<sub>3</sub>)<sub>2</sub> vừa tạo kết tủa trắng vừa giải phóng bọt khí không màu?", "opts": ["Dung dịch H<sub>2</sub>SO<sub>4</sub> loãng", "Dung dịch NaOH", "Dung dịch HCl", "Dung dịch NaCl"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>Ba(HCO<sub>3</sub>)<sub>2</sub> + H<sub>2</sub>SO<sub>4</sub> → BaSO<sub>4</sub> ↓ (kết tủa trắng) + 2CO<sub>2</sub> ↑ (bọt khí không màu) + 2H<sub>2</sub>O.<br>• Phản ứng đồng thời tạo kết tủa bền BaSO<sub>4</sub> và giải phóng khí CO<sub>2</sub>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các mệnh đề tổng kết về nguyên tố nhóm IA và IIA:<br>Phát biểu nào sau đây là <b>ĐÚNG</b>?", "opts": ["Kim loại kiềm và kiềm thổ đều thuộc khối nguyên tố s trong bảng tuần hoàn.", "Tất cả các hợp chất của kim loại kiềm đều tan rất tốt trong nước.", "Độ tan của các hydroxide kim loại kiềm thổ tăng dần từ Mg(OH)₂ đến Ba(OH)₂.", "Có thể dùng dung dịch Na₂CO₃ để làm mềm cả nước cứng tạm thời và nước cứng vĩnh cửu."], "ans": 0, "exp": "• <b>Ý a [Đúng]:</b> Cấu hình electron ns<sup>1</sup> và ns<sup>2</sup> là nguyên tố s.<br>• <b>Ý b [Đúng]:</b> Muối và hydroxide nhóm IA đều tan tốt.<br>• <b>Ý c [Đúng]:</b> Mg(OH)<sub>2</sub> không tan, Ca(OH)<sub>2</sub> ít tan, Ba(OH)<sub>2</sub> tan nhiều base mạnh.<br>• <b>Ý d [Đúng]:</b> Na<sub>2</sub>CO<sub>3</sub> là chất làm mềm nước cứng phổ quát toàn diện.", "svgGraph": null}, {"q": "Ghép từng kim loại kiềm và kiềm thổ (Cột A) với màu ngọn lửa đặc trưng khi thử nghiệm (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Sodium (Na) ➔ Màu vàng tươi sáng chói", "Sodium (Na) ➔ Màu tím nhạt", "Sodium (Na) ➔ Màu đỏ da cam (đỏ gạch)", "Sodium (Na) ➔ Màu lục vàng (xanh táo)"], "ans": 0, "exp": "• <b>1 - A:</b> Na cho màu vàng.<br>• <b>2 - B:</b> K cho màu tím.<br>• <b>3 - C:</b> Ca cho màu đỏ da cam.<br>• <b>4 - D:</b> Ba cho màu lục vàng.", "svgGraph": null}, {"q": "Hoàn thiện tổng kết kiến thức Chương 7:<br><i>\"Nguyên tố nhóm IA có cấu hình ns¹, có tính khử  [ ... ]  nhất bảng tuần hoàn. Nguyên tố nhóm IIA có cấu hình ns², tạo hợp chất có số oxi hoá duy nhất là  [ ... ] . Nước cứng chứa nhiều Ca²⁺ và Mg²⁺ được chia làm nước cứng  [ ... ]  và nước cứng  [ ... ] .\"</i>", "opts": ["mạnh — +2 — tạm thời — vĩnh cửu", "vĩnh cửu — tạm thời — +2 — mạnh", "+2 — tạm thời — vĩnh cửu — yếu", "tạm thời — vĩnh cửu — yếu — +1"], "ans": 0, "exp": "• Kim loại kiềm tính khử mạnh nhất; kiềm thổ số oxi hoá +2; phân loại nước cứng tạm thời và vĩnh cửu.", "svgGraph": null}, {"q": "Sục từ từ đến dư khí CO<sub>2</sub> vào cốc chứa dung dịch nước vôi trong Ca(OH)<sub>2</sub>. Hiện tượng quan sát được theo thứ tự là gì?", "opts": ["Dung dịch bị vẩn đục trắng tăng dần đến cực đại, sau đó kết tủa tan dần đến dung dịch trong suốt trở lại.", "Dung dịch lập tức xuất hiện kết tủa màu vàng không bao giờ tan.", "Dung dịch chuyển sang màu xanh lam đậm.", "Không có hiện tượng gì xảy ra."], "ans": 0, "exp": "• <b>Diễn biến 2 giai đoạn:</b><br>1. Ban đầu: CO<sub>2</sub> + Ca(OH)<sub>2</sub> → CaCO<sub>3</sub> ↓ (kết tủa trắng làm đục nước vôi).<br>2. Khi Ca(OH)<sub>2</sub> hết, CO<sub>2</sub> dư tiếp tục phản ứng:<br>CaCO<sub>3</sub> + CO<sub>2</sub> + H<sub>2</sub>O → Ca(HCO<sub>3</sub>)<sub>2</sub> (muối tan làm kết tủa tan hết, dung dịch trong suốt).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Hoà tan hoàn toàn 10,0 gam hỗn hợp hai kim loại kiềm thuộc hai chu kì kế tiếp nhau vào nước dư, thu được 3,7185 lít khí H<sub>2</sub> (đkc, 24,79 L/mol). Hai kim loại kiềm đó là (cho Li=7, Na=23, K=39, Rb=85,5)?", "opts": ["Sodium (Na = 23) và Potassium (K = 39)", "Lithium (Li = 7) và Sodium (Na = 23)", "Potassium (K = 39) và Rubidium (Rb = 85,5)", "Rubidium (Rb = 85,5) và Caesium (Cs = 133)"], "ans": 0, "exp": "• <b>Tính toán đại số:</b><br>Số mol H<sub>2</sub> = 3,7185 / 24,79 = 0,15 mol.<br>2M̄ + 2H<sub>2</sub>O → 2M̄OH + H<sub>2</sub> ↑<br>Số mol hỗn hợp kim loại = 2 · 0,15 = 0,3 mol.<br>Khối lượng mol trung bình: M̄ = 10,0 / 0,3 = 33,33 g/mol.<br>Vì hai kim loại thuộc 2 chu kì kế tiếp nhau trong nhóm IA:<br>M<sub>1</sub> < 33,33 < M<sub>2</sub> → M<sub>1</sub> là Na (23) và M<sub>2</sub> là K (39).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu ứng dụng thực tế của hợp chất kim loại kiềm và kiềm thổ:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Dung dịch bão hoà của NaCl trong nước (nước muối sinh lí 0,9%) có tính sát khuẩn nhẹ, dùng súc họng và rửa vết thương.", "Magnesium hydroxide Mg(OH)₂ và aluminium hydroxide Al(OH)₃ được dùng làm thuốc kháng acid chữa đau dạ dày do thừa dịch vị HCl.", "Bột nở NaHCO₃ sinh khí CO₂ khi nướng bánh giúp bánh nở phồng, mềm xốp và thơm ngon.", "Vôi sống CaO được rải trực tiếp xuống ao nuôi tôm cá với số lượng vô hạn mà không làm ảnh hưởng đến độ pH của nước ao."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Dung dịch NaCl 0,9% đẳng trương y tế.<br>• <b>Ý b [Đúng]:</b> Thuốc antacid trung hoà acid dạ dày.<br>• <b>Ý c [Đúng]:</b> Baking soda tạo khí CO<sub>2</sub> làm xốp bánh.<br>• <b>Ý d [Sai]:</b> CaO tác dụng nước sinh Ca(OH)<sub>2</sub> kiềm mạnh làm pH nước tăng vọt, chỉ được rải lượng tính toán vừa đủ khử phèn, rải quá mức sẽ làm chết tôm cá.", "svgGraph": null}, {"q": "Một mẫu nước chứa các ion sau: 0,02 mol Ca<sup>2+</sup>; 0,01 mol Mg<sup>2+</sup>; 0,04 mol HCO<sub>3</sub><sup>-</sup> và x mol Cl<sup>-</sup>. Giá trị của x bảo đảm định luật bảo toàn điện tích là bao nhiêu?", "opts": ["0,02 mol", "0,01 mol", "0,03 mol", "0,04 mol"], "ans": 0, "exp": "• <b>Định luật bảo toàn điện tích trong dung dịch:</b><br>Tổng điện tích dương = Tổng điện tích âm<br>2 · n(Ca<sup>2+</sup>) + 2 · n(Mg<sup>2+</sup>) = 1 · n(HCO<sub>3</sub><sup>-</sup>) + 1 · n(Cl<sup>-</sup>)<br>2 · 0,02 + 2 · 0,01 = 0,04 + x<br>0,04 + 0,02 = 0,04 + x → x = 0,02 mol.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "27": [{"q": "Các kim loại chuyển tiếp dãy thứ nhất gồm các nguyên tố từ scandium (Sc, Z=21) đến đồng (Cu, Z=29) thuộc chu kì 4 và có đặc điểm cấu hình electron là:", "opts": ["Electron đang điền dở vào phân lớp 3d có dạng [Ar] 3d<sup>1-10</sup> 4s<sup>1-2</sup>", "Electron điền vào phân lớp 4p ngoài cùng", "Chỉ có electron hoá trị ở phân lớp s", "Có cấu hình electron bão hoà hoàn toàn giống khí hiếm"], "ans": 0, "exp": "• <b>Định nghĩa kim loại chuyển tiếp d:</b> Các nguyên tố d có electron hoá trị đang điền vào phân lớp (n-1)d. Dãy thứ nhất gồm 9 nguyên tố từ Sc đến Cu có cấu hình electron tổng quát là [Ar] 3d<sup>1-10</sup> 4s<sup>1-2</sup>.<br>• Hai trường hợp ngoại lệ bán bão hoà và bão hoà sớm: Cr ([Ar] 3d<sup>5</sup> 4s<sup>1</sup>) và Cu ([Ar] 3d<sup>10</sup> 4s<sup>1</sup>).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">MÀU SẮC ĐẶC TRƯNG CỦA CÁC CATION KIM LOẠI CHUYỂN TIẾP</text>\n  <!-- 4 Colored Solution Tubes -->\n  <!-- Tube 1: Cu2+ Blue -->\n  <g transform=\"translate(60, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"65\" height=\"110\" rx=\"6\" fill=\"rgba(14,165,233,0.15)\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n    <rect x=\"2\" y=\"35\" width=\"61\" height=\"73\" rx=\"4\" fill=\"#0284c7\" opacity=\"0.85\"/>\n    <text x=\"32\" y=\"130\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"12\" font-weight=\"bold\">Cu²⁺</text>\n    <text x=\"32\" y=\"145\" text-anchor=\"middle\" fill=\"#7dd3fc\" font-size=\"10\">Xanh lam</text>\n  </g>\n  <!-- Tube 2: Fe3+ Yellow-Brown -->\n  <g transform=\"translate(160, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"65\" height=\"110\" rx=\"6\" fill=\"rgba(234,179,8,0.15)\" stroke=\"#eab308\" stroke-width=\"1.8\"/>\n    <rect x=\"2\" y=\"35\" width=\"61\" height=\"73\" rx=\"4\" fill=\"#b45309\" opacity=\"0.85\"/>\n    <text x=\"32\" y=\"130\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">Fe³⁺</text>\n    <text x=\"32\" y=\"145\" text-anchor=\"middle\" fill=\"#fef08a\" font-size=\"10\">Vàng nâu</text>\n  </g>\n  <!-- Tube 3: Cr3+ Green -->\n  <g transform=\"translate(260, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"65\" height=\"110\" rx=\"6\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"1.8\"/>\n    <rect x=\"2\" y=\"35\" width=\"61\" height=\"73\" rx=\"4\" fill=\"#047857\" opacity=\"0.85\"/>\n    <text x=\"32\" y=\"130\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Cr³⁺</text>\n    <text x=\"32\" y=\"145\" text-anchor=\"middle\" fill=\"#a7f3d0\" font-size=\"10\">Xanh lục</text>\n  </g>\n  <!-- Tube 4: MnO4- Purple -->\n  <g transform=\"translate(360, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"65\" height=\"110\" rx=\"6\" fill=\"rgba(168,85,247,0.15)\" stroke=\"#a855f7\" stroke-width=\"1.8\"/>\n    <rect x=\"2\" y=\"35\" width=\"61\" height=\"73\" rx=\"4\" fill=\"#7e22ce\" opacity=\"0.85\"/>\n    <text x=\"32\" y=\"130\" text-anchor=\"middle\" fill=\"#c084fc\" font-size=\"12\" font-weight=\"bold\">MnO₄⁻</text>\n    <text x=\"32\" y=\"145\" text-anchor=\"middle\" fill=\"#e9d5ff\" font-size=\"10\">Tím thẫm</text>\n  </g>\n  <!-- Reason explanation box -->\n  <rect x=\"40\" y=\"180\" width=\"440\" height=\"38\" rx=\"6\" fill=\"rgba(30,41,59,0.85)\" stroke=\"rgba(255,255,255,0.12)\"/>\n  <text x=\"260\" y=\"198\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"11\">Màu sắc xuất hiện do sự <tspan fill=\"#fbbf24\" font-weight=\"bold\">chuyển dịch electron d-d</tspan> hấp thụ một số bước sóng ánh sáng</text>\n  <text x=\"260\" y=\"212\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"10.5\">Khả năng thể hiện nhiều trạng thái oxi hoá phong phú: Fe (+2,+3), Mn (+2 ➔ +7), Cr (+2,+3,+6)</text>\n</svg>"}, {"q": "Cấu hình electron của nguyên tử chromium (Cr, Z = 24) ở trạng thái cơ bản là:", "opts": ["[Ar] 3d<sup>5</sup> 4s<sup>1</sup>", "[Ar] 3d<sup>4</sup> 4s<sup>2</sup>", "[Ar] 3d<sup>6</sup>", "[Ar] 4s<sup>2</sup> 4p<sup>4</sup>"], "ans": 0, "exp": "• <b>Hiện tượng bán bão hoà phân lớp d:</b> Theo thứ tự mức năng lượng lí thuyết là [Ar] 3d<sup>4</sup> 4s<sup>2</sup>, nhưng 1 electron từ 4s nhảy sang 3d để tạo phân lớp 3d<sup>5</sup> nửa bão hoà có tính đối xứng cầu và độ bền năng lượng cao hơn hẳn: [Ar] 3d<sup>5</sup> 4s<sup>1</sup>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nguyên tố nào trong dãy kim loại chuyển tiếp thứ nhất có khả năng thể hiện nhiều trạng thái oxi hoá dương nhất (từ +2 đến +7)?", "opts": ["Manganese (Mn, Z = 25)", "Iron (Fe, Z = 26)", "Cobalt (Co, Z = 27)", "Scandium (Sc, Z = 21)"], "ans": 0, "exp": "• Mn có cấu hình [Ar] 3d<sup>5</sup> 4s<sup>2</sup> với tổng cộng 7 electron hoá trị.<br>• Mn có thể nhường từ 2 đến toàn bộ 7 electron để tạo ra các trạng thái oxi hoá phong phú: +2 (Mn<sup>2+</sup>), +3 (Mn<sub>2</sub>O<sub>3</sub>), +4 (MnO<sub>2</sub>), +6 (MnO<sub>4</sub><sup>2-</sup>), +7 (KMnO<sub>4</sub>).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các đặc điểm của các kim loại chuyển tiếp dãy thứ nhất:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Hầu hết các kim loại chuyển tiếp có độ cứng cao, nhiệt độ nóng chảy cao và độ bền cơ học lớn do có sự tham gia của các electron d vào liên kết kim loại.", "Các cation kim loại chuyển tiếp có phân lớp d chưa bão hoà thường có màu sắc đặc trưng do sự chuyển dịch electron giữa các orbital d (chuyển dịch d-d).", "Ion Zn²⁺ ([Ar] 3d¹⁰) và Sc³⁺ ([Ar]) trong dung dịch nước có màu xanh lam rất đậm giống Cu²⁺.", "Nhiều kim loại chuyển tiếp và hợp chất của chúng được ứng dụng làm chất xúc tác quan trọng trong công nghiệp hoá chất."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Electron d tham gia liên kết làm kim loại chuyển tiếp cứng và bền hơn nhiều so với kim loại nhóm s.<br>• <b>Ý b [Đúng]:</b> Hiệu ứng d-d transition sinh màu sắc.<br>• <b>Ý c [Sai]:</b> Cation Sc<sup>3+</sup> (d<sup>0</sup> không có e d) và Zn<sup>2+</sup> (d<sup>10</sup> bão hoà không chuyển dịch được) nên các ion này hoàn toàn <b>không có màu</b> trong dung dịch nước.<br>• <b>Ý d [Đúng]:</b> V<sub>2</sub>O<sub>5</sub> (sản xuất H<sub>2</sub>SO<sub>4</sub>), Fe (tổng hợp NH<sub>3</sub>), Pt (xúc tác ô tô).", "svgGraph": null}, {"q": "Ghép từng cation kim loại chuyển tiếp (Cột A) với màu sắc đặc trưng của dung dịch nước (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Cu²⁺ ➔ Màu xanh lam tươi", "Cu²⁺ ➔ Màu vàng nâu (vàng rơm)", "Cu²⁺ ➔ Màu xanh lục", "Cu²⁺ ➔ Màu xanh nhạt (xanh nõn chuối)"], "ans": 0, "exp": "• <b>1 - A:</b> Cu<sup>2+</sup> xanh lam.<br>• <b>2 - B:</b> Fe<sup>3+</sup> vàng nâu.<br>• <b>3 - C:</b> Cr<sup>3+</sup> xanh lục.<br>• <b>4 - D:</b> Fe<sup>2+</sup> xanh nhạt.", "svgGraph": null}, {"q": "Hoàn thiện đặc điểm kim loại chuyển tiếp dãy thứ nhất:<br><i>\"Kim loại chuyển tiếp dãy thứ nhất gồm các nguyên tố thuộc khối  [ ... ]  chu kì 4. Chúng có đặc tính thể hiện  [ ... ]  trạng thái oxi hoá và các ion thường có  [ ... ]  đặc trưng. Cấu hình electron của Cu là [Ar] 3d¹⁰ 4s¹ đạt trạng thái  [ ... ]  phân lớp d.\"</i>", "opts": ["nguyên tố d — nhiều — màu sắc — bão hoà", "bão hoà — màu sắc — nhiều — nguyên tố d", "nhiều — màu sắc — bão hoà — nguyên tố p", "màu sắc — bão hoà — nguyên tố p — một"], "ans": 0, "exp": "• Khái quát kim loại khối d, đa dạng số oxi hoá, màu sắc ion d và phân lớp d<sup>10</sup> bão hoà của đồng.", "svgGraph": null}, {"q": "Cấu hình electron của cation Fe<sup>2+</sup> và Fe<sup>3+</sup> lần lượt là:", "opts": ["[Ar] 3d<sup>6</sup> và [Ar] 3d<sup>5</sup>", "[Ar] 3d<sup>4</sup> 4s<sup>2</sup> và [Ar] 3d<sup>5</sup>", "[Ar] 3d<sup>5</sup> 4s<sup>1</sup> và [Ar] 3d<sup>5</sup>", "[Ar] 3d<sup>6</sup> 4s<sup>2</sup> và [Ar] 3d<sup>6</sup> 4s<sup>1</sup>"], "ans": 0, "exp": "• Nguyên tử Fe (Z=26): [Ar] 3d<sup>6</sup> 4s<sup>2</sup>.<br>• Khi tạo cation, nguyên tử mất electron ở phân lớp 4s ngoài cùng trước:<br>- Fe<sup>2+</sup>: Mất 2e ở 4s → [Ar] 3d<sup>6</sup>.<br>- Fe<sup>3+</sup>: Mất tiếp 1e ở 3d → [Ar] 3d<sup>5</sup> (cấu hình bán bão hoà phân lớp d rất bền).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Trong phòng thí nghiệm và công nghiệp, chất xúc tác được sử dụng để chuyển hoá SO<sub>2</sub> thành SO<sub>3</sub> trong quá trình tiếp xúc sản xuất H<sub>2</sub>SO<sub>4</sub> là hợp chất của kim loại chuyển tiếp nào?", "opts": ["Vanadium (V) trong oxide V<sub>2</sub>O<sub>5</sub>", "Iron (Fe)", "Titanium (Ti)", "Nickel (Ni)"], "ans": 0, "exp": "• 2SO<sub>2</sub> + O<sub>2</sub> ⎯(V<sub>2</sub>O<sub>5</sub>, 450°C)⇌ 2SO<sub>3</sub>.<br>• Vanadium là kim loại chuyển tiếp dãy thứ nhất, oxide V<sub>2</sub>O<sub>5</sub> là chất xúc tác kinh điển trong công nghệ sản xuất sulfuric acid.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phản ứng oxi hoá - khử của các hợp chất chromium và manganese:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Hợp chất potassium permanganate (KMnO₄) có số oxi hoá của Mn là +7, là chất oxi hoá cực kì mạnh được dùng khử trùng và chuẩn độ oxi hoá khử.", "Trong môi trường acid mạnh, ion permanganate MnO₄⁻ màu tím bị khử về ion Mn²⁺ gần như không màu.", "Ion dichromate Cr₂O₇²⁻ có màu da cam trong môi trường acid, khi thêm kiềm chuyển hoá thành ion chromate CrO₄²⁻ có màu vàng tươi.", "Chromium(VI) oxide (CrO₃) là một basic oxide tan trong nước tạo dung dịch kiềm mạnh làm xanh quỳ tím."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> KMnO<sub>4</sub> là chất oxi hoá chuẩn.<br>• <b>Ý b [Đúng]:</b> MnO<sub>4</sub><sup>-</sup> (tím) + 8H<sup>+</sup> + 5e → Mn<sup>2+</sup> (không màu) + 4H<sub>2</sub>O.<br>• <b>Ý c [Đúng]:</b> Cân bằng màu da cam - vàng: Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + H<sub>2</sub>O ⇌ 2CrO<sub>4</sub><sup>2-</sup> + 2H<sup>+</sup>.<br>• <b>Ý d [Sai]:</b> CrO<sub>3</sub> là an acidic oxide rất mạnh, hút ẩm bốc cháy với chất hữu cơ và tan trong nước tạo acid cromic H<sub>2</sub>CrO<sub>4</sub> (pH rất nhỏ).", "svgGraph": null}, {"q": "Ion kim loại nào sau đây có cấu hình electron [Ar] 3d<sup>10</sup> (phân lớp d bão hoà hoàn toàn)?", "opts": ["Cu<sup>+</sup> và Zn<sup>2+</sup>", "Cu<sup>2+</sup>", "Fe<sup>2+</sup>", "Ni<sup>2+</sup>"], "ans": 0, "exp": "• Cu ([Ar] 3d<sup>10</sup> 4s<sup>1</sup>) nhường 1e thành Cu<sup>+</sup> ([Ar] 3d<sup>10</sup>).<br>• Zn ([Ar] 3d<sup>10</sup> 4s<sup>2</sup>) nhường 2e thành Zn<sup>2+</sup> ([Ar] 3d<sup>10</sup>).<br>• Cả hai đều có phân lớp 3d chứa tối đa 10 electron.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "28": [{"q": "Trong phức chất [Cu(NH<sub>3</sub>)<sub>4</sub>]SO<sub>4</sub>, nguyên tử/ion trung tâm và phối tử (ligand) lần lượt là:", "opts": ["Cation Cu<sup>2+</sup> là ion trung tâm; Phân tử NH<sub>3</sub> là phối tử", "Phân tử NH<sub>3</sub> là ion trung tâm; Cu<sup>2+</sup> là phối tử", "Ion SO<sub>4</sub><sup>2-</sup> là ion trung tâm; Cu<sup>2+</sup> là phối tử", "Nguyên tử Cu là ion trung tâm; Cả NH<sub>3</sub> và SO<sub>4</sub><sup>2-</sup> là phối tử"], "ans": 0, "exp": "• <b>Cấu trúc phức chất chuẩn:</b> Phức chất gồm cầu nội [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> và cầu ngoại SO<sub>4</sub><sup>2-</sup>.<br>- <b>Nguyên tử/ion trung tâm:</b> Cation kim loại Cu<sup>2+</sup> có orbital d trống.<br>- <b>Phối tử (ligand):</b> Phân tử NH<sub>3</sub> có cặp electron tự do trên nguyên tử N nhường vào orbital trống của Cu<sup>2+</sup> tạo liên kết phối trí.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">CẤU TRÚC PHỨC CHẤT VUÔNG PHẲNG [Cu(NH₃)₄]²⁺</text>\n  <!-- Central Ion Cu2+ -->\n  <g transform=\"translate(180, 115)\">\n    <!-- 4 coordinate bonds -->\n    <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"-65\" stroke=\"#34d399\" stroke-width=\"2.5\" stroke-dasharray=\"4,2\"/>\n    <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"65\" stroke=\"#34d399\" stroke-width=\"2.5\" stroke-dasharray=\"4,2\"/>\n    <line x1=\"0\" y1=\"0\" x2=\"-65\" y2=\"0\" stroke=\"#34d399\" stroke-width=\"2.5\" stroke-dasharray=\"4,2\"/>\n    <line x1=\"0\" y1=\"0\" x2=\"65\" y2=\"0\" stroke=\"#34d399\" stroke-width=\"2.5\" stroke-dasharray=\"4,2\"/>\n    <!-- Center circle Cu2+ -->\n    <circle cx=\"0\" cy=\"0\" r=\"22\" fill=\"#0284c7\" stroke=\"#38bdf8\" stroke-width=\"2.2\"/>\n    <text x=\"0\" y=\"5\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"12\" font-weight=\"bold\">Cu²⁺</text>\n    <!-- Ligands NH3 -->\n    <circle cx=\"0\" cy=\"-65\" r=\"15\" fill=\"#1e293b\" stroke=\"#34d399\" stroke-width=\"1.8\"/>\n    <text x=\"0\" y=\"-60\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"10.5\" font-weight=\"bold\">NH₃</text>\n    <circle cx=\"0\" cy=\"65\" r=\"15\" fill=\"#1e293b\" stroke=\"#34d399\" stroke-width=\"1.8\"/>\n    <text x=\"0\" y=\"70\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"10.5\" font-weight=\"bold\">NH₃</text>\n    <circle cx=\"-65\" cy=\"0\" r=\"15\" fill=\"#1e293b\" stroke=\"#34d399\" stroke-width=\"1.8\"/>\n    <text x=\"-65\" y=\"4\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"10.5\" font-weight=\"bold\">NH₃</text>\n    <circle cx=\"65\" cy=\"0\" r=\"15\" fill=\"#1e293b\" stroke=\"#34d399\" stroke-width=\"1.8\"/>\n    <text x=\"65\" y=\"4\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"10.5\" font-weight=\"bold\">NH₃</text>\n    <!-- Bracket 2+ -->\n    <path d=\"M -90 -75 L -98 -75 L -98 75 L -90 75\" fill=\"none\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n    <path d=\"M 90 -75 L 98 -75 L 98 75 L 90 75\" fill=\"none\" stroke=\"#f8fafc\" stroke-width=\"2\"/>\n    <text x=\"106\" y=\"-70\" fill=\"#fbbf24\" font-size=\"14\" font-weight=\"bold\">2+</text>\n  </g>\n  <!-- Geometry Info -->\n  <g transform=\"translate(340, 45)\">\n    <rect width=\"150\" height=\"135\" rx=\"8\" fill=\"rgba(30,41,59,0.8)\" stroke=\"rgba(255,255,255,0.12)\"/>\n    <text x=\"75\" y=\"24\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"12\" font-weight=\"bold\">THÀNH PHẦN</text>\n    <text x=\"15\" y=\"50\" fill=\"#38bdf8\" font-size=\"11\">• Số phối trí: <tspan fill=\"#ffffff\" font-weight=\"bold\">4</tspan></text>\n    <text x=\"15\" y=\"72\" fill=\"#34d399\" font-size=\"11\">• Hình học: <tspan fill=\"#ffffff\" font-weight=\"bold\">Vuông phẳng</tspan></text>\n    <text x=\"15\" y=\"95\" fill=\"#f43f5e\" font-size=\"11\">• Màu: <tspan fill=\"#38bdf8\" font-weight=\"bold\">Xanh thẫm</tspan></text>\n    <text x=\"15\" y=\"118\" fill=\"#94a3b8\" font-size=\"10\">(Xanh lam đậm)</text>\n  </g>\n  <!-- Footnote -->\n  <rect x=\"40\" y=\"190\" width=\"440\" height=\"28\" rx=\"4\" fill=\"rgba(30,41,59,0.9)\"/>\n  <text x=\"260\" y=\"209\" text-anchor=\"middle\" fill=\"#a7f3d0\" font-size=\"11\">Phối tử cho cặp electron tạo liên kết phối trí (cho - nhận) với orbital trống của ion trung tâm</text>\n</svg>"}, {"q": "Số phối trí của ion trung tâm bạc (Ag<sup>+</sup>) trong phức chất [Ag(NH<sub>3</sub>)<sub>2</sub>]OH (thuốc thử Tollens) là bao nhiêu?", "opts": ["2", "4", "6", "1"], "ans": 0, "exp": "• <b>Số phối trí:</b> Là tổng số liên kết sigma giữa các phối tử với nguyên tử/ion trung tâm.<br>• Trong [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup>, có 2 phân tử phối tử đơn càng NH<sub>3</sub> liên kết với ion Ag<sup>+</sup> → Số phối trí là 2, dạng hình học đường thẳng: [H<sub>3</sub>N – Ag – NH<sub>3</sub>]<sup>+</sup>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phức chất nào sau đây có dạng hình học bát diện (octahedral) với số phối trí bằng 6?", "opts": ["[Fe(CN)<sub>6</sub>]<sup>4-</sup> (hoặc [Fe(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup>)", "[Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup>", "[PtCl<sub>4</sub>]<sup>2-</sup>", "[Zn(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup>"], "ans": 0, "exp": "• <b>Hình học phức chất:</b><br>- Số phối trí 2: Dạng đường thẳng ([Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup>).<br>- Số phối trí 4: Vuông phẳng ([PtCl<sub>4</sub>]<sup>2-</sup>) hoặc Tứ diện ([Zn(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup>).<br>- Số phối trí 6: Bát diện đều ([Fe(CN)<sub>6</sub>]<sup>4-</sup>, [Fe(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup>, [Cr(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup>).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về bản chất phối tử (ligand) và liên kết trong phức chất:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Phối tử bắt buộc phải là phân tử hoặc anion có chứa ít nhất một cặp electron chưa liên kết (cặp electron tự do).", "Phối tử đơn càng (monodentate) như H₂O, NH₃, Cl⁻, CN⁻ chỉ tạo được một liên kết phối trí duy nhất với nguyên tử trung tâm.", "Liên kết giữa phối tử và nguyên tử trung tâm là liên kết cộng hoá trị cho – nhận (liên kết phối trí).", "Tất cả các phức chất đều tích điện âm và luôn tồn tại dưới dạng anion phức trong dung dịch."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Phải có cặp e tự do để nhường.<br>• <b>Ý b [Đúng]:</b> Định nghĩa phối tử đơn càng.<br>• <b>Ý c [Đúng]:</b> Phối tử cho cặp e, ion trung tâm nhận e vào AO trống.<br>• <b>Ý d [Sai]:</b> Phức chất có thể là cation phức ([Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup>), anion phức ([Fe(CN)<sub>6</sub>]<sup>4-</sup>) hoặc phân tử phức trung hoà không mang điện ([Ni(CO)<sub>4</sub>], cis-[Pt(NH<sub>3</sub>)<sub>2</sub>Cl<sub>2</sub>]).", "svgGraph": null}, {"q": "Ghép từng phức chất (Cột A) với dạng hình học không gian tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["[Ag(NH₃)₂]⁺ ➔ Đường thẳng (Linear, góc liên kết 180°)", "[Ag(NH₃)₂]⁺ ➔ Vuông phẳng (Square planar)", "[Ag(NH₃)₂]⁺ ➔ Tứ diện (Tetrahedral)", "[Ag(NH₃)₂]⁺ ➔ Bát diện (Octahedral, số phối trí 6)"], "ans": 0, "exp": "• <b>1 - A:</b> [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> đường thẳng.<br>• <b>2 - B:</b> [PtCl<sub>4</sub>]<sup>2-</sup> vuông phẳng.<br>• <b>3 - C:</b> [Zn(OH)<sub>4</sub>]<sup>2-</sup> tứ diện.<br>• <b>4 - D:</b> [Fe(CN)<sub>6</sub>]<sup>3-</sup> bát diện.", "svgGraph": null}, {"q": "Hoàn thiện các khái niệm cơ bản về phức chất:<br><i>\"Phức chất gồm  [ ... ]  trung tâm liên kết với các  [ ... ] . Số liên kết sigma giữa phối tử với nguyên tử trung tâm gọi là  [ ... ] . Phức chất [Ag(NH₃)₂]⁺ có ion trung tâm là  [ ... ]  và số phối trí là 2.\"</i>", "opts": ["nguyên tử — phối tử — số phối trí — Ag⁺", "Ag⁺ — số phối trí — phối tử — nguyên tử", "phối tử — số phối trí — Ag⁺ — nhóm chức", "số phối trí — Ag⁺ — nhóm chức — số oxi hoá"], "ans": 0, "exp": "• Các thành phần cốt lõi cấu tạo nên phức chất: nguyên tử/ion trung tâm, phối tử và số phối trí.", "svgGraph": null}, {"q": "Điện tích của ion phức [Fe(CN)<sub>6</sub>]<sup>x</sup> là bao nhiêu nếu biết ion trung tâm là sắt(III) Fe<sup>3+</sup> và các phối tử là anion cyanide CN<sup>-</sup>?", "opts": ["3-", "4-", "3+", "2-"], "ans": 0, "exp": "• <b>Quy tắc tính điện tích ion phức:</b><br>Điện tích ion phức = Điện tích ion trung tâm + Tổng điện tích các phối tử<br>Điện tích = (+3) + 6 · (-1) = +3 - 6 = -3.<br>Ion phức viết là [Fe(CN)<sub>6</sub>]<sup>3-</sup> (hexacyanidoferrate(III)).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Phối tử nào sau đây thuộc loại phối tử hai càng (bidentate ligand) có khả năng dùng 2 nguyên tử cho cùng liên kết vào 1 ion kim loại?", "opts": ["Oxalate ion (C<sub>2</sub>O<sub>4</sub><sup>2-</sup>, ⁻OOC–COO⁻) hoặc Ethylenediamine (en, H<sub>2</sub>N–CH<sub>2</sub>CH<sub>2</sub>–NH<sub>2</sub>)", "Chloride ion (Cl⁻)", "Ammonia (NH<sub>3</sub>)", "Nước (H<sub>2</sub>O)"], "ans": 0, "exp": "• Phối tử hai càng có 2 vị trí nguyên tử mang cặp e tự do cách nhau khoảng cách thích hợp để cùng 'ngoạm' (chelate) vào 1 ion trung tâm tạo vòng càng 5 hoặc 6 cạnh rất bền vững.<br>• Ion oxalate C<sub>2</sub>O<sub>4</sub><sup>2-</sup> và ethylenediamine là ví dụ kinh điển.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các phát biểu về thuốc chống ung thư cisplatin trong y học:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Cisplatin có công thức phân tử là cis-[Pt(NH₃)₂Cl₂], là một phức chất vuông phẳng trung hoà điện tích.", "Ở đồng phân cis, hai phối tử Cl⁻ nằm ở hai vị trí kề nhau với góc liên kết xấp xỉ 90°.", "Cisplatin có khả năng xâm nhập vào nhân tế bào ung thư, liên kết chéo với chuỗi xoắn kép DNA để ngăn chặn tế bào ung thư nhân đôi.", "Đồng phân trans-[Pt(NH₃)₂Cl₂] có hoạt tính chống ung thư mạnh hơn gấp hàng trăm lần so với đồng phân cis."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Cấu tạo phân tử cisplatin.<br>• <b>Ý b [Đúng]:</b> Cấu hình cis kề nhau.<br>• <b>Ý c [Đúng]:</b> Cơ chế tác dụng ức chế sao chép DNA khối u.<br>• <b>Ý d [Sai]:</b> Đồng phân trans-[Pt(NH<sub>3</sub>)<sub>2</sub>Cl<sub>2</sub>] hoàn toàn không có hoạt tính chữa ung thư vì khoảng cách 2 nhóm Cl ở vị trí trans (180°) quá xa không thể tạo liên kết chéo trên cùng một dải DNA.", "svgGraph": null}, {"q": "Trong phức chất aqua [Cu(H<sub>2</sub>O)<sub>6</sub>]<sup>2+</sup>, nguyên tử nào trong phân tử nước trực tiếp đóng góp cặp electron tạo liên kết phối trí với ion Cu<sup>2+</sup>?", "opts": ["Nguyên tử oxygen (O)", "Nguyên tử hydrogen (H)", "Cả nguyên tử O và nguyên tử H", "Không có nguyên tử nào trực tiếp cho electron"], "ans": 0, "exp": "• Trong phân tử H<sub>2</sub>O, nguyên tử oxygen có độ âm điện lớn và còn 2 cặp electron tự do chưa liên kết. Nguyên tử O dùng một cặp electron tự do này đưa vào orbital trống của cation kim loại để tạo liên kết phối trí M ← OH<sub>2</sub>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "29": [{"q": "Nhỏ từ từ dung dịch NH<sub>3</sub> đến dư vào ống nghiệm chứa dung dịch CuSO<sub>4</sub>. Hiện tượng quan sát được theo thứ tự là gì?", "opts": ["Ban đầu xuất hiện kết tủa Cu(OH)<sub>2</sub> màu xanh lam nhạt, sau đó kết tủa tan dần tạo dung dịch phức chất màu xanh lam đậm thẫm trong suốt.", "Dung dịch lập tức chuyển sang màu vàng tươi sủi bọt khí.", "Xuất hiện kết tủa màu đỏ gạch không bao giờ tan.", "Không có hiện tượng gì xảy ra."], "ans": 0, "exp": "• <b>Diễn biến 2 giai đoạn:</b><br>1. Ban đầu môi trường kiềm của NH<sub>3</sub> tạo kết tủa hydroxide:<br>Cu<sup>2+</sup> + 2NH<sub>3</sub> + 2H<sub>2</sub>O → Cu(OH)<sub>2</sub> ↓ (xanh nhạt) + 2NH<sub>4</sub><sup>+</sup>.<br>2. Khi NH<sub>3</sub> dư, Cu(OH)<sub>2</sub> bị hoà tan do tạo phức tetraamminecopper(II):<br>Cu(OH)<sub>2</sub> + 4NH<sub>3</sub> → [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> (màu xanh lam đậm thẫm) + 2OH<sup>-</sup>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": "<svg viewBox=\"0 0 520 230\" width=\"100%\" height=\"100%\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"100%\" height=\"100%\" fill=\"#070a14\" rx=\"12\"/>\n  <text x=\"260\" y=\"26\" text-anchor=\"middle\" fill=\"#38bdf8\" font-size=\"14\" font-weight=\"800\">SỰ TẠO PHỨC VÀ HOÀ TAN KẾT TỦA Cu(OH)₂ BẰNG DUNG DỊCH NH₃</text>\n  <!-- Step 1 Beaker -->\n  <g transform=\"translate(60, 48)\">\n    <rect x=\"0\" y=\"0\" width=\"100\" height=\"115\" rx=\"6\" fill=\"rgba(14,165,233,0.12)\" stroke=\"#0284c7\" stroke-width=\"1.8\"/>\n    <rect x=\"2\" y=\"40\" width=\"96\" height=\"73\" rx=\"4\" fill=\"rgba(56,189,248,0.2)\"/>\n    <!-- Precipitate at bottom -->\n    <ellipse cx=\"50\" cy=\"100\" rx=\"40\" ry=\"8\" fill=\"#38bdf8\" opacity=\"0.9\"/>\n    <text x=\"50\" y=\"130\" text-anchor=\"middle\" fill=\"#7dd3fc\" font-size=\"11\" font-weight=\"bold\">Cu(OH)₂ ↓</text>\n    <text x=\"50\" y=\"145\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"9.5\">Kết tủa xanh nhạt</text>\n  </g>\n  <!-- Transition Arrow -->\n  <g transform=\"translate(185, 95)\">\n    <path d=\"M 0 0 L 70 0 M 60 -6 L 70 0 L 60 6\" fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.5\"/>\n    <text x=\"35\" y=\"-12\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">+ NH₃ dư</text>\n    <text x=\"35\" y=\"18\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"9.5\">Tạo phức chelate</text>\n  </g>\n  <!-- Step 2 Beaker Deep Blue -->\n  <g transform=\"translate(285, 48)\">\n    <rect x=\"0\" y=\"0\" width=\"100\" height=\"115\" rx=\"6\" fill=\"rgba(30,58,138,0.2)\" stroke=\"#1e40af\" stroke-width=\"1.8\"/>\n    <rect x=\"2\" y=\"40\" width=\"96\" height=\"73\" rx=\"4\" fill=\"#1e3a8a\" opacity=\"0.95\"/>\n    <text x=\"50\" y=\"130\" text-anchor=\"middle\" fill=\"#60a5fa\" font-size=\"11\" font-weight=\"bold\">[Cu(NH₃)₄]²⁺</text>\n    <text x=\"50\" y=\"145\" text-anchor=\"middle\" fill=\"#93c5fd\" font-size=\"9.5\">Dung dịch xanh thẫm</text>\n  </g>\n  <!-- Biological Application box -->\n  <g transform=\"translate(410, 48)\">\n    <rect width=\"90\" height=\"115\" rx=\"6\" fill=\"rgba(30,41,59,0.9)\" stroke=\"#fbbf24\" stroke-width=\"1.5\"/>\n    <text x=\"45\" y=\"24\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10.5\" font-weight=\"bold\">SINH HỌC</text>\n    <text x=\"45\" y=\"48\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"10\" font-weight=\"bold\">Hemoglobin</text>\n    <text x=\"45\" y=\"62\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"9\">(Phức Fe²⁺ máu)</text>\n    <text x=\"45\" y=\"85\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"10\" font-weight=\"bold\">Chlorophyll</text>\n    <text x=\"45\" y=\"100\" text-anchor=\"middle\" fill=\"#cbd5e1\" font-size=\"9\">(Phức Mg²⁺ lá)</text>\n  </g>\n  <!-- Footnote -->\n  <rect x=\"40\" y=\"195\" width=\"440\" height=\"26\" rx=\"4\" fill=\"rgba(30,41,59,0.9)\"/>\n  <text x=\"260\" y=\"213\" text-anchor=\"middle\" fill=\"#f8fafc\" font-size=\"10.5\">Thuốc chống ung thư Cisplatin cis-[Pt(NH₃)₂Cl₂] và chất giải độc kim loại nặng EDTA</text>\n</svg>"}, {"q": "Nhỏ từ từ dung dịch NH<sub>3</sub> vào kết tủa trắng bạc chloride (AgCl) trong ống nghiệm, kết tủa tan hoàn toàn tạo dung dịch trong suốt không màu nhờ phản ứng tạo ion phức nào?", "opts": ["[Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> (diamminesilver(I))", "[Ag(OH)<sub>2</sub>]<sup>-</sup>", "[AgCl<sub>2</sub>]<sup>-</sup>", "[Ag(NH<sub>3</sub>)<sub>4</sub>]<sup>+</sup>"], "ans": 0, "exp": "• <b>Phương trình phản ứng hoà tan kết tủa AgCl:</b><br>AgCl ↓ + 2NH<sub>3</sub> → [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> + Cl<sup>-</sup>.<br>• Phức [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> rất bền vững, làm chuyển dịch cân bằng hoà tan của AgCl sang chiều tan hoàn toàn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Chất diệp lục (chlorophyll) trong lá cây xanh có vai trò hấp thụ ánh sáng mặt trời trong quá trình quang hợp là phức chất thiên nhiên của ion kim loại nào?", "opts": ["Magnesium (Mg<sup>2+</sup>)", "Iron (Fe<sup>2+</sup>)", "Copper (Cu<sup>2+</sup>)", "Cobalt (Co<sup>3+</sup>)"], "ans": 0, "exp": "• <b>Các phức chất sinh học kinh điển:</b><br>- <b>Diệp lục (Chlorophyll):</b> Phức chất của Mg<sup>2+</sup> với vòng porphyrin (hấp thu ánh sáng quang hợp tạo màu xanh lá).<br>- <b>Hemoglobin:</b> Phức chất của Fe<sup>2+</sup> với nhóm heme (vận chuyển oxy trong hồng cầu máu).<br>- <b>Vitamin B12:</b> Phức chất của Co<sup>3+</sup>.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về ứng dụng của phức chất trong y tế, công nghiệp và đời sống:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Hemoglobin trong máu là phức chất của ion Fe²⁺ có khả năng liên kết thuận nghịch với O₂ để vận chuyển oxy từ phổi đến các tế bào.", "Khí carbon monoxide (CO) rất độc vì tạo liên kết phối trí với Fe²⁺ trong hemoglobin bền hơn O₂ gấp hàng trăm lần, ngăn cản máu vận chuyển oxy gây ngạt thở tử vong.", "Chất phối tử EDTA (ethylenediaminetetraacetic acid) là phối tử đa càng được dùng làm thuốc giải độc khi cơ thể bị nhiễm độc kim loại nặng như chì (Pb²⁺), thuỷ ngân (Hg²⁺).", "Trong công nghiệp tuyển quặng vàng sa khoáng, người ta dùng dung dịch acid HCl đặc để hoà tan vàng thành phức tan."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Cơ chế vận chuyển O<sub>2</sub> hô hấp.<br>• <b>Ý b [Đúng]:</b> Cơ chế ngộ độc khí than CO cực kì nguy hiểm.<br>• <b>Ý c [Đúng]:</b> EDTA bọc kín ion kim loại nặng thành phức chất tan không độc bài tiết qua thận.<br>• <b>Ý d [Sai]:</b> Tuyển vàng dùng dung dịch <b>NaCN</b> có sục không khí tạo phức tan dicyanidoaurate(I): 4Au + 8NaCN + O<sub>2</sub> + 2H<sub>2</sub>O → 4Na[Au(CN)<sub>2</sub>] + 4NaOH.", "svgGraph": null}, {"q": "Ghép từng phức chất (Cột A) với vai trò sinh học hoặc ứng dụng thực tế tương ứng (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["Hemoglobin ➔ Protein vận chuyển khí oxygen và carbon dioxide trong máu", "Hemoglobin ➔ Thuốc hoá trị điều trị hiệu quả các bệnh ung thư (tinh hoàn, buồng trứng)", "Hemoglobin ➔ Phức chất sinh học chứa Co³⁺ cần thiết cho quá trình tạo máu và thần kinh", "Hemoglobin ➔ Tráng gương, tráng ruột phích và nhận biết nhóm chức aldehyde"], "ans": 0, "exp": "• <b>1 - A:</b> Hemoglobin vận chuyển khí máu.<br>• <b>2 - B:</b> Cisplatin thuốc hoá trị ung thư.<br>• <b>3 - C:</b> Vitamin B12 phức Co<sup>3+</sup>.<br>• <b>4 - D:</b> Thuốc thử Tollens tráng bạc.", "svgGraph": null}, {"q": "Hoàn thiện nhận định về sự thay đổi màu sắc khi tạo phức chất:<br><i>\"Khi phối tử mới tạo liên kết phối trí  [ ... ]  hơn phối tử cũ, xảy ra phản ứng  [ ... ]  phối tử. Sự thay đổi phối tử làm thay đổi năng lượng tách orbital d, dẫn đến  [ ... ]  của phức chất bị biến đổi rõ rệt. Phức [Cu(H₂O)₄]²⁺ có màu  [ ... ] , khi chuyển thành [Cu(NH₃)₄]²⁺ chuyển sang màu xanh lam đậm thẫm.\"</i>", "opts": ["bền — thế — màu sắc — xanh lam nhạt", "xanh lam nhạt — màu sắc — thế — bền", "thế — màu sắc — xanh lam nhạt — yếu", "màu sắc — xanh lam nhạt — yếu — nhiệt độ"], "ans": 0, "exp": "• Phản ứng thế phối tử, sự biến đổi màu sắc quang phổ của phức chất Cu<sup>2+</sup>.", "svgGraph": null}, {"q": "Tại sao khi đun nóng nhẹ dung dịch phức chất [Cu(NH<sub>3</sub>)<sub>4</sub>](OH)<sub>2</sub> (nước Schweizer) đã hoà tan cellulose thì cellulose lại kết tủa trở lại thành các sợi tơ đồng – amoniac?", "opts": ["Khi đun nóng, khí NH<sub>3</sub> bay ra làm phức chất bị phá huỷ, cellulose mất dung môi hoà tan nên kết tủa tái sinh thành sợi tơ.", "Nhiệt độ cao làm phân huỷ cellulose thành than đen.", "Đồng kim loại bị bay hơi hết.", "Dung dịch bị acid hoá tự nhiên."], "ans": 0, "exp": "• <b>Cơ chế sản xuất tơ đồng - amoniac:</b> Nước Schweizer hoà tan cellulose nhờ tạo phức chất phối trí giữa Cu<sup>2+</sup> và các nhóm –OH của cellulose.<br>• Khi ép dung dịch keo nhớt này qua các lỗ nhỏ vào bồn acid hoặc đun nóng, NH<sub>3</sub> bị trung hoà/bay hơi làm phức tan vỡ, các phân tử cellulose kết tụ lại tạo thành sợi tơ nhân tạo bóng mịn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Chất xúc tác Wilkinson [RhCl(PPh<sub>3</sub>)<sub>3</sub>] là một phức chất của kim loại chuyển tiếp rhodium (Rh), được sử dụng nổi tiếng trong hoá học hữu cơ để thực hiện phản ứng nào?", "opts": ["Phản ứng hydro hoá có chọn lọc liên kết đôi C=C của alkene ở điều kiện êm dịu", "Phản ứng xà phòng hoá chất béo", "Phản ứng tráng bạc của đường", "Phản ứng điện phân nóng chảy"], "ans": 0, "exp": "• Xúc tác Wilkinson là chất xúc tác đồng thể kinh điển (đoạt giải Nobel Hoá học) cho phản ứng cộng H<sub>2</sub> vào liên kết đôi C=C của các hợp chất hữu cơ với độ chọn lọc lập thể rất cao.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về độ bền và hằng số tạo phức trong hoá học dung dịch:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Hằng số cân bằng của phản ứng tạo phức chất gọi là hằng số tạo thành (hằng số bền) K_bền, giá trị này càng lớn thì phức chất càng bền.", "Phức chất vòng càng (chelate) tạo bởi phối tử đa càng như EDTA luôn có độ bền cao hơn nhiều so với phức chất tương ứng tạo bởi các phối tử đơn càng.", "Khi thêm dung dịch acid HCl vào dung dịch phức [Cu(NH₃)₄]²⁺, màu xanh thẫm lập tức biến mất và chuyển về màu xanh lam nhạt của Cu²⁺ ban đầu.", "Phức chất chỉ có thể tồn tại trong phòng thí nghiệm và hoàn toàn không có vai trò gì đối với sự sống của con người."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> K<sub>bền</sub> càng lớn liên kết phối trí càng chặt chẽ.<br>• <b>Ý b [Đúng]:</b> Hiệu ứng vòng càng chelate tạo độ bền entropy và enthalpy vượt trội.<br>• <b>Ý c [Đúng]:</b> H<sup>+</sup> kết hợp mạnh với NH<sub>3</sub> tạo NH<sub>4</sub><sup>+</sup> làm phá huỷ phức [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> tạo lại ion Cu<sup>2+</sup> tự do: [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> + 4H<sup>+</sup> → Cu<sup>2+</sup> + 4NH<sub>4</sub><sup>+</sup>.<br>• <b>Ý d [Sai]:</b> Phức chất duy trì sự sống (hồng cầu, diệp lục, vitamin, enzyme chuyển hoá).", "svgGraph": null}, {"q": "Khi làm thí nghiệm nhận biết ion Fe<sup>3+</sup> trong dung dịch nước, thuốc thử tạo phức chất màu đỏ máu đặc trưng (blood-red color) là:", "opts": ["Dung dịch potassium thiocyanate (KSCN) tạo phức [Fe(SCN)]<sup>2+</sup>", "Dung dịch NaCl", "Dung dịch H<sub>2</sub>SO<sub>4</sub> loãng", "Dung dịch glucose"], "ans": 0, "exp": "• <b>Phản ứng nhận biết đặc trưng:</b><br>Fe<sup>3+</sup> + SCN<sup>-</sup> ⇌ [Fe(SCN)]<sup>2+</sup> (phức chất có màu đỏ máu rực rỡ, rất nhạy kể cả ở nồng độ vết dùng trong phân tích hoá học và đạo cụ máu giả trong phim ảnh sân khấu).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}], "30": [{"q": "Phát biểu nào sau đây là ĐÚNG khi nói về kim loại chuyển tiếp dãy thứ nhất và phức chất?", "opts": ["Cấu hình electron nguyên tử của đồng (Cu) là [Ar] 3d<sup>10</sup> 4s<sup>1</sup> và số phối trí của Cu<sup>2+</sup> trong [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> là 4.", "Tất cả các kim loại chuyển tiếp dãy thứ nhất đều có nhiệt độ nóng chảy thấp hơn thuỷ ngân.", "Ion trung tâm trong phức chất bắt buộc phải là anion phi kim.", "Các cation kim loại chuyển tiếp d<sup>0</sup> và d<sup>10</sup> luôn có màu tím thẫm trong dung dịch nước."], "ans": 0, "exp": "• <b>Phân tích:</b><br>- Cu (Z=29) có cấu hình [Ar] 3d<sup>10</sup> 4s<sup>1</sup> chuẩn.<br>- Trong [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup>, ion Cu<sup>2+</sup> liên kết với 4 phối tử NH<sub>3</sub> nên số phối trí bằng 4.<br>- Các đáp án còn lại đều sai kiến thức cơ bản.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Cặp phức chất nào sau đây đều có dạng hình học bát diện với số phối trí bằng 6?", "opts": ["[Fe(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup> và [Cr(NH<sub>3</sub>)<sub>6</sub>]<sup>3+</sup>", "[Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> và [PtCl<sub>4</sub>]<sup>2-</sup>", "[Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> và [Zn(OH)<sub>4</sub>]<sup>2-</sup>", "[Ag(CN)<sub>2</sub>]<sup>-</sup> và [Ni(CO)<sub>4</sub>]"], "ans": 0, "exp": "• Các ion phức có 6 phối tử đơn càng (như 6 H<sub>2</sub>O hoặc 6 NH<sub>3</sub>) đều có số phối trí bằng 6 và dạng hình học không gian là bát diện đều (octahedral).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Khi cho dung dịch NaOH từ từ vào dung dịch ZnSO<sub>4</sub> đến dư, hiện tượng quan sát được là:", "opts": ["Xuất hiện kết tủa trắng keo Zn(OH)<sub>2</sub>, sau đó kết tủa tan dần tạo dung dịch trong suốt chứa ion phức [Zn(OH)<sub>4</sub>]<sup>2-</sup>.", "Xuất hiện kết tủa màu nâu đỏ không tan.", "Có khí màu nâu đỏ bay ra.", "Không có hiện tượng gì."], "ans": 0, "exp": "• <b>Diễn biến phản ứng:</b><br>1. Zn<sup>2+</sup> + 2OH<sup>-</sup> → Zn(OH)<sub>2</sub> ↓ (kết tủa keo trắng).<br>2. Zn(OH)<sub>2</sub> lưỡng tính tan trong kiềm dư tạo ion phức tetrahydroxidozincate(II):<br>Zn(OH)<sub>2</sub> + 2OH<sup>-</sup> → [Zn(OH)<sub>4</sub>]<sup>2-</sup> (tan trong suốt).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét tính Đúng/Sai của các nhận định tổng kết Chương 8:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Kim loại chuyển tiếp có độ cứng cao và nhiệt độ nóng chảy cao hơn nhiều so với kim loại nhóm kiềm và kiềm thổ.", "Phức chất cisplatin cis-[Pt(NH₃)₂Cl₂] được ứng dụng thành công làm thuốc điều trị ung thư trong y học.", "Ion Fe²⁺ trong hemoglobin có khả năng liên kết thuận nghịch với O₂ để thực hiện chức năng hô hấp của máu.", "Liên kết phối trí trong phức chất là liên kết trong đó cả hai nguyên tử đều đóng góp 1 electron để dùng chung."], "ans": 3, "exp": "• <b>Ý a [Đúng]:</b> Do liên kết kim loại có sự tham gia của electron d bền vững.<br>• <b>Ý b [Đúng]:</b> Thuốc chống ung thư cisplatin kinh điển.<br>• <b>Ý c [Đúng]:</b> Vai trò hô hấp của hemoglobin.<br>• <b>Ý d [Sai]:</b> Liên kết phối trí (cho - nhận) là liên kết mà cặp electron liên kết <b>chỉ do một nguyên tử (phối tử) đóng góp</b> đưa vào orbital trống của nguyên tử kia.", "svgGraph": null}, {"q": "Ghép từng ion kim loại hoặc phức chất (Cột A) với màu sắc đặc trưng trong dung dịch nước (Cột B):<br>Cặp ghép nối nào sau đây thể hiện <b>ĐÚNG BẢN CHẤT HÓA HỌC</b>?", "opts": ["[Cu(NH₃)₄]²⁺ ➔ Màu xanh lam đậm thẫm", "[Cu(NH₃)₄]²⁺ ➔ Màu vàng nâu", "[Cu(NH₃)₄]²⁺ ➔ Màu tím thẫm rực rỡ", "[Cu(NH₃)₄]²⁺ ➔ Màu đỏ máu (blood red)"], "ans": 0, "exp": "• <b>1 - A:</b> [Cu(NH<sub>3</sub>)<sub>4</sub>]<sup>2+</sup> xanh lam đậm.<br>• <b>2 - B:</b> Fe<sup>3+</sup> vàng nâu.<br>• <b>3 - C:</b> MnO<sub>4</sub><sup>-</sup> tím thẫm.<br>• <b>4 - D:</b> [Fe(SCN)]<sup>2+</sup> đỏ máu.", "svgGraph": null}, {"q": "Hoàn thiện tổng kết toàn diện Chương 8:<br><i>\"Dãy kim loại chuyển tiếp thứ nhất gồm các nguyên tố có phân lớp  [ ... ]  đang xây dựng dở. Chúng có khả năng tạo phức chất cao nhờ có các orbital trống. Phức chất gồm ion trung tâm liên kết với các  [ ... ]  bằng liên kết  [ ... ] . Phức chất [Fe(CN)₆]⁴⁻ có số phối trí bằng  [ ... ]  và dạng bát diện.\"</i>", "opts": ["3d — phối tử — phối trí — 6", "6 — phối trí — phối tử — 3d", "phối tử — phối trí — 6 — 4s", "phối trí — 6 — 4s — ion"], "ans": 0, "exp": "• Tổng kết phân lớp 3d, phối tử, liên kết phối trí và số phối trí 6 của phức chất bát diện.", "svgGraph": null}, {"q": "Khi thêm từ từ dung dịch KCN vào dung dịch AgNO<sub>3</sub>, ban đầu xuất hiện kết tủa trắng AgCN, sau đó kết tủa tan khi cho dư KCN tạo ra phức chất tan có công thức là:", "opts": ["K[Ag(CN)<sub>2</sub>]", "K<sub>2</sub>[Ag(CN)<sub>3</sub>]", "K<sub>3</sub>[Ag(CN)<sub>4</sub>]", "Ag[Ag(CN)<sub>2</sub>]"], "ans": 0, "exp": "• <b>Phương trình phản ứng:</b><br>AgCN ↓ + KCN → K[Ag(CN)<sub>2</sub>].<br>• Phức chất potassium dicyanidoargentate(I) tan tốt trong nước, được ứng dụng rộng rãi trong kĩ thuật mạ điện bạc trang sức và công nghiệp chiết xuất bạc từ quặng.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Nguyên tử kim loại chuyển tiếp nào sau đây có số electron độc thân nhiều nhất ở trạng thái cơ bản?", "opts": ["Chromium (Cr có 6 electron độc thân: 3d<sup>5</sup> 4s<sup>1</sup>)", "Manganese (Mn có 5 electron độc thân)", "Iron (Fe có 4 electron độc thân)", "Copper (Cu có 1 electron độc thân)"], "ans": 0, "exp": "• Cấu hình của Cr là [Ar] 3d<sup>5</sup> 4s<sup>1</sup>: Cả 5 electron ở phân lớp 3d đều độc thân và 1 electron ở phân lớp 4s cũng độc thân → tổng cộng có đúng <b>6 electron độc thân</b>, nhiều nhất trong toàn bộ bảng tuần hoàn.<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}, {"q": "Xét các nhận định về tầm quan trọng của phức chất trong các công nghệ hiện đại:<br>Trong các phát biểu sau, phát biểu nào <b>SAI</b>?", "opts": ["Các phức chất phát quang của kim loại chuyển tiếp (như iridium, platin) là vật liệu then chốt chế tạo màn hình diode phát quang hữu cơ (OLED) cho tivi và điện thoại cao cấp.", "Thuốc giải độc EDTA cứu sống bệnh nhân ngộ độc ion chì (Pb²⁺) bằng cách tạo phức chelate bền vững với chì để đào thải ra ngoài theo đường nước tiểu.", "Tất cả các phức chất của kim loại chuyển tiếp đều rất độc và bị cấm sử dụng trong y tế điều trị bệnh cho con người.", "Enzyme carbonic anhydrase trong hồng cầu chứa phức chất của ion Zn²⁺ xúc tác phản ứng chuyển hoá CO₂ thành HCO₃⁻ với tốc độ hàng triệu phân tử mỗi giây."], "ans": 2, "exp": "• <b>Ý a [Đúng]:</b> Phức kim loại trong công nghệ màn hình OLED.<br>• <b>Ý b [Đúng]:</b> EDTA giải độc chì và kim loại nặng.<br>• <b>Ý c [Sai]:</b> Nhiều phức chất là thuốc chữa bệnh cứu người (Cisplatin chống ung thư, phức sắt bổ máu).<br>• <b>Ý d [Đúng]:</b> Enzyme chứa kẽm carbonic anhydrase có tốc độ xúc tác nhanh nhất sinh giới.", "svgGraph": null}, {"q": "Cation kim loại chuyển tiếp M<sup>2+</sup> có cấu hình electron [Ar] 3d<sup>7</sup>. Kim loại M là nguyên tố nào sau đây?", "opts": ["Cobalt (Co, Z = 27)", "Iron (Fe, Z = 26)", "Nickel (Ni, Z = 28)", "Copper (Cu, Z = 29)"], "ans": 0, "exp": "• Cation M<sup>2+</sup> có cấu hình [Ar] 3d<sup>7</sup>.<br>• Nguyên tử M trung hoà điện có thêm 2 electron ở phân lớp 4s ngoài cùng: [Ar] 3d<sup>7</sup> 4s<sup>2</sup>.<br>• Tổng số electron = 18 + 7 + 2 = 27 electron → Z = 27, đó chính là nguyên tố Cobalt (Co).<br>• <b>Kết luận:</b> Chọn đáp án A.", "svgGraph": null}]}};
